function R.Normalize(text)    if A.Normalize then return A.Normalize(text) end
    text = tostring(text or ""):lower():gsub("[,;:!?%(%)]", " "):gsub("%s+", " ")
    return R.Trim(text)
end

function R.StripResponseLanguageDirective(text)
    local norm = R.Normalize(text)
    if norm == "" then return norm end
    local data = MSUF.AssistantDialogLocaleData
    local directives = data and data.explicitLanguage
    if type(directives) ~= "table" then
        -- The isolated Lua audits load Router without the later DialogLocale
        -- data file. Keep only the structural fallback here; the game runtime
        -- consumes the complete phrase set from AssistantDialogLocaleData.
        directives = {
            de = { "answer in german", "in german", "antworte auf deutsch", "auf deutsch" },
            en = { "answer in english", "in english", "antworte auf englisch", "auf englisch" },
        }
    end

    local candidate = norm:gsub("^please%s+", "")
    local bestPrefix, bestSuffix = 0, 0
    for _, language in ipairs({ "de", "en" }) do
        for _, phrase in ipairs(directives[language] or {}) do
            phrase = R.Normalize(phrase)
            if phrase ~= "" then
                if candidate == phrase then return "" end
                if candidate:sub(1, #phrase + 1) == phrase .. " " and #phrase > bestPrefix then bestPrefix = #phrase end
                local suffixDirective = phrase:match("^answer%s+") or phrase:match("^reply%s+")
                    or phrase:match("^please%s+") or phrase:match("^speak%s+")
                    or phrase:match("^antworte%s+") or phrase:match("^antwort%s+")
                    or phrase:match("^bitte%s+") or phrase:match("^sprich%s+")
                if suffixDirective and candidate:sub(-#phrase - 1) == " " .. phrase and #phrase > bestSuffix then
                    bestSuffix = #phrase
                end
            end
        end
    end
    if bestPrefix > 0 then candidate = R.Trim(candidate:sub(bestPrefix + 1)) end
    if bestSuffix > 0 then candidate = R.Trim(candidate:sub(1, #candidate - bestSuffix - 1)) end
    return candidate
end

function R.MaybeYield()    if A and type(A.MaybeYield) == "function" then A.MaybeYield() end
end

function R.HasNormalizedPhrase(normalizedText, phrase)    phrase = R.Normalize(phrase)
    if phrase == "" then return false end
    return (" " .. tostring(normalizedText or "") .. " "):find(" " .. phrase .. " ", 1, true) ~= nil
end

function R.HasPhrase(text, phrase)    return R.HasNormalizedPhrase(R.Normalize(text), phrase)
end

function R.ContainsAny(text, words)    local normalizedText = R.Normalize(text)
    for i = 1, #(words or {}) do
        if R.HasNormalizedPhrase(normalizedText, words[i]) then return true end
    end
    if type(A.FuzzyPhraseMatch) == "function" then
        for i = 1, #(words or {}) do
            if A.FuzzyPhraseMatch(normalizedText, words[i]) then return true end
        end
    end
    return false
end

function R.IsExactGenericDiagnosticRequest(text)
    local norm = R.Normalize(text)
    return norm == "run checks"
        or norm == "run check"
        or norm == "run diagnostics"
        or norm == "run diagnostic"
        or norm == "health check"
        or norm == "run health check"
        or norm == "msuf status"
        or norm == "show msuf status"
        or norm == "assistant status"
        or norm == "show assistant status"
        or norm == "diagnostic report"
        or norm == "show diagnostic report"
        or norm == "diagnostik"
        or norm == "diagnosebericht"
        or norm == "fehlerbericht"
        or norm == "support text"
        or norm == "show support text"
        or norm == "assistant support text"
        or norm == "show assistant support text"
end

function R.IsStandaloneCancelReply(text)    local norm = R.Normalize(text)
    return norm == "no"
        or norm == "no thanks"
        or norm == "cancel"
        or norm == "abort"
        or norm == "stop"
        or norm == "nein"
        or norm == "nein danke"
        or norm == "abbrechen"
end

function R.IsStandaloneFlowReply(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    if R.IsStandaloneCancelReply(norm) then return true end
    return norm == "yes"
        or norm == "y"
        or norm == "yeah"
        or norm == "yep"
        or norm == "yup"
        or norm == "ja"
        or norm == "confirm"
        or norm == "apply"
        or norm == "apply it"
        or norm == "apply that"
        or norm == "do it"
        or norm == "do that"
        or norm == "fix it"
        or norm == "fix that"
        or norm == "ok"
        or norm == "okay"
        or norm == "next"
        or norm == "back"
        or norm == "finish"
        or norm == "stop"
        or norm == "abort"
        or norm == "undo"
        or norm == "redo"
        or norm == "undo last"
        or norm == "redo last"
end

R.exactAssistantKeyCache = nil
R.exactAssistantKeyCacheCount = 0
function R.LooksLikeExactAssistantKey(text)    local raw = tostring(text or "")
    if not raw:find("[%.%_]") then return false end
    local registry = A.Registry
    if not registry then return false end
    local settings = type(registry.AllSettings) == "function" and registry:AllSettings() or {}
    local actions = type(registry.AllActions) == "function" and registry:AllActions() or {}
    local count = #settings + #actions
    if type(R.exactAssistantKeyCache) ~= "table" or R.exactAssistantKeyCacheCount ~= count then
        R.exactAssistantKeyCache = {}
        R.exactAssistantKeyCacheCount = count
        for i = 1, #settings do
            local key = tostring(settings[i] and settings[i].key or ""):lower()
            if key ~= "" then R.exactAssistantKeyCache[key] = true end
        end
        for i = 1, #actions do
            local key = tostring(actions[i] and actions[i].key or ""):lower()
            if key ~= "" then R.exactAssistantKeyCache[key] = true end
        end
    end
    for token in raw:gmatch("[%w_%.]+") do
        if token:find("[%.%_]") and R.exactAssistantKeyCache[token:lower()] then return true end
    end
    return false
end

function R.LooksLikeBareLookup(text)    local norm = R.Normalize(text)
    if norm == "" then return false end
    if norm:match("%d") then return false end
    if norm:match("#%x%x%x") then return false end
    for i = 1, #R.COMMAND_TERMS do
        if R.HasPhrase(norm, R.COMMAND_TERMS[i]) then return false end
    end
    for i = 1, #R.COLOR_TERMS do
        if R.HasPhrase(norm, R.COLOR_TERMS[i]) then return false end
    end
    return true
end


function R.LooksLikeMutation(text)    local norm = R.Normalize(text)
    if norm == "" then return false end
    if R.ContainsAny(norm, { "help", "why", "where", "where is", "what", "how", "search", "find", "show commands", "hilfe", "warum", "wo", "suche", "finde" }) then
        return false
    end
    return R.ContainsAny(norm, R.MUTATION_TERMS)
end

function R.LooksLikeKnowledgeQuestionPrefix(text)    local norm = R.Normalize(text)
    if norm == "" then return false end
    if norm:match("^how%s+do%s+i%s+undo") or norm:match("^how%s+can%s+i%s+undo") then return true end
    if norm:match("^how%s+do%s+i%s+redo") or norm:match("^how%s+can%s+i%s+redo") then return true end
    if norm:match("^can%s+i%s+undo") or norm:match("^can%s+you%s+undo") then return true end
    if norm:match("^can%s+i%s+redo") or norm:match("^can%s+you%s+redo") then return true end
    if (norm:match("^how%s+do%s+i%s+") or norm:match("^how%s+can%s+i%s+"))
        and R.ContainsAny(norm, { "move", "drag", "position", "place", "verschiebe", "positionieren" })
    then
        return true
    end
    if (norm:match("^how%s+do%s+i%s+") or norm:match("^how%s+can%s+i%s+"))
        and R.ContainsAny(norm, {
            "change", "set", "make", "hide", "show", "turn on", "turn off", "enable", "disable",
            "lock", "unlock", "resize", "increase", "decrease", "scale", "scaling",
        })
        and R.ContainsAny(norm, {
            "text", "name", "hp", "health", "power", "mana", "castbar", "cast bar",
            "class resource", "class power", "combat timer", "totem", "raid frame", "party frame",
            "group frame", "ready check", "role icon", "range fade", "menu scale", "menu bigger",
            "menu smaller", "options scale", "ui scale", "raid", "party", "mythic raid",
            "players", "player count", "raid size",
        })
    then
        return true
    end
    if norm:match("^help%s+with%s+")
        and R.ContainsAny(norm, { "cooldown manager", "cooldownmanager", "essential cooldown", "essential cooldowns", "cdm" })
    then
        return true
    end
    if R.ContainsAny(norm, {
        "what did you change", "what changed", "what was changed", "what did you do",
        "what did you just change", "what exactly did you change", "what did you set",
        "last change", "last assistant change", "previous change", "what is it now",
        "what is it set to", "current value", "value now", "show last change",
        "show me last change", "show me the last change",
    }) then
        return false
    end
    if norm:match("^explain%s+") or norm:match("^erklaere%s+") then return true end
    if norm:match("^what%s+does%s+") or norm:match("^what%s+is%s+") or norm:match("^what%s+are%s+") then return true end
    if norm:match("^where%s+do%s+") or norm:match("^where%s+can%s+") or norm:match("^where%s+to%s+") then return true end
    if norm:match("^where%s+is%s+") or norm:match("^where%s+are%s+") then return true end
    if norm:match("^show%s+me%s+.+settings") or norm:match("^show%s+me%s+.+options") then return true end
    if norm:match("^wo%s+ist%s+") or norm:match("^wo%s+kann%s+") or norm:match("^was%s+ist%s+") then return true end
    if norm:match("^was%s+kann%s+") or norm:match("^was%s+kannst%s+") or norm:match("^wie%s+kann%s+") then return true end
    return false
end

function R.StartsWithMutationCommand(text)    local norm = R.Normalize(text)
    if norm == "" then return false end
    if R.LooksLikeKnowledgeQuestionPrefix(norm) then return false end
    for i = 1, #R.MUTATION_TERMS do
        local term = R.Normalize(R.MUTATION_TERMS[i])
        if norm == term or norm:sub(1, #term + 1) == term .. " " then return true end
    end
    return false
end

R.UNMISTAKABLE_BOOLEAN_COMMANDS = {
    enable = true, disable = true, show = true, hide = true,
    aktivieren = true, deaktivieren = true, anzeigen = true, verstecken = true,
    einblenden = true, ausblenden = true,
}
R.UNMISTAKABLE_RELATIVE_COMMANDS = {
    increase = true, decrease = true, raise = true, lower = true, move = true, nudge = true, shift = true,
    erhoehe = true, senke = true, verschiebe = true,
}
R.UNMISTAKABLE_VALUE_COMMANDS = {
    set = true, change = true, make = true, setze = true, stelle = true, aendere = true,
}

function R.HasUnmistakableMutationRequest(text)
    local norm = R.Normalize(text)
    norm = norm:gsub("^please%s+", ""):gsub("^bitte%s+", "")
    norm = norm:gsub("^can%s+you%s+", ""):gsub("^could%s+you%s+", ""):gsub("^would%s+you%s+", "")
    norm = norm:gsub("^kannst%s+du%s+", ""):gsub("^koenntest%s+du%s+", "")
    if norm == "" then return false end
    if norm:match("^show%s+me%s+") or norm:match("^zeige%s+mir%s+")
        or R.LooksLikeKnowledgeQuestionPrefix(norm)
        or R.ContainsAny(norm, { "where", "which setting", "which option", "current value", "explain", "wo", "welche einstellung", "erklaere" })
    then
        return false
    end

    if norm:match("^turn%s+on%s+") or norm:match("^turn%s+off%s+") then return true end
    local firstWord = norm:match("^(%S+)")
    if R.UNMISTAKABLE_BOOLEAN_COMMANDS[firstWord] and norm:find(" ", 1, true) then return true end
    if R.UNMISTAKABLE_RELATIVE_COMMANDS[firstWord] then
        return norm:match("%d") ~= nil or R.ContainsAny(norm, {
            "left", "right", "up", "down", "more", "less", "links", "rechts", "hoch", "runter", "mehr", "weniger",
        })
    end
    if not R.UNMISTAKABLE_VALUE_COMMANDS[firstWord] then return false end
    return norm:match("%d") ~= nil
        or norm:find(" to ", 1, true) ~= nil
        or norm:find(" auf ", 1, true) ~= nil
        or norm:find(" = ", 1, true) ~= nil
        or R.ContainsAny(norm, R.COLOR_TERMS)
        or R.ContainsAny(norm, { "on", "off", "enabled", "disabled", "an", "aus", "aktiv", "inaktiv" })
end

function R.IsCapabilityMutationQuestion(text)
    local norm = R.Normalize(text)
    return norm:match("^is%s+it%s+possible%s+to%s+") ~= nil
        or norm:match("^would%s+it%s+be%s+possible%s+to%s+")
        or norm:match("^could%s+i%s+")
end

function R.CapabilityCommandSubject(command)
    local subject = R.Normalize(command)
    subject = subject:gsub("^please%s+", "")
    local prefixes = {
        "turn off ", "turn on ", "change ", "configure ", "adjust ",
        "create ", "rotate ", "render ", "generate ", "disable ",
        "enable ", "remove ", "move ", "show ", "hide ", "make ",
        "play ", "draw ", "browse ", "add ", "set ",
    }
    for i = 1, #prefixes do
        local prefix = prefixes[i]
        if subject:sub(1, #prefix) == prefix then
            subject = R.Trim(subject:sub(#prefix + 1))
            break
        end
    end
    subject = R.Trim(subject:gsub("%s+to%s+.+$", "")
        :gsub("%s+by%s+[%+%-]?%d+%.?%d*$", "")
        :gsub("%s+[%+%-]?%d+%.?%d*$", ""))
    return subject
end

-- Polite setting writes such as "can you set target width to 300" stay
-- actionable.  These exploratory verbs, on the other hand, are commonly
-- capability questions and must not fall through to an unrelated fuzzy match
-- when MSUF has no corresponding control.
function R.PotentialUnsupportedCapabilityCommand(text)
    local norm = R.Normalize(text)
    local command = norm:match("^can%s+you%s+(.+)$")
        or norm:match("^could%s+you%s+(.+)$")
        or norm:match("^would%s+you%s+(.+)$")
    if not command then return nil end
    command = command:gsub("^please%s+", "")
    -- "add" is an ordinary MSUF verb too: aura-list actions and numeric
    -- adjustments both use it (for example, "add Rejuvenation to ..." and
    -- "add 5 to target width").  Let those requests reach the typed action /
    -- setting routes instead of classifying them as unknown capabilities.
    if command:match("^add%s+")
        and (command:find("weather", 1, true)
            or command:find("radar", 1, true)
            or command:find("chess", 1, true))
    then
        return R.Trim(command)
    end
    if command:match("^create%s+")
        or command:match("^rotate%s+") or command:match("^play%s+")
        or command:match("^draw%s+") or command:match("^render%s+")
        or command:match("^generate%s+") or command:match("^browse%s+")
    then
        return R.Trim(command)
    end
    return nil
end

-- Treat arithmetic wording as a relative numeric adjustment. Without this
-- normalization, the generic value parser can read the leading number as an
-- absolute value ("add 5 to Target Width" becoming Width = 5).
function R.NormalizeNumericAddCommand(text)
    local command = R.Normalize(text)
    command = command:gsub("^can%s+you%s+", "")
        :gsub("^could%s+you%s+", "")
        :gsub("^would%s+you%s+", "")
        :gsub("^please%s+", "")
    local amount, subject = command:match("^add%s+([%+%-]?%d+%.?%d*)%s+to%s+(.+)$")
    subject = subject and R.Trim(subject:gsub("%s+please$", "")) or nil
    if not amount or not subject or subject == "" then return nil end
    return "increase " .. subject .. " by " .. amount
end

function R.ObviousUnsupportedCapabilityTopic(command)
    local norm = R.Normalize(command)
    if norm:find("weather", 1, true) or norm:find("radar", 1, true) then return "weather" end
    if norm:find("chess", 1, true) then return "chess" end
    if norm:find("3d", 1, true) and norm:find("rotate", 1, true) then return "rotation" end
    return nil
end

function R.VerifiedCapabilitySettingEntries(subject)
    subject = R.Normalize(subject)
    if subject == "" then return nil, nil end
    local exact = (R.ExactRegistrySettingLabelEntries and R.ExactRegistrySettingLabelEntries(subject, 8))
        or (R.CanonicalExplicitSearchEntries and R.CanonicalExplicitSearchEntries(subject))
        or (R.ExactRegistrySettingAliasEntries and R.ExactRegistrySettingAliasEntries(subject, 8))
    if exact and #exact > 0 then return exact, exact end

    local nearest = R.CompactRegistrySettingSearchEntries
        and R.CompactRegistrySettingSearchEntries(subject, 5) or nil
    if nearest and #nearest > 0 then
        local confident = #nearest == 1
            or (R.OpenEndedEntriesAreConfident and R.OpenEndedEntriesAreConfident(nearest))
        if confident then return nearest, nearest end
    end
    return nil, nearest
end

function R.UnsupportedCapabilityReply(command, nearest, topic)
    local lines
    if topic == "rotation" then
        lines = {
            "No - MSUF does not have a 3D frame-rotation control, so I kept everything unchanged.",
            "Closest MSUF options are moving or resizing the Player frame, changing its scale, or switching the Player portrait style.",
            "You can ask: move player frame | where is Player Frame Scale | change player portrait to 2D",
        }
    elseif topic == "weather" then
        lines = {
            "No - MSUF does not provide weather data or a radar widget, so I kept everything unchanged.",
            "MSUF can instead help with unit frames, auras, cast bars, class resources, profiles, and UI readability.",
            "You can ask: what can you do | open Player | find target buffs",
        }
    elseif topic == "chess" then
        lines = {
            "No - the in-game MSUF Assistant cannot play chess, and I kept everything unchanged.",
            "I am focused on MSUF settings and WoW UI setup.",
            "You can ask: what can you do | show me around MSUF | open Player",
        }
    else
        lines = {
            "I could not verify that as an MSUF capability, so I kept everything unchanged instead of claiming that I can do it.",
        }
        local visible = math.min(3, type(nearest) == "table" and #nearest or 0)
        if visible > 0 then
            lines[#lines + 1] = "These are the nearest real MSUF controls; pick one only if it matches what you meant:"
            for i = 1, visible do lines[#lines + 1] = R.RegistryLocationLine(i, nearest[i].item) end
            lines[#lines + 1] = "Or rephrase with the frame and exact result you want."
        else
            lines[#lines + 1] = "MSUF can help with unit frames, auras, cast bars, class resources, profiles, and UI readability."
            lines[#lines + 1] = "You can ask: what can you do | show me around MSUF | name the frame and result you want"
        end
    end
    local result = {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Explains an unsupported or unverified MSUF capability without changing settings.",
    }
    if type(nearest) == "table" and #nearest > 0 and R.RegistryLocationResultFollowups then
        result.searchResults = R.RegistryLocationResultFollowups(nearest, math.min(3, #nearest))
    end
    return result
end

-- Feature-existence questions ("does MSUF have a GCD bar?") are their own
-- family: they ask whether a capability exists at all, not to change it. They
-- used to fall through every specialist to the generic "here is what I can
-- point you at" list, which answers a different question than the one asked.
-- The lane is strictly read-only; it never writes a setting.
R.FEATURE_EXISTENCE_PATTERNS = {
    "^does%s+msuf%s+have%s+(.+)$", "^does%s+msuf%s+support%s+(.+)$",
    "^does%s+msuf%s+offer%s+(.+)$", "^does%s+msuf%s+include%s+(.+)$",
    "^does%s+msuf%s+come%s+with%s+(.+)$", "^does%s+msuf%s+do%s+(.+)$",
    "^does%s+msuf%s+provide%s+(.+)$", "^does%s+msuf%s+handle%s+(.+)$",
    "^does%s+this%s+addon%s+have%s+(.+)$", "^does%s+the%s+addon%s+have%s+(.+)$",
    "^does%s+it%s+have%s+(.+)$", "^does%s+it%s+support%s+(.+)$",
    "^do%s+you%s+have%s+(.+)$", "^do%s+you%s+support%s+(.+)$",
    "^has%s+msuf%s+got%s+(.+)$", "^has%s+msuf%s+(.+)$",
    "^is%s+there%s+(.+)$", "^are%s+there%s+(.+)$",
    "^msuf%s+have%s+(.+)$", "^any%s+(.+)$",
    "^can%s+msuf%s+(.+)$", "^is%s+msuf%s+able%s+to%s+(.+)$",
}

-- Things users genuinely ask for that MSUF is not: answering these with a
-- fuzzy setting list would be a false "yes". Keep this list to capabilities
-- that are unambiguously another addon's job — anything not listed falls
-- through to an honest "I could not find it" rather than a confident "no".
-- R.ContainsAny matches whole normalized phrases, so singular and plural have
-- to be listed separately ("nameplate" does not match "nameplates").
R.FEATURE_NOT_IN_MSUF = {
    { terms = { "damage meter", "damage meters", "dps meter", "dps meters", "damage metre",
                "recount", "details addon", "skada", "my dps", "dps number", "hps meter", "healing meter" },
      what = "a damage or healing meter", instead = "Details!, Recount, or Skada" },
    { terms = { "nameplate", "nameplates", "name plate", "name plates" },
      what = "nameplates", instead = "Plater or Blizzard's own nameplate options" },
    { terms = { "boss mod", "boss mods", "boss timer", "boss timers", "dbm", "bigwigs",
                "big wigs", "boss warning", "boss warnings", "encounter timer" },
      what = "boss timers or encounter warnings", instead = "DBM or BigWigs" },
    { terms = { "action bar", "action bars", "actionbar", "actionbars", "hotbar", "hotbars",
                "keybind", "keybinds", "keybinding", "keybindings" },
      what = "action bars or keybinds", instead = "Bartender, Dominos, or Blizzard's Edit Mode" },
    { terms = { "bag", "bags", "inventory", "bank addon", "bag addon" },
      what = "a bag or inventory replacement", instead = "Baganator or AdiBags" },
    { terms = { "quest tracker", "questie", "quest log", "objective tracker", "quest tracking" },
      what = "quest tracking", instead = "Questie or the Blizzard objective tracker" },
    { terms = { "auction", "auction house", "tsm", "trade skill master", "auctionator" },
      what = "auction house tooling", instead = "TradeSkillMaster or Auctionator" },
    { terms = { "transmog", "wardrobe" }, what = "transmog tools", instead = "a wardrobe addon" },
    { terms = { "chat frame", "chat frames", "chat window", "chat windows", "chat bubble", "chat bubbles" },
      what = "chat frame customisation", instead = "Prat or Chatter" },
    { terms = { "map addon", "world map", "minimap button bar", "coordinates", "gathering nodes" },
      what = "map replacement", instead = "a map addon such as Carbonite" },
    { terms = { "loot frame", "loot window", "roll frame", "loot addon" },
      what = "loot frame customisation", instead = "a dedicated loot addon" },
    { terms = { "combat log", "combat logging", "warcraftlogs", "warcraft logs", "log upload" },
      what = "combat logging or log upload", instead = "the WarcraftLogs uploader" },
    { terms = { "gear score", "gearscore", "inspect addon", "item level of others" },
      what = "gear inspection", instead = "an inspect addon" },
    { terms = { "voice chat", "discord" }, what = "voice chat", instead = "Discord itself" },
    { terms = { "auto sell", "auto repair", "vendor addon", "junk seller" },
      what = "vendoring or auto-repair automation", instead = "an inventory addon" },
    { terms = { "dungeon finder", "group finder", "lfg addon", "premade group" },
      what = "group finding", instead = "the Blizzard group finder or Premade Groups Filter" },
}

function R.FeatureExistenceQuestionSubject(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    norm = R.Trim((norm:gsub("%s*%?+%s*$", "")))
    if norm == "" then return nil end

    local subject
    for i = 1, #R.FEATURE_EXISTENCE_PATTERNS do
        subject = norm:match(R.FEATURE_EXISTENCE_PATTERNS[i])
        if subject then break end
    end
    if not subject then return nil end

    -- "any ..." is the one opener that is not inherently interrogative, so it
    -- only counts as an existence question when the addon is actually named.
    if norm:match("^any%s+") and not norm:find("msuf", 1, true) and not norm:find("addon", 1, true) then
        return nil
    end

    -- "can msuf ..." also fronts ordinary commands ("can msuf set player width
    -- to 300"); a request carrying an explicit value is a mutation, not an
    -- existence question, so leave it to the setting routes.
    if norm:match("^can%s+msuf%s+") and norm:match("%s+to%s+[%+%-]?%d") then return nil end

    subject = R.Trim(subject)
    -- Run the article/lead-in strip twice around the verb strip: "a way to hide
    -- the power bar" has to lose "a ", then "way to ", then "hide ", then "the "
    -- before "power bar" is left.
    local function stripLeadIns(value)
        return R.Trim((value:gsub("^an%s+", ""):gsub("^a%s+", "")
            :gsub("^the%s+", ""):gsub("^any%s+", ""):gsub("^some%s+", "")
            :gsub("^way%s+to%s+", ""):gsub("^option%s+to%s+", "")
            :gsub("^ability%s+to%s+", ""):gsub("^feature%s+to%s+", "")
            :gsub("^setting%s+for%s+", ""):gsub("^settings%s+for%s+", "")
            :gsub("^support%s+for%s+", ""):gsub("^options%s+for%s+", "")))
    end
    local VERB_LEAD_INS = {
        "show ", "hide ", "display ", "change ", "set ", "make ", "track ",
        "see ", "get ", "use ", "adjust ", "configure ", "customize ",
        "customise ", "control ", "move ", "resize ", "enable ", "disable ",
        "turn on ", "turn off ", "color ", "colour ", "do ",
    }
    -- Strip the "... in MSUF" tail before the verb, or "any move in msuf"
    -- loses "move" and is left asking about the literal words "in msuf".
    local function stripTails(value)
        return R.Trim((value:gsub("%s+in%s+msuf$", ""):gsub("%s+in%s+the%s+addon$", "")
            :gsub("%s+for%s+msuf$", ""):gsub("%s+in%s+this%s+addon$", "")
            :gsub("%s+at%s+all$", "")))
    end

    subject = stripTails(stripLeadIns(subject))
    -- Some real controls are named after the verb ("Show Spark", "Hide Right %
    -- Sign"), so the verb-stripped form cannot be the only candidate. Keep the
    -- unstripped subject as well and let the caller try both.
    local kept = subject
    for i = 1, #VERB_LEAD_INS do
        local verb = VERB_LEAD_INS[i]
        if subject:sub(1, #verb) == verb then
            subject = R.Trim(subject:sub(#verb + 1))
            break
        end
    end
    subject = stripTails(stripLeadIns(subject))
    if subject == "" then
        if kept == "" then return nil end
        return kept, nil
    end
    if kept == subject then return subject, nil end
    return subject, kept
end

-- Exported so the low-latency submit lanes can stand down: they run before
-- A.RouteInput and would otherwise read the digits inside a setting label
-- ("Texture Layer 3 Offset X") as a value to write.
-- Pending state is deliberately not consulted here; see
-- A.RouterIsNamedSettingLookup for why.
function A.RouterIsFeatureExistenceQuestion(text)
    return R.FeatureExistenceQuestionSubject(text) ~= nil
end

-- Exact label -> setting, built once. Three lanes ask "does this name a
-- control?" on every input; answering that with a linear scan over 6000+
-- settings each time made a routed question measurably slower, which is the
-- opposite of what a lookup guard should cost. The map is built lazily, only
-- once a question actually uses one of the lead-ins below, and is rebuilt if
-- the registry grows.
function R.EnsureSettingLabelIndex()
    local settings = R.EnsureCompleteSettingRegistry and R.EnsureCompleteSettingRegistry() or nil
    if type(settings) ~= "table" then return nil end
    local cached = R._settingLabelIndex
    if type(cached) == "table" and cached.settings == settings and cached.count == #settings then
        return cached.map
    end
    local map, unique = {}, {}
    for i = 1, #settings do
        local setting = settings[i]
        local label = setting and R.Normalize(setting.label or "") or ""
        if label ~= "" then
            -- First registration wins, matching the scan order it replaces.
            if map[label] == nil then map[label] = setting end
            -- A second claimant makes the label ambiguous. Built in the same
            -- pass because a writer may only act on a label exactly one setting
            -- owns, while the readers above are content with the first match.
            if unique[label] == nil then unique[label] = setting
            elseif unique[label] ~= setting then unique[label] = false end
        end
    end
    R._settingLabelIndex = { settings = settings, count = #settings, map = map, unique = unique }
    return map
end

-- Labels owned by exactly one setting. Same lazy build and cache as the map
-- above, so asking for it never costs a second pass.
function R.UniqueSettingLabelIndex()
    R.EnsureSettingLabelIndex()
    local cached = R._settingLabelIndex
    return type(cached) == "table" and cached.unique or nil
end

-- Alias -> setting, for the explain fallback only. The location lane
-- ("where is rounding strength") and the mutation lane ("set rounding strength
-- to 4") both resolve aliases, but the explain lane knew labels only, so
-- "what is rounding strength" / "explain corner rounding" dead-ended on wording
-- the rest of the Assistant understands -- every "what is"/"explain"/"describe"
-- form asked by alias did.
--
-- Deliberately a SEPARATE index from EnsureSettingLabelIndex: that one also
-- backs the guards deciding whether an input names a control exactly, and
-- widening those to aliases would change which requests topic lanes may claim.
-- Built once, same lazy contract, so the per-input cost stays O(1).
-- An alias claimed by more than one setting is dropped rather than guessed at.
local EMPTY_ALIAS_LIST = {}
function R.EnsureSettingAliasIndex()
    local settings = R.EnsureCompleteSettingRegistry and R.EnsureCompleteSettingRegistry() or nil
    if type(settings) ~= "table" then return nil end
    local cached = R._settingAliasIndex
    if type(cached) == "table" and cached.settings == settings and cached.count == #settings then
        return cached.map
    end
    local owner, conflict = {}, {}
    for i = 1, #settings do
        local setting = settings[i]
        local lists = { setting.exactAliases or EMPTY_ALIAS_LIST, setting.aliases or EMPTY_ALIAS_LIST }
        for l = 1, #lists do
            local list = lists[l]
            for j = 1, #list do
                local alias = R.Normalize(list[j] or "")
                if alias ~= "" then
                    if owner[alias] == nil then
                        owner[alias] = setting
                    elseif owner[alias] ~= setting then
                        conflict[alias] = true
                    end
                end
            end
        end
    end
    local map = {}
    for alias, setting in pairs(owner) do
        if not conflict[alias] then map[alias] = setting end
    end
    R._settingAliasIndex = { settings = settings, count = #settings, map = map }
    return map
end

-- Last-resort answer for a control the explain/location shortcuts cannot
-- format (a handful of settings carry a category but no page). Naming the
-- control and where it lives always beats a generic "here is what I can point
-- you at". Deliberately does not read the current value: some getters need a
-- live frame, and this exists precisely for the cases that fall through.
function R.NamedSettingDirectAnswer(label)
    local normalized = R.Normalize(label or "")
    local map = R.EnsureSettingLabelIndex()
    local setting = map and map[normalized] or nil
    if not setting then
        -- A real label always wins; only fall back to an unambiguous alias.
        local aliasMap = R.EnsureSettingAliasIndex()
        setting = aliasMap and aliasMap[normalized] or nil
    end
    if not setting then return nil end

    local name = tostring(setting.label or label)
    local lines = { name .. " explanation" }
    local category = tostring(setting.category or "")
    if category ~= "" then
        lines[#lines + 1] = name .. " is an MSUF setting under " .. category .. "."
    else
        lines[#lines + 1] = name .. " is an MSUF setting."
    end

    local kind = tostring(setting.kind or setting.valueType or "")
    if kind == "boolean" then
        lines[#lines + 1] = "It is an on/off switch. Examples: turn on " .. name .. "; turn off " .. name .. "."
    elseif kind == "number" then
        lines[#lines + 1] = "It takes a number. Example: set " .. name .. " to a value."
    else
        lines[#lines + 1] = "Examples: where is " .. name .. "; change " .. name .. "."
    end
    lines[#lines + 1] = "Ask me to open or change it and I will do that from here."

    return {
        text = table.concat(lines, "\n"),
        status = "info", result = "info",
        summary = "Explains a named MSUF control from the registry record.",
    }
end

-- Lead-ins a user puts in front of a control name when asking about it.
R.SETTING_QUESTION_LEAD_INS = {
    "what is the default for ", "what are the options for ",
    "i need help with ", "how do i change ", "why would i change ",
    "what page is ", "tell me about ", "can i change ", "help with ",
    "what does ", "what are ", "where is ", "show me ", "what is ",
    -- Contractions with the apostrophe already normalised away. Spelling them
    -- with one ("what's") can never match, because normalisation strips it
    -- before these are compared -- so "whats the target frame width" was read
    -- as a command and answered with "what value do you want me to use?".
    "whats ", "wheres ", "hows ", "whats the ", "wheres the ",
    "explain ", "find ",
    -- "how do i decide which border is shown first" names a control just as
    -- exactly as "how do i change" does; without the lead-in the question fell
    -- to a topic article about colour layers.
    "how do i decide ", "how do i pick ", "how do i choose ", "how do i control ",
}

-- Command counterpart to SETTING_QUESTION_LEAD_INS. Kept separate on purpose:
-- RouterNamedSettingLabel answers question shapes only, so a COMMAND that names
-- a control exactly ("turn on the target dispel overlay") is invisible to it and
-- topic lanes claimed the phrase instead.
-- Composed rather than enumerated: politeness, then verb, then article. The
-- cross-product is far too big to list by hand -- "can you disable X" was
-- missing while "can you turn off X" was present, so one phrasing of the same
-- request reached the control and the other got a readability article.
R.SETTING_COMMAND_POLITENESS = {
    "can you please ", "could you please ", "would you please ", "will you please ",
    "can you ", "could you ", "would you ", "will you ", "please ",
    "i want to ", "i would like to ", "id like to ", "i need to ", "help me ",
    "hey ", "ok ", "okay ", "now ", "just ", "go ahead and ",
}
R.SETTING_COMMAND_VERBS = {
    "turn on ", "turn off ", "switch on ", "switch off ", "toggle ",
    "enable ", "disable ", "activate ", "deactivate ",
    "show ", "hide ", "set ", "change ", "adjust ", "configure ", "update ",
    "make ", "put ", "raise ", "lower ", "increase ", "decrease ",
    -- Result-shaped verbs. A player describing what they want to end up with
    -- ("i want to see damage absorbs") names the control just as exactly as
    -- "turn on damage absorbs", and the guidance lanes were claiming those.
    "see ", "display ", "keep ", "stop ", "remove ", "round ",
    "give ", "add ", "mark ", "highlight ", "animate ", "anchor ", "move ", "draw ", "use ",
}
R.SETTING_COMMAND_ARTICLES = { "the ", "my ", "a ", "an ", "its " }

-- Does a COMMAND name one exact control? Uses the same O(1) label and alias
-- indexes as the question lane, so it costs a table lookup once the index
-- exists. Call it only where a lane is about to answer with generic help --
-- never on the general input path, where building the index would blow the
-- cold-path budgets.
function R.CommandNamedSettingLabel(text, force)
    local norm = R.Trim((R.Normalize(text):gsub("%s*%?+%s*$", "")))
    if norm == "" then return nil end
    local function StripOnce(text, list)
        for i = 1, #list do
            local lead = list[i]
            if text:sub(1, #lead) == lead then return R.Trim(text:sub(#lead + 1)), true end
        end
        return text, false
    end
    -- Politeness may repeat ("please can you ..."), the verb appears once, and
    -- an article may follow it.
    local subject, sawVerb = norm, false
    for _ = 1, 3 do
        local stripped, changed = StripOnce(subject, R.SETTING_COMMAND_POLITENESS)
        subject = stripped
        if not changed then break end
    end
    subject, sawVerb = StripOnce(subject, R.SETTING_COMMAND_VERBS)
    if not sawVerb then return nil end
    subject = StripOnce(subject, R.SETTING_COMMAND_ARTICLES)
    if not subject or subject == "" then return nil end
    -- Drop a trailing value clause so "set X to 20" and "turn on X" both reduce
    -- to the control's own name.
    subject = R.Trim((subject:gsub("%s+to%s+.+$", ""):gsub("^the%s+", ""):gsub("^my%s+", "")))
    if subject == "" then return nil end
    -- Consult the indexes only once something else has paid to build them.
    -- Submit's synchronous preflight has an 8ms budget and the label index
    -- costs ~47ms to build; the question-shaped lane above returns early for
    -- commands, so it never pays that itself. Every later pass runs warm, which
    -- is where this lane does its work.
    if type(R._settingLabelIndex) ~= "table" and not force then return nil end
    local map = R.EnsureSettingLabelIndex and R.EnsureSettingLabelIndex()
    local setting = map and map[subject] or nil
    if not setting and (force or type(R._settingAliasIndex) == "table") then
        -- Alias fallback only when that index is already warm. Forcing it here
        -- costs ~80ms, and Submit's synchronous preflight has an 8ms budget to
        -- keep; the label index above is the cheap one and covers the common
        -- case of a control named exactly.
        local aliasMap = R.EnsureSettingAliasIndex and R.EnsureSettingAliasIndex()
        setting = aliasMap and aliasMap[subject] or nil
    end
    local label = setting and tostring(setting.label or "") or ""
    return label ~= "" and label or nil
end

-- The subject of a command, with politeness, verb, article and trailing value
-- clause removed. Shared with R.CommandNamedSettingLabel above so the reader
-- and the writer can never disagree about what a sentence names.
function R.CommandSubjectPhrase(text)
    local norm = R.Trim((R.Normalize(text):gsub("%s*%?+%s*$", "")))
    if norm == "" then return nil end
    local function StripOnce(value, list)
        for i = 1, #list do
            local lead = list[i]
            if value:sub(1, #lead) == lead then return R.Trim(value:sub(#lead + 1)), true end
        end
        return value, false
    end
    local subject, sawVerb = norm, false
    for _ = 1, 3 do
        local stripped, changed = StripOnce(subject, R.SETTING_COMMAND_POLITENESS)
        subject = stripped
        if not changed then break end
    end
    subject, sawVerb = StripOnce(subject, R.SETTING_COMMAND_VERBS)
    if not sawVerb then return nil end
    subject = StripOnce(subject, R.SETTING_COMMAND_ARTICLES)
    if not subject or subject == "" then return nil end
    subject = R.Trim((subject:gsub("%s+to%s+.+$", ""):gsub("^the%s+", ""):gsub("^my%s+", "")))
    return subject ~= "" and subject or nil
end

-- A command that spells a control's visible label in full, for a control no
-- other setting shares a name with, names that control and nothing else. The
-- exact-alias pre-pass deliberately declines several types here (colours most
-- of all -- see the comment in ParseRegistryExactAliasShortcut), so a fully
-- named "set Pet Frame Color to red" reached the fuzzy candidate list and was
-- answered with "several MSUF controls fit that name" even though exactly one
-- carries that name.
--
-- Returns an executable plan, never a result: the caller hands it to the normal
-- execution boundary so confirmation, transactions and undo all still apply.
-- Only call this where a lane is about to give up -- it forces the label index,
-- which Submit's synchronous preflight has no budget for.
function R.ExactLabelSingleChange(text)
    local subject = R.CommandSubjectPhrase(text)
    if not subject then return nil end
    local unique = R.UniqueSettingLabelIndex and R.UniqueSettingLabelIndex()
    local setting = unique and unique[subject] or nil
    if type(setting) ~= "table" or type(setting.set) ~= "function" then return nil end
    -- The sentence may name a frame as well as the control ("turn on the
    -- dispel border for party frames"). The subject resolves to the shared
    -- control, because the scope word sits outside it, so swap in the scoped
    -- twin: same attribute, that scope's key.
    do
        local scope = type(R.UnitScopeFromText) == "function" and R.UnitScopeFromText(norm) or nil
        if type(scope) == "string" and scope ~= "" and tostring(setting.unit or "") == "global" then
            local attribute = tostring(setting.attribute or "")
            local wanted = { ["barScope." .. scope .. "."] = true }
            if scope == "party" then wanted["barScope.gf_party."] = true end
            if scope == "raid" then wanted["barScope.gf_raid."] = true end
            if attribute ~= "" and A.Registry and type(A.Registry.AllSettings) == "function" then
                local all = A.Registry:AllSettings()
                for i = 1, #all do
                    local candidate = all[i]
                    local key = tostring(candidate.key or "")
                    for prefix in pairs(wanted) do
                        if key:sub(1, #prefix) == prefix
                            and tostring(candidate.attribute or "") == attribute
                            and candidate.type == setting.type
                            and type(candidate.set) == "function"
                        then
                            setting = candidate
                            break
                        end
                    end
                    if setting == candidate then break end
                end
            end
        end
    end
    local parser = A.Parser or {}
    if type(parser.ValueForRegistrySetting) ~= "function" then return nil end
    local ok, value = pcall(parser.ValueForRegistrySetting, setting, R.Normalize(text), text)
    if not ok or value == nil then return nil end
    return {
        kind = "changes",
        changes = { { setting = setting, value = value } },
        label = tostring(setting.label or setting.key),
        summary = "Changes the control named exactly by its menu label.",
        raw = text,
        sourceText = text,
        exactSettingMutation = true,
    }
end

-- The exact control a question is about, if it names one. Exported so the
-- pending-search-result follow-up can tell "what is it" (a follow-up) from
-- "what is Mythic Raid Bottom Right Corner Custom Color" (a new request that
-- merely starts with the same two words).
function A.RouterNamedSettingLabel(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    norm = R.Trim((norm:gsub("%s*%?+%s*$", "")))

    -- Several lanes ask this about the same input, and the exact-label lookup
    -- scans the whole registry for each distinct subject. Memoize per input so
    -- one request costs one scan rather than one per lane.
    local cached = R._namedSettingLabelCache
    if type(cached) == "table" and cached.text == norm then
        return cached.label ~= false and cached.label or nil
    end

    local matched = false
    for i = 1, #R.SETTING_QUESTION_LEAD_INS do
        local lead = R.SETTING_QUESTION_LEAD_INS[i]
        if norm:sub(1, #lead) == lead then
            norm = R.Trim(norm:sub(#lead + 1))
            matched = true
            break
        end
    end
    -- Only phrasing that actually asks about a control is worth the scan. An
    -- ordinary command ("set player width to 300") never names a bare label,
    -- and paying a full registry scan for it on every input is wasteful.
    if not matched then
        R._namedSettingLabelCache = { text = R.Trim((R.Normalize(text):gsub("%s*%?+%s*$", ""))), label = false }
        return nil
    end

    local subject = R.Trim((norm:gsub("%s+set%s+to$", ""):gsub("%s+do$", "")
        :gsub("^the%s+", ""):gsub("^my%s+", "")))
    local key = R.Trim((R.Normalize(text):gsub("%s*%?+%s*$", "")))
    if subject == "" then
        R._namedSettingLabelCache = { text = key, label = false }
        return nil
    end

    local map = R.EnsureSettingLabelIndex()
    local setting = map and map[subject] or nil
    -- "What page is X on" wraps the label in a trailing preposition. Try the
    -- literal subject first so labels that genuinely end in "on" ("Dispel
    -- Overlay on Current Health") still resolve, then retry without the tail.
    if not setting and map then
        local trimmed = subject:match("^(.-)%s+on$") or subject:match("^(.-)%s+at$")
        if trimmed and trimmed ~= "" then setting = map[trimmed] end
    end
    -- Players name a control by the alias the registry already publishes, not
    -- only by its visible label. "where is rounding strength" and "set rounding
    -- strength to 4" both resolve, so "what is rounding strength" dead-ending
    -- was an inconsistency, not a missing control -- every explain/describe form
    -- asked by alias hit the generic catch-all. Labels still win outright, and
    -- EnsureSettingAliasIndex drops any alias claimed by two settings, so this
    -- can only resolve names that were already unambiguous. Still O(1).
    if not setting then
        local aliasMap = R.EnsureSettingAliasIndex()
        setting = aliasMap and aliasMap[subject] or nil
    end
    local label = setting and tostring(setting.label or "") or ""
    if label == "" then
        R._namedSettingLabelCache = { text = key, label = false }
        return nil
    end
    R._namedSettingLabelCache = { text = key, label = label }
    return label
end

-- True when the input is question-shaped *and* names an exact control, e.g.
-- "show me Mythic Raid Masque Enabled". Only the question lead-ins in
-- R.SETTING_QUESTION_LEAD_INS can produce a label here, so an ordinary command
-- ("set player width to 300") never matches. The immediate mutation lanes use
-- this to stand down: a label ending in "Enabled" otherwise read as the
-- instruction to enable it, and that write only surfaced after enough
-- conversation state had built up to push the request past the usual guards.
-- Deliberately does not consult pending state. A. RouteInput gates its own
-- lanes on that separately, and these predicates only ever make a *mutation*
-- lane stand down -- so exempting them while a confirmation was open reopened
-- the hole they exist to close: after enough conversation a pending state is
-- usually live, and "show me Mythic Raid Masque Enabled" went back to enabling
-- it. A pending confirmation is never permission to execute a question.
function A.RouterIsNamedSettingLookup(text)
    local label = A.RouterNamedSettingLabel(text)
    return label ~= nil and label ~= ""
end

function R.FeatureNotInMsufMatch(subject)
    local norm = R.Normalize(subject)
    if norm == "" then return nil end
    for i = 1, #R.FEATURE_NOT_IN_MSUF do
        local row = R.FEATURE_NOT_IN_MSUF[i]
        if R.ContainsAny(norm, row.terms) then return row end
    end
    return nil
end

function R.TryFeatureExistenceQuestion(text, Core)
    local subject, verbatimSubject = R.FeatureExistenceQuestionSubject(text)
    if not subject then return nil end

    -- A real control always outranks the out-of-scope list. MSUF does not do
    -- nameplates, but it does have "Boss Custom Aura 1 Include Nameplate Only";
    -- checking the registry first keeps that from being answered "no".
    local confirmed = R.VerifiedCapabilitySettingEntries(subject)
    if not confirmed and verbatimSubject then
        confirmed = R.VerifiedCapabilitySettingEntries(verbatimSubject)
        if confirmed then subject = verbatimSubject end
    end

    if not confirmed then
        local absent = R.FeatureNotInMsufMatch(subject)
        if absent then
            return {
                text = table.concat({
                    "No - MSUF does not do " .. absent.what .. ", so there is no setting for it.",
                    "MSUF covers unit frames, auras, cast bars, class resources, group frames, and profiles. For " .. absent.what .. " use " .. absent.instead .. ".",
                    "You can ask: what can you do | open Player | find auras",
                }, "\n"),
                status = "info", result = "info",
                summary = "Answers a feature-existence question with a verified no.",
            }
        end

        local topic = R.ObviousUnsupportedCapabilityTopic(subject)
        if topic then return R.UnsupportedCapabilityReply(subject, nil, topic) end
    end

    -- Yes path: prove it with the real control before claiming MSUF has it.
    if confirmed and A.RouterTryRegistrySettingLocationShortcut then
        local location = A.RouterTryRegistrySettingLocationShortcut("where is " .. subject, Core, confirmed)
        if location then
            location.text = "Yes - MSUF has that.\n" .. tostring(location.text or "")
                .. "\nI only looked it up; nothing changed. Tell me the value you want and I will set it."
            location.summary = "Answers a feature-existence question with a verified yes."
            return location
        end
    end

    -- Whole subsystems (cast bars, class resources, profiles) have no single
    -- "the" control, so a confident setting match is the wrong test for them.
    -- Reviewed topic guidance is the authoritative yes in that case.
    local K = A.Knowledge
    local guidance = K and type(K.TopicGuidance) == "function" and K.TopicGuidance(subject) or nil
    if guidance and (guidance.body or guidance.title) then
        local lines = { "Yes - MSUF covers that. " .. tostring(guidance.title or "") }
        if guidance.body then lines[#lines + 1] = tostring(guidance.body) end
        if guidance.examples then lines[#lines + 1] = "You can ask: " .. tostring(guidance.examples) end
        return {
            text = R.Trim(table.concat(lines, "\n")),
            status = "info", result = "info",
            summary = "Answers a feature-existence question from topic guidance.",
        }
    end

    -- Reviewed concept help covers real features that are explained rather
    -- than owned by one control (absorbs, ready check, raid markers). Pass the
    -- original wording: its "does msuf"/"can msuf" lead-in is what satisfies
    -- the concept-help intent gate.
    if K and type(K.DirectConceptHelp) == "function" then
        local concept = K.DirectConceptHelp(text)
        if concept and concept.text then
            concept.text = "Yes - MSUF covers that.\n" .. tostring(concept.text)
            concept.summary = "Answers a feature-existence question from concept help."
            return concept
        end
    end

    local _, nearest = R.VerifiedCapabilitySettingEntries(subject)
    local lines = { "I could not find an MSUF control for '" .. subject .. "', so I will not claim it exists." }
    local visible = math.min(3, type(nearest) == "table" and #nearest or 0)
    if visible > 0 then
        lines[#lines + 1] = "The closest real MSUF controls are:"
        for i = 1, visible do lines[#lines + 1] = R.RegistryLocationLine(i, nearest[i].item) end
        lines[#lines + 1] = "If none of those is it, name the frame and the result you want."
    else
        lines[#lines + 1] = "MSUF covers unit frames, auras, cast bars, class resources, group frames, and profiles."
        lines[#lines + 1] = "You can ask: what can you do | open Player | find auras"
    end
    local result = {
        text = table.concat(lines, "\n"),
        status = "info", result = "info",
        summary = "Answers a feature-existence question without inventing a capability.",
    }
    if visible > 0 and R.RegistryLocationResultFollowups then
        result.searchResults = R.RegistryLocationResultFollowups(nearest, visible)
    end
    return result
end

-- "Reset everything" and "hide everything" name a scope, not a control. MSUF
-- has several different wholesale resets with very different blast radii, so
-- guessing one is worse than explaining them: "start over" used to land on the
-- Dispel Overlay control, and "hide everything" produced a broken reply. The
-- lane is read-only and always names the exact command that does the job.
R.GLOBAL_SCOPE_TERMS = {
    "everything", "all my settings", "all settings", "all of msuf",
    "all of my settings", "the whole addon", "whole addon", "entire addon",
    "whole ui", "entire ui", "the whole thing", "all my options",
}
R.GLOBAL_RESET_VERBS = {
    "reset", "wipe", "clear", "restore", "default", "defaults",
    "start over", "start fresh", "factory", "nuke", "erase",
}
-- Wording that already resolves to one exact action must not be intercepted.
R.EXACT_RESET_PHRASES = {
    "factory reset all", "reset active profile", "reset current page",
    "reset current menu page", "reset all unit positions", "reset unit options",
    "reset all aura overrides", "reset all aura style overrides",
    "reset aura scope overrides", "reset menu session changes",
    "reset frame positions", "reset my profile", "reset profile",
}

function R.TryGlobalScopeGuidance(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    norm = R.Trim((norm:gsub("%s*%?+%s*$", "")))

    for i = 1, #R.EXACT_RESET_PHRASES do
        if R.HasNormalizedPhrase(norm, R.EXACT_RESET_PHRASES[i]) then return nil end
    end

    local globalScope = R.ContainsAny(norm, R.GLOBAL_SCOPE_TERMS)
    local resetVerb = R.ContainsAny(norm, R.GLOBAL_RESET_VERBS)
    -- "reset msuf" and "start over" carry the scope in the verb phrase itself.
    local impliedGlobalReset = norm:match("^reset%s+msuf$") ~= nil
        or norm:match("^start%s+over$") ~= nil
        or norm:match("^start%s+fresh$") ~= nil
        or norm:match("^restore%s+defaults?$") ~= nil
        or norm:match("^wipe%s+my%s+settings$") ~= nil

    if (resetVerb and globalScope) or impliedGlobalReset then
        return {
            text = table.concat({
                "Factory reset and recovery help",
                "'Everything' can mean two very different resets in MSUF, so I did not run either one yet.",
                "1. Reset Active Profile - clears the profile you are using now and leaves your other profiles alone. Say: reset active profile",
                "2. Factory Reset All - clears every profile and every global option, back to a fresh install. Say: factory reset all",
                "Both ask for confirmation before anything changes, and neither can be undone with 'undo'. If you might want the current setup back, save it first: say open profiles and use Export there.",
                "If you only meant one area, name it instead - for example: reset all unit positions, reset all aura overrides, or reset cast bar colors.",
            }, "\n"),
            status = "info", result = "info",
            summary = "Explains the wholesale reset options instead of guessing one.",
        }
    end

    local hideVerb = R.ContainsAny(norm, { "hide", "turn off", "disable", "remove" })
    if hideVerb and globalScope then
        return {
            text = table.concat({
                "'Everything' covers several separate MSUF switches, so I did not turn anything off yet. Tell me which one you meant:",
                "1. Every unit frame (Player, Target, Focus, Pet, and so on). Say: hide all frames",
                "2. Every group frame (Party, Raid, Mythic Raid). Say: turn off party frames and turn off raid frames",
                "3. Only the auras. Say: hide all player buffs, or hide all target debuffs",
                "4. Only the text on the frames. Say: hide player name text, or hide player hp text",
                "If you want MSUF out of the way completely, disabling the addon in the AddOns list is cleaner than switching off every option.",
            }, "\n"),
            status = "info", result = "info",
            summary = "Explains what a wholesale hide would cover instead of guessing.",
        }
    end

    return nil
end

-- "The bar color for NPCs should be class color" names a qualifier (NPCs) that
-- the generic bar-colour controls do not cover. The colour lanes matched
-- "bar color ... class color", dropped the qualifier, and wrote Party Bar Color
-- Mode instead -- a silent wrong write. MSUF owns this as one global switch,
-- General Npc Class Color Bar, so route the request there and say plainly that
-- it is not per-frame.
R.NPC_BAR_CLASS_COLOR_OFF_TERMS = {
    "should not", "shouldnt", "should nt", "no longer", "stop", "disable",
    "turn off", "dont", "do not", "never", "remove", "off",
}

-- Exported so the low-latency mutation lane stands down: it runs before
-- A.RouteInput and is the lane that wrote Party Bar Color Mode.
-- Pending state is deliberately not consulted here; see
-- A.RouterIsNamedSettingLookup for why.
function A.RouterIsNpcQualifiedBarColorRequest(text)
    return R.NpcQualifiedBarColorSubject(text) == true
end

function R.NpcQualifiedBarColorSubject(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    if not R.ContainsAny(norm, { "npc", "npcs" }) then return false end
    -- Wording that already names the control resolves correctly on its own.
    if R.HasNormalizedPhrase(norm, "npc class color bar") then return false end

    local barIntent = R.ContainsAny(norm, {
        "bar color", "bar colors", "bars color", "health bar", "health bars",
        "hp bar", "hp bars", "healthbar", "bar colour", "bar colours",
    })
    local classIntent = R.ContainsAny(norm, {
        "class color", "class colors", "class colour", "class colours",
        "class colored", "class coloured", "classcolor", "class colouring",
        "class coloring",
    })
    return (barIntent and classIntent) == true
end

function R.TryNpcQualifiedBarColorRequest(text)
    if not R.NpcQualifiedBarColorSubject(text) then return nil end
    local norm = R.Normalize(text)

    local setting = A.Registry and type(A.Registry.GetSetting) == "function"
        and A.Registry:GetSetting("general.npcClassColorBar") or nil
    if not setting then return nil end

    local enable = not R.ContainsAny(norm, R.NPC_BAR_CLASS_COLOR_OFF_TERMS)
    local result = A.ExecutePlan({
        kind = "changes",
        changes = { { setting = setting, value = enable } },
        label = "NPC class-coloured bars",
        summary = "Routes an NPC-qualified bar colour request to the NPC control.",
    })
    if type(result) == "table" then
        local note = "NPC bar colouring is one global MSUF switch, so it covers every frame that can show an NPC rather than a single frame."
        result.text = tostring(result.text or "") .. "\n" .. note
    end
    return result
end

-- "No, I meant target" corrects the scope of the change that just happened. It
-- is not a new standalone request and not an undo: the user still wants the
-- same thing done, just somewhere else. Without this the correction fell
-- through to a generic "I did not catch which MSUF option you meant", leaving
-- the wrong change applied.
R.CORRECTION_RETARGET_PATTERNS = {
    "^no%s*,?%s*i%s+meant%s+(.+)$", "^no%s*,?%s*i%s+mean%s+(.+)$",
    "^sorry%s*,?%s*i%s+meant%s+(.+)$", "^sorry%s*,?%s*i%s+mean%s+(.+)$",
    "^i%s+meant%s+(.+)$", "^i%s+mean%s+(.+)$",
    "^no%s*,?%s*for%s+(.+)$", "^not%s+that%s*,?%s*i%s+meant%s+(.+)$",
    "^no%s+not%s+that%s*,?%s*(.+)$",
}

-- Scope words that a correction can replace inside the previous request.
R.CORRECTION_SCOPE_TOKENS = {
    "target of target", "focus target", "mythic raid", "npcs", "npc",
    "player", "target", "focus", "pet", "boss", "party", "raid",
}

function R.CorrectionRetargetSubject(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    norm = R.Trim((norm:gsub("%s*%?+%s*$", "")))
    for i = 1, #R.CORRECTION_RETARGET_PATTERNS do
        local subject = norm:match(R.CORRECTION_RETARGET_PATTERNS[i])
        if subject then
            subject = R.Trim((subject:gsub("^for%s+", ""):gsub("^the%s+", "")))
            if subject ~= "" then return subject end
        end
    end
    return nil
end

function R.LastSubmittedUserRequest(exclude)
    local adb = type(A.EnsureDB) == "function" and A.EnsureDB() or nil
    local history = type(adb) == "table" and adb.history or nil
    if type(history) ~= "table" then return nil end
    exclude = R.Normalize(exclude or "")
    for i = #history, 1, -1 do
        local item = history[i]
        if type(item) == "table" and tostring(item.role or "") == "user" then
            local candidate = R.Trim(tostring(item.text or ""))
            if candidate ~= "" and R.Normalize(candidate) ~= exclude then return candidate end
        end
    end
    return nil
end

function R.TryRetargetCorrection(text, coreHandler)
    if R._correctionRetargetActive then return nil end
    local subject = R.CorrectionRetargetSubject(text)
    if not subject then return nil end

    local previous = R.LastSubmittedUserRequest(text)
    if not previous then return nil end

    -- A correction that carries its own verb is a complete replacement
    -- request; otherwise it only names the scope, so graft it onto what was
    -- asked before.
    local corrected
    if R.ContainsAny(subject, R.COMMAND_TERMS) then
        corrected = subject
    else
        local previousNorm = R.Normalize(previous)
        for i = 1, #R.CORRECTION_SCOPE_TOKENS do
            local token = R.CORRECTION_SCOPE_TOKENS[i]
            if R.HasNormalizedPhrase(previousNorm, token) then
                corrected = (previousNorm:gsub("%f[%w]" .. token .. "%f[%W]", subject, 1))
                break
            end
        end
        if not corrected then corrected = previousNorm .. " for " .. subject end
    end
    corrected = R.Trim(corrected or "")
    if corrected == "" or R.Normalize(corrected) == R.Normalize(previous) then return nil end

    local undone = type(A.UndoLast) == "function" and A.UndoLast() == true

    R._correctionRetargetActive = true
    local result = A.HandleInput(corrected, { skipTurnSerialAdvance = true })
    R._correctionRetargetActive = nil

    if type(result) == "table" then
        local prefix = undone
            and "Got it - I reverted the previous change and used what you meant instead."
            or "Got it - I used what you meant instead."
        result.text = prefix .. "\n" .. tostring(result.text or "")
        result.summary = "Re-applies the previous request against the corrected subject."
    end
    return result
end

-- Auras3 owns real Buff/Debuff Full-Frame Effects.  Keep them distinct from
-- UnitFrame Dispel Overlay: they have different triggers, saved owners and
-- render paths even though players can describe both as an aura overlay.
R.FULL_FRAME_EFFECT_SHAPE_TERMS = {
    "full frame", "full-frame", "fullframe", "whole frame", "entire frame",
    "frame wide", "frame-wide", "framewide", "full bar", "across the frame",
    "vollbild", "ganzer rahmen", "gesamter rahmen",
}
R.FULL_FRAME_EFFECT_KIND_TERMS = {
    "effect", "effects", "overlay", "overlays", "glow", "glows",
    "tint", "tints", "flash", "flashes", "border", "outline", "rand", "effekt",
}
R.FULL_FRAME_EFFECT_SOURCE_TERMS = {
    "aura", "auras", "buff", "buffs", "debuff", "debuffs", "dispel", "dispels",
}
R.FULL_FRAME_EFFECT_STYLE_TERMS = {
    { value = "namecolor", words = { "name overlay", "name color", "name colour" } },
    { value = "healthtint", words = { "health tint", "health bar tint", "health color", "health colour", "tint" } },
    { value = "border", words = { "border", "outline", "rand", "umrandung" } },
    { value = "glow", words = { "glow", "glowing", "leuchten" } },
    { value = "pulse", words = { "pulse", "pulsing", "pulsieren" } },
}

function R.FullFrameAuraEffectRequest(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    if not R.ContainsAny(norm, R.FULL_FRAME_EFFECT_SHAPE_TERMS) then return nil end
    if not R.ContainsAny(norm, R.FULL_FRAME_EFFECT_KIND_TERMS) then return nil end
    -- Without an aura/dispel word this is some other frame-wide request.
    if not R.ContainsAny(norm, R.FULL_FRAME_EFFECT_SOURCE_TERMS) then return nil end
    return norm
end

function R.FullFrameAuraEffectStyle(norm)
    for i = 1, #R.FULL_FRAME_EFFECT_STYLE_TERMS do
        local spec = R.FULL_FRAME_EFFECT_STYLE_TERMS[i]
        if R.ContainsAny(norm, spec.words) then return spec.value end
    end
    return nil
end

function R.FullFrameAuraEffectSetting(scope, lane)
    local key = "auras3." .. tostring(scope or "") .. "." .. tostring(lane or "") .. ".frameEffectType"
    return A.Registry and type(A.Registry.GetSetting) == "function" and A.Registry:GetSetting(key) or nil
end

function R.FullFrameAuraEffectClarification(scopeLabel, laneLabel, reason)
    local subject = tostring(scopeLabel or "that frame")
    if laneLabel then subject = subject .. " " .. laneLabel end
    return {
        text = tostring(reason or ("Which " .. subject .. " Full-Frame Effect do you mean?"))
            .. "\nChoose Buffs or Debuffs, then choose Border, Glow, Pulse, Health Tint, or Name Overlay."
            .. " This is under " .. subject:gsub(" Buff$", ""):gsub(" Debuff$", "")
            .. " > Auras > " .. tostring(laneLabel and (laneLabel .. "s") or "Buffs/Debuffs")
            .. " > Style > Full-Frame Effect. UnitFrame Dispel Overlay is a separate feature. I kept MSUF unchanged.",
        status = "ambiguous",
        result = "ambiguous",
        summary = "Clarifies the Aura lane and Full-Frame effect style before changing anything.",
    }
end

function R.TryFullFrameAuraEffectRequest(text)
    local norm = R.FullFrameAuraEffectRequest(text)
    if not norm then return nil end

    -- Refusals and scoped exclusions are handled by the shared fail-closed
    -- lanes below this specialist. Never let their negative words become an
    -- Aura mutation merely because "off" also looks like a setting value.
    if R.IsExplicitMutationRefusal and R.IsExplicitMutationRefusal(text) then return nil end
    if R.ContainsAny(norm, {
        "except", "except for", "but not", "other than", "excluding",
        "ausser", "ausser fuer", "aber nicht",
    }) then return nil end

    -- Explicit Dispel Overlay wording belongs to the existing UnitFrame owner.
    if R.ContainsAny(norm, { "dispel overlay", "unitframe dispel", "unit frame dispel" }) then return nil end
    local hasAuraLaneWord = R.ContainsAny(norm, { "buff", "buffs", "debuff", "debuffs", "aura", "auras" })
    if R.ContainsAny(norm, { "dispel", "dispels" }) and not hasAuraLaneWord then return nil end

    local scope, scopeLabel
    if R.UnitScopeFromText then scope, scopeLabel = R.UnitScopeFromText(norm) end
    if not scope and R.ContainsAny(norm, { "shared", "global", "all unit auras" }) then
        scope, scopeLabel = "shared", "Shared"
    end
    local lane, laneLabel
    if R.AuraLaneFromText then lane, laneLabel = R.AuraLaneFromText(norm) end
    local disable = R.ContainsAny(norm, {
        "turn off", "off", "disable", "remove", "hide", "no", "without",
        "stop", "get rid of", "kill", "dont", "do not", "ausschalten", "deaktivieren", "entfernen",
    })
    local enable = R.ContainsAny(norm, {
        "turn on", "enable", "show", "use", "apply", "einschalten", "aktivieren", "anzeigen",
    })
    local style = R.FullFrameAuraEffectStyle(norm)
    local intentNorm = norm:gsub("^please%s+", ""):gsub("^bitte%s+", "")
    local readOnlyRequest = (R.LooksLikeKnowledgeQuestionPrefix and R.LooksLikeKnowledgeQuestionPrefix(intentNorm))
        or intentNorm:match("^why%s+") or intentNorm:match("^what%s+") or intentNorm:match("^where%s+")
        or intentNorm:match("^how%s+") or intentNorm:match("^is%s+") or intentNorm:match("^are%s+")
        or intentNorm:match("^does%s+") or intentNorm:match("^do%s+i%s+")
        or intentNorm:match("^can%s+i%s+") or intentNorm:match("^could%s+i%s+") or intentNorm:match("^should%s+i%s+")
        or intentNorm:match("^if%s+") or intentNorm:match("^would%s+it%s+") or intentNorm:match("^will%s+it%s+")
        or intentNorm:match("^warum%s+") or intentNorm:match("^was%s+") or intentNorm:match("^wo%s+")
        or intentNorm:match("^wie%s+") or intentNorm:match("^ist%s+") or intentNorm:match("^sind%s+")
        or intentNorm:match("^show%s+me%s+") or intentNorm:match("^tell%s+me%s+")
        or intentNorm:match("^zeige%s+mir%s+")
    local mutation = not readOnlyRequest and (disable or enable or R.StartsWithMutationCommand(norm))

    if not mutation then
        -- A visual question can carry the exact control name. Prefer the
        -- compiled live owner/color explanation over the generic glossary.
        local live = R.TryLiveUnitColorExplanation and R.TryLiveUnitColorExplanation(text)
        if live then return live end
        return {
            text = "MSUF has separate Buff and Debuff Full-Frame Effects: Border, Glow, Pulse, Health Tint, or Name Overlay."
                .. " They are Aura lane effects, not UnitFrame Dispel Overlay. The exact native AuraSlot match can be opaque,"
                .. " but I can identify the configured owner, color, thickness, and trigger without changing anything."
                .. " Open a Unit Frame > Auras > Buffs or Debuffs > Style > Full-Frame Effect.",
            status = "info",
            summary = "Explains Auras3 Full-Frame Effect ownership.",
        }
    end
    if not scope then
        return R.FullFrameAuraEffectClarification(nil, laneLabel,
            "Which Unit Frame should I change: Player, Target, Focus, or Boss?")
    end
    if scope ~= "shared" and scope ~= "player" and scope ~= "target"
        and scope ~= "focus" and scope ~= "boss"
    then
        return R.FullFrameAuraEffectClarification(nil, laneLabel,
            "Aura Full-Frame Effects are available for Player, Target, Focus, and Boss, not "
                .. tostring(scopeLabel or scope) .. ".")
    end

    local changes = {}
    if disable and not lane and R.ContainsAny(norm, { "all", "both" }) then
        local buffSetting = R.FullFrameAuraEffectSetting(scope, "buff")
        local debuffSetting = R.FullFrameAuraEffectSetting(scope, "debuff")
        if not buffSetting or not debuffSetting then return nil end
        changes[1] = { setting = buffSetting, value = "none" }
        changes[2] = { setting = debuffSetting, value = "none" }
    elseif not lane then
        local active = {}
        if disable then
            for _, kind in ipairs({ "buff", "debuff" }) do
                local setting = R.FullFrameAuraEffectSetting(scope, kind)
                local ok, value = false, nil
                if setting and type(setting.get) == "function" then ok, value = pcall(setting.get) end
                if setting and tostring(value or "none") ~= "none" then active[#active + 1] = setting end
            end
        end
        if #active == 1 then
            changes[1] = { setting = active[1], value = "none" }
        else
            return R.FullFrameAuraEffectClarification(scopeLabel, nil,
                enable and ("Choose the " .. tostring(scopeLabel) .. " Buff or Debuff lane and an effect style before I turn it on.")
                    or ("Choose the " .. tostring(scopeLabel) .. " Buff or Debuff Full-Frame Effect."))
        end
    else
        local setting = R.FullFrameAuraEffectSetting(scope, lane)
        if not setting then return nil end
        if disable then style = "none" end
        if not style then
            return R.FullFrameAuraEffectClarification(scopeLabel, laneLabel,
                "Which " .. tostring(scopeLabel) .. " " .. tostring(laneLabel) .. " Full-Frame style should I use?")
        end
        changes[1] = { setting = setting, value = style }
    end

    local result = A.ExecutePlan({
        kind = "changes",
        changes = changes,
        label = #changes == 2 and (tostring(scopeLabel) .. " Buff and Debuff Full-Frame Effects")
            or tostring(changes[1] and changes[1].setting and changes[1].setting.label or "Aura Full-Frame Effect"),
        summary = "Changes the Auras3 Buff/Debuff Full-Frame effect without touching UnitFrame Dispel Overlay.",
    })
    if type(result) == "table" then
        result.text = tostring(result.text or "")
            .. "\nThis changes Auras > " .. tostring(laneLabel and (laneLabel .. "s") or "Buffs and Debuffs")
            .. " > Style > Full-Frame Effect. UnitFrame Dispel Overlay remains separate."
    end
    return result
end

function R.IsSemanticAuraFilterNegation(text)
    local norm = R.Normalize(text)
    if not R.ContainsAny(norm, { "aura", "auras", "buff", "buffs", "debuff", "debuffs" }) then return false end
    -- These negative words describe which Aura entries should be filtered;
    -- they are not a refusal to perform the surrounding configuration change.
    return R.ContainsAny(norm, {
        "no timer", "without timer", "no duration", "without duration",
        "never expires", "not timed", "not mine", "not cast by me",
        "cast by others", "not dispellable", "not dispelable",
    })
end

function R.ExplicitMutationRefusalAction(text)
    local norm = R.Normalize(text)
    norm = norm:gsub("^please%s+", "")
    norm = norm:gsub("^bitte%s+", "")
    norm = norm:gsub("^nein%s+", "")
    if norm == "do not" or norm == "dont" or norm == "don t"
        or norm == "not" or norm == "never" or norm == "nicht"
    then
        -- A bare refusal has no useful action label, but it is still an
        -- explicit cancellation. `false` distinguishes it from nil while
        -- keeping the response generic and fully English.
        return false
    end
    local action = norm:match("^can%s+you%s+please%s+not%s+(.+)$")
        or norm:match("^could%s+you%s+please%s+not%s+(.+)$")
        or norm:match("^would%s+you%s+please%s+not%s+(.+)$")
        or norm:match("^can%s+you%s+not%s+(.+)$")
        or norm:match("^could%s+you%s+not%s+(.+)$")
        or norm:match("^would%s+you%s+not%s+(.+)$")
        or norm:match("^i%s+do%s+not%s+want%s+to%s+(.+)$")
        or norm:match("^i%s+don%s+t%s+want%s+to%s+(.+)$")
        or norm:match("^i%s+dont%s+want%s+to%s+(.+)$")
        or norm:match("^do%s+not%s+want%s+to%s+(.+)$")
        or norm:match("^don%s+t%s+want%s+to%s+(.+)$")
        or norm:match("^dont%s+want%s+to%s+(.+)$")
        or norm:match("^do%s+not%s+(.+)$")
        or norm:match("^don%s+t%s+(.+)$")
        or norm:match("^dont%s+(.+)$")
        or norm:match("^no%s+(.+)$")
        or norm:match("^never%s+(.+)$")
        or norm:match("^not%s+(.+)$")
        or norm:match("^nicht%s+(.+)$")
    if not action then
        -- German refusals commonly place the negation after the action
        -- ("mach das nicht").  Fold that form into the same fail-closed
        -- path as English prefix negation before any substring-based apply,
        -- fix, undo, or redo matcher can see it.
        action = (norm == "mach das nicht" and "mach das")
            or (norm == "mach es nicht" and "mach es")
            or norm:match("^mach%s+das%s+nicht%s+(.+)$")
            or norm:match("^mach%s+es%s+nicht%s+(.+)$")
    end
    if not action or action == "" then return nil end
    if R.IsSemanticAuraFilterNegation(norm) and action:match("^show%s+") then
        -- "Do not show buffs with no timer" describes the entries to filter
        -- and therefore means Hide Permanent.  "Do not hide ..." and
        -- "never hide ..." are explicit refusals, however; allowing the broad
        -- no-duration exemption to swallow those phrases would perform the
        -- exact mutation the user asked us not to make.
        return nil
    end
    if type(R.LooksLikeNameShorteningDotsRequest) == "function"
        and R.LooksLikeNameShorteningDotsRequest(norm)
    then
        -- "Do not show/hide the dots" has two opposite readings for name
        -- shortening. Let the dedicated semantic parser show its choices.
        return nil
    end
    local followupMutation = action:match("^do%s+")
        or action:match("^fix%s*")
        or action:match("^repair%s*")
        or action:match("^run%s*")
        or action:match("^confirm%s*")
        or action:match("^undo%s*")
        or action:match("^redo%s*")
        or action:match("^revert%s*")
        or action:match("^reapply%s*")
        or action:match("^continue%s*")
        or action:match("^proceed%s*")
        or action:match("^mach%s*")
        or action:match("^machen%s*")
        or action:match("^anwenden%s*")
        or action:match("^uebernehmen%s*")
        or action:match("^bestaetigen%s*")
        or action:match("^reparieren%s*")
        or action:match("^beheben%s*")
        or action:match("^ausfuehren%s*")
        or action:match("^fortfahren%s*")
        or action:match("^rueckgaengig%s*")
        or action:match("^wiederholen%s*")
        or action:match("^erneut%s+anwenden%s*")
    if R.StartsWithMutationCommand(action)
        or followupMutation
        or action:match("^position%s+")
        or action:match("^reposition%s+")
        or action:match("^turn%s+on%s+")
        or action:match("^turn%s+off%s+")
    then
        return R.Trim(action)
    end
    return nil
end

function R.HasContradictoryMutationConsent(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    local explicitOppositeClause = norm:match("^.-%s+but%s+do%s+not%s+(.+)$")
        or norm:match("^.-%s+but%s+dont%s+(.+)$")
        or norm:match("^.-%s+but%s+don%s+t%s+(.+)$")
    if explicitOppositeClause and R.StartsWithMutationCommand(explicitOppositeClause) then
        -- "Show power text but don't show the power bar" contains two
        -- explicit, differently scoped commands. It is not a withdrawal of
        -- consent for the first clause; the compound parser owns it.
        return false
    end
    if R.IsSemanticAuraFilterNegation(norm)
        and R.ContainsAny(norm, { "do not show", "dont show", "don t show" })
    then
        -- The semantic clause can follow an explicit filter lead, as in
        -- "filter player buffs; do not show buffs with no timer".  It still
        -- describes the entries to filter rather than revoking the command.
        -- Keep "do not hide ..." outside this exemption: that is an actual
        -- refusal to enable Hide Permanent Auras.
        return false
    end
    if R.ContainsAny(norm, { "geht nicht", "funktioniert nicht", "does not work", "doesnt work", "not working" })
        and not R.ContainsAny(norm, { "yes", "yeah", "okay", "ok", "sure", "apply", "fix", "undo", "redo", "ja" })
    then
        return false
    end

    local padded = " " .. norm .. " "
    local strongNegative = padded:find(" do not ", 1, true)
        or padded:find(" dont ", 1, true)
        or padded:find(" don t ", 1, true)
        or padded:find(" never mind ", 1, true)
        or padded:find(" not now ", 1, true)
        or padded:find(" no wait ", 1, true)
        or padded:find(" wait no ", 1, true)
        or padded:find(" actually no ", 1, true)
        or padded:find(" actually not ", 1, true)
        or padded:find(" but no ", 1, true)
        or padded:find(" nein ", 1, true)
        or padded:find(" nicht ", 1, true)
        or norm:match("%s+no$")
        or norm:match("%s+not$")
        or norm:match("%s+dont$")
    if not strongNegative then return false end
    return R.ContainsAny(norm, R.MUTATION_TERMS)
        or R.ContainsAny(norm, {
            "yes", "yeah", "yep", "okay", "ok", "sure", "go ahead",
            "do it", "fix it", "repair it", "undo", "redo", "revert", "reapply",
            "ja", "mach das", "mach es", "rueckgaengig", "wiederholen",
        })
end

function R.IsExplicitMutationRefusal(text)
    if type(R.LooksLikeNameShorteningDotsRequest) == "function"
        and R.LooksLikeNameShorteningDotsRequest(text)
    then
        -- Negated dots/ellipsis wording has two valid readings. Keep both
        -- refusal detectors from replacing the dedicated clarification.
        return false
    end
    return R.ExplicitMutationRefusalAction(text) ~= nil
        or R.HasContradictoryMutationConsent(text)
end

local SCOPED_EXCLUSION_HEADS = {
    "player", "target", "target target", "target of target", "focus", "focus target",
    "pet", "boss", "party", "raid", "mythic raid", "arena",
}

function R.ScopedMutationExclusion(text)
    local norm = R.Normalize(text)
    if norm == "" or not R.StartsWithMutationCommand(norm) then return nil end
    if norm:find(" neither ", 1, true) and norm:find(" nor ", 1, true) then
        return { cancel = true }
    end

    local keep, excluded = norm:match("^(.-)%s+but%s+not%s+(.+)$")
    if not keep then keep, excluded = norm:match("^(.-)%s+except%s+(.+)$") end
    if not keep then keep, excluded = norm:match("^(.-)%s+not%s+(.+)$") end
    keep = R.Trim(keep or "")
    excluded = R.Trim(excluded or ""):gsub("^the%s+", "")
    if keep == "" or excluded == "" or not R.StartsWithMutationCommand(keep) then return nil end

    local excludedHasScope = false
    for i = 1, #SCOPED_EXCLUSION_HEADS do
        local scope = SCOPED_EXCLUSION_HEADS[i]
        if excluded == scope or excluded:sub(1, #scope + 1) == scope .. " " then
            excludedHasScope = true
            break
        end
    end
    if not excludedHasScope then return nil end
    return { keep = keep, excluded = excluded }
end

function R.ReviewedSemanticMutationKind(text)
    local norm = R.Normalize(text)
    local unitScope, anchorValue = norm:match(
        "^set%s+(.+)%s+name%s+anchor%s+to%s+(%S+)$")
    local reviewedUnitScopes = {
        player = true, target = true, focus = true, pet = true, boss = true,
        targettarget = true, focustarget = true,
        ["target of target"] = true, ["focus target"] = true,
    }
    local reviewedAnchorValues = { left = true, center = true, middle = true, right = true }
    if reviewedUnitScopes[unitScope] and reviewedAnchorValues[anchorValue] then
        return "unit-name-anchor"
    end

    local groupScope, spacingValue = norm:match(
        "^set%s+(.+)%s+aura%s+spacing%s+to%s+([%+%-]?%d+%.?%d*)$")
    local reviewedGroupScopes = {
        party = true, raid = true, ["mythic raid"] = true, mythicraid = true,
    }
    if reviewedGroupScopes[groupScope] and tonumber(spacingValue) ~= nil then
        return "group-aura-spacing"
    end
    return nil
end

function R.IsSubjectiveSafePlanningRequest(text)
    local norm = R.StripResponseLanguageDirective(text)
    if norm == "" then return false end
    -- Submit's low-latency mutation lane runs before RouteInput. Keep exact
    -- subjective planning requests out of that lane so words such as
    -- "important" cannot be mistaken for a concrete Aura filter token or a
    -- frame toggle before the Router can ask what signal the player means.
    local planningTerms = A.RouterSafePlanningTerms or {}
    local broadImportantAura = norm == "show important debuffs"
        or norm == "show important buffs"
    return broadImportantAura
        or R.ContainsAny(norm, planningTerms.vagueTarget or {})
        or (R.ContainsAny(norm, planningTerms.subjectiveAura or {})
            and R.ContainsAny(norm, planningTerms.aura or {}))
end

-- One exact, whole-phrase alias match carrying a value is not a fuzzy idea:
-- the player typed the control's visible name. Two lanes have to agree on that
-- or a request falls between them -- TryOpenEndedSettingIdea stands down here
-- expecting the exact-alias writer to take over, while the fail-closed guard
-- refuses the write because the FUZZY search still sees eight similarly named
-- controls. That gap answered "set the frame outline thickness to 2" (one
-- match: Global Bar Outline Thickness) with "I treated that as a read-only
-- question ... to change it, use a direct command with an explicit value".
-- Politeness that carries no control identity. "can you disable X" names X
-- exactly as much as "disable X" does, but fullPhrase matching sees the extra
-- words and refuses, so topic lanes kept claiming a request that named one
-- control outright.
local EXACT_ALIAS_WRAPPERS = {
    "can you please ", "could you please ", "would you please ",
    "can you ", "could you ", "would you ", "will you ", "please ",
    "i want you to ", "i want to ", "i would like to ", "id like to ",
    "i need you to ", "i need to ", "help me ", "lets ", "let us ",
    -- Conversational filler people actually type: "hey turn off show power",
    -- "just turn on portrait border use class color".
    "hey ", "hi ", "hello ", "yo ", "just ", "ok ", "okay ", "now ",
}

function R.ExactAliasSingleChange(text)
    local parser = A.Parser or {}
    if type(parser.ParseRegistryExactAliasShortcut) ~= "function" then return nil end
    local function Attempt(candidate)
        local ok, exact = pcall(parser.ParseRegistryExactAliasShortcut, R.Normalize(candidate), candidate,
            { minTokens = 3, fullPhrase = true })
        if ok and type(exact) == "table" and exact.kind == "changes"
            and type(exact.changes) == "table" and #exact.changes == 1
        then
            return exact
        end
        return nil
    end
    local direct = Attempt(text)
    if direct then return direct end
    -- Peel every leading wrapper, not just one: "hey can you turn off X" stacks
    -- filler in front of a perfectly ordinary command.
    local normalized = R.Normalize(text)
    -- The addon's own name is not part of any control's name, but it is how
    -- people address it: "set msuf druid bar color to red". As a stray token it
    -- broke whole-phrase alias matching while the identical sentence without it
    -- applied. Compare the final result against THIS original, not against the
    -- cleaned copy, or a text that only needed the name removed never retries.
    local cleaned = R.Trim((" " .. normalized .. " "):gsub("%smsuf%s", " "))
    local peeled, changed = cleaned, true
    while changed do
        changed = false
        for i = 1, #EXACT_ALIAS_WRAPPERS do
            local wrapper = EXACT_ALIAS_WRAPPERS[i]
            if peeled:sub(1, #wrapper) == wrapper then
                peeled = R.Trim(peeled:sub(#wrapper + 1))
                changed = true
                break
            end
        end
    end
    if peeled ~= "" and peeled ~= normalized then return Attempt(peeled) end
    return nil
end

-- People put the state last: "put Focus Target Power Bar Gradient off", "player
-- name off". The exact-alias parser only accepts the state in front ("turn off
-- X", "disable X") or joined by "to" ("set X to off"), so those trailing forms
-- fell through to a generic "I understand the area but not one control" reply
-- even though the label in the middle was exact.
--
-- This rewrites the sentence into the form the parser already understands and
-- returns it only when the rewrite really does name one control -- so the
-- caller can hand the canonical text to the ordinary command path and keep
-- every existing guard, rather than executing anything from here.
local TRAILING_STATE_WORDS = {
    ["on"] = "on", ["off"] = "off",
    ["enabled"] = "on", ["disabled"] = "off",
}

-- `skipVerify` returns the rewrite on syntax alone. Two callers, two needs:
-- the topic-lane GUARD must stay conservative (only suppress an article when
-- the rewrite provably names one control), while the APPLY path can afford to
-- be generous because it hands the sentence to coreHandler, which has every
-- normal guard and simply declines what it cannot resolve. Verifying with
-- ExactAliasSingleChange in both places was throwing away valid rewrites:
-- "make focus frame on" -> "set focus frame to on" resolves through a
-- different lane, so the exact-alias check rejected a sentence that works.
function R.CanonicalTrailingStateCommand(text, skipVerify)
    local norm = R.Normalize(text)
    local body, tail = norm:match("^(.-)%s+(%a+)$")
    local state = tail and TRAILING_STATE_WORDS[tail] or nil
    if not state or not body or body == "" then return nil end
    -- Never re-wrap a sentence that already carries a connector. A leading
    -- verb is fine and gets stripped below: "turn X off" and "toggle X on" put
    -- the verb in front and the state at the end, which is ordinary English.
    if body:find("%s+to$") then return nil end
    body = body:gsub("^please%s+", ""):gsub("^can%s+you%s+", ""):gsub("^could%s+you%s+", "")
        :gsub("^i%s+want%s+", ""):gsub("^i%s+would%s+like%s+", ""):gsub("^id%s+like%s+", "")
        :gsub("^i%s+need%s+", "")
        :gsub("^hey%s+", ""):gsub("^just%s+", ""):gsub("^ok%s+", ""):gsub("^okay%s+", "")
        :gsub("^now%s+", ""):gsub("^put%s+", ""):gsub("^make%s+", ""):gsub("^switch%s+", "")
        :gsub("^turn%s+", ""):gsub("^toggle%s+", ""):gsub("^set%s+", "")
        :gsub("^the%s+", ""):gsub("^my%s+", "")
    if body == "" then return nil end
    local canonical = "set " .. body .. " to " .. state
    if skipVerify then return canonical end
    if R.ExactAliasSingleChange(canonical) then return canonical end
    return nil
end

-- Does the request already name exactly one control, in any of the forms the
-- Assistant can resolve? Topic-help lanes use this to stand down: an article
-- about raid healing is the wrong answer to "i want raid heal prediction off".
-- Both halves are only paid for once a topic lane is about to answer, which is
-- a small fraction of inputs -- never hoist this to the top of a lane.
-- "X to be 75" and "X set to 50" are how people phrase a value without the bare
-- "to" the exact-alias parser expects. Same treatment as the trailing-state
-- form: rewrite into the canonical sentence and only accept it if that really
-- names one control.
local VALUE_CONNECTOR_PATTERNS = {
    "^(.-)%s+to%s+be%s+(.+)$",
    "^(.-)%s+set%s+to%s+(.+)$",
    "^(.-)%s+should%s+be%s+(.+)$",
}

function R.CanonicalValueConnectorCommand(text, skipVerify)
    local norm = R.Normalize(text)
    for i = 1, #VALUE_CONNECTOR_PATTERNS do
        local body, value = norm:match(VALUE_CONNECTOR_PATTERNS[i])
        if body and value and body ~= "" and value ~= "" then
            body = body:gsub("^please%s+", ""):gsub("^can%s+you%s+", ""):gsub("^could%s+you%s+", "")
                :gsub("^i%s+want%s+", ""):gsub("^i%s+would%s+like%s+", ""):gsub("^id%s+like%s+", "")
                :gsub("^i%s+need%s+", ""):gsub("^hey%s+", ""):gsub("^just%s+", "")
                :gsub("^now%s+", ""):gsub("^the%s+", ""):gsub("^my%s+", "")
                :gsub("^set%s+", ""):gsub("^change%s+", ""):gsub("^make%s+", "")
            if body ~= "" then
                local canonical = "set " .. body .. " to " .. value
                if skipVerify then return canonical end
                if R.ExactAliasSingleChange(canonical) then return canonical end
            end
        end
    end
    return nil
end

-- Media requests routinely put the value first and the control last: "use the
-- flat texture for the absorb bar", "apply the shadow border on my frames".
-- The parser expects "set <control> to <value>", so the whole family reported
-- "what value do you want me to use?" after correctly finding the control.
local VALUE_BEFORE_CONTROL_VERBS = {
    "use", "using", "apply", "set", "switch", "pick", "choose", "change", "put", "give",
}
local VALUE_BEFORE_CONTROL_NOUNS = { "texture", "art", "style", "border", "font", "skin", "shape" }

function R.CanonicalValueBeforeControlCommand(text, skipVerify)
    local norm = R.Normalize(text)
    local verb, rest = norm:match("^(%a+)%s+(.+)$")
    if not verb or not rest then return nil end
    local verbAllowed = false
    for i = 1, #VALUE_BEFORE_CONTROL_VERBS do
        if verb == VALUE_BEFORE_CONTROL_VERBS[i] then verbAllowed = true break end
    end
    if not verbAllowed then return nil end
    rest = rest:gsub("^the%s+", ""):gsub("^a%s+", ""):gsub("^an%s+", "")
    for i = 1, #VALUE_BEFORE_CONTROL_NOUNS do
        local noun = VALUE_BEFORE_CONTROL_NOUNS[i]
        local value, control = rest:match("^(.-)%s+" .. noun .. "%s+for%s+(.+)$")
        if not value then value, control = rest:match("^(.-)%s+" .. noun .. "%s+on%s+(.+)$") end
        if value and control and value ~= "" and control ~= "" then
            control = R.Trim((control:gsub("^the%s+", ""):gsub("^my%s+", "")))
            for _, canonical in ipairs({
                "set " .. control .. " " .. noun .. " to " .. value,
                "set " .. control .. " to " .. value,
            }) do
                if skipVerify then return canonical end
                if R.ExactAliasSingleChange(canonical) then return canonical end
            end
        end
    end
    return nil
end

-- The third way people phrase a change carries no value at all, only a
-- direction: "make the frame border thicker", "make the maximum health loss
-- overlay more transparent", "move the absorb bar down a bit". There is no
-- number and no trailing on/off, so the two rewrites above cannot see it and a
-- topic article claimed the sentence.
R.COMPARATIVE_CHANGE_TAILS = {
    "more transparent", "less transparent", "more see through", "less see through",
    "more opaque", "less opaque", "more subtle", "less subtle", "more visible", "less visible",
    "more faded", "less faded", "more rounded", "less rounded",
    "thicker", "thinner", "bigger", "smaller", "taller", "shorter", "wider", "narrower",
    "stronger", "weaker", "rounder", "softer", "brighter", "dimmer", "fainter",
    "longer", "higher", "lower", "up", "down", "transparent", "opaque",
}
local COMPARATIVE_TRAILING_FILLER = {
    "%s+a%s+bit$", "%s+a%s+little$", "%s+a%s+lot$", "%s+slightly$", "%s+please$", "%s+now$",
}

-- A size is routinely stated as a dimension idiom rather than as an attribute
-- and a value: "make the shield bar 6 pixels tall", "make my target frame 200
-- pixels wide". The attribute noun the registry knows ("height", "width")
-- never appears, so the rewrites above see only a bare number attached to a
-- subject; the request either drew a pick-list of every per-unit Height or --
-- worse -- was claimed by a setup article, because "make ... healing ..." also
-- reads as a request for healer advice.
--
-- Each tail names exactly one attribute, so the rewrite is mechanical. This is
-- deliberately not an alias list: aliases would have to be spelled out per
-- control and per scope, and the registry keeps only the first
-- MAX_SETTING_ALIASES of them.
local DIMENSION_TAILS = {
    { word = "tall", attribute = "height" },
    { word = "high", attribute = "height" },
    { word = "wide", attribute = "width" },
    { word = "thick", attribute = "thickness" },
}
local DIMENSION_UNITS = { "%s*pixels", "%s*pixel", "%s*px", "" }

function R.CanonicalDimensionCommand(text, skipVerify)
    local norm = R.Normalize(text)
    if norm == "" or not norm:find("%d") then return nil end
    for i = 1, #COMPARATIVE_TRAILING_FILLER do
        norm = R.Trim((norm:gsub(COMPARATIVE_TRAILING_FILLER[i], "")))
    end
    for i = 1, #DIMENSION_TAILS do
        local spec = DIMENSION_TAILS[i]
        for j = 1, #DIMENSION_UNITS do
            local body, number = norm:match("^(.-)%s+([-+]?%d+%.?%d*)" .. DIMENSION_UNITS[j] .. "%s+" .. spec.word .. "$")
            if body and number and body ~= "" then
                body = body:gsub("^please%s+", ""):gsub("^can%s+you%s+", ""):gsub("^could%s+you%s+", "")
                    :gsub("^i%s+want%s+", ""):gsub("^i%s+would%s+like%s+", ""):gsub("^id%s+like%s+", "")
                    :gsub("^i%s+need%s+", ""):gsub("^hey%s+", ""):gsub("^just%s+", "")
                    :gsub("^now%s+", "")
                    :gsub("^make%s+", ""):gsub("^set%s+", ""):gsub("^change%s+", "")
                    :gsub("^the%s+", ""):gsub("^my%s+", "")
                body = R.Trim(body)
                if body ~= "" then
                    -- "make the absorb bar height 6 pixels tall" already names
                    -- the attribute; appending it again would never match.
                    local canonical = body:match("%f[%w]" .. spec.attribute .. "$")
                        and ("set " .. body .. " to " .. number)
                        or ("set " .. body .. " " .. spec.attribute .. " to " .. number)
                    if skipVerify then return canonical end
                    if R.ExactAliasSingleChange(canonical) then return canonical end
                end
            end
        end
    end
    return nil
end

-- The control name a comparative change is about, or nil. Shares the subject
-- peeling of R.CommandSubjectPhrase so the two can never disagree.
function R.ComparativeChangeSubject(text)
    local norm = R.Trim((R.Normalize(text):gsub("%s*%?+%s*$", "")))
    if norm == "" then return nil end
    for i = 1, #COMPARATIVE_TRAILING_FILLER do
        norm = R.Trim((norm:gsub(COMPARATIVE_TRAILING_FILLER[i], "")))
    end
    local body, matchedTail
    for i = 1, #R.COMPARATIVE_CHANGE_TAILS do
        local candidate = norm:match("^(.-)%s+" .. R.COMPARATIVE_CHANGE_TAILS[i] .. "$")
        if candidate and candidate ~= "" then
            body, matchedTail = candidate, R.COMPARATIVE_CHANGE_TAILS[i]
            break
        end
    end
    if not body then return nil end
    -- "make it thicker" names no control; the follow-up lane owns that.
    body = R.Trim((body:gsub("%s+it$", ""):gsub("%s+them$", "")))
    if body == "" then return nil end
    return R.CommandSubjectPhrase(body .. " to 1"), matchedTail
end

-- Does a comparative change name exactly one control? Only called from
-- RequestNamesOneControl, which already pays for an index build, so forcing
-- the label and alias maps here adds no cost to the general input path.
function R.ComparativeChangeNamesOneControl(text)
    local subject, tail = R.ComparativeChangeSubject(text)
    if not subject then return false end
    local map = R.EnsureSettingLabelIndex and R.EnsureSettingLabelIndex()
    local aliasMap = R.EnsureSettingAliasIndex and R.EnsureSettingAliasIndex()
    -- Controls are named both ways: "outline thickness" drops the comparative,
    -- while "corners rounder" IS the registered wording.
    for _, candidate in ipairs({ subject, tail and (subject .. " " .. tail) or subject }) do
        if map and map[candidate] then return true end
        if aliasMap and aliasMap[candidate] then return true end
    end
    return false
end

-- Among several fuzzy candidates, the one whose own label or alias IS the
-- request's subject is not a candidate -- it is the control. "change the bar
-- texture to flat" lists Absorb Bar Texture and Boss Bar Texture beside it,
-- because they all answer to those words, but only one is called that.
function R.EntriesNamedExactlyOnce(entries, text)
    if type(entries) ~= "table" or #entries < 2 then return nil end
    local subject = type(R.CommandSubjectPhrase) == "function" and R.CommandSubjectPhrase(text) or nil
    if not subject or subject == "" then return nil end
    local found, count, globalFound, globalCount = nil, 0, nil, 0
    for i = 1, #entries do
        local item = entries[i] and entries[i].item
        local setting = item and item.setting
        if setting then
            local names = { tostring(setting.label or "") }
            for _, list in ipairs({ setting.exactAliases or {}, setting.aliases or {} }) do
                for j = 1, #list do names[#names + 1] = tostring(list[j] or "") end
            end
            for j = 1, #names do
                if names[j] ~= "" and R.Normalize(names[j]) == subject then
                    count = count + 1
                    found = item
                    if tostring(setting.unit or "") == "global" then
                        globalCount = globalCount + 1
                        globalFound = item
                    end
                    break
                end
            end
        end
    end
    if count == 1 then return found end
    -- Every per-unit copy answers to the same bare words, so "bar texture" is
    -- claimed by the shared control AND by seven generated per-unit ones. A
    -- sentence that names no frame means the shared one.
    if globalCount == 1
        and not (type(R.UnitScopeFromText) == "function" and R.UnitScopeFromText(R.Normalize(text)))
    then
        return globalFound
    end
    -- Value-kind preference. When the request states a value of a recognisable
    -- kind -- a colour name, an opacity word, a position, a texture key -- the
    -- candidates that cannot hold such a value are not candidates at all. This
    -- is the general form of the sibling lookup: no name guessing, just the
    -- type the stated value needs.
    if type(R.StatedValueKindForText) == "function" then
        local wanted = R.StatedValueKindForText(text)
        if wanted then
            local typed, typedCount = nil, 0
            for i = 1, #entries do
                local item = entries[i] and entries[i].item
                local candidate = item and item.setting
                if candidate and candidate.type == wanted then
                    typedCount = typedCount + 1
                    typed = item
                end
            end
            if typedCount == 1 then return typed end
        end
    end
    return nil
end

-- A result-shaped sentence names a boolean control and never says "on":
-- "give the health bars a gradient look", "mark shields that overflow past
-- full health", "i don't want shields drawn on the health bar". Asking for a
-- thing to exist is asking for it to be on, and asking for it not to is off.
--
-- Bounded on purpose: one control, resolved from the sentence's own subject,
-- boolean only, and only for long number-free sentences so the index build
-- stays off the cold route.
R.NAMED_BOOLEAN_NEGATIONS = {
    "dont", "do not", "no longer", "never", "stop showing", "stop the",
    "get rid of", "without", "hide", "remove", "turn off", "switch off", "disable",
}

-- Does the sentence actually contain the enum value that was read out of it?
-- NamedBooleanIntentPlan treats "the rest of the sentence" as the value once
-- the subject resolves to one control, and for an enum that let it write a
-- choice the player never typed: "show me target portrait position dropdown"
-- resolved Portrait Position and set it to LEFT. A value that cannot be found
-- in the text -- as its own token, its display label, or one of the control's
-- registered value aliases -- is an invention, not a reading.
-- Openers that can ONLY mean "take me there". Deliberately excludes "show me":
-- "show me how much maximum health i lost" is navigation-shaped but asks for a
-- feature to be switched on, and treating it as navigation stopped that
-- working. "direct me to target portrait position left" names a value only to
-- identify the control it wants opened, so it must never be applied.
R.UNAMBIGUOUS_NAVIGATION_OPENERS = {
    "^direct me to%f[%W]", "^take me to%f[%W]", "^bring me to%f[%W]",
    "^navigate to%f[%W]", "^jump to%f[%W]", "^go to%f[%W]", "^scroll to%f[%W]",
    "^where is%f[%W]", "^where are%f[%W]", "^where do i find%f[%W]",
    "^bring mich zu%f[%W]", "^springe zu%f[%W]", "^wo finde ich%f[%W]",
}

function R.IsUnambiguousNavigationCommand(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    for i = 1, #R.UNAMBIGUOUS_NAVIGATION_OPENERS do
        if norm:find(R.UNAMBIGUOUS_NAVIGATION_OPENERS[i]) then return true end
    end
    return false
end
A.RouterIsUnambiguousNavigationCommand = R.IsUnambiguousNavigationCommand

R.ENUM_VALUE_LEADIN_PATTERNS = {
    "^show me%f[%W]", "^take me to%f[%W]", "^bring me to%f[%W]", "^jump to%f[%W]",
    "^go to%f[%W]", "^where is%f[%W]", "^where are%f[%W]", "^find%f[%W]",
    "^zeig mir%f[%W]", "^bring mich zu%f[%W]",
}

function R.EnumValueAppearsInText(setting, value, norm)
    if value == nil then return false end
    local stripped = R.Normalize(norm)
    -- A navigational lead-in is not the value. Enable-style enums register
    -- one-word polarity aliases ("show", "on", "enabled") pointing at their
    -- default ON choice -- Portrait Position maps "show" to LEFT -- so the
    -- "show" in "SHOW ME target portrait position dropdown" was read as that
    -- alias and the dropdown was written. "show the target portrait" has no
    -- lead-in and still resolves.
    for i = 1, #R.ENUM_VALUE_LEADIN_PATTERNS do
        stripped = stripped:gsub(R.ENUM_VALUE_LEADIN_PATTERNS[i], "")
    end
    local hay = " " .. R.Trim(stripped) .. " "
    local function mentions(phrase)
        phrase = R.Normalize(phrase)
        if phrase == "" then return false end
        return hay:find(" " .. phrase .. " ", 1, true) ~= nil
    end
    local target = tostring(value)
    if mentions(target) then return true end
    -- Prefixed media keys ("BORDER:SHADOW") are named by their tail in speech.
    local tail = target:match("[^:]+$")
    if tail and tail ~= target and mentions(tail) then return true end
    if type(R.RegistryValueLabel) == "function" then
        local ok, label = pcall(R.RegistryValueLabel, setting, value)
        if ok and label and mentions(label) then return true end
    end
    local aliases = setting and setting.valueAliases
    if type(aliases) == "table" then
        for alias, mapped in pairs(aliases) do
            if tostring(mapped) == target and mentions(alias) then return true end
        end
    end
    return false
end

function R.NamedBooleanIntentPlan(text)
    local norm = R.Normalize(text)
    if norm == "" or norm:find("%d") then return nil end
    local tokens = 0
    for _ in norm:gmatch("%S+") do tokens = tokens + 1 end
    if tokens < 5 then return nil end
    local bestNamedLength = 0
    local map = R.EnsureSettingLabelIndex and R.EnsureSettingLabelIndex()
    local aliasMap = R.EnsureSettingAliasIndex and R.EnsureSettingAliasIndex()
    local function Lookup(phrase)
        if not phrase or phrase == "" then return nil end
        return (map and map[phrase]) or (aliasMap and aliasMap[phrase]) or nil
    end
    local subject = type(R.CommandSubjectPhrase) == "function" and R.CommandSubjectPhrase(text) or nil
    local setting = Lookup(subject)
    if setting and subject then
        -- Callers weigh how much of the sentence the control's own name
        -- covered, so a subject match has to report its length too.
        for _ in subject:gmatch("%S+") do bestNamedLength = bestNamedLength + 1 end
    end
    if not setting then
        -- The subject rarely IS the control's name word for word: "i want a
        -- marker for shields while my health is full" wraps it in filler that
        -- no verb/article peeling removes. The registered wording is in there
        -- somewhere, so take the longest run of words that names exactly one
        -- control. Longest first, so a specific name always beats a shorter
        -- one contained in it.
        local words = {}
        for word in norm:gmatch("%S+") do words[#words + 1] = word end
        local bestLength = 0
        bestNamedLength = 0
        for first = 1, #words do
            for last = #words, first + 2, -1 do
                local length = last - first + 1
                if length > bestLength then
                    local candidate = Lookup(table.concat(words, " ", first, last))
                    if candidate then
                        setting, bestLength = candidate, length
                        bestNamedLength = length
                        break
                    end
                    -- (bestLength is reported below so callers can require a
                    -- long, unambiguous wording before pre-empting a lane.)
                end
            end
        end
    end
    if type(setting) ~= "table" or type(setting.set) ~= "function" then return nil end
    -- Any type, not just booleans: once the subject resolves to exactly one
    -- control, the rest of the sentence is its value ("anchor the heal absorb
    -- bar to the left side"). Only when no value can be read does the boolean
    -- polarity inference below take over.
    if setting.type ~= "boolean" then
        local parser = A.Parser or {}
        local parsed = type(parser.ValueForRegistrySetting) == "function"
            and parser.ValueForRegistrySetting(setting, norm, text) or nil
        -- Trust an enum reading only if the sentence really says it. The on/off
        -- inference below is exempt on purpose: that one is meant to be
        -- inferred from the mention alone.
        if parsed ~= nil and setting.type == "enum"
            and not R.EnumValueAppearsInText(setting, parsed, norm)
        then
            parsed = nil
        end
        -- An on/off enum is a toggle wearing an enum's clothes: the border
        -- controls store "on"/"off", so a sentence that describes the result
        -- ("highlight the frame when something is attacking me") states its
        -- value just as plainly as it would for a boolean.
        if parsed == nil and setting.type == "enum" and type(setting.values) == "table"
            and #setting.values == 2
        then
            local onOff = {}
            for i = 1, #setting.values do onOff[tostring(setting.values[i])] = true end
            if onOff.on and onOff.off then
                parsed = R.ContainsAny(norm, R.NAMED_BOOLEAN_NEGATIONS) and "off" or "on"
            end
        end
        if parsed == nil then
            -- "i want a chunkier outline around my frames" names the control
            -- and states a direction; the planner turns that into one step.
            local plan = type(parser.PlanForExactRegistrySetting) == "function"
                and parser.PlanForExactRegistrySetting(setting, norm, text) or nil
            if type(plan) == "table" and plan.kind == "changes" then
                -- The planner will happily pick an enum choice for a sentence
                -- that names only the control, which is how "show me target
                -- portrait position dropdown" became Portrait Position = LEFT.
                -- A relative step (relativeDelta) is fine -- "a chunkier
                -- outline" really does state a direction -- but a concrete enum
                -- value has to be in the words.
                for i = 1, #(plan.changes or {}) do
                    local change = plan.changes[i]
                    local target = change and change.setting
                    if type(target) == "table" and target.type == "enum"
                        and change.value ~= nil
                        and not R.EnumValueAppearsInText(target, change.value, norm)
                    then
                        return nil
                    end
                end
                plan.raw, plan.sourceText = text, text
                plan.namedWordingTokens = bestNamedLength
                return plan
            end
            return nil
        end
        return {
            kind = "changes",
            changes = { { setting = setting, value = parsed } },
            label = tostring(setting.label or setting.key),
            summary = "Changes the control the sentence names, with the value it states.",
            raw = text,
            sourceText = text,
            exactSettingMutation = true,
        }
    end
    -- Only HIDE-named controls are inverted ("Hide Name on Dead or Offline"),
    -- and the reviewed parser owns those. A "Show ..." label is not inverted:
    -- on means shown, which is exactly what this lane infers.
    local hay = (tostring(setting.label or "") .. " " .. tostring(setting.key or "")):lower()
    if hay:find("hide", 1, true) or hay:find("hidden", 1, true) then return nil end
    local value = not R.ContainsAny(norm, R.NAMED_BOOLEAN_NEGATIONS)
    return {
        kind = "changes",
        changes = { { setting = setting, value = value } },
        label = tostring(setting.label or setting.key),
        summary = "Switches the boolean control the sentence describes.",
        raw = text,
        sourceText = text,
        exactSettingMutation = true,
        namedWordingTokens = bestNamedLength,
    }
end

function R.RequestNamesOneControl(text)
    if R.ExactAliasSingleChange(text) then return true end
    if R.CanonicalTrailingStateCommand(text) then return true end
    if R.CanonicalValueConnectorCommand(text) then return true end
    if R.CanonicalValueBeforeControlCommand(text) then return true end
    if R.CanonicalDimensionCommand(text) then return true end
    if R.ComparativeChangeNamesOneControl(text) then return true end
    -- A result-shaped command ("give the health bars a gradient look") names
    -- its control in the subject even though it states no value word, so the
    -- three rewrites above cannot see it and a guidance article claimed the
    -- sentence.
    --
    -- Forcing the label and alias maps costs about a second on the very first
    -- turn, so it is spent only on the shape that needs it: a long sentence
    -- with no number in it. Every case pinned by assistant_perf_budget_smoke
    -- ("move boss castbar down 5") carries a number and skips this entirely.
    local norm = R.Normalize(text)
    local tokens = 0
    for _ in norm:gmatch("%S+") do tokens = tokens + 1 end
    local descriptive = tokens >= 5 and not norm:find("%d")
    if R.CommandNamedSettingLabel(text, descriptive) then return true end
    return false
end

-- Guards a topic-help answer at the moment it is about to be returned. A help
-- article is the right reply to "how do I make my raid readable" and the wrong
-- one to "i want raid heal prediction off", which names a control outright.
--
-- Deliberately evaluated only when a topic lane already produced something AND
-- the request looks like a change: RequestNamesOneControl builds the exact-alias
-- index, so running it per input would break the cold-path budgets.
function R.TopicAnswerSurvivesExactControl(result, text)
    if not result then return nil end
    -- Cheap filter first. "i want raid heal prediction off" is a change even
    -- though LooksLikeMutation says no, so gating on that alone let the article
    -- through; a trailing state word or a number is the tell. A pure question
    -- ("how do I make my raid readable") matches none of these and never pays
    -- for the index build below.
    local norm = R.Normalize(text)
    local carriesValue = norm:find("%d")
        or norm:match("%s(on)$") or norm:match("%s(off)$")
        or norm:match("%s(enabled)$") or norm:match("%s(disabled)$")
        or R.LooksLikeMutation(text) or R.StartsWithMutationCommand(text)
        -- Result-shaped commands carry no state word at all ("give the health
        -- bars a gradient look"), yet they are instructions, not questions.
        -- CommandSubjectPhrase is plain string work and needs a leading verb,
        -- so a question can never match it.
        or (type(R.CommandSubjectPhrase) == "function" and R.CommandSubjectPhrase(text) ~= nil)
    if not carriesValue then return result end
    if type(R.RequestNamesOneControl) == "function" and R.RequestNamesOneControl(text) then return nil end
    -- The sentence may describe its control in wording no label or alias
    -- spells, yet a dedicated parser lane still recognises it in full: "make
    -- the healing absorb bar 5 pixels tall" is Heal Absorb Bar Height, but the
    -- word "make" plus the word "healing" also reads as a request for healer
    -- setup advice, and the article won. A scoreless single-change plan is a
    -- recognised sentence rather than a fuzzy name guess, so no setup article
    -- may outrank one. Paid only here -- an article has already been built for
    -- a value-carrying request, and this parse is the work the request was
    -- going to do anyway once the article stood down.
    if type(A.Parse) == "function" and type(R.OpenEndedSpecialistOwnsChange) == "function" then
        local parsed = A.Parse(text)
        if R.OpenEndedSpecialistOwnsChange(parsed) then return nil end
    end
    return result
end

function A.RouterIsFailClosedReadOnlyRequest(text)
    local norm = R.StripResponseLanguageDirective(text)
    if norm == "" then return true end
    if R.IsSubjectiveSafePlanningRequest(norm) then return true end
    if type(R.AuraGrowthMutationAmbiguity) == "function" and R.AuraGrowthMutationAmbiguity(norm) then
        return true
    end
    if type(R.IsExplicitNavigationCommand) == "function" and R.IsExplicitNavigationCommand(norm) then
        -- Navigation wording grants permission to open/focus a control, never
        -- to change its value. Force it past every mutation fast path.
        return true
    end
    if type(R.ScopedMutationExclusion) == "function" and R.ScopedMutationExclusion(norm) then
        -- The Router must isolate the included clause before any single-plan
        -- or batch fast path sees the explicitly excluded control.
        return true
    end
    -- Capability questions ask whether/how something can be done; they are not
    -- permission to do it. Keep direct polite requests ("could you change")
    -- actionable while treating possible/could-I forms as guidance.
    if R.IsCapabilityMutationQuestion(norm) or R.IsExplicitMutationRefusal(norm) then return true end
    -- Question-shaped AND naming an exact control: "whats the target frame
    -- width" asks what the value is, and was being answered with "what value do
    -- you want me to use?". Only the question lead-ins can produce a label
    -- here, so an ordinary command can never reach this.
    if type(A.RouterIsNamedSettingLookup) == "function" and A.RouterIsNamedSettingLookup(text) then
        return true
    end
    if type(R.LooksLikeComparativeSizeRelationshipRequest) == "function"
        and R.LooksLikeComparativeSizeRelationshipRequest(norm)
    then
        return true
    end
    -- Exact setting labels identify a control; they do not grant write
    -- permission. Counterfactuals, previews, impact questions, and explicit
    -- no-write wrappers must remain read-only even when they include a valid
    -- value that the exact-label parser could otherwise apply.
    if norm:match("^if%s+[a-z]+%s+")
        or norm:match("^what%s+happens%s+if%s+")
        or norm:match("^what%s+would%s+happen%s+if%s+")
        or norm:match("^preview%s+")
        or norm:find("without changing", 1, true)
        or norm:find("without applying", 1, true)
        or norm:find("without setting", 1, true)
        or norm:find("tell me about", 1, true)
        or (R.ContainsAny(norm, { "will it affect", "would it affect", "does it affect", "what does it affect", "what will it affect", "impact on", "effect on" })
            and R.ContainsAny(norm, { "what", "which", "how", "will", "would", "does", "tell", "explain" }))
    then
        return true
    end
    -- Advice questions ask whether a change is a good idea; they never authorize
    -- it. "is General Power Bar Gradient Color Green Channel worth changing"
    -- named a colour channel and enabled Power Bar Gradient across all ten bar
    -- scopes, because no classifier recognised the shape as a question and a
    -- topic lane claimed it. Asking about a control must always be free.
    if R.ContainsAny(norm, {
        "worth changing", "worth setting", "worth enabling", "worth disabling",
        "worth turning on", "worth turning off", "worth using", "worth it",
        "should i change", "should i set", "should i enable", "should i disable",
        "should i turn on", "should i turn off", "should i use", "should i adjust",
        "do i need", "do i have to", "is it a good idea", "would you recommend",
        "lohnt es sich", "sollte ich",
    }) then
        return true
    end
    -- A direction-less movement phrase is a clarification request. It must
    -- reach the Router even when an Aura alias could also be read as a
    -- visibility toggle ("move player buffs" must never mean "show buffs").
    if type(R.IncompleteMovementSubject) == "function" and R.IncompleteMovementSubject(norm) then return true end
    -- Value-less setting ideas must reach the Router before the direct-write
    -- fast path. The Router can then show the exact control, range, or enum
    -- choices without letting a label word masquerade as a value.
    if type(R.IsExactRegistrySettingMutation) == "function"
        and R.IsExactRegistrySettingMutation(text)
    then
        return false
    end
    -- The parser owns these complete, reviewed semantic shapes even though
    -- the generic open-ended search sees multiple related controls. Their
    -- closed scope/value grammar prevents this exemption from authorizing a
    -- broader or value-less write.
    if R.ReviewedSemanticMutationKind(norm) then return false end
    if type(R.OpenEndedSettingAnalysis) == "function" then
        local openEnded = R.OpenEndedSettingAnalysis(norm)
        if openEnded and (openEnded.explicitValue ~= true
            or type(R.OpenEndedEntriesAreConfident) ~= "function"
            or not R.OpenEndedEntriesAreConfident(openEnded.entries))
        then
            -- About to fail-close a request that DID carry a value. Only now is
            -- the exact-alias index worth building: it is the one thing that
            -- can prove the request names a single control after the fuzzy
            -- search saw several. Asking earlier would build that index on
            -- every input and break the cold-path budget; asking for a
            -- value-less request is pointless, because a single change needs a
            -- value. Everything above this point is still a question guard, so
            -- "is it worth changing X to 2" never reaches here.
            -- ExactAliasSingleChange goes through the exact-alias pre-pass,
            -- which declines several types outright (colours above all). A
            -- request that spells one control's whole visible label is just as
            -- unambiguous, so consult that index too -- otherwise "set Pet Frame
            -- Color to red" is fail-closed as a question and the reply tells the
            -- player to "use a direct command with an explicit value", which is
            -- exactly what they typed.
            if openEnded.explicitValue == true
                and (R.ExactAliasSingleChange(text)
                    or (type(R.ExactLabelSingleChange) == "function" and R.ExactLabelSingleChange(text))
                    or (type(R.CanonicalValueBeforeControlCommand) == "function"
                        and R.CanonicalValueBeforeControlCommand(text))
                    or R.EntriesNamedExactlyOnce(openEnded.entries, text))
            then
                return false
            end
            -- A comparative names no value word, so the check above cannot see
            -- one -- but "make the corners rounder" is still a change, and
            -- fail-closing it answered a direct instruction with "ask for the
            -- option's location". When the fuzzy search already resolved one
            -- control confidently, the direction is all that was missing.
            if type(R.ComparativeChangeSubject) == "function"
                and R.ComparativeChangeSubject(text)
                and (type(R.OpenEndedEntriesAreConfident) ~= "function"
                    or R.OpenEndedEntriesAreConfident(openEnded.entries))
            then
                return false
            end
            -- Otherwise the sentence still earns the exemption if it spells a
            -- control by name. That test is plain string work until a
            -- comparative tail really matches, so ordinary requests pay
            -- nothing for it.
            if type(R.ComparativeChangeNamesOneControl) == "function"
                and R.ComparativeChangeNamesOneControl(text)
            then
                return false
            end
            if type(R.NamedBooleanIntentPlan) == "function" and R.NamedBooleanIntentPlan(text) then
                return false
            end
            if type(R.StatedValueKindSiblingPlan) == "function" and R.StatedValueKindSiblingPlan(text) then
                return false
            end
            return true
        end
    end
    if type(A.RouterLooksLikeExplicitSettingRelationshipRequest) == "function"
        and A.RouterLooksLikeExplicitSettingRelationshipRequest(norm)
    then
        return true
    end
    if type(R.LooksLikeRegistrySettingDecisionQuestion) == "function"
        and R.LooksLikeRegistrySettingDecisionQuestion(norm)
    then
        return true
    end
    if type(R.LooksLikeNaturalEvaluationQuestion) == "function"
        and R.LooksLikeNaturalEvaluationQuestion(norm)
    then
        return true
    end
    if R.ContainsAny(norm, { "dependencies", "dependency", "depend on", "depends on", "relationship", "relationships", "connection", "connections", "related settings", "related options", "related to", "connected to other settings" })
        and R.ContainsAny(norm, { "what", "which", "how", "show", "explain", "list" })
    then
        return true
    end
    if R.HasUnmistakableMutationRequest(norm) then return false end

    local parser = A.Parser
    if parser and type(parser.NonMutatingIntent) == "function" and parser.NonMutatingIntent(norm) then return true end
    if norm:match("^show%s+me%s+") or norm:match("^zeige%s+mir%s+") then return true end
    if R.LooksLikeKnowledgeQuestionPrefix(norm)
        or R.LooksLikeKnowledgeRequest(norm)
        or R.LooksLikeDirectDefinitionQuestion(norm)
        or (type(R.IsExplicitReadOnlyDiagnosticCommand) == "function" and R.IsExplicitReadOnlyDiagnosticCommand(norm))
    then
        return true
    end
    return R.ContainsAny(norm, {
        "missing", "hidden", "not showing", "not visible", "broken", "disabled", "does not work", "doesn't work",
        "fehlt", "fehlend", "versteckt", "nicht sichtbar", "kaputt", "deaktiviert", "funktioniert nicht",
        "current value", "current setting", "list settings", "list options", "related settings", "related options",
    })
end

function R.LooksLikeKnowledgeRequest(text)    local norm = R.Normalize(text)
    if norm == "" then return false end
    return R.ContainsAny(norm, {
        "help", "why", "where", "where is", "where are", "what", "what is", "what are", "how", "how do",
        "search", "find", "faq", "explain", "show me",
        "hilfe", "warum", "wo", "wo ist", "wie", "suche", "finde", "erklaere",
        "was", "was ist", "was sind", "was kann", "was kannst",
    })
end

function R.LooksLikeKnowledgeFirstRequest(text)    local norm = R.Normalize(text)
    if norm == "" then return false end
    if A.Knowledge and type(A.Knowledge.LooksLikeComplementaryAddonQuestion) == "function"
        and A.Knowledge.LooksLikeComplementaryAddonQuestion(norm)
    then
        return true
    end
    if R.LooksLikeKnowledgeQuestionPrefix(norm) then return true end
    if R.ContainsAny(norm, R.MUTATION_TERMS) then return false end
    if R.ContainsAny(norm, { "open", "go to", "show settings", "show me settings", "oeffne" }) then return false end
    if R.ContainsAny(norm, {
        "what did you change", "what changed", "what was changed", "what did you do",
        "what did you just change", "what exactly did you change", "what did you set",
        "last change", "last assistant change", "previous change", "what is it now",
        "what is it set to", "current value", "value now", "show last change",
        "show me last change", "show me the last change",
    }) then return false end
    return R.ContainsAny(norm, {
        "search", "find", "where", "where is", "where are", "faq", "explain",
        "suche", "finde", "wo", "wo ist", "erklaere",
        "was ist", "was sind", "was kann", "was kannst",
    })
end

function R.LooksLikeDirectDefinitionQuestion(text)    local norm = R.Normalize(text)
    if norm == "" then return false end
    if R.ContainsAny(norm, {
        "what did you change", "what changed", "what was changed", "what did you do",
        "what did you just change", "what exactly did you change", "what did you set",
        "last change", "last assistant change", "previous change", "what is it now",
        "what is it set to", "current value", "value now", "show last change",
        "show me last change", "show me the last change",
    }) then return false end
    if R.LooksLikeConcreteScopedValueRequest and R.LooksLikeConcreteScopedValueRequest(norm) then return false end
    if R.ContainsAny(norm, { "where", "where is", "where are", "where can", "where do", "how do i", "how can i", "how to" }) then return false end
    if norm:match("^what%s+is%s+") or norm:match("^what%s+are%s+")
        or norm:match("^what%s+does%s+") or norm:match("^explain%s+")
        or norm:match("^describe%s+")
    then
        return true
    end
    return false
end

function R.LooksLikeChangelogKnowledgeRequest(text)    if A.Knowledge and type(A.Knowledge.LooksLikeChangelogQuestion) == "function" then
        return A.Knowledge.LooksLikeChangelogQuestion(text) == true
    end
    local norm = R.Normalize(text)
    if norm == "" then return false end
    if R.ContainsAny(norm, { "open changelog", "close changelog", "toggle changelog", "oeffne changelog" }) then return false end
    if R.ContainsAny(norm, { "release notes", "patch notes", "build notes", "latest changes", "changelog", "change log", "was ist neu", "was hat sich geaendert" }) then return true end
    if R.ContainsAny(norm, { "what changed", "what is new", "whats new" })
        and (norm:find("%d+%.%d+") or R.ContainsAny(norm, { "release", "version", "preview", "alpha", "beta", "patch", "build" })) then
        return true
    end
    return false
end

