function R.LooksLikeConcreteScopedValueRequest(text)    local norm = R.Normalize(text)
    if norm == "" then return false end
    if R.ContainsAny(norm, {
        "option", "options", "where", "which page", "which menu", "what page", "what menu",
        "help me find", "help me locate", "find options", "locate options",
    }) then
        return false
    end
    if norm:match("%d") or norm:match("#%x%x%x") then return true end
    if R.ContainsAny(norm, {
        "turn on", "turn off", "enable", "disable", "hide", "show",
        "bigger", "smaller", "larger", "wider", "narrower", "taller", "shorter",
        "increase", "decrease", "raise", "lower", "on", "off", "true", "false",
    }) then
        return true
    end
    if R.ContainsAny(norm, R.COLOR_TERMS) and R.ContainsAny(norm, { "set", "change", "make" }) then return true end
    return false
end

function R.LooksLikeScopedHelpKnowledgeRequest(text)    local norm = R.Normalize(text)
    if norm == "" then return false end
    if R.ContainsAny(norm, { "what did you change", "what changed", "what was changed", "last change", "previous change" }) then return false end
    if R.LooksLikeGuidedTourRequest(norm) then return false end
    if R.ContainsAny(norm, { "open", "go to", "show settings", "show me settings", "oeffne" })
        and not R.ContainsAny(norm, { "where should i go", "where should i go to", "where should i go for" })
    then
        return false
    end
    if R.LooksLikeConcreteScopedValueRequest(norm) then return false end

    local hasIntent = R.ContainsAny(norm, R.SCOPED_HELP_INTENT_TERMS)
    if not hasIntent
        and R.ContainsAny(norm, { "i want", "i need" })
        and R.ContainsAny(norm, { "option", "options", "where", "find", "locate", "page", "menu" })
    then
        hasIntent = true
    end
    return hasIntent and R.ContainsAny(norm, R.SCOPED_HELP_SCOPE_TERMS)
end

function R.BugReportReply(text)    return {
        text = "Thanks for wanting to report it. That would really help MSUF development, especially if I can reproduce it.\nDiscord: " .. R.DISCORD_INVITE .. "\nAlternatively, you can leave a comment on the MSUF CurseForge page: " .. R.CURSEFORGE_PAGE .. "\nHelpful details: the exact Assistant text, the open MSUF page, what you expected, and what actually happened.",
        status = "info",
        summary = "Assistant bug report help",
    }
end

function R.NextConversationJoke()    local jokes = R.WOW_JOKES_EN
    if #jokes == 0 then return nil end

    local key = "lastEnglishJokeIndex"
    local index = 1
    local ctx = A.GetContext and A.GetContext() or nil
    if type(ctx) == "table" then
        index = (tonumber(ctx[key]) or 0) + 1
        if index > #jokes then index = 1 end
        ctx[key] = index
    end
    return jokes[index]
end

function R.AssistantCapabilityReply()    local helper = A.Knowledge and A.Knowledge.CapabilityHelp
    if type(helper) == "function" then
        local result = helper(false)
        if result then return result end
    end
    return {
        text = "MSUF Assistant: what I can do\nI'm the local MSUF Assistant. I can find and explain MSUF options, open pages, run checks, and apply safe changes. If the full setting index is still starting, I answer from the built-in MSUF routes and finish that work in the menu job.",
        status = "info",
        summary = "Assistant capabilities",
    }
end

function R.TryRuntimeVersionQuestion(text)
    local norm = R.Normalize(text)
    local asksClient = R.ContainsAny(norm, {
        "what patch am i on", "which patch am i on", "what wow patch",
        "current wow patch", "what wow version", "which wow version",
        "what game version", "which game version", "client version",
    })
    local asksMSUF = R.ContainsAny(norm, {
        "what msuf version", "which msuf version", "current msuf version",
        "what version of msuf", "which version of msuf", "addon version",
    })
    if not asksClient and not asksMSUF then return nil end
    local lines = { "Version information" }
    if asksClient then
        local version, build, date
        if type(_G.GetBuildInfo) == "function" then
            version, build, date = _G.GetBuildInfo()
        end
        if version then
            local detail = tostring(version)
            if build and tostring(build) ~= "" then detail = detail .. " (build " .. tostring(build) .. ")" end
            if date and tostring(date) ~= "" then detail = detail .. ", " .. tostring(date) end
            lines[#lines + 1] = "World of Warcraft client: " .. detail .. "."
        else
            lines[#lines + 1] = "I cannot read the current World of Warcraft client build in this session."
        end
    end
    local metadata = _G.C_AddOns and type(_G.C_AddOns.GetAddOnMetadata) == "function"
        and _G.C_AddOns.GetAddOnMetadata("MidnightSimpleUnitFrames", "Version")
        or (type(_G.GetAddOnMetadata) == "function"
            and _G.GetAddOnMetadata("MidnightSimpleUnitFrames", "Version"))
    if asksMSUF or metadata then
        lines[#lines + 1] = metadata and ("MSUF: " .. tostring(metadata) .. ".")
            or "I cannot read the installed MSUF version metadata in this session."
    end
    lines[#lines + 1] = "This only reads local client/addon metadata; it does not change MSUF."
    return { text = table.concat(lines, "\n"), status = "info", summary = "Reports local WoW and MSUF version metadata." }
end

function R.ClearMutationReferentContext()
    local ctx = A.GetContext and A.GetContext() or nil
    if type(ctx) ~= "table" then return end
    for _, key in ipairs({
        "lastChangeBundle", "lastSetting", "lastSettingTurn", "lastSubjectTurn",
        "lastAction", "lastActionArgs", "lastUnit", "lastFrameType", "lastCategory",
        "lastDirection", "lastAttribute", "lastMentionedSetting", "lastMentionedUnit",
    }) do
        ctx[key] = nil
    end
end

function A.RouterChatGPTStyleReply()
    return {
        text = "Yes—for MSUF and WoW UI setup, that is the goal. I run locally inside MSUF instead of calling an external ChatGPT service, so I understand the addon through its menu registry and your current profile state.\nI can converse naturally, remember recent MSUF context, find and open controls, explain how settings connect, diagnose blockers, apply concrete safe changes, and help with undo or redo. When wording is uncertain, I give you choices instead of inventing an answer.\nMy limits: I do not browse live patch data, invent current class or talent guides, or bypass WoW combat restrictions. The Assistant does no active work after the menu closes or while combat blocks it.",
        status = "info",
        summary = "Assistant ChatGPT-style answer",
    }
end

function A.RouterLimitsReply()
    return {
        text = "MSUF Assistant limits\nI work locally from MSUF's own menu, registry, profile, and diagnostic data. I can help with MSUF UI setup and WoW UI readability, but I do not call an external AI service, browse the web, or know live class/talent tuning.\nI also will not guess destructive profile actions, bypass WoW combat lockdown, or apply vague changes when several MSUF options could match. In those cases I explain the choice, ask for a specific target, or suggest a safe page to open.",
        status = "info",
        summary = "Assistant limits",
    }
end

-- Exact Assistant-meta questions must be handled before registry setting
-- discovery. Words such as "limit" and "cap" are also valid setting terms;
-- without this narrow priority lane, "what are your limits" can be answered
-- with unrelated aura-cap sliders instead of the Assistant's real boundaries.
R.ASSISTANT_LIMIT_QUESTIONS = R.ASSISTANT_LIMIT_QUESTIONS or {
    ["what are your limits"] = true,
    ["what are your limitations"] = true,
    ["assistant limits"] = true,
    ["assistant limitations"] = true,
    ["what cant you do"] = true,
    ["what can't you do"] = true,
    ["what can you not do"] = true,
    ["what do you not do"] = true,
    ["can you do everything"] = true,
    ["are you online"] = true,
    ["do you use internet"] = true,
    ["do you browse"] = true,
    ["was kannst du nicht"] = true,
    ["was kannst du nicht machen"] = true,
    ["wo sind deine grenzen"] = true,
    ["was sind deine grenzen"] = true,
    ["bist du online"] = true,
    ["hast du internet"] = true,
}

function R.TryEarlyAssistantMetaConversationReply(text)
    local norm = R.Normalize(text)
    if R.ASSISTANT_LIMIT_QUESTIONS[norm] then return A.RouterLimitsReply() end
    -- This common German imperative is a capability/help request. Keep it in
    -- the early meta lane so an open Party/Raid page cannot reinterpret
    -- "zeige" as permission to toggle the page's first visible control.
    if norm == "zeige mir befehle" then return R.AssistantCapabilityReply() end
    return nil
end

function R.TroubleshootingReply()    return {
        text = "Troubleshooting help\nI can run local MSUF checks, inspect common visibility problems, build support text, and open recovery tools. Start with 'run checks' or name the broken area, for example: why is target cast bar hidden; why are party frames hidden; why are target buffs hidden.\nYou can ask: Run Checks | Assistant Support Text | Open Display & Recovery",
        status = "info",
        summary = "Assistant troubleshooting help",
    }
end

local function ConversationPlayerName()
    if type(_G.UnitName) ~= "function" then return nil end
    local ok, name = pcall(_G.UnitName, "player")
    name = ok and tostring(name or ""):match("^%s*(.-)%s*$") or ""
    return name ~= "" and name or nil
end

-- "How do I create X" is a build request, not a setting lookup. Without this
-- the aura lanes answered "create a custom aura" with a generic disclaimer, and
-- "track shield wall on my player frame" matched the words "player frame" and
-- reported that the Player Frame was already enabled. Creation intent is
-- answered with the actual sequence of commands, and never writes anything.
R.CREATION_VERB_TERMS = {
    "create", "make", "set up", "setup", "add", "build", "new",
    "how do i create", "how do i make", "how do i add", "how do i set up",
    "i want to create", "i want to make", "i want to add", "i want to set up",
    "i want to track", "i want to see when", "track", "show me when",
}

R.CREATION_GUIDES = {
    {
        terms = { "custom aura", "custom auras", "custom container", "custom aura container",
                  "own aura", "own auras", "aura group", "aura display", "track a spell",
                  "track spell", "track a buff", "track a debuff" },
        Build = function()
            return "Making your own aura group in MSUF"
                .. "\nMSUF calls these Custom Aura containers. Each frame has four (Custom 1-4), and each one is an independent group with its own spell list, filters, position and size. On the Player frame, Custom 4 is the defensive container."
                .. "\nWalk it with me -- say each line and I will do it:"
                .. "\n1. Turn the container on:  turn on player custom aura 1 enabled"
                .. "\n2. Add the spells you want to see:  whitelist 871 in player custom aura 1   (a SpellID, a spell name, or a spell link all work; repeat for each spell)"
                .. "\n3. Place it:  set player custom aura 1 y offset to 20  and  set player custom aura 1 x offset to 0"
                .. "\n4. Size it:  set player custom aura 1 icon size to 30,  set player custom aura 1 per row to 4,  set player custom aura 1 spacing to 2"
                .. "\n5. Cap how many show at once:  set player custom aura 1 max icons to 8"
                .. "\nSwap 'player' for target, focus or boss, and 1 for 2-4. To see what a container currently holds, ask 'list player custom aura 1'. To start over, say 'reset player custom aura 1'."
                .. "\nI can also just open the page for you -- say 'open player auras'."
        end,
    },
    {
        terms = { "profile", "profiles" },
        Build = function()
            return "Making a new MSUF profile"
                .. "\nProfiles hold a complete MSUF configuration, and you can bind them per character or per specialisation."
                .. "\n1. Copy what you have as a starting point:  copy current profile to Raid"
                .. "\n2. Or start clean:  create profile Raid"
                .. "\n3. Switch to it:  switch to profile Raid"
                .. "\n4. Share or back it up:  export current profile   (and 'import profile' to bring one in)"
                .. "\nI will always confirm before overwriting or deleting a profile."
        end,
    },
    {
        terms = { "spell indicator", "spell indicators", "corner icon", "corner indicator" },
        Build = function()
            return "Adding a group-frame spell indicator"
                .. "\nSpell indicators are the small corner icons on Party/Raid frames that show one tracked spell per corner."
                .. "\n1. Open the page:  open group status & indicators"
                .. "\n2. Pick the corner and assign the spell you want that slot to watch."
                .. "\n3. Size and place it with the corner's own controls on that page."
                .. "\nTell me the scope and corner and I will take you straight there, for example 'open party spell indicators'."
        end,
    },
}

function R.TryCreationGuidance(text)
    local norm = R.Normalize(text)
    if norm == "" or #norm > 120 then return nil end
    -- Explicit onboarding wording belongs to the native guided setup. Without
    -- this guard, phrases such as "profile setup guide" are mistaken for a
    -- profile-creation question because "setup" is also a creation verb.
    if R.LooksLikeGuidedTourRequest(norm) then return nil end
    if not R.ContainsAny(norm, R.CREATION_VERB_TERMS) then return nil end

    -- A concrete container command is not a build question. "add 871 to player
    -- custom aura 1" must still execute rather than be answered with the
    -- recipe it is already following.
    if norm:find("custom aura%s+%d") and norm:find("%d%d") then return nil end

    -- "Track shield wall on my player frame" and "I want to see when I have
    -- Power Infusion" name a spell rather than the word "spell", so the term
    -- lists below cannot match them -- yet they are the single most common way
    -- players ask for a custom aura. Match the shape instead of the noun.
    if norm:find("%f[%w]track%f[%W].+%f[%w]on%f[%W].+%f[%w]frame%f[%W]")
        or norm:find("^i want to see when")
        or norm:find("^show me when")
        or norm:find("^i want to know when")
    then
        return {
            text = R.CREATION_GUIDES[1].Build(),
            status = "info",
            result = "info",
            summary = "Guides the player through building this without changing MSUF.",
        }
    end

    for i = 1, #R.CREATION_GUIDES do
        local guide = R.CREATION_GUIDES[i]
        if R.ContainsAny(norm, guide.terms) then
            return {
                text = guide.Build(),
                status = "info",
                result = "info",
                summary = "Guides the player through building this without changing MSUF.",
            }
        end
    end
    return nil
end

-- Asked point blank what it is, the Assistant must not imply it is ChatGPT or
-- a language model. It is a local rule-based system.
--
-- Every phrase below starts with "are you"/"bist du" or names a model vendor,
-- so a cheap pre-check keeps the fuzzy phrase scan off the common path.
function R.IsDirectAiIdentityQuestion(norm)
    norm = R.Normalize(norm)
    if #norm > 40 then return false end
    if not (norm:find("are you", 1, true) or norm:find("bist du", 1, true)
        or norm:find("chatgpt", 1, true) or norm:find("gpt", 1, true)
        or norm:find("is this", 1, true) or norm:find("ist das", 1, true)
        or norm:find("benutzt du", 1, true) or norm:find("do you use", 1, true))
    then
        return false
    end
    return R.ContainsAny(norm, {
        "are you an ai", "are you a ai", "are you ai", "are you chatgpt", "are you gpt",
        "are you a bot", "are you a robot", "are you a real ai", "are you a language model",
        "do you use chatgpt", "are you an llm", "are you using chatgpt", "is this chatgpt",
        "bist du eine ki", "bist du ki", "bist du ein bot", "bist du chatgpt",
        "benutzt du chatgpt", "ist das chatgpt",
    })
end

function R.HumanConversationReply(text)    local norm = R.Normalize(text)
    if norm == "" then return nil end

    local ctx = A.GetContext and A.GetContext() or nil
    local choice = type(ctx) == "table" and ctx.humanConversationChoice or nil
    local choiceNumber = tonumber(norm:match("^(%d+)$"))
    local currentTurn = tonumber(ctx and (ctx.turnSerial or ctx.lastTurnSerial)) or 0
    if type(choice) == "table" and currentTurn > (tonumber(choice.turn) or 0) + 1 then
        ctx.humanConversationChoice = nil
        choice = nil
    end
    if choiceNumber and type(choice) == "table" then
        ctx.humanConversationChoice = nil
        if choice.kind == "confusion" then
            if choiceNumber == 1 then
                return {
                    text = "Tell me any words you remember from the control, plus the frame or page if you know it. For example: 'find target portrait position' or 'list all target settings'.",
                    status = "info",
                    summary = "Assistant find-setting choice",
                }
            elseif choiceNumber == 2 then
                return {
                    text = "Tell me the frame and the result you want. Examples: 'make target wider', 'move player name up', 'show dispellable target debuffs', or 'set party health texture to Smooth'. If several controls fit, I'll give you numbered options.",
                    status = "info",
                    summary = "Assistant change-setting choice",
                }
            elseif choiceNumber == 3 then
                return R.TroubleshootingReply()
            elseif choiceNumber == 4 then
                local answer = A.Knowledge and type(A.Knowledge.Answer) == "function"
                    and A.Knowledge.Answer("what can this page do", { currentPage = M and M.activeKey }) or nil
                return answer or R.AssistantCapabilityReply()
            end
        elseif choice.kind == "correction" then
            if choice.canUndo == true and choiceNumber == 1 then
                local ok, message = false, nil
                if type(A.UndoLast) == "function" then ok, message = A.UndoLast() end
                return {
                    text = message or (ok and "Undid the last Assistant change." or "I could not undo that change."),
                    status = ok and "applied" or "failed",
                    summary = "Assistant correction undo",
                }
            end
            local keepIndex = choice.canUndo == true and 2 or 1
            local expectedIndex = choice.canUndo == true and 3 or 2
            if choiceNumber == keepIndex then
                return {
                    text = "Okay, I'll keep the current change. Tell me the corrected frame and option—for example, 'I meant Target Portrait Position, not Player Portrait Position.'",
                    status = "info",
                    summary = "Assistant correction clarification",
                }
            elseif choiceNumber == expectedIndex then
                return {
                    text = "Describe what you expected to see in game and which frame it concerns. I'll map that result to the closest MSUF controls and give you choices if more than one fits.",
                    status = "info",
                    summary = "Assistant expected-result clarification",
                }
            end
        end
        choice.turn = currentTurn
        ctx.humanConversationChoice = choice
        return {
            text = "That number is not one of the choices I offered. Please pick a listed number or describe what you want in your own words.",
            status = "ambiguous",
            summary = "Assistant conversation choice clarification",
        }
    end

    if R.ContainsAny(norm, {
        "tell me a joke", "tell joke", "tell me another joke", "another joke", "say something funny", "make me laugh", "joke", "jokes",
        "erzaehl mir einen witz", "erzaehle mir einen witz", "erzaehl einen witz",
        "erzaehle einen witz", "mach einen witz", "noch einen witz", "noch ein witz", "naechster witz", "witz",
    }) then
        R.ClearMutationReferentContext()
        if type(ctx) == "table" then
            ctx.lastConversationKind = "joke"
            ctx.lastConversationTurn = tonumber(ctx.turnSerial or ctx.lastTurnSerial) or 0
        end
        return {
            text = R.NextConversationJoke() or "Sure. MSUF is ready for the next joke.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    if R.ContainsAny(norm, {
        "thats not what i meant", "that is not what i meant", "not what i meant", "you misunderstood",
        "you got that wrong", "wrong thing", "das meinte ich nicht", "falsch verstanden",
    }) then
        local canUndo = type(A.undoStack) == "table" and #A.undoStack > 0
        local lines = {
            "I may have misunderstood you, so I won't guess at another change.",
            "Pick what you want to do:",
        }
        if canUndo then lines[#lines + 1] = "1. Type 'undo' to revert my last MSUF change." end
        lines[#lines + 1] = tostring(canUndo and 2 or 1) .. ". Keep the change and tell me the corrected frame plus option."
        lines[#lines + 1] = tostring(canUndo and 3 or 2) .. ". Tell me what result you expected, and I'll offer matching MSUF controls."
        if type(ctx) == "table" then
            ctx.humanConversationChoice = { kind = "correction", canUndo = canUndo, turn = currentTurn }
        end
        return {
            text = table.concat(lines, "\n"),
            status = "ambiguous",
            result = "ambiguous",
            summary = "Assistant correction choices",
        }
    end

    if R.ContainsAny(norm, {
        "im confused", "i am confused", "i dont know what to ask", "not sure what to ask", "where do i start",
        "ich bin verwirrt", "weiss nicht was ich fragen soll", "wo fange ich an",
    }) then
        if type(ctx) == "table" then
            ctx.humanConversationChoice = { kind = "confusion", turn = currentTurn }
        end
        return {
            text = "No problem. Pick a direction:\n1. Find or open an MSUF setting.\n2. Change a frame, bar, aura, color, or text option.\n3. Diagnose something hidden or not working.\n4. Ask what the current page can do.\nYou can answer with a number or describe what you see.",
            status = "info",
            summary = "Assistant starting choices",
        }
    end

    if norm == "help"
        or norm == "help me"
        or norm == "i need help"
        or norm == "show me help"
        or norm == "show help"
        or norm == "hilfe"
        or norm == "hilf mir"
        or norm == "ich brauche hilfe"
        or norm == "brauche hilfe"
        or norm == "zeige mir hilfe"
        or norm == "zeig mir hilfe"
        or norm == "zeige mir alles"
        or norm == "show me everything"
    then
        return R.AssistantCapabilityReply()
    end

    if R.ContainsAny(norm, {
        "what is msuf", "what is midnight simple unit frames", "what are midnight simple unit frames",
        "was ist msuf", "was sind midnight simple unit frames",
    }) then
        return {
            text = "MSUF is Midnight Simple Unit Frames, a local WoW unit-frame addon. I can help with its frames, cast bars, auras, group frames, class resources, gameplay helpers, profiles, and diagnostics. Ask me to find an option, open a page, explain a setting, run checks, or apply a concrete MSUF change.",
            status = "info",
            summary = "MSUF overview",
        }
    end

    if R.ContainsAny(norm, {
        "cant find auras", "can't find auras", "cannot find auras", "where are auras",
        "where do i find auras", "where is auras", "find auras",
        "tell me about auras", "tell me something about auras", "talk about auras",
        "ich finde auren nicht", "finde auren nicht", "wo sind auren", "wo finde ich auren",
        "auren nicht finden", "auren suche",
        "erzaehl mir was zu auras", "erzaehle mir was zu auras",
        "erzaehl mir etwas ueber auren", "erzaehle mir etwas ueber auren", "rede ueber auren",
    }) then
        return {
            text = "Auras are in the MSUF Auras pages. I can guide or change lane visibility, no-expiration filtering, live filter tokens, exact SpellID/category lists, Custom Aura include lists, icon size/count/growth, cooldown and stack text, and visibility checks. Ask: open auras; filter target debuffs to ones I can dispel; hide permanent player buffs; why are target buffs hidden?",
            status = "info",
            summary = "Auras help",
        }
    end

    if R.ContainsAny(norm, {
        "profile import broken", "profile import not working", "import broken", "import not working",
        "import failed", "profile import failed", "import kaputt", "profil import kaputt",
        "profile import kaputt", "import geht nicht", "profil import geht nicht",
    }) then
        return {
            text = "Profile import help\nOpen Profiles first, paste a full MSUF profile string, and import into a backup or new profile when possible. I can open the import panel, export the current profile first, or run a profile check.\nYou can ask: Open Profile Import | Export Current Profile | Check Profiles",
            status = "info",
            summary = "Profile import help",
        }
    end

    if R.ContainsAny(norm, {
        "what are your limits", "what are your limitations", "assistant limits", "assistant limitations",
        "what cant you do", "what can't you do", "what can you not do", "what do you not do",
        "can you do everything", "are you online", "do you use internet", "do you browse",
        "was kannst du nicht", "was kannst du nicht machen", "wo sind deine grenzen",
        "was sind deine grenzen", "bist du online", "hast du internet",
    }) then
        return A.RouterLimitsReply()
    end

    if R.ContainsAny(norm, {
        "what can you do", "what can i ask", "what can i ask you", "what can the assistant do",
        "what can msuf assistant do", "assistant help", "show commands", "what commands",
        "which commands", "available commands", "commands list", "list commands",
        "was kannst du", "was kannst du alles", "was kann der assistant", "was kann der assistent",
        "was kann msuf assistant", "was kann msuf assistent", "was kann ich fragen", "zeig mir befehle",
        "welche befehle", "welche befehle gibt es", "befehle gibt es", "befehle anzeigen",
    }) then
        return R.AssistantCapabilityReply()
    end

    -- "Can you be like ChatGPT for MSUF?" is a capability question and "yes,
    -- that is the goal" answers it. "Are you ChatGPT?" is an identity question
    -- and the same reply reads as claiming to be ChatGPT, which is false. The
    -- direct form is answered honestly further down.
    if not R.IsDirectAiIdentityQuestion(norm) and R.ContainsAny(norm, {
        "chatgpt", "chat gpt", "ai assistant", "ai chat", "like chatgpt", "like chat gpt",
        "be like chatgpt", "talk like chatgpt", "wie chatgpt", "wie chat gpt",
        "how close are you to chatgpt", "close to chatgpt", "chatgpt in game", "chatgpt ingame",
        "ingame chatgpt", "in game chatgpt", "local chatgpt", "ki assistant", "ki assistent",
        "ki chat", "wie eine ki", "wie nah an chatgpt", "wie nahe an chatgpt", "chatgpt ingame",
    }) then
        return A.RouterChatGPTStyleReply()
    end

    if R.ContainsAny(norm, {
        "can we talk", "talk to me", "chat with me", "normal talk", "talk normally", "just talk",
        "small talk", "talk about msuf", "talk about wow", "chat about msuf", "chat about wow",
        "normal reden", "einfach reden", "lass uns reden", "kannst du normal reden",
        "rede ueber msuf", "reden ueber msuf", "ueber msuf reden",
        "rede ueber wow", "reden ueber wow", "ueber wow reden",
    }) then
        return {
            text = "Yes. I work best with MSUF, unit frames, auras, cast bars, profiles, or WoW UI readability. For current class, talent, and patch guides I point to current guides because MSUF runs offline.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    if R.ContainsAny(norm, {
        "interface broken", "ui broken", "addon broken", "broken interface", "broken ui",
        "everything is broken", "something is broken", "interface problem", "ui problem",
        "addon problem", "interface issue", "ui issue", "not working", "does not work",
        "doesnt work", "why is my interface broken", "why is my ui broken",
        "interface kaputt", "interface ist kaputt", "mein interface ist kaputt",
        "ui kaputt", "ui ist kaputt", "meine ui ist kaputt", "addon kaputt", "alles kaputt",
        "warum ist mein interface kaputt", "warum ist meine ui kaputt", "funktioniert nicht",
        "geht nicht", "problem mit interface", "problem mit ui", "fehler im interface",
        "unitframes weg", "unit frames weg", "frames weg", "rahmen weg",
        "unit frames gone", "unitframes gone", "unit frames missing", "unitframes missing",
        "unit frames not shown", "unitframes not shown", "unit frames not showing", "unitframes not showing",
        "frames gone", "frames are gone", "my frames are gone", "frames missing", "frames are missing",
        "frames not shown", "frames not showing", "my ui is gone", "everything is gone",
        "settings disappeared", "settings missing", "settings are missing", "options disappeared",
        "party frames weg", "raid frames weg", "group frames weg", "gruppenframes weg",
        "ziel buffs weg", "target buffs gone", "ziel castbar weg", "target castbar gone",
        "spieler frame unsichtbar", "player frame invisible", "frames unsichtbar", "rahmen unsichtbar",
    }) then
        return R.TroubleshootingReply()
    end

    if R.ContainsAny(norm, {
        "get better at wow", "better at wow", "improve at wow", "improve in wow", "wow improvement",
        "learn wow", "wow guide", "guide for wow", "class guide", "rotation guide", "talent guide",
        "best talents", "best build", "dps guide", "healer guide", "tank guide", "raid guide",
        "mythic plus guide", "m plus guide", "m+ guide", "how do i play my class",
        "where can i find wow guides", "wowhead", "help with wow", "wow help",
        "can you help with wow", "can you help me with wow", "help me with wow",
        "besser in wow", "besser bei wow", "wow besser", "wie werde ich besser",
        "wie werde ich besser in wow", "kannst du mit wow helfen", "hilf mir mit wow",
        "hilfe mit wow", "wow hilfe", "klassenguide", "klassen guide", "talente",
        "rotation", "spielweise", "wow guide deutsch",
    }) then
        return {
            text = "For live class, talent, and patch guides, I point to current Wowhead guides because MSUF runs offline. Check Wowhead: " .. R.WOWHEAD_GUIDES .. ". For UI setup, unit frames, visibility, text, and MSUF profiles, I can help directly here.",
            status = "info",
            summary = "General WoW help",
        }
    end

    if R.ContainsAny(norm, { "how are you", "how are you doing", "hows it going", "how is it going", "are you ok", "you good", "wie gehts", "wie geht es dir", "alles gut", "gehts dir gut" }) then
        return {
            text = "Doing well—quietly waiting for the next UI puzzle. Name the MSUF option or frame you want to tune, or just tell me what looks wrong.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    -- Only when the message is nothing BUT a greeting. ContainsAny matches the
    -- word anywhere, so "hey turn off show power" used to be answered with
    -- "Hey. Good to see you." and the command was dropped on the floor.
    if R.IsGreetingOnly(norm) then
        local name = ConversationPlayerName()
        return {
            text = "Hey" .. (name and (", " .. name) or "") .. ". Good to see you. What are we tuning in MSUF today?",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    if R.ContainsAny(norm, { "thanks", "thank you", "thx", "danke", "danke dir" }) then
        return {
            text = "You're welcome. I'm here when you're ready for the next tweak.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    if R.ContainsAny(norm, { "nice work", "great job", "that was helpful", "well done", "gut gemacht" }) then
        return {
            text = "Glad that helped. We can keep refining it, or leave it exactly as it is.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    if R.ContainsAny(norm, { "that was funny", "good one", "haha", "lol" }) then
        return {
            text = "Glad it landed. I do have more—type 'another joke' if you want one.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    if R.ContainsAny(norm, { "bye", "goodbye", "good night", "see you later", "see you", "tschuss", "tschuess", "bis spaeter" }) then
        return {
            text = "See you. Your MSUF settings will be right where you left them.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    -- A bare "yes"/"no" only means something when something is waiting. With
    -- nothing pending it is not an unrecognised command, it is a reply to a
    -- question nobody asked -- so say that rather than "I did not understand".
    if norm == "yes" or norm == "yeah" or norm == "yep" or norm == "sure" or norm == "ok"
        or norm == "okay" or norm == "no" or norm == "nope" or norm == "ja" or norm == "nein"
    then
        return {
            text = "There is nothing waiting for a yes or no right now, so I have not done anything."
                .. "\nTell me what you want changed and I will either do it or show you the choices, for example 'set target width to 250' or 'why are target buffs hidden'.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    -- A bare question word is a real attempt at a question, just an incomplete
    -- one. Ask for the missing half instead of rejecting it.
    if norm == "why" or norm == "how" or norm == "what" or norm == "where" or norm == "which"
        or norm == "warum" or norm == "wie" or norm == "was" or norm == "wo"
    then
        return {
            text = "Happy to answer -- about what?"
                .. "\nFinish the question with the frame or the option you mean, for example 'why are target buffs hidden', 'how do I change the font', or 'where do I change colors'.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    -- "Never mind" with nothing pending is a conversational close, not a
    -- request. Answering it with the generic "I did not understand" made the
    -- Assistant look like it had missed a command.
    if norm == "never mind" or norm == "nevermind" or norm == "forget it"
        or norm == "forget that" or norm == "no worries" or norm == "its fine"
        or norm == "it's fine" or norm == "schon gut" or norm == "vergiss es"
    then
        return {
            text = "No problem — I left everything as it is. Say the word when you want to change something in MSUF.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    -- A bare offer of help, with no command attached, is a request for the
    -- capability overview. Wrapped commands such as "can you help me set the
    -- target width" are handled by the mutation lanes and never reach here.
    if norm == "can you help me" or norm == "can you help" or norm == "could you help me"
        or norm == "can u help me" or norm == "will you help me" or norm == "kannst du mir helfen"
        or norm == "kannst du helfen"
    then
        return R.AssistantCapabilityReply()
    end

    if R.IsDirectAiIdentityQuestion(norm) then
        return {
            text = "No — I'm not a language model and I don't call ChatGPT or any online service. I'm a local, rule-based assistant that runs entirely inside your WoW client and reads MSUF's own menu data and your current profile. That's why I work offline and never send your settings anywhere. The trade-off is that I understand MSUF well and general chit-chat poorly, so keep requests about MSUF and I'll be useful.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    if R.ContainsAny(norm, { "who are you", "what are you", "whats your name", "what is your name", "tell me about yourself", "wer bist du", "was bist du" }) then
        return {
            text = "I'm the local MSUF Assistant—an in-game setup partner built around MSUF's own settings and current profile. I can find controls, explain how they connect, guide you to them, apply safe changes, and offer choices when your request could mean several things.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    return nil
end

-- Questions about MSUF or the Assistant itself are exact, high-confidence
-- intents. Fuzzy option search must not answer them first: "what is msuf"
-- otherwise returned a list of settings whose labels merely start with "MSUF".
R.IDENTITY_QUESTION_MARKERS = {
    "msuf", "you", "chatgpt", "chat gpt", "gpt", "bot", "robot", "llm",
    "midnight", "bist du", "eine ki", "yourself",
}

function R.LooksLikeAssistantIdentityQuestion(text)
    local norm = R.Normalize(text)
    if norm == "" or #norm > 64 then return false end
    -- This runs on every routed input, so the expensive phrase scan below needs
    -- a near-free gate in front of it. Every phrase in that list contains one of
    -- these markers, so text without them cannot match and can skip the scan.
    local marked = false
    for i = 1, #R.IDENTITY_QUESTION_MARKERS do
        if norm:find(R.IDENTITY_QUESTION_MARKERS[i], 1, true) then marked = true break end
    end
    if not marked then return false end
    return R.ContainsAny(norm, {
        "what is msuf", "what is midnight simple unit frames", "what are midnight simple unit frames",
        "was ist msuf", "was sind midnight simple unit frames",
        "who are you", "what are you", "whats your name", "what is your name",
        "tell me about yourself", "wer bist du", "was bist du",
        "are you an ai", "are you a ai", "are you ai", "are you chatgpt", "are you gpt",
        "are you a bot", "are you a robot", "are you a language model", "are you an llm",
        "do you use chatgpt", "bist du eine ki", "bist du ki", "bist du ein bot", "bist du chatgpt",
    })
end

function R.IsAdjacentJokeFollowup(norm)
    norm = R.Normalize(norm)
    if norm == "another one" or norm == "one more" or norm == "another" or norm == "again" then
        local ctx = A.GetContext and A.GetContext() or nil
        local currentTurn = type(ctx) == "table" and (tonumber(ctx.turnSerial or ctx.lastTurnSerial) or 0) or 0
        local conversationTurn = type(ctx) == "table" and tonumber(ctx.lastConversationTurn) or nil
        if type(ctx) == "table"
            and ctx.lastConversationKind == "joke"
            and conversationTurn ~= nil
            and currentTurn == conversationTurn + 1
        then
            return true
        end
    end
    return false
end
A.RouterIsAdjacentJokeFollowup = R.IsAdjacentJokeFollowup

function A.TryImmediateConversationReply(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    if R.IsAdjacentJokeFollowup(norm) then return R.HumanConversationReply("another joke") end
    if A.RouterHasBlockingPendingAssistantState and A.RouterHasBlockingPendingAssistantState() then return nil end
    local parser = A.Parser or {}
    if type(parser.LooksLikeAuraFilteringConversation) == "function"
        and parser.LooksLikeAuraFilteringConversation(
            norm,
            type(A.GetContext) == "function" and A.GetContext() or {}
        )
    then
        return nil
    end
    local liveColor = R.TryLiveUnitColorExplanation and R.TryLiveUnitColorExplanation(text)
    if liveColor then return liveColor end
    local auraDurationChoice = R.AuraDurationFilterQuestionReply and R.AuraDurationFilterQuestionReply(norm)
    if auraDurationChoice then return auraDurationChoice end
    if norm:match("^wo%s+") or norm:match("^wie%s+kann%s+ich%s+")
        or norm:match("^welche%s+einstellung%s+") or norm:match("^welche%s+option%s+")
    then
        -- German setting-location forms have a dedicated compact route. Do
        -- not spend time testing every small-talk phrase first.
        return nil
    end
    local mayBePageHelp = norm:find("page", 1, true) or R.HasNormalizedPhrase(norm, "here")
    local pageHelp = mayBePageHelp and R.TryPageHelpShortcut and R.TryPageHelpShortcut(text, A.HandleCommandInput)
    if pageHelp then return pageHelp end
    if R.IMMEDIATE_SHORT_CONVERSATION[norm] then
        return R.HumanConversationReply(text)
    end
    for i = 1, #(R.IMMEDIATE_CONVERSATION_PHRASES or {}) do
        if R.HasNormalizedPhrase(norm, R.IMMEDIATE_CONVERSATION_PHRASES[i]) then
            return R.HumanConversationReply(text)
        end
    end
    if R.HasNormalizedPhrase(norm, "help") and #norm <= 20 then
        return R.HumanConversationReply(text)
    end
    if norm == "help me" or norm == "i need help" or norm == "show help" then
        return R.HumanConversationReply(text)
    end
    if R.AsksSettingLocation(norm) and A.RouterLooksLikeVisualSettingTopic
        and A.RouterLooksLikeVisualSettingTopic(norm)
        and A.RouterTryVisualSettingShortcut
    then
        local visualHelp = A.RouterTryVisualSettingShortcut(norm, nil)
        if visualHelp then
            visualHelp.status = "info"
            visualHelp.result = "info"
            if R.LooksLikeRegistrySettingLocationQuestion(norm)
                and R.CompactRegistrySettingSearchEntries
                and A.RouterTryRegistrySettingLocationShortcut
            then
                local subject = R.RegistryLocationSubject(norm)
                local compact = subject ~= "" and R.CompactRegistrySettingSearchEntries(subject, 1) or nil
                local compactLabel = compact and compact[1] and compact[1].item and R.Normalize(compact[1].item.label) or ""
                -- A specialist can accurately explain that no literal control
                -- exists (for example per-frame Background Color). Override it
                -- only for an exact full setting label, not a fuzzy generated
                -- leaf that merely shares words such as portrait/background.
                local exactSubject = R.Normalize(subject)
                if compactLabel ~= "" and compactLabel == exactSubject
                    and not R.Normalize(visualHelp.text):find(compactLabel, 1, true)
                then
                    local location = A.RouterTryRegistrySettingLocationShortcut(norm, nil, compact)
                    if location then return location end
                end
            end
            return visualHelp
        end
    end
    return nil
end

-- A greeting only counts when nothing else is being asked. Anything left over
-- after the greeting and a little politeness is the actual request.
local GREETING_WORDS = {
    "good morning", "good afternoon", "good evening", "good day",
    "hi", "hello", "hey", "heya", "yo", "hallo", "moin", "servus", "greetings",
}
local GREETING_FILLER = {
    "there", "msuf", "assistant", "again", "buddy", "friend", "mate", "pal",
    "everyone", "all", "you", "how", "are",
}

function R.IsGreetingOnly(norm)
    local remaining = " " .. R.Trim(tostring(norm or "")) .. " "
    if R.Trim(remaining) == "" then return false end
    local matchedGreeting = false
    for i = 1, #GREETING_WORDS do
        local padded = " " .. GREETING_WORDS[i] .. " "
        while remaining:find(padded, 1, true) do
            matchedGreeting = true
            local at = remaining:find(padded, 1, true)
            remaining = remaining:sub(1, at) .. remaining:sub(at + #padded)
        end
    end
    if not matchedGreeting then return false end
    for i = 1, #GREETING_FILLER do
        local padded = " " .. GREETING_FILLER[i] .. " "
        while remaining:find(padded, 1, true) do
            local at = remaining:find(padded, 1, true)
            remaining = remaining:sub(1, at) .. remaining:sub(at + #padded)
        end
    end
    return R.Trim(remaining) == ""
end

R.AURA_FALLBACK_SUMMARY = "Aura option fallback."

-- The aura fallback is a "no control matches that wording" notice, not an
-- answer. The parser publishes it as an ordinary command result, so it used to
-- win the router race against the generated control schema -- which is exactly
-- where the aura icon border, thickness and shadow controls live. Recognising
-- it lets the router hold it back until the schema has had its turn.
function R.IsAuraFallbackResult(result)
    return type(result) == "table" and result.kind == "unsupported"
        and tostring(result.summary or "") == R.AURA_FALLBACK_SUMMARY
end

function R.UnsupportedAuraReply(text)    local norm = R.Normalize(text)
    local parser = A.Parser or {}
    if type(parser.CopyCommandExcludesAuras) == "function" and parser.CopyCommandExcludesAuras(norm) then return nil end
    if R.ContainsAny(norm, { "debuff stripe", "debuff stripes" }) then return nil end
    if R.ContainsAny(norm, { "dispel overlay", "unitframe dispel overlay", "unit frame dispel overlay" }) then return nil end
    if not R.ContainsAny(norm, R.AURA_OUT_OF_SCOPE_TERMS)
        and not (R.ContainsAny(norm, R.AURA_BUFF_TERMS) and R.ContainsAny(norm, R.AURA_BUFF_CONTEXT_TERMS))
    then
        return nil
    end
    return {
        kind = "unsupported",
        status = "info",
        summary = "Aura option fallback.",
        text = "I don't see a precise MSUF aura option in that wording yet. I can change lane visibility, permanent/no-expiration filtering, live tokens, exact SpellID/category lists, Custom Aura include lists, icon layout, timer/stack styling, presets, and group aura copy. Name the frame or group, Buffs or Debuffs, and what should be kept or hidden; if more than one control fits, I will offer choices.",
    }
end

R.NATURAL_PROBLEM_TERMS = {    "gone", "missing", "failed", "failing", "fails", "failure", "error", "errors", "stuck", "broken",
    "filtered out", "filtered", "blacklisted", "blocked", "disappeared", "vanished", "lost", "not shown", "not showing",
    "not displayed", "not appearing", "does not show", "doesn't show", "cannot see", "can't see", "cant see", "hidden",
    "fix", "repair",
    "weg", "fehlt", "fehlen", "fehlende", "fehlender", "fehlendes", "fehlenden", "fehlgeschlagen", "verschwunden", "nicht angezeigt", "wird nicht angezeigt",
    "werden nicht angezeigt", "unsichtbar", "nicht sichtbar", "versteckt", "ausgeblendet",
}

function R.HasNaturalProblemTerm(norm)    return R.ContainsAny(norm, R.NATURAL_PROBLEM_TERMS)
        or (R.ContainsAny(norm, { "sehe", "sehen" }) and R.ContainsAny(norm, { "nicht" }))
end

R.NATURAL_PROFILE_PROBLEM_TERMS = {    "profile", "profiles", "profil", "profile import", "import profile",
}

R.NATURAL_GENERIC_PROBLEM_TOPICS = {    "frame", "frames", "unit frame", "unit frames", "unitframe", "unitframes",
    "ui", "interface", "settings", "setting", "options", "option",
    "everything", "all", "alles",
    "einstellungen", "optionen",
}

R.NATURAL_CONCRETE_VISIBILITY_TOPICS = {    "player", "target", "focus", "pet", "boss", "party", "raid", "mythic raid",
    "spieler", "ziel", "fokus", "begleiter", "gruppe", "schlachtzug",
    "aura", "auras", "auren", "buff", "buffs", "debuff", "debuffs",
    "castbar", "cast bar", "zauberleiste",
    "class resource", "class resources", "class power", "combo point", "combo points",
    "holy power", "alternative mana", "alt mana", "combat timer",
    "totem", "totems", "totem frame", "statue frame", "combat crosshair", "crosshair",
    "target sound", "target sounds",
}

function R.TryNaturalProblemShortcut(text, coreHandler)    local norm = R.Normalize(text)
    if norm == "" or not R.HasNaturalProblemTerm(norm) then return nil end

    if type(coreHandler) == "function" and R.ContainsAny(norm, R.NATURAL_PROFILE_PROBLEM_TERMS) then
        local result = coreHandler("diagnose profile status")
        if result and not (type(result) == "table" and result.kind == "unknown") then return R.AsReadOnlyProblemDiagnostic(result) end
    end

    if R.ContainsAny(norm, R.NATURAL_GENERIC_PROBLEM_TOPICS)
        and not R.ContainsAny(norm, R.NATURAL_CONCRETE_VISIBILITY_TOPICS)
    then
        return R.TroubleshootingReply()
    end

    return nil
end

R.READABILITY_PROBLEM_TERMS = {    "too small", "too tiny", "too big", "too large", "tiny", "unreadable",
    "hard to read", "hard to see", "cannot read", "can't read", "cant read",
    "easier to read", "easier to see", "easier to track", "easier to understand",
    "more readable", "hard to understand", "cleaner", "clean up", "simpler",
    "too busy", "busy", "too noisy", "noisy", "messy", "confusing", "overwhelming",
    "overlap", "overlaps", "overlapping", "crowded", "cluttered",
    "zu klein", "zu gross", "schwer zu lesen", "nicht lesen",
    "kann den text nicht lesen", "ueberlappen", "ueberlappt",
    -- Truncation is a readability complaint too: the player can see the text,
    -- there just is not enough of it. Without these the chain never opened and
    -- "names are getting cut off" reached no topic at all.
    "cut off", "cut short", "getting cut", "chopped", "clipped", "truncated",
    "not showing the full", "only shows part of", "abgeschnitten",
}

R.READABILITY_AURA_TERMS = {    "aura", "auras", "auren", "buff", "buffs", "debuff", "debuffs", "icon", "icons",
}

R.READABILITY_CASTBAR_TERMS = {    "cast", "casts", "boss cast", "boss casts", "castbar", "castbars", "cast bar", "cast bars", "zauberleiste", "zauberleisten",
}

R.READABILITY_GROUP_TERMS = {    "party", "party frame", "party frames", "raid", "raid frame", "raid frames",
    "group frame", "group frames", "gruppe", "gruppenframes", "schlachtzug",
}

R.READABILITY_TEXT_TERMS = {    "text", "font", "name", "names", "hp", "health", "power", "read",
    "lesen", "schrift",
}

-- Truncated names are a specific symptom with specific controls (name
-- shortening, max characters, clip side, ellipsis) -- not a font-size problem.
-- Matched on the SYMPTOM, because a player who sees "Thrallmar..." describes
-- what they see and never uses the word "shortening".
R.READABILITY_NAME_CLIP_TERMS = {
    "cut off", "cutoff", "cut short", "getting cut", "chopped", "clipped",
    "truncated", "truncating", "abbreviated", "shortened", "not showing the full",
    "only shows part of", "three dots", "dot dot dot", "ellipsis",
    "abgeschnitten", "abgekuerzt",
}

R.READABILITY_MENU_TERMS = {    "menu", "dashboard", "options", "config", "assistant", "ui", "interface",
    "everything", "all", "alles",
}

R.READABILITY_FRAME_TERMS = {    "frame", "frames", "unit frame", "unit frames", "unitframe", "unitframes",
    "player", "target", "focus", "boss", "spieler", "ziel", "fokus",
}

function R.TryReadabilityShortcut(text)    local norm = R.Normalize(text)
    -- Copy requests own their source, destination, category, transaction, and
    -- undo behavior. Keep them out of fuzzy readability matching (notably the
    -- near-match between "overlay" and "overlap") so Router help cannot
    -- replace a valid deterministic copy action.
    local copyTerms = {
        "copy", "use", "kopiere", "kopieren", "uebernehme", "uebernehmen",
        "look like", "looks like", "same as", "the same as", "match", "mirror", "clone",
    }
    for i = 1, #copyTerms do
        if R.HasNormalizedPhrase(norm, copyTerms[i]) then return nil end
    end
    if norm == "" or not R.ContainsAny(norm, R.READABILITY_PROBLEM_TERMS) then return nil end
    -- READABILITY_FRAME_TERMS contains "unitframe", which is also the prefix of
    -- real control names. A request naming one exactly ("what is UnitFrame
    -- Dispel Overlay") is about that control, not about how to make the UI
    -- easier to read.
    --
    -- Deliberately below the readability-term gate: both lookups are only worth
    -- paying for once this lane is actually about to answer with generic help,
    -- and only a fraction of inputs get that far. The named-label index sees
    -- question forms only, by design, so a COMMAND naming a control exactly
    -- ("turn on Party Heal Prediction Overlay") slipped past it and was
    -- answered with a readability article instead of being applied.
    if type(A.RouterNamedSettingLabel) == "function" and A.RouterNamedSettingLabel(text) then
        return nil
    end
    -- Only when the exact-alias index is already warm. Building it costs ~80ms
    -- and Submit's synchronous preflight has an 8ms budget it must keep, so
    -- this may never be what forces the build; the deferred pass that follows
    -- resolves with the index present.
    local aliasParser = A.Parser or {}
    if type(aliasParser._registryExactAliasIndex) == "table"
        and type(R.RequestNamesOneControl) == "function" and R.RequestNamesOneControl(text)
    then
        return nil
    end
    -- RC9 moved the Dispel Overlay and Dispel Symbol controls onto the Player,
    -- Target, Focus and Boss pages. "turn on the target dispel overlay" names
    -- one of them exactly, but as a command, so neither check above sees it and
    -- this lane answered with a readability article.
    if type(R.CommandNamedSettingLabel) == "function" and R.CommandNamedSettingLabel(text) then
        return nil
    end
    if R.ContainsAny(norm, {
        "make my ui cleaner", "make my interface cleaner",
        "clean up my ui", "clean up my interface",
    }) then
        return nil
    end

    if R.ContainsAny(norm, R.READABILITY_AURA_TERMS) then
        local openAction = "Open Auras"
        if R.ContainsAny(norm, { "party", "raid", "mythic raid", "group" }) then
            openAction = "Open Group Auras"
        elseif R.ContainsAny(norm, { "target" }) then
            openAction = R.ContainsAny(norm, { "debuff", "debuffs" }) and "Open Target Debuffs" or "Open Target Buffs"
        elseif R.ContainsAny(norm, { "focus" }) then
            openAction = R.ContainsAny(norm, { "debuff", "debuffs" }) and "Open Focus Debuffs" or "Open Focus Buffs"
        elseif R.ContainsAny(norm, { "player" }) then
            openAction = R.ContainsAny(norm, { "debuff", "debuffs" }) and "Open Player Debuffs" or "Open Player Buffs"
        end
        local reply = R.ReadabilityReply(
            "Aura readability help",
            "For aura size and overlap, I can change icon size, caps/count, spacing, growth direction, anchors, X/Y offsets, layer, cooldown text, and stack text when the scope is clear.",
            "set target buff icon size to 30; set party aura spacing to 4; make raid buffs grow up.",
            openAction .. " | Check target buffs"
        )
        if type(A.lastAssistantHelpContext) == "table" then
            A.lastAssistantHelpContext.nextStep = "Start with the least destructive visible setting: open Auras and adjust the named lane's Icon Size first. Then tune spacing or count only if the icons are still crowded."
            A.RouterPersistHelpContext()
        end
        return reply
    end

    if R.ContainsAny(norm, R.READABILITY_CASTBAR_TERMS) then
        return R.ReadabilityReply(
            "Cast bar readability help",
            "For cast bars, I can adjust Player, Target, Focus, and Boss cast bar size, text, icon, position, fill direction, and preview settings.",
            "set target cast bar height to 24; make focus cast bar wider; open cast bars.",
            "Open Cast Bars | Check target cast bar"
        )
    end

    if R.ContainsAny(norm, R.READABILITY_GROUP_TERMS) then
        local reply = R.ReadabilityReply(
            "Group frame readability help",
            "For Party, Raid, and Mythic Raid readability, I can adjust group frame scale, layout, spacing, health text, name text, range fade, and aura layout.",
            "set raid scale for 20 players to 90; set party name text size to 13; open group layout.",
            "Open Group Layout | Open Group Dispel Overlay"
        )
        if type(A.lastAssistantHelpContext) == "table" then
            A.lastAssistantHelpContext.nextStep = "Start with the least destructive visible setting: open Group Layout and adjust scale or frame spacing first. If the frames are large enough but the words are not, adjust name or health text next."
            A.RouterPersistHelpContext()
        end
        return reply
    end

    -- Before the generic text branch: a clipped name is not a font-size problem,
    -- and answering it with font advice sent players to the wrong controls.
    if R.ContainsAny(norm, R.READABILITY_NAME_CLIP_TERMS)
        and R.ContainsAny(norm, { "name", "names", "namen" })
    then
        -- The two families are genuinely different controls, so the examples
        -- must not be swapped: group frames own <scope> Name Shortening /
        -- Name Max Characters, while unit frames are shortened per FONT SCOPE
        -- (Shared, or a per-frame scope) with Name Max Length. There is no
        -- per-unit-frame shortening control -- the player frame follows Shared.
        local group = R.ContainsAny(norm, { "party", "raid", "group" })
        if group then
            return R.ReadabilityReply(
                "Name shortening help",
                "Group-frame names are cut when they do not fit, so MSUF shortens them. Name Shortening decides whether that happens, Name Max Characters how many letters survive, Name Truncation Style which end is kept, and Name No Ellipsis whether the trailing '..' is dropped. A wider frame is the other fix, because it fits more of the name before any shortening applies.",
                "turn off raid name shortening; set raid name max characters to 12; set party name truncation style to right; make raid frames wider.",
                "Open Group Layout | Open Fonts"
            )
        end
        return R.ReadabilityReply(
            "Name shortening help",
            "Unit-frame names are shortened per font scope, not per frame: Shared Name Shortening covers every frame that follows Shared (including Player), and Target, Focus, Pet, Boss and the two -of-target frames can override it. Name Max Length sets how many letters survive, Name Truncation Style which end is kept, and Name No Ellipsis whether the trailing '..' is dropped. A wider frame also fits more of the name before shortening applies.",
            "turn off shared name shortening; set shared name max length to 12; set target name truncation style to right; make target frame wider.",
            "Open Fonts | Open Player"
        )
    end

    if R.ContainsAny(norm, R.READABILITY_TEXT_TERMS) then
        return R.ReadabilityReply(
            "Text readability help",
            "For text readability, I can adjust unit-frame name, health, power, level, status, font-size, anchor, slot, offset, and global font settings.",
            "set player name font size to 14; set target hp text left current; open fonts.",
            "Open Fonts | Open Player | Open Target"
        )
    end

    local unit, unitLabel = R.UnitFrameScopeFromText(norm)
    if unit and unitLabel then
        local examples
        if R.ContainsAny(norm, { "too big", "too large", "overwhelming", "crowded", "cluttered" }) then
            examples = "set " .. unit .. " width to 240; set " .. unit .. " height to 34; open " .. unit .. "."
        else
            examples = "set " .. unit .. " width to 280; set " .. unit .. " height to 44; open " .. unit .. "."
        end
        return R.ReadabilityReply(
            unitLabel .. " frame readability help",
            unitLabel .. " readability usually starts with that frame's Width and Height. If only the words are hard to read, use text/font settings instead; use broad scaling only when the entire UI is too small.",
            examples,
            "Open " .. unitLabel .. " | set " .. unit .. " width to 280 | set " .. unit .. " height to 44",
            "I can help tune " .. unitLabel .. ", but I need an exact Width, Height, text-size, or page-open request before changing it."
        )
    end

    if R.ContainsAny(norm, R.READABILITY_MENU_TERMS) or R.ContainsAny(norm, R.READABILITY_FRAME_TERMS) then
        return R.ReadabilityReply(
            "Scaling readability help",
            "For broad readability, start with Dashboard scaling. I can adjust the MSUF menu scale, MSUF frame scale, WoW UI scale, and then refine frame sizes or text.",
            "open dashboard scaling; set MSUF frame scale to 100; set player width to 300.",
            "Open Dashboard Scaling | Open Fonts"
        )
    end

    return nil
end

