local function SafeLiveValue(value)
    return not (_G.issecretvalue and _G.issecretvalue(value) == true) and value or nil
end

local function LiveDebuffCount(unit)
    local api = _G.C_UnitAuras and _G.C_UnitAuras.GetAuraDataByIndex
    if type(api) ~= "function" then return nil end
    local count = 0
    for index = 1, 40 do
        local ok, aura = pcall(api, unit, index, "HARMFUL")
        if not ok or aura == nil then break end
        count = count + 1
    end
    return count
end

R.LIVE_AURA_EFFECT_LABELS = {
    border = "Border",
    glow = "Glow",
    pulse = "Pulse",
    healthtint = "Health Tint",
    namecolor = "Name Overlay",
}

function R.LiveAuraRequestedEffectType(norm)
    if R.ContainsAny(norm, { "border", "outline", "edge", "rand", "umrandung" }) then return "border" end
    if R.ContainsAny(norm, { "glow", "glowing", "leuchten" }) then return "glow" end
    if R.ContainsAny(norm, { "pulse", "pulsing", "pulsieren" }) then return "pulse" end
    if R.ContainsAny(norm, { "health tint", "health bar tint", "tint" }) then return "healthtint" end
    if R.ContainsAny(norm, { "name overlay", "name color", "name colour" }) then return "namecolor" end
    return nil
end

function R.LiveAuraEffectColorMatches(norm, effect)
    local color = effect and effect.color
    local r, g, b = tonumber(color and color[1]), tonumber(color and color[2]), tonumber(color and color[3])
    if not (r and g and b) then return false end
    if R.ContainsAny(norm, { "purple", "violet", "lila", "violett" }) then return b > g and r > g end
    if R.ContainsAny(norm, { "pink", "rosa" }) then return r > 0.55 and b > 0.35 and g < r end
    if R.ContainsAny(norm, { "orange" }) then return r > 0.65 and g > 0.20 and g < r and b < g end
    if R.ContainsAny(norm, { "yellow", "gelb" }) then return r > 0.60 and g > 0.55 and b < 0.45 end
    if R.ContainsAny(norm, { "red", "rot" }) then return r > g * 1.25 and r > b * 1.25 end
    if R.ContainsAny(norm, { "green", "gruen" }) then return g > r * 1.20 and g > b * 1.20 end
    if R.ContainsAny(norm, { "blue", "blau", "cyan" }) then return b > r * 1.20 and b > g * 1.05 end
    if R.ContainsAny(norm, { "black", "schwarz" }) then return math.max(r, g, b) < 0.25 end
    if R.ContainsAny(norm, { "white", "weiss" }) then return math.min(r, g, b) > 0.75 end
    if R.ContainsAny(norm, { "gray", "grey", "grau" }) then return math.max(r, g, b) - math.min(r, g, b) < 0.12 end
    return false
end

function R.LiveAuraHasSpecificColor(norm)
    return R.ContainsAny(norm, {
        "purple", "violet", "lila", "violett", "pink", "rosa", "orange",
        "yellow", "gelb", "red", "rot", "green", "gruen", "blue", "blau", "cyan",
        "black", "schwarz", "white", "weiss", "gray", "grey", "grau",
    })
end

function R.LiveAuraFrameEffectDiagnostics(frame, unit)
    local a3 = MSUF and MSUF.MSUF_Auras3 or _G.MSUF_Auras3
    if not (a3 and type(a3.GetUnitFrameEffectDiagnostics) == "function") then return nil end
    local ok, snapshot = pcall(a3.GetUnitFrameEffectDiagnostics, unit, frame)
    return ok and type(snapshot) == "table" and snapshot or nil
end

function R.LiveAuraFrameEffectCandidate(norm, frame, unit)
    local snapshot = R.LiveAuraFrameEffectDiagnostics(frame, unit)
    if not snapshot then return nil end
    local laneHint = R.AuraLaneFromText and select(1, R.AuraLaneFromText(norm)) or nil
    local requestedType = R.LiveAuraRequestedEffectType(norm)
    local auraHint = R.ContainsAny(norm, { "aura", "auras", "buff", "buffs", "debuff", "debuffs" })
    local customHint = R.ContainsAny(norm, { "custom aura", "tracked aura", "target dot", "dots on target" })
    local targetDotsHint = R.ContainsAny(norm, { "target dot", "dots on target" })
    local best, bestScore, matches

    local function Consider(effect)
        if type(effect) ~= "table" then return end
        local kind = tostring(effect.renderedType or effect.configuredType or "none"):lower()
        if kind == "none" or kind == "" then return end
        -- A configured but unarmed lane cannot be the visible effect: its
        -- lane is disabled, has no capacity, or was otherwise compiled out.
        if effect.armed ~= true then return end
        -- If a live frame exists, a merely resolvable setting is not enough:
        -- the effect must actually be installed on that frame.
        if frame ~= nil and effect.installed ~= true then return end
        if laneHint and effect.ownerKind == "lane" and effect.lane ~= laneHint then return end
        if requestedType and kind ~= requestedType then return end
        local colorMatch = R.LiveAuraEffectColorMatches(norm, effect)
        if R.LiveAuraHasSpecificColor(norm) and not colorMatch then return end
        local relevant = colorMatch or auraHint or laneHint ~= nil or requestedType ~= nil
        if not relevant then return end
        local score = (effect.armed == true and 8 or 0)
            + (effect.installed == true and 4 or 0)
            + (colorMatch and 50 or 0)
            + (requestedType and 40 or 0)
            + (laneHint and effect.lane == laneHint and 100 or 0)
            + (customHint and effect.ownerKind == "custom" and 80 or 0)
            + (targetDotsHint and effect.ownerKind == "targetDots" and 120 or 0)
        if not bestScore or score > bestScore then
            best, bestScore, matches = effect, score, { effect }
        elseif score == bestScore then
            matches[#matches + 1] = effect
        end
    end

    local lanes = snapshot.lanes
    if type(lanes) == "table" then
        Consider(lanes.buff)
        Consider(lanes.debuff)
    end
    for i = 1, #(snapshot.custom or {}) do Consider(snapshot.custom[i]) end
    return best, snapshot, matches
end

function R.LiveAuraFrameEffectAmbiguityExplanation(unitLabel, effects)
    local found = {}
    for i = 1, #(effects or {}) do
        local effect = effects[i]
        local ownerLabel
        if effect.ownerKind == "lane" then
            ownerLabel = effect.lane == "buff" and "Buff" or "Debuff"
        elseif effect.ownerKind == "targetDots" then
            ownerLabel = tostring(effect.display or "Dots on Target")
        else
            ownerLabel = tostring(effect.display or "Custom Aura")
        end
        local kind = tostring(effect.renderedType or effect.configuredType or "effect"):lower()
        local kindLabel = R.LIVE_AURA_EFFECT_LABELS[kind] or kind
        local color = effect.color
        local r, g, b = tonumber(color and color[1]), tonumber(color and color[2]), tonumber(color and color[3])
        local rgb = r and g and b and string.format(" (RGB %d, %d, %d)",
            math.floor(r * 255 + 0.5), math.floor(g * 255 + 0.5), math.floor(b * 255 + 0.5)) or ""
        found[#found + 1] = tostring(ownerLabel) .. " " .. tostring(kindLabel) .. rgb
    end
    return "I found multiple matching " .. tostring(unitLabel) .. " Aura Full-Frame effects: "
        .. table.concat(found, "; ") .. ". WoW keeps the exact live native AuraSlot match opaque to addon Lua, so I cannot safely choose one from configuration alone."
        .. " Name the Buff, Debuff, Custom Aura, or Dots-on-Target owner and I can explain that setting precisely."
        .. " I did not fall back to the normal UnitFrame border and kept MSUF unchanged."
end

function R.LiveAuraFrameEffectExplanation(unitLabel, effect)
    local kind = tostring(effect and (effect.renderedType or effect.configuredType) or "none"):lower()
    local effectLabel = R.LIVE_AURA_EFFECT_LABELS[kind]
        or tostring(effect and (effect.renderedType or effect.configuredType) or "Effect")
    local laneLabel
    if effect and effect.ownerKind == "lane" then
        laneLabel = effect.lane == "buff" and "Buff" or "Debuff"
    else
        laneLabel = tostring(effect and effect.display or "Custom Aura")
    end
    local color = effect and effect.color or {}
    local r, g, b = tonumber(color[1]), tonumber(color[2]), tonumber(color[3])
    local a = tonumber(color[4])
    local colorLine = r and g and b and string.format(
        " Its effective color is RGB %d, %d, %d%s.",
        math.floor(r * 255 + 0.5), math.floor(g * 255 + 0.5), math.floor(b * 255 + 0.5),
        a and (" at " .. tostring(math.floor(a * 100 + 0.5)) .. "% opacity") or "") or ""
    local detailLine = " Thickness " .. tostring(tonumber(effect and effect.thickness) or 2)
        .. ", priority " .. tostring(tonumber(effect and effect.priority) or 5)
        .. ", layer " .. tostring(tonumber(effect and effect.layer) or 0) .. "."
    local ownerLine
    if effect and effect.ownerKind == "targetDots" then
        ownerLine = " The Effect value is owned by this Dots-on-Target tracking slot."
    elseif effect and effect.ownerKind == "custom" then
        ownerLine = " The Effect value is owned by this tracked Custom Aura slot."
    elseif effect and effect.source == "unit" then
        ownerLine = " The Effect value is owned by the " .. tostring(unitLabel)
            .. " " .. tostring(laneLabel) .. " Aura lane."
    else
        ownerLine = " The Effect value uses the built-in default of the " .. tostring(unitLabel)
            .. " " .. tostring(laneLabel) .. " Aura lane."
    end
    local armedLine = effect and effect.armed == true
        and " It is armed in the compiled Aura lane and can appear while WoW assigns a matching aura to that native slot."
        or " It is configured but is not armed in the compiled lane right now, for example because that Aura lane is disabled."
    local triggerLine
    if effect and effect.ownerKind == "lane" then
        triggerLine = effect.lane == "buff"
            and " Its trigger is any helpful aura that passes the Buff lane's native filters and blacklist."
            or " Its trigger is any harmful aura that passes the Debuff lane's native filters and blacklist."
    elseif effect and effect.ownerKind == "targetDots" then
        triggerLine = " Its trigger is the tracked Dots-on-Target aura configured for this slot."
    else
        triggerLine = " Its trigger is the tracked Custom Aura configured for this slot."
    end
    local geometryLine = kind == "namecolor" and " Name Overlay colors the UnitFrame name instead of drawing on the health fill."
        or " The renderer attaches this visual to the current StatusBar health-fill texture, not the outer UnitFrame; at 49% health its right edge sits at the fill edge, and at 100% it reaches the frame edge."
    local pathLine = effect and effect.ownerKind == "lane"
        and (" Change it at " .. tostring(unitLabel) .. " > Auras > " .. tostring(laneLabel) .. "s > Style > Full-Frame Effect; set Effect to None to remove it.")
        or (" Change it in " .. tostring(unitLabel) .. " > Auras > " .. tostring(laneLabel) .. " > Style > Full-Frame Effect.")
    return tostring(unitLabel) .. " " .. tostring(laneLabel) .. " Full-Frame Effect is configured as " .. effectLabel .. "."
        .. colorLine .. detailLine .. ownerLine .. armedLine .. triggerLine .. geometryLine
        .. " WoW keeps the exact live AuraSlot match opaque to addon Lua, so I can identify the owner and configuration but cannot safely name the assigned aura right now."
        .. pathLine .. " UnitFrame Dispel Overlay is separate. I kept MSUF unchanged."
end

local function LiveBorderVisual(frame, uf, spec)
    if uf and type(uf.GetActiveBorderVisual) == "function" then
        local ok, visual = pcall(uf.GetActiveBorderVisual, frame)
        if ok and type(visual) == "table" then return visual end
    end
    if not frame then return nil end
    local source = frame._msufBorderActiveSource
    if source and frame._msufBorderShown ~= false then
        return {
            source = source,
            r = frame._msufBorderR,
            g = frame._msufBorderG,
            b = frame._msufBorderB,
            a = frame._msufBorderA,
        }
    end
    local border = spec and spec.border
    if frame._msufA3DispelActive == true and (not border or border.dispel ~= false) then
        return {
            source = "dispel",
            r = frame._msufA3DispelR,
            g = frame._msufA3DispelG,
            b = frame._msufA3DispelB,
            a = frame._msufA3DispelA,
        }
    end
    return nil
end

local function LiveBorderExplanation(unitLabel, visual)
    local source = tostring(visual and visual.source or "normal")
    local cause
    if source == "dispel" then
        cause = "That is MSUF's active dispel/debuff highlight border. The Aura runtime marked a readable debuff for the current dispel rules; it is not the health fill changing reaction color."
    elseif source == "aggro" then
        cause = "That is MSUF's active aggro highlight border. It is showing current threat state, not a class or health-fill color."
    elseif source == "purge" then
        cause = "That is MSUF's purge highlight border, used to call attention to a purgeable effect."
    elseif source == "bossTarget" then
        cause = "That is MSUF's Boss Target highlight border, showing that this boss unit frame is your current target."
    else
        cause = "That is the normal configured MSUF border color; no higher-priority dispel, aggro, purge, or Boss Target highlight currently owns it."
    end
    local r = tonumber(SafeLiveValue(visual and visual.r))
    local g = tonumber(SafeLiveValue(visual and visual.g))
    local b = tonumber(SafeLiveValue(visual and visual.b))
    local rgb = r and g and b and string.format(" The visible border is RGB %d, %d, %d.",
        math.floor(r * 255 + 0.5), math.floor(g * 255 + 0.5), math.floor(b * 255 + 0.5)) or ""
    return unitLabel .. " border: " .. cause .. rgb
end

function R.TryLiveUnitColorExplanation(text)
    local norm = R.Normalize(text)
    if not R.LooksLikeLiveUnitColorQuestion(norm) then return nil end
    local unit, unitLabel = LiveColorUnit(norm)
    if not unit then
        local _, groupLabel = LiveColorGroup(norm)
        if groupLabel then return LiveColorGroupGuide(groupLabel, norm) end
        return LiveColorGeneralGuide()
    end

    local frame = _G["MSUF_" .. unit]
    local uf = MSUF and (MSUF.UnitFrames or MSUF.UF)
    if not frame and uf and type(uf.GetFrame) == "function" then frame = uf.GetFrame(unit) end
    local spec = frame and frame.MSUFSpec
    local health = spec and spec.health or {}
    local asksBorder = R.ContainsAny(norm, { "border", "outline", "highlight", "edge", "rand", "umrandung" })
    local asksHealthFill = R.ContainsAny(norm, { "health", "health bar", "health fill", "bar fill", "hp bar", "lebensbalken" })
    local auraEffect, _, auraMatches = R.LiveAuraFrameEffectCandidate(norm, frame, unit)
    if auraEffect and (asksBorder or not asksHealthFill
        or R.ContainsAny(norm, { "aura", "buff", "debuff", "glow", "tint", "pulse" })) then
        if type(auraMatches) == "table" and #auraMatches > 1 then
            return {
                text = R.LiveAuraFrameEffectAmbiguityExplanation(unitLabel, auraMatches),
                status = "info",
                summary = "Ambiguous live Auras3 Full-Frame Effect explanation",
            }
        end
        return {
            text = R.LiveAuraFrameEffectExplanation(unitLabel, auraEffect),
            status = "info",
            summary = "Live Auras3 Full-Frame Effect explanation",
        }
    end

    local exists = type(_G.UnitExists) == "function" and SafeLiveValue(_G.UnitExists(unit)) or nil
    if exists == false or exists == nil then
        local debuffHint = R.ContainsAny(norm, LIVE_COLOR_DEBUFF_TERMS)
            or R.ContainsAny(norm, { "debuff", "debuffs", "dispel", "aura", "auras" })
        local offlineGuide = debuffHint
            and " Your debuff clue points first to the dispel/debuff highlight border: debuffs normally affect their aura icon or that border, not the health fill. An orange health fill can instead be the neutral-NPC reaction color."
            or " The health fill can come from class/reaction, NPC Type, Gradient, or Unified/Dark mode; a separate border can show dispel, aggro, purge, or Boss Target highlights."
        return {
            text = "I can explain the likely layers, but I can't inspect " .. unitLabel .. " live right now because no readable unit is there."
                .. offlineGuide
                .. " Target it again and ask 'why is my " .. unitLabel:lower() .. " this color?' and I'll check the live bar mode, unit reaction, and winning highlight. I kept MSUF unchanged.",
            status = "info",
            summary = "Live MSUF unit color explanation",
        }
    end

    local borderVisual = LiveBorderVisual(frame, uf, spec)
    if borderVisual and (asksBorder or (tostring(borderVisual.source or "normal") ~= "normal" and not asksHealthFill)) then
        return {
            text = LiveBorderExplanation(unitLabel, borderVisual)
                .. "\nHighlight priority comes from the MSUF border settings; the first active source wins.",
            status = "info",
            summary = "Live MSUF border color explanation",
        }
    end
    local mode = tostring(health.mode or "class"):lower()
    local cause
    if mode == "dark" or mode == "unified" then
        cause = "MSUF is using the fixed " .. mode .. " health-bar color."
    elseif mode == "gradient" then
        cause = "MSUF is using the health gradient, so the color follows the unit's current health percentage."
    elseif type(_G.UnitIsPlayer) == "function" and SafeLiveValue(_G.UnitIsPlayer(unit)) == true then
        cause = "This is a player, so MSUF is using that player's class color."
    else
        local reaction = type(_G.UnitReaction) == "function" and tonumber(SafeLiveValue(_G.UnitReaction(unit, "player"))) or nil
        if tostring(health.npcColorMode or ""):lower() == "type" and health.npcTypeColorBar ~= false then
            cause = "MSUF's NPC Type coloring is active, so this bar follows the NPC's classification rather than a debuff."
        elseif reaction and reaction >= 5 then
            cause = "The unit is friendly, so MSUF is using the friendly reaction color."
        elseif reaction == 4 then
            cause = "The unit is neutral, so MSUF is using the neutral reaction color (usually yellow/orange)."
        elseif reaction then
            cause = "The unit is hostile, so MSUF is using the enemy reaction color."
        else
            cause = "MSUF is using the unit's class/reaction color mode."
        end
    end

    local rgb
    local bar = frame and (frame.hpBar or frame.Health)
    if bar and type(bar.GetStatusBarColor) == "function" then
        local r, g, b = bar:GetStatusBarColor()
        r, g, b = tonumber(SafeLiveValue(r)), tonumber(SafeLiveValue(g)), tonumber(SafeLiveValue(b))
        if r and g and b then
            rgb = string.format(" The visible fill is RGB %d, %d, %d.", math.floor(r * 255 + 0.5), math.floor(g * 255 + 0.5), math.floor(b * 255 + 0.5))
        end
    end

    local auraLine
    if borderVisual and tostring(borderVisual.source or "") ~= "normal" then
        auraLine = LiveBorderExplanation(unitLabel, borderVisual)
    else
        local debuffs = LiveDebuffCount(unit)
        if debuffs and debuffs > 0 then
            auraLine = "I can also see " .. tostring(debuffs) .. " readable debuff" .. (debuffs == 1 and "" or "s") .. ". On Target/Focus unit frames, debuffs normally affect their aura icons or highlight borders; they do not recolor the health fill."
        elseif debuffs == 0 then
            auraLine = "I don't see a readable debuff right now. Debuffs normally affect aura icons or highlight borders, not the Target/Focus health fill."
        else
            auraLine = "Debuffs normally affect aura icons or highlight borders, not the Target/Focus health fill."
        end
    end

    return {
        text = "Yep—this one has a concrete reason. " .. cause .. (rgb or "") .. "\n" .. auraLine
            .. "\nColor guide: players use class colors; friendly, neutral, and hostile NPCs use reaction colors; NPC Type mode uses classification colors; Gradient follows health; Unified/Dark use a fixed profile color.",
        status = "info",
        summary = "Live MSUF unit color explanation",
    }
end

function R.LooksLikeLiveUnitColorQuestion(text)
    local norm = R.Normalize(text)
    if norm == "" or LiveColorHasExplicitMutation(norm) then return false end
    if not R.ContainsAny(norm, LIVE_COLOR_VISUAL_TERMS) or not LiveColorHasDiagnosticIntent(norm) then return false end
    return LiveColorUnit(norm) ~= nil
        or LiveColorGroup(norm) ~= nil
        or R.ContainsAny(norm, {
            "frame", "frames", "unit frame", "unit frames", "unitframe", "unitframes",
            "health bar", "health fill", "bar fill", "border", "outline",
        })
end

function R.AuraDurationFilterQuestionReply(norm)
    norm = R.Normalize(norm)
    local durationIntent = R.ContainsAny(norm, {
        "permanent", "no timer", "without timer", "no duration", "without duration", "timeless",
    })
    local auraIntent = R.ContainsAny(norm, { "aura", "auras", "buff", "buffs", "debuff", "debuffs" })
    local questionIntent = R.ContainsAny(norm, {
        "can you", "could you", "would you", "how can", "how do", "what filter", "which filter", "what are my choices",
    })
    if not durationIntent or not auraIntent or not questionIntent then return nil end

    local lane, laneLabel = R.AuraLaneFromText(norm)
    lane = lane or "buff"
    laneLabel = laneLabel or (lane == "debuff" and "Debuffs" or "Buffs")
    local scope, scopeLabel, isGroup = R.AuraFilterScopeFromText(norm)
    scope = scope or "player"
    scopeLabel = scopeLabel or "Player"
    local hideKey = isGroup
        and ("gf_" .. tostring(scope) .. ".auras." .. tostring(lane) .. ".blacklist.hidePermanent")
        or ("auras3." .. tostring(scope) .. "." .. tostring(lane) .. ".blacklist.hidePermanent")
    local command = "hide permanent " .. tostring(lane) .. "s on " .. tostring(scope) .. " frame"

    local lines = {
        scopeLabel .. " " .. laneLabel .. ": filter choices",
        "Your 'no timer' description means permanent/no-duration auras. That is a real MSUF Hide Permanent Auras control; it is not a SpellID blacklist and it is not Blizzard's Not Cancelable filter.",
        "Choices:",
        "1. Hide permanent/no-duration " .. laneLabel:lower() .. " - automatically hides every aura in this lane that has no finite duration. Command: '" .. command .. "'.",
        "2. Use a live " .. laneLabel:lower() .. " filter - Player, Raid, Raid In Combat"
            .. (lane == "debuff" and ", Dispellable, or Crowd Control." or ", Cancelable, Not Cancelable, External Defensive, or Big Defensive."),
        "3. Blacklist a specific spell - hides one exact SpellID; it does not mean all permanent auras. Command example: 'blacklist spell 12345 in " .. tostring(scope) .. " " .. tostring(lane) .. "s'.",
        "Reply with the choice or use the exact command. I will not treat 'no timer' as an arbitrary SpellID.",
    }
    return {
        kind = "answer",
        status = "info",
        result = "info",
        text = table.concat(lines, "\n"),
        summary = "Explains and offers executable Aura filter choices.",
        searchResults = R.SettingFollowupResults and R.SettingFollowupResults(hideKey, scopeLabel .. " " .. laneLabel .. " Hide Permanent Auras") or nil,
    }
end

function R.AuraRaidFilterRecommendationReply(norm)
    local lines = {}
    lines[#lines + 1] = "Raid aura filter recommendation"
    lines[#lines + 1] = "Short answer: start with Raid for general raid relevance, use Raid In Combat when you want less clutter during pulls, and use Dispellable Debuffs if your main job is cleansing."
    lines[#lines + 1] = "For a new player, think of filters as a sieve. The aura lane still exists, but the filter decides which icons are allowed through."
    lines[#lines + 1] = "Good raid starting points:"
    lines[#lines + 1] = "- Raid or Mythic Raid debuffs: set the Debuff filter to Raid. If the frame is still too noisy, try RaidInCombat."
    lines[#lines + 1] = "- Group dispels: use RAID_PLAYER_DISPELLABLE for auras someone in your group can remove; use DISPELLABLE for every aura with a dispel type."
    lines[#lines + 1] = "- DPS personal tracking: use Player on target debuffs when you only care about your own DoTs."
    lines[#lines + 1] = "- Defensive cooldown tracking: use BigDefensive for non-player major defensives, BigDefensivePlayer for yours, or ExternalDefensive for externals."
    lines[#lines + 1] = "I would not start with Include Nameplate-only. Use that only when you know a specific aura appears on nameplates but is missing from MSUF."
    lines[#lines + 1] = "MSUF detail: Player/Target/Focus/Boss use separate filter toggles. Party/Raid/Mythic Raid use one live dropdown token per Buff or Debuff lane."
    lines[#lines + 1] = "Examples: set raid debuff filter to Raid; set raid debuff filter to RAID_PLAYER_DISPELLABLE; set target debuffs to any dispel type; set target buffs to Important."
    return {
        kind = "answer",
        status = "info",
        result = "info",
        text = table.concat(lines, "\n"),
        summary = "Recommends beginner-friendly aura filters for raid use.",
        searchResults = R.PageFollowupResults and R.PageFollowupResults("auras3_filters", "Aura Filters", "Aura filter recommendations live in Aura Filters.") or nil,
    }
end

function R.AuraFilterOverviewReply(norm)
    local lines = {}
    local examples = "hide spell 12345; what active target debuff filters do I have; explain party buff filters; what is a good filter for raid."
    lines[#lines + 1] = "Aura filters, in normal words"
    lines[#lines + 1] = "Filters do not move icons or resize them. They decide which Buff or Debuff icons are allowed to show."
    lines[#lines + 1] = "Common choices:"
    lines[#lines + 1] = "- ALL: no extra narrowing on group frames."
    lines[#lines + 1] = "- Player: only your own buffs/debuffs. Good for tracking your DoTs or HoTs."
    lines[#lines + 1] = "- Raid / RaidPlayer: Blizzard's raid-frame relevant list, split by not-player vs player-applied auras."
    lines[#lines + 1] = "- RaidInCombat / RaidInCombatPlayer: stricter raid list while fighting, split by not-player vs player-applied auras."
    lines[#lines + 1] = "- RAID: harmful auras your character can dispel."
    lines[#lines + 1] = "- RAID_PLAYER_DISPELLABLE: auras someone in your group can dispel."
    lines[#lines + 1] = "- DISPELLABLE: every aura with a dispel type, regardless of group capability."
    lines[#lines + 1] = "- IMPORTANT: auras Blizzard flags as important."
    lines[#lines + 1] = "- BigDefensive / ExternalDefensive and their Player variants: defensive cooldown tracking."
    lines[#lines + 1] = "- CROWD_CONTROL: CC effects, usually more useful in PvP or control-heavy situations."
    lines[#lines + 1] = "To read the exact active state I need the frame and lane, for example Target Debuffs, Player Buffs, Raid Debuffs, or Party Buffs."
    lines[#lines + 1] = "Examples: " .. examples
    A.lastAssistantHelpContext = {
        kind = "knowledge",
        title = "Aura filters, in normal words",
        examples = examples,
        actions = "Open Aura Filters",
        clarification = "Name the exact frame and Buff or Debuff lane before I change a live filter, so I do not guess wrong.",
        nextStep = "Open Aura Filters to inspect the lists, or name a frame and lane before applying a live filter.",
    }
    A.RouterPersistHelpContext()
    return {
        kind = "answer",
        status = "info",
        result = "info",
        text = table.concat(lines, "\n"),
        summary = "Explains aura filters for beginners.",
        searchResults = R.PageFollowupResults and R.PageFollowupResults("auras3_filters", "Aura Filters", "Aura filters live on the Aura Filters page.") or nil,
    }
end

function R.AuraUnitFilterStatusReply(norm, scope, scopeLabel, lane, laneLabel, requestedKey)
    local filtersEnabled = R.AuraReadSettingValue("auras3." .. tostring(scope) .. "." .. tostring(lane) .. ".filtersEnabled")
    if filtersEnabled == nil then filtersEnabled = true end

    local lines = {}
    lines[#lines + 1] = scopeLabel .. " " .. laneLabel .. " filters"
    lines[#lines + 1] = "Plain English: this controls which " .. laneLabel:lower() .. " icons MSUF lets through on " .. scopeLabel .. ". It does not change icon size or position."
    lines[#lines + 1] = filtersEnabled and "Filter gate: enabled. The active toggles below affect the live native AuraContainer." or "Filter gate: disabled. The lane can still show auras, but these filter toggles will not narrow it until filters are enabled."

    if requestedKey and requestedKey ~= "exclusive" then
        local spec = R.AuraFilterBoolSpec(lane, requestedKey)
        if spec then
            local value = R.AuraReadSettingValue("auras3." .. tostring(scope) .. "." .. tostring(lane) .. ".filter." .. tostring(spec.key))
            local active = value == true and filtersEnabled ~= false
            local stateLine = spec.label .. " is " .. (active and "active" or "inactive") .. "."
            local specLines = R.AuraFilterSpecLines(spec, stateLine)
            for i = 1, #specLines do lines[#lines + 1] = specLines[i] end
        end
    elseif requestedKey == "exclusive" then
        lines[#lines + 1] = R.AuraExclusiveFilterLine(scope, scopeLabel, lane)
    else
        local active = {}
        local specs = R.AURA_UNIT_FILTER_SPECS[lane] or {}
        for i = 1, #specs do
            local spec = specs[i]
            local value = R.AuraReadSettingValue("auras3." .. tostring(scope) .. "." .. tostring(lane) .. ".filter." .. tostring(spec.key))
            if value == true then active[#active + 1] = spec.label .. ": " .. R.AuraFilterEffectSentence(spec.effect) end
        end
        lines[#lines + 1] = R.AuraExclusiveFilterLine(scope, scopeLabel, lane)
        if #active == 0 then
            lines[#lines + 1] = "Active filters right now: none. That means this lane is not being narrowed by MSUF's live filter toggles."
            if lane == "debuff" then
                lines[#lines + 1] = "Beginner tip: for raid debuffs, Raid is the normal first filter; Dispellable is the healer-cleanse view; Player is only your own debuffs."
            else
                lines[#lines + 1] = "Beginner tip: for raid buffs, Raid is the normal clean view; Big Defensive and External Defensive are specialized cooldown-tracking views."
            end
        else
            lines[#lines + 1] = "Active filters right now:"
            for i = 1, #active do lines[#lines + 1] = "- " .. active[i] end
        end
    end

    if not requestedKey then
        lines[#lines + 1] = "Available choices for this lane:"
        local availableSpecs = R.AURA_UNIT_FILTER_SPECS[lane] or {}
        for i = 1, #availableSpecs do
            local spec = availableSpecs[i]
            lines[#lines + 1] = "- " .. tostring(spec.label) .. ": " .. R.AuraFilterEffectSentence(spec.effect)
        end
        if scope ~= "shared" then
            lines[#lines + 1] = "- Hide Permanent Auras: hides auras with no finite duration. This is separate from Not Cancelable and from the exact SpellID blacklist."
        end
    end

    local tokens = R.AuraFilterTokenList(scope, lane, filtersEnabled)
    lines[#lines + 1] = "Native filter string MSUF builds from this: " .. table.concat(tokens, "|") .. "."
    lines[#lines + 1] = "Safe next commands: 'turn on " .. tostring(scope) .. " " .. tostring(lane) .. " raid filter', 'turn off " .. tostring(scope) .. " " .. tostring(lane) .. " player filter', or 'set " .. tostring(scope) .. " " .. tostring(lane) .. " exclusive filter to none'."
    local reply = {
        kind = "answer",
        status = "info",
        result = "info",
        text = table.concat(lines, "\n"),
        summary = "Explains active unit aura filters.",
        searchResults = R.SettingFollowupResultsByQuery(scopeLabel .. " " .. laneLabel .. " filters", scopeLabel .. " " .. laneLabel .. " Filters"),
    }
    return reply
end

function R.AuraGroupFilterStatusReply(norm, scope, scopeLabel, lane, laneLabel, requestedKey)
    local rootEnabled = R.AuraReadSettingValue("gf_" .. tostring(scope) .. ".auras.enabled")
    local laneEnabled = R.AuraReadSettingValue("gf_" .. tostring(scope) .. ".auras." .. tostring(lane) .. ".enabled")
    local token, tokenSetting = R.AuraReadSettingValue("gf_" .. tostring(scope) .. ".auras." .. tostring(lane) .. ".filterToken")
    token = tostring(token or "ALL")
    local tokenLabel = tokenSetting and R.RegistryValueLabel(tokenSetting, token) or (A.HumanizeDisplayKey and A.HumanizeDisplayKey(token) or token)
    local effect = R.AURA_GROUP_FILTER_EFFECTS[token] or "uses that group aura filter token for the lane."

    local lines = {}
    lines[#lines + 1] = scopeLabel .. " " .. laneLabel .. " group aura filter"
    lines[#lines + 1] = "Plain English: group-frame aura filters are a single dropdown per lane. Pick one main job for the lane: all auras, your auras, raid-relevant auras, dispellable debuffs, defensive buffs, or crowd control."
    lines[#lines + 1] = (rootEnabled == false) and "Group Auras are disabled for this scope, so this filter will not be visible until Group Auras are enabled." or "Group Auras are enabled or using their default enabled state."
    lines[#lines + 1] = (laneEnabled == false) and laneLabel .. " lane is disabled, so the filter cannot show icons yet." or laneLabel .. " lane is enabled or using its default enabled state."
    lines[#lines + 1] = "Current live filter token: " .. tostring(tokenLabel) .. ". Plain English: it " .. effect
    if token == "ALL" then
        lines[#lines + 1] = "That means the group lane is not currently narrowed by the live group filter dropdown."
    else
        lines[#lines + 1] = "That means normal auras outside this token may be hidden even when the lane itself is enabled."
    end
    if lane == "debuff" then
        lines[#lines + 1] = "Raid beginner tip: Raid is the player-dispellable view, RAID_PLAYER_DISPELLABLE covers the whole group's dispels, and DISPELLABLE includes every dispel type."
    else
        lines[#lines + 1] = "Raid beginner tip: Raid is the usual not-player buff view; BigDefensive and ExternalDefensive are for non-player defensive cooldown tracking."
    end
    lines[#lines + 1] = "Safe next commands: 'set " .. tostring(scope) .. " " .. tostring(lane) .. " filter to Raid', 'set " .. tostring(scope) .. " " .. tostring(lane) .. " filter to RaidInCombat', or 'set " .. tostring(scope) .. " " .. tostring(lane) .. " filter to ALL'."

    return {
        kind = "answer",
        status = "info",
        result = "info",
        text = table.concat(lines, "\n"),
        summary = "Explains active group aura filter.",
        searchResults = R.SettingFollowupResults("gf_" .. tostring(scope) .. ".auras." .. tostring(lane) .. ".filterToken", scopeLabel .. " " .. laneLabel .. " filter"),
    }
end

A.RouterTryAuraFilterStatusShortcut = function(norm)
    norm = R.Normalize(norm)
    if not R.AuraFilterStatusWantsAnswer(norm) then return nil end

    -- A question that names one exact control is about that control. Filter
    -- vocabulary appears inside plenty of unrelated labels ("Gameplay Enable
    -- Nameplate Counter"), and answering those with the generic aura-filter
    -- overview explains something the user did not ask about.
    if type(A.RouterNamedSettingLabel) == "function" and A.RouterNamedSettingLabel(norm) then
        return nil
    end

    if R.AuraFilterRecommendationWantsAnswer(norm) then
        return R.AuraRaidFilterRecommendationReply(norm)
    end

    local requestedKey = R.AuraFilterKeyFromText(norm)
    local lane, laneLabel = R.AuraLaneFromText(norm)
    lane = R.AuraFilterLaneForKey(requestedKey, lane)
    if lane and not laneLabel then laneLabel = lane == "buff" and "Buff" or "Debuff" end

    local scope, scopeLabel, isGroupScope = R.AuraFilterScopeFromText(norm)
    if requestedKey and not scope then
        local effect
        if requestedKey == "exclusive" then
            effect = "Exclusive filters are stricter lane filters. 'none' means no exclusive restriction; debuff lanes can use raid/encounter style exclusive filtering where supported."
        else
            local buffSpec = R.AuraFilterBoolSpec("buff", requestedKey)
            local debuffSpec = R.AuraFilterBoolSpec("debuff", requestedKey)
            local spec = debuffSpec or buffSpec
            if spec then
                local detail = R.AuraFilterSpecLines(spec)
                effect = table.concat(detail, "\n")
            end
        end
        if effect then
            return A.RouterAuraProblemReply(
                "Aura filter explanation",
                R.AuraFilterEffectSentence(effect) .. "\nTo tell you whether it is active, name the scope and lane, for example Target Debuffs or Party Buffs.",
                "what active target debuff filters do I have; is player buff raid filter on; set target debuff dispellable filter on.",
                "Open Aura Filters | Check Target Debuffs"
            )
        end
    end

    if not scope or not lane then
        return R.AuraFilterOverviewReply(norm)
    end

    if isGroupScope then
        return R.AuraGroupFilterStatusReply(norm, scope, scopeLabel, lane, laneLabel or (lane == "buff" and "Buff" or "Debuff"), requestedKey)
    end
    return R.AuraUnitFilterStatusReply(norm, scope, scopeLabel, lane, laneLabel or (lane == "buff" and "Buff" or "Debuff"), requestedKey)
end

A.RouterTryAuraProblemShortcut = function(text, coreHandler)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    if norm:match("^search%s+") or norm:match("^find%s+") or norm:match("^look%s+for%s+")
        or norm:match("^suche%s+") or norm:match("^finde%s+")
    then
        return nil
    end

    local terms = A.RouterAuraProblemTerms
    if R.ContainsAny(norm, terms.masque) then
        local reply = A.RouterAuraProblemReply(
            "Masque aura skinning",
            "MSUF 6.0 deliberately does not register its aura buttons with Masque. Masque remains available to other addons, but it cannot skin MSUF auras. In MSUF, I can still change aura icon size, caps, borders, cooldown text, stack text, duration bars, and live filters.",
            "open auras; set target buff icon size to 30; set aura cooldown text size to 14; open aura style.",
            "Open Auras | Open Aura Style | Open Aura Filters"
        )
        reply.status = "info"
        reply.result = "info"
        return reply
    end
    local mentionsAura = R.ContainsAny(norm, terms.aura)
        or R.ContainsAny(norm, terms.filter)
        or R.ContainsAny(norm, terms.text)
        or R.AuraSpecificSpellRequest(norm)
    if not mentionsAura then return nil end

    local filterStatusResult = A.RouterTryAuraFilterStatusShortcut and A.RouterTryAuraFilterStatusShortcut(norm)
    if filterStatusResult then return filterStatusResult end

    local detailSettingResult = A.RouterTryAuraDetailSettingShortcut and A.RouterTryAuraDetailSettingShortcut(norm, coreHandler)
    if detailSettingResult then return detailSettingResult end

    local naturalSettingResult = A.RouterTryAuraSettingShortcut and A.RouterTryAuraSettingShortcut(norm, coreHandler)
    if naturalSettingResult then return naturalSettingResult end

    if R.AsksSettingLocation(norm) and R.ContainsAny(norm, terms.text) then
        local unit, unitLabel = R.UnitScopeFromText(norm)
        local groupScope, groupLabel = R.GroupScopeFromText(norm)
        local scope = groupScope or unit or "target"
        local scopeLabel = groupLabel or unitLabel or "Target"
        local textLabel = R.ContainsAny(norm, { "stack text", "stack count", "count text" }) and "Stack Text" or "Cooldown Text"
        local page = groupScope and "Group Auras" or "Aura Style"
        local pageBody = groupScope and (page .. " and Aura Style") or "Aura Style"
        local reply = A.RouterAuraProblemReply(
            scopeLabel .. " Aura " .. textLabel .. " setting location",
            scopeLabel .. " aura " .. textLabel .. " controls live in " .. pageBody .. ". Use cooldown/stack text visibility, font size, color, anchor, and offset controls there; lane-specific Buff/Debuff pages still control which icons are shown.",
            "open aura style; set target buff cooldown text size to 14; show target buff stack text.",
            "Open Aura Style | Open Auras | Open Aura Filters"
        )
        reply.status = "info"
        reply.result = "info"
        return reply
    end

    if norm:match("%d") and R.ContainsAny(norm, R.MUTATION_TERMS)
        and not R.HasNaturalProblemTerm(norm)
        and not R.ContainsAny(norm, terms.layout)
        and not R.ContainsAny(norm, terms.filter)
    then
        return nil
    end

    if R.ContainsAny(norm, terms.filter) then
        return A.RouterAuraProblemReply(
            "Aura filter help",
            "Aura filters depend on the exact scope and lane: unit buffs, unit debuffs, group buffs, or group debuffs. Choose the frame/group and lane, then a goal: only mine, raid relevance, dispellable/CC, defensives, only timed, show all, or an exact SpellID/category list. I can guide that one choice at a time.",
            "open aura filters; set aura editing scope to target; set target debuff dispellable filter on; check target buffs.",
            "Open Aura Filters | Open Auras | Check target buffs | Open Group Auras"
        )
    end

    if R.ContainsAny(norm, terms.layout) then
        return A.RouterAuraProblemReply(
            "Aura layout help",
            "Aura position, side, growth direction, anchor, icon count, and offsets are scoped by frame and lane. Name the exact frame and buff/debuff lane when you want me to change it.",
            "set target debuffs grow down; set target buff anchor to top right; open auras.",
            "Open Auras | Open Group Auras | Check target buffs"
        )
    end

    if R.ContainsAny(norm, terms.text) and R.HasNaturalProblemTerm(norm) then
        return A.RouterAuraProblemReply(
            "Aura text visibility help",
            "Aura cooldown and stack text are separate from normal frame text. If they are missing, check aura cooldown text, stack text, font size, color, and lane-specific aura visibility for the affected frame.",
            "set target buff cooldown text size to 14; show target buff stack text; open auras.",
            "Open Auras | Open Aura Filters | Check target buffs"
        )
    end

    return nil
end

A.RouterCastbarProblemTerms = A.RouterCastbarProblemTerms or {
    castbar = {
        "castbar", "castbars", "cast bar", "cast bars", "casting bar",
        "player cast", "target cast", "focus cast", "boss cast",
        "cast color", "cast colours", "cast colors", "interruptible", "uninterruptible",
        "non interruptible", "noninterruptible", "focus kick", "kick tracker", "interrupt tracker",
    },
    position = {
        "wrong place", "wrong position", "position is wrong", "anchor is wrong",
        "offset is wrong", "offset wrong", "off screen", "stuck", "not moving",
        "does not move", "doesn't move", "cannot move", "can't move", "cant move",
        -- "Somewhere odd" is the same report as "in the wrong place", and it
        -- should reach position help rather than a visibility check.
        "weird place", "weird position", "weird spot", "strange place",
        "strange position", "odd place", "odd position", "out of place",
        "misplaced", "wrong spot",
    },
    preview = {
        "preview", "test cast", "test mode",
    },
    part = {
        "icon", "timer", "time text", "timer text", "cast text", "spell text",
    },
    broken = {
        "not working", "does not work", "doesn't work", "broken", "not showing",
        "missing", "hidden", "gone",
    },
}

A.RouterCastbarProblemReply = function(title, body, examples, actions)
    return {
        text = tostring(title or "Cast bar help") .. "\n" .. tostring(body or "") .. "\nExamples: " .. tostring(examples or "open cast bars; check target cast bar.") .. "\nYou can ask: " .. tostring(actions or "Open Cast Bars | Check target cast bar"),
        status = "info",
        summary = "Assistant cast bar help",
    }
end

function R.CastbarUnitFromText(norm)
    local unit, label = R.UnitScopeFromText(norm)
    if unit == "player" or unit == "target" or unit == "focus" or unit == "boss" then return unit, label end
    return nil, nil
end

function R.UnsupportedCastbarUnitFromText(norm)
    norm = R.Normalize(norm)
    if R.ContainsAny(norm, { "target of target", "targettarget", "tot" }) then
        return "targettarget", "Target of Target", "Target"
    end
    if R.ContainsAny(norm, { "focus target", "focustarget" }) then
        return "focustarget", "Focus Target", "Focus"
    end
    return nil, nil, nil
end

function A.RouterTryUnsupportedUnitCastbarShortcut(text, coreHandler)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    if not R.ContainsAny(norm, { "castbar", "castbars", "cast bar", "cast bars", "casting bar" }) then return nil end
    local unit, unitLabel, fallbackUnitLabel = R.UnsupportedCastbarUnitFromText(norm)
    if not unit then return nil end
    local asksLocation = R.AsksSettingLocation(norm)
    local wantsChange = R.ContainsAny(norm, {
        "show", "hide", "enable", "disable", "turn on", "turn off", "make visible", "visible",
        "anzeigen", "ausblenden", "einblenden", "aktivieren", "deaktivieren",
    })
    if not asksLocation and not wantsChange and not R.HasNaturalProblemTerm(norm) then return nil end

    local reply = A.RouterCastbarProblemReply(
        unitLabel .. " cast bar help",
        unitLabel .. " does not have its own separate cast bar toggle in MSUF. Cast bar controls are available for Player, Target, Focus, and Boss. For " .. unitLabel .. " readability, use its normal frame options, or tune the " .. fallbackUnitLabel .. " cast bar when that is the cast signal you want to see.",
        "open " .. unitLabel:lower() .. "; open cast bars; show " .. fallbackUnitLabel:lower() .. " cast bar; set " .. fallbackUnitLabel:lower() .. " cast bar height to 24.",
        "Open " .. unitLabel .. " | Open Cast Bars | show " .. fallbackUnitLabel:lower() .. " cast bar"
    )
    reply.status = "info"
    reply.result = reply.status
    return reply
end

function R.CastbarSettingFromText(norm)
    if R.ContainsAny(norm, { "icon", "spell icon", "cast icon", "castbar icon", "cast bar icon" }) then
        return "icon", "Castbar Icon", "castbar icon"
    end
    if R.ContainsAny(norm, { "time", "timer", "time text", "timer text", "cast time" }) then
        return "time", "Cast Time Text", "cast time"
    end
    if R.ContainsAny(norm, { "text", "spell text", "spell name", "cast text" }) then
        return "text", "Castbar Spell Text", "castbar text"
    end
    if R.ContainsAny(norm, { "width", "wider", "wide" }) then return "width", "Castbar Width", "castbar width" end
    if R.ContainsAny(norm, { "height", "taller", "high" }) then return "height", "Castbar Height", "castbar height" end
    if R.ContainsAny(norm, { "position", "move", "anchor", "offset", "x offset", "y offset", "wrong place" }) then
        return "position", "Castbar Position", "castbar position"
    end
    return "visibility", "Cast Bar", "castbar"
end

A.RouterTryCastbarSpecialSettingShortcut = function(norm, coreHandler)
    local asksLocation = R.AsksSettingLocation(norm)
    if not asksLocation then return nil end

    if R.ContainsAny(norm, { "focus kick", "kick tracker", "focus interrupt tracker", "interrupt tracker" }) then
        local settingLabel = "Focus Kick Tracker"
        local command = "show focus kick tracker"
        if R.ContainsAny(norm, { "width", "wider", "bigger", "larger", "size" }) then
            settingLabel = "Focus Kick Width"
            command = "set focus kick width to 48"
        elseif R.ContainsAny(norm, { "height", "taller" }) then
            settingLabel = "Focus Kick Height"
            command = "set focus kick height to 48"
        elseif R.ContainsAny(norm, { "text", "font" }) then
            settingLabel = "Focus Kick Text Size"
            command = "set focus kick text size to 14"
        elseif R.ContainsAny(norm, { "move", "position", "offset", "x offset", "y offset" }) then
            settingLabel = "Focus Kick Position"
            command = "move focus kick tracker left 10"
        end
        local reply = A.RouterCastbarProblemReply(
            settingLabel .. " setting location",
            settingLabel .. " lives in Cast Bars under the Focus Kick Tracker controls. Use its visibility, preview, width, height, text size, X offset, and Y offset options there.",
            "open cast bars; " .. command .. "; reset focus kick position.",
            "Open Cast Bars | " .. command
        )
        reply.status = "info"
        reply.result = "info"
        reply.searchResults = R.SettingFollowupResultsByQuery(settingLabel, settingLabel)
            or R.PageFollowupResults("opt_castbar", "Cast Bars", "Focus Kick Tracker controls live in Cast Bars.")
        return reply
    end

    if R.ContainsAny(norm, { "interruptible color", "interruptible cast color", "uninterruptible color", "uninterruptible cast color", "non interruptible color", "non interruptible cast color", "noninterruptible cast color", "castbar interrupt color", "cast bar interrupt color", "kickable cast color", "unkickable cast color" }) then
        local settingLabel = R.ContainsAny(norm, { "uninterruptible", "non interruptible", "noninterruptible", "unkickable", "not kickable" })
            and "Non-Interruptible Cast Color"
            or "Interruptible Cast Color"
        local command = settingLabel == "Non-Interruptible Cast Color" and "set uninterruptible cast color to red" or "set interruptible cast color to blue"
        local reply = A.RouterCastbarProblemReply(
            settingLabel .. " setting location",
            "Cast Bar interrupt color help: " .. settingLabel .. " lives in Colors/Cast Bars as a global cast-bar color option. It controls the color used for casts that are " .. (settingLabel == "Non-Interruptible Cast Color" and "not interruptible" or "interruptible") .. "; it is separate from the Interrupt Ready indicator.",
            "open cast bars; open colors; " .. command .. ".",
            "Open Cast Bars | Open Colors | " .. command
        )
        reply.status = "info"
        reply.result = "info"
        reply.searchResults = R.SettingFollowupResultsByQuery(settingLabel, settingLabel)
            or R.PageFollowupResults("opt_castbar", "Cast Bars", "Cast bar interrupt color controls live in Cast Bars and Colors.")
        return reply
    end

    return nil
end

A.RouterTryCastbarSettingShortcut = function(norm, coreHandler)
    local asksLocation = R.AsksSettingLocation(norm)
    if not asksLocation then return nil end
    if R.ContainsAny(norm, {
        "font size", "text size", "spell name font", "spell name size",
        "spell text size", "castbar spell name font size", "cast bar spell name font size",
    }) then
        return nil
    end
    local specialResult = A.RouterTryCastbarSpecialSettingShortcut and A.RouterTryCastbarSpecialSettingShortcut(norm, coreHandler)
    if specialResult then return specialResult end
    local unit, unitLabel = R.CastbarUnitFromText(norm)
    if not unit then return nil end
    local key, settingLabel, commandNoun = R.CastbarSettingFromText(norm)
    local title = unitLabel .. " " .. settingLabel .. " setting location"
    local body = unitLabel .. " " .. settingLabel .. " lives in Cast Bars. Open Cast Bars and use " .. unitLabel .. " " .. settingLabel .. "."
    if key == "position" then
        body = unitLabel .. " cast bar placement lives in Cast Bars and MSUF Edit Mode. Use " .. unitLabel .. " Castbar X/Y, anchors, or Edit Mode before changing unrelated frame size."
    end
    local wantsOff = R.WantsVisibilityOff(norm)
    local wantsOn = R.WantsVisibilityOn(norm)
    if asksLocation and R.IsDisplayOnlySettingsRequest(norm) then
        wantsOff, wantsOn = false, false
    end
    local verb = wantsOff and "turn off " or (wantsOn and "turn on " or "set ")
    local example = (key == "width" or key == "height") and ("set " .. unit .. " " .. commandNoun .. " to 24")
        or (verb .. unit .. " " .. commandNoun)
    local reply = A.RouterCastbarProblemReply(
        title,
        body,
        example .. "; open cast bars; check " .. unit .. " cast bar.",
        "Open Cast Bars | " .. example
    )
    reply.status = "info"
    reply.result = "info"
    if key == "position" then
        reply.searchResults = R.PageFollowupResults("opt_castbar", "Cast Bars", unitLabel .. " cast bar position is controlled by Cast Bars placement settings and MSUF Edit Mode.")
    else
        reply.searchResults = R.SettingFollowupResultsByQuery(unitLabel .. " " .. settingLabel, unitLabel .. " " .. settingLabel)
            or R.PageFollowupResults("opt_castbar", "Cast Bars", unitLabel .. " " .. settingLabel .. " lives in Cast Bars.")
    end
    return reply
end

A.RouterTryCastbarProblemShortcut = function(text, coreHandler)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    if norm:match("^search%s+") or norm:match("^find%s+") or norm:match("^look%s+for%s+")
        or norm:match("^suche%s+") or norm:match("^finde%s+")
    then
        return nil
    end

    local terms = A.RouterCastbarProblemTerms
    if not R.ContainsAny(norm, terms.castbar) then return nil end

    local unsupportedUnitCastbarResult = A.RouterTryUnsupportedUnitCastbarShortcut and A.RouterTryUnsupportedUnitCastbarShortcut(text, coreHandler)
    if unsupportedUnitCastbarResult then return unsupportedUnitCastbarResult end

    local specialSettingResult = A.RouterTryCastbarSpecialSettingShortcut and A.RouterTryCastbarSpecialSettingShortcut(norm, coreHandler)
    if specialSettingResult then return specialSettingResult end

    local naturalSettingResult = A.RouterTryCastbarSettingShortcut and A.RouterTryCastbarSettingShortcut(norm, coreHandler)
    if naturalSettingResult then return naturalSettingResult end

    if R.AsksSettingLocation(norm) and R.ContainsAny(norm, {
        "font size", "text size", "spell name font", "spell name size",
        "spell text size", "castbar spell name font size", "cast bar spell name font size",
    }) then
        local registryResult = A.RouterTryRegistrySettingLocationShortcut and A.RouterTryRegistrySettingLocationShortcut(text, coreHandler)
        if registryResult then return registryResult end
    end

    if norm:match("%d") and R.ContainsAny(norm, R.MUTATION_TERMS)
        and not R.HasNaturalProblemTerm(norm)
        and not R.ContainsAny(norm, terms.position)
        and not R.ContainsAny(norm, terms.broken)
    then
        return nil
    end

    if R.ContainsAny(norm, terms.preview) and R.ContainsAny(norm, terms.broken) then
        return A.RouterCastbarProblemReply(
            "Cast bar preview help",
            "Cast bar previews are controlled in Cast Bars and MSUF Edit Mode. If preview or test casts do not appear, check the relevant cast bar visibility first, then use preview controls out of combat.",
            "preview target cast bar; preview boss cast bar; open cast bars; enter edit mode.",
            "Open Cast Bars | Enter Edit Mode | Check target cast bar"
        )
    end

    if R.ContainsAny(norm, terms.position) then
        return A.RouterCastbarProblemReply(
            "Cast bar position help",
            "Cast bar position depends on the unit cast bar, detached/anchored placement options, and MSUF Edit Mode. I should not guess a new position from a problem report; name the unit and direction if you want a concrete move.",
            "open cast bars; enter edit mode; move target cast bar down 10; check target cast bar.",
            "Open Cast Bars | Enter Edit Mode | Check target cast bar"
        )
    end

    if R.ContainsAny(norm, terms.part) and R.HasNaturalProblemTerm(norm) then
        return A.RouterCastbarProblemReply(
            "Cast bar text and icon help",
            "Cast bar icons, timer text, spell text, text size, and icon position are Cast Bar options. If the bar itself is visible but a part is missing, check the unit cast bar text/icon settings before changing size.",
            "show target cast bar icon; set target cast bar text size to 14; open cast bars.",
            "Open Cast Bars | Check target cast bar"
        )
    end

    if R.ContainsAny(norm, terms.broken) or R.HasNaturalProblemTerm(norm) then
        local unit, unitLabel = R.CastbarUnitFromText(norm)
        if not unit then
            unit = R.VisibilityCastbarUnitForText and R.VisibilityCastbarUnitForText(R.VisibilityUnitForText(norm)) or nil
        end
        if unit ~= "player" and unit ~= "target" and unit ~= "focus" and unit ~= "boss" then unit = "target" end
        unitLabel = unitLabel or (unit == "player" and "Player" or unit == "focus" and "Focus" or unit == "boss" and "Boss" or "Target")
        if type(coreHandler) == "function" then
            local result = coreHandler("diagnose " .. unit .. " castbar")
            if result and not A.RouterIsUnknownResult(result) then return R.AsReadOnlyResult(result) end
        end
        return A.RouterCastbarProblemReply(
            unitLabel .. " cast bar visibility help",
            unitLabel .. " cast bar visibility depends on the Cast Bars page, the owning unit frame being enabled, the selected MSUF/Blizzard backend, Edit Mode position, and whether that unit is currently casting. I will check those first instead of guessing a setting change from a problem report.",
            "diagnose " .. unit .. " castbar; show " .. unit .. " cast bar; open cast bars.",
            "Check " .. unitLabel .. " cast bar | Open Cast Bars | show " .. unit .. " cast bar"
        )
    end

    return nil
end

