function R.TextSettingFromText(norm)
    if R.ContainsAny(norm, { "name text", "name", "unit name" }) then return "name", "Name Text", "name text" end
    if R.ContainsAny(norm, { "health text", "hp text", "health", "hp" }) then return "health", "Health Text", "health text" end
    if R.ContainsAny(norm, { "power text", "mana text", "energy text", "rage text" }) then return "power", "Power Text", "power text" end
    if R.ContainsAny(norm, { "status text", "dead text", "offline text" }) then return "status", "Status Text", "status text" end
    if R.ContainsAny(norm, { "font", "font size", "text size" }) then return "font", "Font Size", "text font size" end
    return "text", "Frame Text", "text"
end

local TEXT_MOVEMENT_ATTRS = {
    name = { x = "nameOffsetX", y = "nameOffsetY", anchorUnit = "nameTextAnchor", anchorGroup = "nameAnchor", noun = "name text", kindLabel = "Name Text" },
    health = { x = "hpOffsetX", y = "hpOffsetY", noun = "hp text", kindLabel = "Health Text" },
    power = { x = "powerOffsetX", y = "powerOffsetY", noun = "power text", kindLabel = "Power Text" },
    status = { x = "statusTextOffsetX", y = "statusTextOffsetY", anchorUnit = "statusTextAnchor", anchorGroup = "statusTextAnchor", noun = "status text", kindLabel = "Status Text" },
}

local TEXT_MOVEMENT_DIRECTION_WORDS = {
    left = { "left" },
    right = { "right" },
    down = { "down", "lower" },
    up = { "up", "higher", "raise" },
}

function R.TextMovementNumberCount(text)
    local raw = tostring(text or ""):lower()
    -- Indexed unit names identify the frame and are not movement amounts
    -- (for example, "boss 3 power text down 5").
    for _, scope in ipairs({ "boss", "arena", "party", "raid", "group" }) do
        raw = raw:gsub("%f[%a]" .. scope .. "%s*%d+%f[%D]", scope)
    end
    local count = 0
    for _ in raw:gmatch("[%+%-]?%d+%.?%d*") do count = count + 1 end
    return count
end

function R.TextMovementAmountForDirection(text, direction)
    local raw = tostring(text or ""):lower()
    local directions = TEXT_MOVEMENT_DIRECTION_WORDS[tostring(direction or "")] or {}
    for i = 1, #directions do
        local word = directions[i]
        local amount = raw:match("%f[%a]" .. word .. "%f[%A]%s+by%s+([%+%-]?%d+%.?%d*)")
            or raw:match("%f[%a]" .. word .. "%f[%A]%s+([%+%-]?%d+%.?%d*)")
            or raw:match("^%s*" .. word .. "%f[%A].-%sby%s+([%+%-]?%d+%.?%d*)")
            or raw:match("^%s*" .. word .. "%f[%A].-%s([%+%-]?%d+%.?%d*)%s+pixels?%s*$")
            or raw:match("^%s*" .. word .. "%f[%A].-%s([%+%-]?%d+%.?%d*)%s*$")
            or raw:match("by%s+([%+%-]?%d+%.?%d*)%s+to%s+the%s+" .. word .. "%f[%A]")
            or raw:match("by%s+([%+%-]?%d+%.?%d*)%s+to%s+" .. word .. "%f[%A]")
            or raw:match("by%s+([%+%-]?%d+%.?%d*)%s+pixels?%s+to%s+the%s+" .. word .. "%f[%A]")
            or raw:match("by%s+([%+%-]?%d+%.?%d*)%s+pixels?%s+to%s+" .. word .. "%f[%A]")
            or raw:match("([%+%-]?%d+%.?%d*)%s+pixels?%s+to%s+the%s+" .. word .. "%f[%A]")
            or raw:match("([%+%-]?%d+%.?%d*)%s+pixels?%s+to%s+" .. word .. "%f[%A]")
            or raw:match("by%s+([%+%-]?%d+%.?%d*)%s*px%s+to%s+the%s+" .. word .. "%f[%A]")
            or raw:match("by%s+([%+%-]?%d+%.?%d*)%s*px%s+to%s+" .. word .. "%f[%A]")
            or raw:match("([%+%-]?%d+%.?%d*)%s*px%s+to%s+the%s+" .. word .. "%f[%A]")
            or raw:match("([%+%-]?%d+%.?%d*)%s*px%s+to%s+" .. word .. "%f[%A]")
            or raw:match("([%+%-]?%d+%.?%d*)%s+to%s+the%s+" .. word .. "%f[%A]")
            or raw:match("([%+%-]?%d+%.?%d*)%s+to%s+" .. word .. "%f[%A]")
            or raw:match("([%+%-]?%d+%.?%d*)%s+pixels?%s+" .. word .. "%f[%A]")
            or raw:match("([%+%-]?%d+%.?%d*)%s*[Pp]?[Xx]?%s+" .. word .. "%f[%A]")
        amount = tonumber(amount)
        if amount ~= nil then return math.abs(amount) end
    end
    return nil
end

function R.TextMovementAmount(text)
    for _, direction in ipairs({ "left", "right", "down", "up" }) do
        local amount = R.TextMovementAmountForDirection(text, direction)
        if amount ~= nil then return amount end
    end
    return nil
end

-- A follow-up such as "move now power text up" names the text object but never
-- the frame that owns it. The remembered conversation subject is the only
-- honest referent for that sentence; without it the request falls through to
-- the fuzzy registry search, which happily lands on an unrelated object that
-- merely shares a word (that is how "power text" became Class Resource Text).
-- Only a recent unitframe/group subject is trusted, and the caller still
-- requires the sentence to name a text object explicitly.
function R.RememberedTextMovementScope()
    if type(A.GetContext) ~= "function" then return nil end
    local ctx = A.GetContext()
    if type(ctx) ~= "table" then return nil end
    local subjectTurn = tonumber(ctx.lastSubjectTurn or ctx.lastMentionedTurn)
    if not subjectTurn then return nil end
    local age = (tonumber(ctx.turnSerial or ctx.lastTurnSerial) or 0) - subjectTurn
    if age < 0 or age > 3 then return nil end
    local unit = tostring(ctx.lastUnit or "")
    if unit == "" then return nil end
    local frameType = tostring(ctx.lastFrameType or "")
    if frameType == "unitframe" then
        local scope, label = R.UnitScopeFromText(unit)
        if scope == unit and label then return unit, label, false end
    elseif frameType == "group" then
        local scope, label = R.GroupScopeFromText(unit)
        if scope == unit and label then return unit, label, true end
    end
    return nil
end

-- `subject` lets a caller that already knows the retained conversational object
-- (unit, group flag, text kind) skip the sentence-based resolution. It exists
-- so a pronoun follow-up such as "anchor it to the left" can be answered about
-- the object it really refers to instead of being refused for lack of a noun.
function R.TextMovementIntent(text, subject)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    local parser = A.Parser or {}
    local actionable = type(parser.ActionableText) == "function" and parser.ActionableText(text) or norm
    actionable = R.Normalize(actionable):gsub("^the%s+", "")

    local unit, unitLabel, settingScope, isGroup, textKind, settingKindLabel
    if type(subject) == "table" then
        unit = tostring(subject.unit or "")
        isGroup = subject.isGroup and true or false
        local resolvedUnit, resolvedLabel
        if isGroup then
            resolvedUnit, resolvedLabel = R.GroupScopeFromText(unit)
        else
            resolvedUnit, resolvedLabel = R.UnitScopeFromText(unit)
        end
        -- Only accept a scope the router recognizes as exactly that unit, so a
        -- stale or malformed remembered subject cannot build a bogus key.
        if resolvedUnit ~= unit then return nil end
        unitLabel = resolvedLabel
        settingScope = isGroup and ("gf_" .. unit) or unit
        textKind = tostring(subject.textKind or "")
    else
        unit, unitLabel = R.UnitScopeFromText(actionable)
        if not unit then unit, unitLabel = R.UnitScopeFromText(norm) end
        settingScope = unit
        isGroup = false
        if not unit then
            unit, unitLabel = R.GroupScopeFromText(actionable)
            if not unit then unit, unitLabel = R.GroupScopeFromText(norm) end
            if unit then settingScope, isGroup = "gf_" .. tostring(unit), true end
        end
        if not unit then
            unit, unitLabel, isGroup = R.RememberedTextMovementScope()
            settingScope = isGroup and ("gf_" .. tostring(unit)) or unit
        end
    end
    if not unit or not unitLabel then return nil end

    if not textKind then textKind, settingKindLabel = R.TextSettingFromText(actionable) end
    local attrs = TEXT_MOVEMENT_ATTRS[textKind]
    if not attrs then return nil end
    settingKindLabel = settingKindLabel or attrs.kindLabel
    if type(subject) ~= "table" then
        local namesPlainText = actionable:match("%f[%a]name%f[%A]") ~= nil
        if not namesPlainText and not R.ContainsAny(actionable, {
            "name text", "unit name", "health text", "hp text", "power text", "mana text",
            "energy text", "rage text", "status text", "dead text", "offline text",
        }) then
            return nil
        end
    end
    if R.ContainsAny(actionable, {
        "font size", "text size", "smaller", "bigger", "larger", "shrink", "enlarge",
    }) then
        return nil
    end

    local firstWord = actionable:match("^(%S+)")
    -- Fixed anchor values belong to an Anchor enum, not to relative X/Y
    -- offsets. In particular, "position ... top left" must never become a
    -- silent ten-pixel left nudge.
    -- A movement verb ("move/drag/nudge the name to the left") is a relative
    -- offset, not a fixed anchor.  Only "position ... to the left" or a bare
    -- "name to the left" is a cardinal anchor.  The movement-verb set lives in
    -- one place (A.HasNudgeMovementVerb) so the parser and this router path can
    -- never drift apart -- that drift is exactly what let "move name to the
    -- left" silently set the Name Text Anchor.
    local hasMovementVerb = type(A.HasNudgeMovementVerb) == "function" and A.HasNudgeMovementVerb(text)
    local plainCardinalAnchor = R.TextMovementNumberCount(text) == 0
        and R.ContainsAny(actionable, { "to the left", "to the right" })
        and not hasMovementVerb
        and not R.ContainsAny(actionable, { "more to", "further", " by " })
    local fixedAnchorRequested = firstWord == "position" or plainCardinalAnchor
        or R.ContainsAny(actionable, { " anchor", "center", "centre", "middle", "to top", "to bottom" })
    local fixedAnchorValue
    if fixedAnchorRequested then
        if R.ContainsAny(actionable, { "top left", "upper left" }) then fixedAnchorValue = "TOPLEFT"
        elseif R.ContainsAny(actionable, { "top right", "upper right" }) then fixedAnchorValue = "TOPRIGHT"
        elseif R.ContainsAny(actionable, { "bottom left", "lower left" }) then fixedAnchorValue = "BOTTOMLEFT"
        elseif R.ContainsAny(actionable, { "bottom right", "lower right" }) then fixedAnchorValue = "BOTTOMRIGHT"
        elseif R.ContainsAny(actionable, { "top center", "top centre", "upper center", "upper centre" }) then fixedAnchorValue = "TOP"
        elseif R.ContainsAny(actionable, { "center", "centre", "middle" }) then fixedAnchorValue = "CENTER"
        elseif R.ContainsAny(actionable, { "left" }) then fixedAnchorValue = "LEFT"
        elseif R.ContainsAny(actionable, { "right" }) then fixedAnchorValue = "RIGHT"
        elseif R.ContainsAny(actionable, { "top", "upper" }) then fixedAnchorValue = "TOP"
        elseif R.ContainsAny(actionable, { "bottom", "lower" }) then fixedAnchorValue = "BOTTOM" end
    end
    if fixedAnchorValue and not isGroup then
        fixedAnchorValue = ({
            LEFT = "FRAMELEFT",
            CENTER = "FRAMECENTER",
            RIGHT = "FRAMERIGHT",
        })[fixedAnchorValue] or fixedAnchorValue
    end

    local hasLeft = R.ContainsAny(actionable, { "left", "to the left" })
    local hasRight = R.ContainsAny(actionable, { "right", "to the right" })
    local hasDown = R.ContainsAny(actionable, { "down", "lower", "lower down", "further down" })
    local hasUp = R.ContainsAny(actionable, { "up", "higher", "raise", "raise up", "further up" })
    local horizontalDirection = hasLeft ~= hasRight and (hasLeft and "left" or "right") or nil
    local verticalDirection = hasDown ~= hasUp and (hasDown and "down" or "up") or nil
    local conflictingDirections = (hasLeft and hasRight) or (hasDown and hasUp)
    local direction = not conflictingDirections and (horizontalDirection or verticalDirection) or nil

    local hasMovementVerb = R.ContainsAny(actionable, {
        "move", "nudge", "shift", "position", "reposition", "offset",
    })
    if not hasMovementVerb and not direction then return nil end

    local readOnly = norm:match("^how%s+do%s+i%s+") ~= nil
        or norm:match("^how%s+can%s+i%s+") ~= nil
        or norm:match("^where%s+") ~= nil
        or norm:match("^can%s+i%s+") ~= nil
        or norm:match("^show%s+me%s+where%s+") ~= nil
        or norm:match("^help%s+me%s+find%s+") ~= nil
        or norm:match("^help%s+me%s+locate%s+") ~= nil
        or norm:find("help me find", 1, true) ~= nil
        or norm:find("help me locate", 1, true) ~= nil

    local axis
    if R.ContainsAny(actionable, { "x offset", "horizontal" }) or direction == "left" or direction == "right" then
        axis = "x"
    elseif R.ContainsAny(actionable, { "y offset", "vertical" }) or direction == "up" or direction == "down" then
        axis = "y"
    end

    local amount = R.TextMovementAmount(text)
    local numberCount = R.TextMovementNumberCount(text)
    local horizontalAmount = horizontalDirection
        and R.TextMovementAmountForDirection(text, horizontalDirection) or nil
    local verticalAmount = verticalDirection
        and R.TextMovementAmountForDirection(text, verticalDirection) or nil
    if numberCount == 1 then
        horizontalAmount = horizontalAmount or amount
        verticalAmount = verticalAmount or amount
    end
    local amountMappingAmbiguous = numberCount > 1 and (
        (horizontalDirection and verticalDirection and (horizontalAmount == nil or verticalAmount == nil))
        or (not (horizontalDirection and verticalDirection))
    )
    local noun = tostring(unit) .. " " .. tostring(attrs.noun)
    return {
        unit = unit,
        unitLabel = unitLabel,
        textKind = textKind,
        label = tostring(unitLabel) .. " " .. tostring(settingKindLabel),
        noun = noun,
        xKey = tostring(settingScope) .. "." .. tostring(attrs.x),
        yKey = tostring(settingScope) .. "." .. tostring(attrs.y),
        anchorKey = (isGroup and attrs.anchorGroup or attrs.anchorUnit)
            and (tostring(settingScope) .. "." .. tostring(isGroup and attrs.anchorGroup or attrs.anchorUnit)) or nil,
        fixedAnchorValue = fixedAnchorValue,
        fixedAnchorRequested = fixedAnchorRequested and true or false,
        direction = direction,
        horizontalDirection = horizontalDirection,
        verticalDirection = verticalDirection,
        conflictingDirections = conflictingDirections and true or false,
        amount = amount,
        horizontalAmount = horizontalAmount,
        verticalAmount = verticalAmount,
        numberCount = numberCount,
        amountMappingAmbiguous = amountMappingAmbiguous and true or false,
        axis = axis,
        readOnly = readOnly,
    }
end

function R.IsAbsoluteTextOffsetAssignment(text, intent)
    if type(intent) ~= "table" or intent.readOnly or intent.direction
        or intent.conflictingDirections or intent.numberCount ~= 1
        or (intent.axis ~= "x" and intent.axis ~= "y")
    then
        return false
    end
    local parser = A.Parser or {}
    local actionable = type(parser.ActionableText) == "function" and parser.ActionableText(text) or text
    actionable = R.Normalize(actionable)
    if actionable == "" or actionable:find(" by ", 1, true) then return false end
    if not (actionable:match("^set%s+") or actionable:match("^change%s+")
        or actionable:match("^adjust%s+") or actionable:match("^configure%s+")
        or actionable:match("^make%s+"))
    then
        return false
    end
    return actionable:match("%f[%a]" .. tostring(intent.axis) .. "%s+offset%f[%A]") ~= nil
end

function R.TextMovementFixedAnchorResult(intent)
    if type(intent) ~= "table" or not intent.fixedAnchorValue then return nil end
    local item = intent.anchorKey and R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(intent.anchorKey) or nil
    local setting = item and item.setting
    local validValue
    if setting and setting.type == "enum" then
        for i = 1, #(setting.values or {}) do
            if tostring(setting.values[i]):upper() == tostring(intent.fixedAnchorValue):upper() then
                validValue = setting.values[i]
                break
            end
        end
    end
    if validValue and intent.readOnly then
        return {
            text = tostring(item.label or setting.label) .. " is the exact fixed-position control for " .. tostring(intent.label)
                .. ". I kept it unchanged. Ask me to open it or say 'set " .. tostring(intent.noun)
                .. " anchor to " .. tostring(validValue):lower() .. "'.",
            status = "info",
            summary = "Explains the exact fixed text-anchor control.",
            searchResults = R.RegistryLocationResultFollowups({ { item = item, score = 10000, rawScore = 10000 } }, 1),
        }
    end
    if validValue and type(A.ExecutePlan) == "function" then
        return A.ExecutePlan({
            kind = "changes",
            changes = { { setting = setting, value = validValue } },
            label = "Position " .. tostring(intent.label) .. " " .. tostring(validValue):lower(),
            summary = "Changes the exact fixed text-anchor option.",
            sourceText = "set " .. tostring(setting.label or setting.key) .. " to " .. tostring(validValue),
        })
    end
    return R.TextMovementMissingAnchorGuidance(intent)
end

-- Guidance for a fixed-anchor request the object cannot satisfy. It is split
-- out of the result path so the follow-up engine can answer a pronoun
-- reference such as "anchor it to the left" about the object the user really
-- means, without routing through the applying branches above.
function R.TextMovementMissingAnchorGuidance(intent)
    if type(intent) ~= "table" or not intent.fixedAnchorValue then return nil end
    local item = intent.anchorKey and R.RegistrySettingItemForKey
        and R.RegistrySettingItemForKey(intent.anchorKey) or nil
    local setting = item and item.setting
    -- A satisfiable request is not this function's business: leave it to the
    -- applying path so an external caller can never turn a real anchor change
    -- into a refusal.
    if setting and setting.type == "enum" then
        for i = 1, #(setting.values or {}) do
            if tostring(setting.values[i]):upper() == tostring(intent.fixedAnchorValue):upper() then return nil end
        end
    end
    local requestedAxis = intent.axis
    intent.axis = nil
    local guidance = R.TextMovementGuidance(intent, true)
    intent.axis = requestedAxis
    if not guidance then return nil end
    guidance.status = "ambiguous"
    guidance.result = "ambiguous"
    -- Which of the two cases applies changes what the user should do next.
    -- "No anchor control at all" tells them to stop looking for one; "not
    -- that choice" means the control exists and only the value was wrong.
    local lead = item ~= nil
        and (tostring(intent.label) .. " does not have that fixed anchor choice in MSUF. I kept it unchanged.")
        or (tostring(intent.label) .. " has no anchor control in MSUF. Its position comes from its X and Y offsets, and I kept it unchanged.")
    guidance.text = lead .. "\n"
        .. tostring(guidance.text or "Use its X Offset and Y Offset controls to place it instead.")
    guidance.summary = "Offers the supported text-position controls instead of guessing an anchor."
    return guidance
end

function R.TextMovementFollowupResults(intent)
    if type(intent) ~= "table" then return nil end
    local entries = {}
    local keys = intent.axis == "x" and { intent.xKey }
        or intent.axis == "y" and { intent.yKey }
        or { intent.xKey, intent.yKey }
    for _, key in ipairs(keys) do
        local item = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(key) or nil
        if item then entries[#entries + 1] = { item = item, score = 10000, rawScore = 10000 } end
    end
    if #entries == 0 then return nil end
    return R.RegistryLocationResultFollowups and R.RegistryLocationResultFollowups(entries, #entries) or nil
end

function R.TextMovementGuidance(intent, readOnly)
    if type(intent) ~= "table" then return nil end
    local xItem = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(intent.xKey) or nil
    local yItem = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(intent.yKey) or nil
    if not xItem and not yItem then return nil end
    if not readOnly and type(A.StartPendingFlow) == "function" then
        A.StartPendingFlow("settingMovement", {
            label = intent.label,
            noun = intent.noun,
            xKey = intent.xKey,
            yKey = intent.yKey,
            page = (xItem and xItem.page) or (yItem and yItem.page),
            step = 10,
        })
    end
    local lines = {
        (readOnly and "Absolutely — here is where to move " or "Absolutely — I found ") .. tostring(intent.label) .. ".",
    }
    if xItem and intent.axis ~= "y" then lines[#lines + 1] = tostring(xItem.label) .. " moves it left or right." end
    if yItem and intent.axis ~= "x" then lines[#lines + 1] = tostring(yItem.label) .. " moves it up or down." end
    if intent.amountMappingAmbiguous then
        lines[#lines + 1] = "I found more than one amount, but could not safely pair every amount with one axis, so I kept both offsets unchanged. Say for example 'up 5 and right 10', or cancel."
    elseif readOnly then
        lines[#lines + 1] = "I kept it unchanged. Ask me to open the horizontal or vertical control, or say for example 'move " .. tostring(intent.noun) .. " down 5'."
    else
        lines[#lines + 1] = "Which way should I move it? Reply Up, Down, Left, or Right; you can include an amount, such as 'down 5'. You can also say 'open horizontal', 'open vertical', or cancel."
    end
    return {
        text = table.concat(lines, "\n"),
        status = readOnly and "info" or "ambiguous",
        result = readOnly and "info" or "ambiguous",
        summary = readOnly and "Explains the exact text position controls." or "Guides an exact text position adjustment.",
        searchResults = R.TextMovementFollowupResults(intent),
    }
end

function R.TryTextMovementConversation(text, coreHandler)
    local intent = R.TextMovementIntent(text)
    if not intent then return nil end
    -- "set ... X/Y offset to N" is an absolute registry assignment, not a
    -- direction-less relative movement request. Let the deterministic parser
    -- own it even when the Knowledge index is cold and an alias lookup cannot
    -- yet resolve labels such as "name text" to "Name Y Offset".
    if R.IsAbsoluteTextOffsetAssignment(text, intent) and type(coreHandler) == "function" then
        local result = coreHandler(text)
        if result and not A.RouterIsUnknownResult(result) then return result end
    end
    if intent.fixedAnchorValue then return R.TextMovementFixedAnchorResult(intent) end
    if intent.readOnly or not intent.direction or intent.conflictingDirections or intent.amountMappingAmbiguous then
        return R.TextMovementGuidance(intent, intent.readOnly)
    end
    if intent.horizontalDirection and intent.verticalDirection then
        local xItem = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(intent.xKey) or nil
        local yItem = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(intent.yKey) or nil
        local xSetting = xItem and xItem.setting
        local ySetting = yItem and yItem.setting
        if xSetting and ySetting and type(A.ExecutePlan) == "function" then
            local xAmount = math.abs(tonumber(intent.horizontalAmount) or tonumber(intent.amount) or 10)
            local yAmount = math.abs(tonumber(intent.verticalAmount) or tonumber(intent.amount) or 10)
            if xAmount == 0 or yAmount == 0 then return R.TextMovementGuidance(intent, false) end
            local xDelta = intent.horizontalDirection == "left" and -xAmount or xAmount
            local yDelta = intent.verticalDirection == "down" and -yAmount or yAmount
            return A.ExecutePlan({
                kind = "changes",
                changes = {
                    { setting = xSetting, relativeDelta = xDelta, direction = intent.horizontalDirection },
                    { setting = ySetting, relativeDelta = yDelta, direction = intent.verticalDirection },
                },
                label = "Move " .. tostring(intent.label) .. " "
                    .. tostring(intent.verticalDirection) .. " and " .. tostring(intent.horizontalDirection),
                summary = "Moves both exact text-position axes in one atomic Assistant change.",
                sourceText = "move " .. tostring(intent.noun) .. " " .. tostring(intent.verticalDirection)
                    .. " " .. tostring(yAmount) .. " and " .. tostring(intent.horizontalDirection)
                    .. " " .. tostring(xAmount),
            })
        end
        return R.TextMovementGuidance(intent, false)
    end
    -- The exact text-offset key is already known here. Apply the one-axis
    -- nudge directly just like the atomic two-axis path above; handing the
    -- canonical sentence back to the generic parser would cold-build three
    -- broad registry indices before reaching this same setting.
    local settingKey = (intent.direction == "left" or intent.direction == "right")
        and intent.xKey or intent.yKey
    local registry = A.Registry
    local directSetting = registry and type(registry.GetSetting) == "function"
        and registry:GetSetting(settingKey) or nil
    if directSetting and directSetting.type == "number" and type(A.ExecutePlan) == "function" then
        local amount = math.abs(tonumber(intent.amount) or 10)
        if amount == 0 then return R.TextMovementGuidance(intent, false) end
        local delta = (intent.direction == "left" or intent.direction == "down") and -amount or amount
        return A.ExecutePlan({
            kind = "changes",
            changes = { { setting = directSetting, relativeDelta = delta, direction = intent.direction } },
            label = "Move " .. tostring(intent.label) .. " " .. tostring(intent.direction),
            summary = "Moves the exact text-position offset.",
            sourceText = "move " .. tostring(intent.noun) .. " " .. tostring(intent.direction)
                .. " " .. tostring(amount),
        })
    end
    if type(coreHandler) ~= "function" then return nil end
    local canonical = "move " .. tostring(intent.noun) .. " " .. tostring(intent.direction)
    if intent.amount then canonical = canonical .. " " .. tostring(intent.amount) end
    local result = coreHandler(canonical)
    if result and not A.RouterIsUnknownResult(result) then return result end
    return R.TextMovementGuidance(intent, false)
end

-- Cast-bar root movement has four reviewed per-unit X/Y settings. Resolve
-- that small fixed family directly instead of asking the generic registry
-- parser to build its exact, light-candidate, and full-alias indices on the
-- first Assistant request. Component words deliberately fail closed so
-- "move the castbar icon/text" keeps its existing specialist route.
function R.CastbarMovementIntent(text)
    local norm = R.Normalize(text)
    if norm == "" or not R.ContainsAny(norm, { "castbar", "cast bar" }) then return nil end
    if type(A.RouterIsFailClosedReadOnlyRequest) == "function"
        and A.RouterIsFailClosedReadOnlyRequest(text)
    then
        return nil
    end

    local parser = A.Parser or {}
    local actionable = type(parser.ActionableText) == "function" and parser.ActionableText(text) or norm
    actionable = R.Normalize(actionable):gsub("^the%s+", "")
    if R.ContainsAny(actionable, {
        "castbar icon", "cast bar icon", "spell icon", "castbar text", "cast bar text",
        "spell text", "spell name", "cast time", "time text", "timer text", "target name",
        "width", "height", "size", "font", "texture", "border", "fill direction", "anchor",
    }) then
        return nil
    end
    if not R.ContainsAny(actionable, {
        "move", "nudge", "shift", "position", "reposition", "raise", "lower",
    }) then
        return nil
    end

    local unit, unitLabel = R.UnitScopeFromText(actionable)
    if not unit then unit, unitLabel = R.UnitScopeFromText(norm) end
    if unit ~= "player" and unit ~= "target" and unit ~= "focus" and unit ~= "boss" then return nil end

    local hasLeft = R.ContainsAny(actionable, { "left", "to the left" })
    local hasRight = R.ContainsAny(actionable, { "right", "to the right" })
    local hasDown = R.ContainsAny(actionable, { "down", "lower", "lower down", "further down" })
    local hasUp = R.ContainsAny(actionable, { "up", "higher", "raise", "further up" })
    local conflictingDirections = (hasLeft and hasRight) or (hasDown and hasUp)
    local horizontal = hasLeft ~= hasRight and (hasLeft and "left" or "right") or nil
    local vertical = hasDown ~= hasUp and (hasDown and "down" or "up") or nil
    if not conflictingDirections and not horizontal and not vertical then return nil end

    local data = A.CastbarsRegistry and A.CastbarsRegistry.CASTBAR_KEYS
    local keys = type(data) == "table" and data[unit] or nil
    local attribute = horizontal and not vertical and keys and keys.x
        or vertical and not horizontal and keys and keys.y
    if not keys then return nil end
    local numberCount = R.TextMovementNumberCount(text)
    local amount = R.TextMovementAmount(text)
    local horizontalAmount = horizontal and R.TextMovementAmountForDirection(text, horizontal) or nil
    local verticalAmount = vertical and R.TextMovementAmountForDirection(text, vertical) or nil
    if numberCount == 1 then
        horizontalAmount = horizontalAmount or amount
        verticalAmount = verticalAmount or amount
    end
    local amountMappingAmbiguous = numberCount > 1 and (
        (horizontal and vertical and (horizontalAmount == nil or verticalAmount == nil))
        or not (horizontal and vertical)
    )
    return {
        unit = unit,
        unitLabel = unitLabel or (unit:sub(1, 1):upper() .. unit:sub(2)),
        direction = horizontal or vertical,
        settingKey = attribute and ("general." .. tostring(attribute)) or nil,
        xKey = keys.x and ("general." .. tostring(keys.x)) or nil,
        yKey = keys.y and ("general." .. tostring(keys.y)) or nil,
        horizontalDirection = horizontal,
        verticalDirection = vertical,
        conflictingDirections = conflictingDirections and true or false,
        amountMappingAmbiguous = amountMappingAmbiguous and true or false,
        amount = amount,
        horizontalAmount = horizontalAmount,
        verticalAmount = verticalAmount,
    }
end

function R.TryCastbarMovementConversation(text)
    local intent = R.CastbarMovementIntent(text)
    if not intent then return nil end
    if intent.conflictingDirections or intent.amountMappingAmbiguous then
        if type(A.StartPendingFlow) == "function" then
            A.StartPendingFlow("settingMovement", {
                label = tostring(intent.unitLabel) .. " Castbar",
                noun = tostring(intent.unit) .. " castbar",
                xKey = intent.xKey,
                yKey = intent.yKey,
                step = 10,
            })
        end
        return {
            text = intent.conflictingDirections
                and "Those castbar directions conflict on the same axis, so I kept both offsets unchanged. Pick one of Left/Right and one of Up/Down, or say cancel."
                or "I found more than one amount for one castbar axis, so I kept both offsets unchanged. Give one amount with its direction, or say cancel.",
            status = "ambiguous",
            result = "ambiguous",
            summary = "Clarifies an exact castbar movement without guessing a direction or amount.",
        }
    end
    local registry = A.Registry
    if intent.horizontalDirection and intent.verticalDirection then
        local xSetting = registry and type(registry.GetSetting) == "function"
            and registry:GetSetting(intent.xKey) or nil
        local ySetting = registry and type(registry.GetSetting) == "function"
            and registry:GetSetting(intent.yKey) or nil
        if not (xSetting and xSetting.type == "number" and ySetting and ySetting.type == "number")
            or type(A.ExecutePlan) ~= "function"
        then
            return nil
        end
        local xAmount = math.abs(tonumber(intent.horizontalAmount) or tonumber(intent.amount)
            or tonumber(xSetting.moveStep) or 10)
        local yAmount = math.abs(tonumber(intent.verticalAmount) or tonumber(intent.amount)
            or tonumber(ySetting.moveStep) or 10)
        if xAmount == 0 or yAmount == 0 then return nil end
        return A.ExecutePlan({
            kind = "changes",
            changes = {
                {
                    setting = xSetting,
                    relativeDelta = intent.horizontalDirection == "left" and -xAmount or xAmount,
                    direction = intent.horizontalDirection,
                },
                {
                    setting = ySetting,
                    relativeDelta = intent.verticalDirection == "down" and -yAmount or yAmount,
                    direction = intent.verticalDirection,
                },
            },
            label = "Move " .. tostring(intent.unitLabel) .. " Castbar "
                .. tostring(intent.verticalDirection) .. " and " .. tostring(intent.horizontalDirection),
            summary = "Moves both exact per-unit cast-bar offsets in one atomic Assistant change.",
            sourceText = "move " .. tostring(intent.unit) .. " castbar " .. tostring(intent.verticalDirection)
                .. " " .. tostring(yAmount) .. " and " .. tostring(intent.horizontalDirection)
                .. " " .. tostring(xAmount),
        })
    end
    local setting = registry and type(registry.GetSetting) == "function"
        and registry:GetSetting(intent.settingKey) or nil
    if not setting or setting.type ~= "number" or type(A.ExecutePlan) ~= "function" then return nil end

    local amount = math.abs(tonumber(intent.amount) or tonumber(setting.moveStep) or 10)
    if amount == 0 then return nil end
    local delta = (intent.direction == "left" or intent.direction == "down") and -amount or amount
    return A.ExecutePlan({
        kind = "changes",
        changes = { { setting = setting, relativeDelta = delta, direction = intent.direction } },
        label = "Move " .. tostring(intent.unitLabel) .. " Castbar " .. tostring(intent.direction),
        summary = "Moves the exact per-unit cast-bar offset.",
        sourceText = "move " .. tostring(intent.unit) .. " castbar " .. tostring(intent.direction)
            .. " " .. tostring(amount),
    })
end

-- Cast-bar detail movement has a small, fixed ownership matrix: each of the
-- four supported cast bars exposes independent X/Y offsets for its icon,
-- spell text, and time text. Resolve that matrix before the root cast-bar
-- shortcut so a natural request such as "move boss castbar icon down 5"
-- cannot silently lose "icon" and move the whole cast bar instead.
local CASTBAR_COMPONENT_MOVEMENT_KEYS = {
    player = {
        icon = { x = "general.castbarPlayerIconOffsetX", y = "general.castbarPlayerIconOffsetY", position = "general.castbarPlayerIconPosition" },
        spell = { x = "general.castbarPlayerTextOffsetX", y = "general.castbarPlayerTextOffsetY" },
        time = { x = "general.castbarPlayerTimeOffsetX", y = "general.castbarPlayerTimeOffsetY" },
    },
    target = {
        icon = { x = "general.castbarTargetIconOffsetX", y = "general.castbarTargetIconOffsetY", position = "general.castbarTargetIconPosition" },
        spell = { x = "general.castbarTargetTextOffsetX", y = "general.castbarTargetTextOffsetY" },
        time = { x = "general.castbarTargetTimeOffsetX", y = "general.castbarTargetTimeOffsetY" },
    },
    focus = {
        icon = { x = "general.castbarFocusIconOffsetX", y = "general.castbarFocusIconOffsetY", position = "general.castbarFocusIconPosition" },
        spell = { x = "general.castbarFocusTextOffsetX", y = "general.castbarFocusTextOffsetY" },
        time = { x = "general.castbarFocusTimeOffsetX", y = "general.castbarFocusTimeOffsetY" },
    },
    boss = {
        icon = { x = "general.bossCastIconOffsetX", y = "general.bossCastIconOffsetY", position = "general.bossCastIconPosition" },
        spell = { x = "general.bossCastTextOffsetX", y = "general.bossCastTextOffsetY" },
        time = { x = "general.bossCastTimeOffsetX", y = "general.bossCastTimeOffsetY" },
    },
}

function R.CastbarIconFixedPositionIntent(text)
    local norm = R.Normalize(text)
    if norm == "" or not R.ContainsAny(norm, { "castbar", "cast bar" }) then return nil end
    if type(A.RouterIsFailClosedReadOnlyRequest) == "function"
        and A.RouterIsFailClosedReadOnlyRequest(text)
    then
        return nil
    end

    local parser = A.Parser or {}
    local actionable = type(parser.ActionableText) == "function" and parser.ActionableText(text) or norm
    actionable = R.Normalize(actionable):gsub("^the%s+", "")
    if not R.ContainsAny(actionable, {
        "castbar icon", "cast bar icon", "spell icon", "cast icon",
    }) then
        return nil
    end
    -- Relative movement owns move/nudge/shift/offset wording. Fixed placement
    -- owns put/place/set/position wording, so "move icon right" continues to
    -- mean an X nudge while "put icon on the right" means the RIGHT enum.
    if R.ContainsAny(actionable, {
        "move", "nudge", "shift", "reposition", "offset", "x offset", "y offset",
        "raise", "lower",
    }) then
        return nil
    end
    if not R.ContainsAny(actionable, {
        "put", "place", "set", "position", "placement", "on the", "to the", "in the",
    }) then
        return nil
    end
    if actionable:match("%f[%d][%+%-]?%d") then return nil end

    local hasLeft = R.ContainsAny(actionable, { "left", "on the left", "to the left", "inside left" })
    local hasRight = R.ContainsAny(actionable, { "right", "on the right", "to the right", "inside right" })
    if hasLeft == hasRight then return nil end
    local inside = R.ContainsAny(actionable, { "inside", "inside left", "inside right" })
    local value = hasLeft and (inside and "INSIDE_LEFT" or "LEFT")
        or (inside and "INSIDE_RIGHT" or "RIGHT")

    local unit, unitLabel = R.UnitScopeFromText(actionable)
    if not unit then unit, unitLabel = R.UnitScopeFromText(norm) end
    local unitKeys = unit and CASTBAR_COMPONENT_MOVEMENT_KEYS[unit] or nil
    local settingKey = unitKeys and unitKeys.icon and unitKeys.icon.position or nil
    if not settingKey then return nil end
    return {
        unit = unit,
        unitLabel = unitLabel or (unit:sub(1, 1):upper() .. unit:sub(2)),
        settingKey = settingKey,
        value = value,
    }
end

function R.TryCastbarIconFixedPositionConversation(text)
    local intent = R.CastbarIconFixedPositionIntent(text)
    if not intent or type(A.ExecutePlan) ~= "function" then return nil end
    local registry = A.Registry
    local setting = registry and type(registry.GetSetting) == "function"
        and registry:GetSetting(intent.settingKey) or nil
    if not setting or (setting.type ~= "enum" and setting.type ~= "string") then return nil end
    return A.ExecutePlan({
        kind = "changes",
        changes = { { setting = setting, value = intent.value } },
        label = "Set " .. tostring(intent.unitLabel) .. " Castbar Icon Position",
        summary = "Sets the exact per-unit cast-bar icon position preset.",
        sourceText = "set " .. tostring(intent.unit) .. " castbar icon position to "
            .. tostring(intent.value):lower():gsub("_", " "),
    })
end

function R.CastbarComponentMovementIntent(text)
    local norm = R.Normalize(text)
    if norm == "" or not R.ContainsAny(norm, { "castbar", "cast bar" }) then return nil end
    if type(A.RouterIsFailClosedReadOnlyRequest) == "function"
        and A.RouterIsFailClosedReadOnlyRequest(text)
    then
        return nil
    end

    local parser = A.Parser or {}
    local actionable = type(parser.ActionableText) == "function" and parser.ActionableText(text) or norm
    actionable = R.Normalize(actionable):gsub("^the%s+", "")
    if not R.ContainsAny(actionable, {
        "move", "nudge", "shift", "reposition", "raise", "lower",
    }) then
        return nil
    end
    -- Fixed-position enums (for example Icon Position = INSIDE_RIGHT) are not
    -- relative movement. Keep those on their typed registry route.
    if R.ContainsAny(actionable, {
        "icon position", "spell icon position", "spell text position", "spell name position",
        "time text position", "cast time position", "timer position", "anchor",
    }) then
        return nil
    end

    local unit, unitLabel = R.UnitScopeFromText(actionable)
    if not unit then unit, unitLabel = R.UnitScopeFromText(norm) end
    local unitKeys = unit and CASTBAR_COMPONENT_MOVEMENT_KEYS[unit] or nil
    if not unitKeys then return nil end

    local component, componentLabel, componentNoun
    if R.ContainsAny(actionable, {
        "castbar icon", "cast bar icon", "spell icon", "cast icon",
    }) then
        component, componentLabel, componentNoun = "icon", "Icon", "castbar icon"
    elseif R.ContainsAny(actionable, {
        "time text", "timer text", "cast time", "castbar time", "cast bar time",
        "castbar timer", "cast bar timer",
    }) then
        component, componentLabel, componentNoun = "time", "Time Text", "castbar time text"
    elseif R.ContainsAny(actionable, {
        "spell text", "spell name", "castbar text", "cast bar text",
        "castbar name", "cast bar name", "cast text",
    }) then
        component, componentLabel, componentNoun = "spell", "Spell Text", "castbar spell text"
    end
    local keys = component and unitKeys[component] or nil
    if not keys then return nil end

    local hasLeft = R.ContainsAny(actionable, { "left", "to the left" })
    local hasRight = R.ContainsAny(actionable, { "right", "to the right" })
    local hasDown = R.ContainsAny(actionable, { "down", "lower", "lower down", "further down" })
    local hasUp = R.ContainsAny(actionable, { "up", "higher", "raise", "raise up", "further up" })
    local conflictingDirections = (hasLeft and hasRight) or (hasDown and hasUp)
    local horizontal = hasLeft ~= hasRight and (hasLeft and "left" or "right") or nil
    local vertical = hasDown ~= hasUp and (hasDown and "down" or "up") or nil
    if not conflictingDirections and not horizontal and not vertical then return nil end

    local amount = R.TextMovementAmount(text)
    local numberCount = R.TextMovementNumberCount(text)
    local horizontalAmount = horizontal and R.TextMovementAmountForDirection(text, horizontal) or nil
    local verticalAmount = vertical and R.TextMovementAmountForDirection(text, vertical) or nil
    if numberCount == 1 then
        horizontalAmount = horizontalAmount or amount
        verticalAmount = verticalAmount or amount
    end
    local amountMappingAmbiguous = numberCount > 1 and (
        (horizontal and vertical and (horizontalAmount == nil or verticalAmount == nil))
        or not (horizontal and vertical)
    )

    return {
        unit = unit,
        unitLabel = unitLabel or (unit:sub(1, 1):upper() .. unit:sub(2)),
        componentLabel = componentLabel,
        componentNoun = componentNoun,
        xKey = keys.x,
        yKey = keys.y,
        horizontalDirection = horizontal,
        verticalDirection = vertical,
        conflictingDirections = conflictingDirections and true or false,
        amountMappingAmbiguous = amountMappingAmbiguous and true or false,
        amount = amount,
        horizontalAmount = horizontalAmount,
        verticalAmount = verticalAmount,
    }
end

function R.TryCastbarComponentMovementConversation(text)
    local intent = R.CastbarComponentMovementIntent(text)
    if not intent or type(A.ExecutePlan) ~= "function" then return nil end
    local registry = A.Registry
    if not registry or type(registry.GetSetting) ~= "function" then return nil end

    if intent.conflictingDirections or intent.amountMappingAmbiguous then
        if type(A.StartPendingFlow) == "function" then
            A.StartPendingFlow("settingMovement", {
                label = tostring(intent.unitLabel) .. " Castbar " .. tostring(intent.componentLabel),
                noun = tostring(intent.unit) .. " " .. tostring(intent.componentNoun),
                xKey = intent.xKey,
                yKey = intent.yKey,
                step = 10,
            })
        end
        return {
            text = intent.conflictingDirections
                and "Those castbar component directions conflict on the same axis, so I kept both offsets unchanged. Pick one of Left/Right and one of Up/Down, or say cancel."
                or "I found more than one amount, but could not safely pair every amount with one castbar component axis, so I kept both offsets unchanged. Say for example 'up 5 and right 10', or cancel.",
            status = "ambiguous",
            result = "ambiguous",
            summary = "Clarifies an exact castbar component movement without guessing an axis.",
        }
    end

    local xSetting = intent.horizontalDirection and registry:GetSetting(intent.xKey) or nil
    local ySetting = intent.verticalDirection and registry:GetSetting(intent.yKey) or nil
    if (intent.horizontalDirection and (not xSetting or xSetting.type ~= "number"))
        or (intent.verticalDirection and (not ySetting or ySetting.type ~= "number"))
    then
        return nil
    end

    local stepSetting = xSetting or ySetting
    local fallbackAmount = math.abs(tonumber(intent.amount) or tonumber(stepSetting and stepSetting.moveStep) or 10)
    local xAmount = math.abs(tonumber(intent.horizontalAmount) or fallbackAmount)
    local yAmount = math.abs(tonumber(intent.verticalAmount) or fallbackAmount)
    if xAmount == 0 or yAmount == 0 then return nil end
    local changes = {}
    if xSetting then
        changes[#changes + 1] = {
            setting = xSetting,
            relativeDelta = intent.horizontalDirection == "left" and -xAmount or xAmount,
            direction = intent.horizontalDirection,
        }
    end
    if ySetting then
        changes[#changes + 1] = {
            setting = ySetting,
            relativeDelta = intent.verticalDirection == "down" and -yAmount or yAmount,
            direction = intent.verticalDirection,
        }
    end
    local directions = intent.horizontalDirection and intent.verticalDirection
        and (intent.verticalDirection .. " and " .. intent.horizontalDirection)
        or (intent.horizontalDirection or intent.verticalDirection)
    return A.ExecutePlan({
        kind = "changes",
        changes = changes,
        label = "Move " .. tostring(intent.unitLabel) .. " Castbar "
            .. tostring(intent.componentLabel) .. " " .. tostring(directions),
        summary = #changes == 2
            and "Moves both exact cast-bar component offset axes in one atomic Assistant change."
            or "Moves the exact per-unit cast-bar component offset.",
        sourceText = "move " .. tostring(intent.unit) .. " " .. tostring(intent.componentNoun)
            .. (intent.verticalDirection and (" " .. tostring(intent.verticalDirection) .. " " .. tostring(yAmount)) or "")
            .. (intent.horizontalDirection and (" " .. tostring(intent.horizontalDirection) .. " " .. tostring(xAmount)) or ""),
    })
end

function R.IncompleteMovementSubject(text)
    local parser = A.Parser or {}
    local actionable = type(parser.ActionableText) == "function" and parser.ActionableText(text) or text
    actionable = R.Normalize(actionable)
    local verb, subject = actionable:match("^(%S+)%s+(.+)$")
    if not verb or not subject or not ({
        move = true, nudge = true, shift = true, position = true, reposition = true,
    })[verb] then return nil end
    if actionable:match("%d") or R.ContainsAny(actionable, {
        "left", "right", "up", "down", "above", "below", "over", "under", "higher", "lower",
        "x offset", "y offset", "horizontal", "vertical",
    }) then
        return nil
    end
    subject = R.Trim(subject:gsub("^the%s+", ""))
    if subject == "" then return nil end
    if R.ContainsAny(subject, { "frame", "frames", "unit frame", "group frame" })
        and not R.ContainsAny(subject, {
            "text", "name", "health", "hp", "power", "mana", "portrait", "buff", "debuff", "aura",
            "icon", "marker", "indicator", "cast bar", "castbar", "resource", "totem",
        })
    then
        return nil
    end
    return subject
end

function R.IncompleteMovementEntries(subject)
    subject = R.Normalize(subject)
    if subject == "" then return nil end
    subject = subject:gsub("%f[%a]buffs%f[%A]", "buff")
        :gsub("%f[%a]debuffs%f[%A]", "debuff")
        :gsub("%f[%a]auras%f[%A]", "aura")
        :gsub("%f[%a]classpower%f[%A]", "class resource")
        :gsub("%f[%a]class%s+power%f[%A]", "class resource")
        :gsub("%f[%a]readycheck%f[%A]", "ready check")
        :gsub("%f[%a]raidmarker%f[%A]", "raid marker")
        :gsub("%f[%a]castbar%f[%A]", "cast bar")
    local settings = R.EnsureCompleteSettingRegistry()
    if type(settings) ~= "table" then return nil end
    local cached = R._incompleteMovementEntryCache
    if type(cached) == "table" and cached.subject == subject and cached.count == #settings then
        return cached.entries ~= false and cached.entries or nil
    end

    -- The old implementation performed four full 4.5k-setting searches (and
    -- repeated all four again on a miss later in the same route). Do one
    -- bounded registry pass, rank the four geometry families, and retain only
    -- the last scalar subject result. This is submit-time/LoD work only.
    local subjectWords = R.CompactRegistrySettingTokens(subject)
    if #subjectWords == 0 then return nil end
    local auraSubject = R.ContainsAny(subject, { "buff", "debuff", "aura" })
    local requestedKind, requestedScope, requestedLabel
    local requestedUnit, requestedUnitLabel = R.UnitScopeFromText(subject)
    if requestedUnit then
        requestedKind, requestedScope, requestedLabel = "unit", requestedUnit, requestedUnitLabel
    else
        local requestedGroup, requestedGroupLabel = R.GroupScopeFromText(subject)
        if requestedGroup then requestedKind, requestedScope, requestedLabel = "group", requestedGroup, requestedGroupLabel end
    end
    local familyRank = auraSubject
        and { growth = 4, offset = 3, position = 2, anchor = 1 }
        or { offset = 4, position = 3, anchor = 2, growth = 1 }
    local entries = {}
    for i = 1, #settings do
        if i % 64 == 0 and type(A.MaybeYield) == "function" then A.MaybeYield() end
        local setting = settings[i]
        local candidateText = R.CompactRegistrySettingLabel(setting and setting.label or "")
        local padded = " " .. candidateText .. " "
        local ownsSubject = candidateText ~= ""
        for j = 1, #subjectWords do
            if not padded:find(" " .. subjectWords[j] .. " ", 1, true) then
                ownsSubject = false
                break
            end
        end
        if ownsSubject then
            local rank
            for family, value in pairs(familyRank) do
                if padded:find(" " .. family .. " ", 1, true) and (not rank or value > rank) then rank = value end
            end
            if rank then
                local item = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(setting.key) or nil
                local scopeScore = item and R.RegistryItemScopeScore(item, requestedKind, requestedScope, requestedLabel) or 0
                if item and (not requestedScope or scopeScore > 0) then
                    local wordCount = 0
                    for _ in candidateText:gmatch("%S+") do wordCount = wordCount + 1 end
                    local specificity = math.max(0, 80 - math.max(0, wordCount - #subjectWords) * 10)
                    entries[#entries + 1] = {
                        score = 10000 + rank * 100 + specificity,
                        rawScore = 10000 + rank * 100 + specificity,
                        item = item,
                    }
                end
            end
        end
    end
    table.sort(entries, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        return tostring(a.item and a.item.label or "") < tostring(b.item and b.item.label or "")
    end)
    while #entries > 8 do entries[#entries] = nil end
    local result = #entries > 0 and entries or false
    R._incompleteMovementEntryCache = { subject = subject, count = #settings, entries = result }
    return result ~= false and result or nil
end

function R.TryIncompleteMovementConversation(text)
    local subject = R.IncompleteMovementSubject(text)
    if not subject then return nil end
    local entries = R.IncompleteMovementEntries(subject)
    if not entries then return nil end
    if type(A.RouterClearPendingResultsForRoute) == "function" then A.RouterClearPendingResultsForRoute() end
    local visible = math.min(6, #entries)
    local canonicalSubject = R.Normalize(subject):gsub("%f[%a]buffs%f[%A]", "buff")
        :gsub("%f[%a]debuffs%f[%A]", "debuff"):gsub("%f[%a]auras%f[%A]", "aura")
        :gsub("%f[%a]classpower%f[%A]", "class resource"):gsub("%f[%a]class%s+power%f[%A]", "class resource")
        :gsub("%f[%a]readycheck%f[%A]", "ready check"):gsub("%f[%a]raidmarker%f[%A]", "raid marker")
        :gsub("%f[%a]castbar%f[%A]", "cast bar")
    local movementKeys = {}
    for i = 1, visible do
        local item = entries[i] and entries[i].item
        local label = R.Normalize(item and item.label or "")
        local key = tostring(item and (item.settingKey or item.key) or "")
        if label == canonicalSubject .. " growth" then movementKeys.growthKey, movementKeys.growthChoice = key, i end
        if label == canonicalSubject .. " x offset" or label == canonicalSubject .. " offset x"
            or label == canonicalSubject .. " icon x offset"
        then
            movementKeys.xKey, movementKeys.xChoice = key, i
        end
        if label == canonicalSubject .. " y offset" or label == canonicalSubject .. " offset y"
            or label == canonicalSubject .. " icon y offset"
        then
            movementKeys.yKey, movementKeys.yChoice = key, i
        end
    end
    if movementKeys.xKey and movementKeys.yKey and type(A.StartPendingFlow) == "function" then
        A.StartPendingFlow("componentMovement", {
            label = canonicalSubject,
            noun = canonicalSubject,
            xKey = movementKeys.xKey,
            yKey = movementKeys.yKey,
            growthKey = movementKeys.growthKey,
            xChoice = movementKeys.xChoice,
            yChoice = movementKeys.yChoice,
            growthChoice = movementKeys.growthChoice,
            page = entries[1] and entries[1].item and entries[1].item.page,
            step = 10,
        })
    end
    local lines = {
        "I found several MSUF controls that can move or arrange " .. tostring(subject) .. ", so I kept everything unchanged. Which one did you mean?",
    }
    for i = 1, visible do lines[#lines + 1] = R.RegistryLocationLine(i, entries[i].item) end
    if #entries > visible then lines[#lines + 1] = "Add a detail such as growth direction, anchor, X offset, or Y offset and I will narrow it further." end
    if movementKeys.xKey and movementKeys.yKey then
        lines[#lines + 1] = "Say left, right, up, or down (optionally with an amount) to move the whole component. Reply with a listed number to choose its exact control."
    else
        lines[#lines + 1] = "Reply with a number, or ask me to open one."
    end
    return {
        text = table.concat(lines, "\n"),
        status = "ambiguous",
        result = "ambiguous",
        summary = "Clarifies an incomplete movement request with exact MSUF controls.",
        searchResults = R.RegistryLocationResultFollowups(entries, visible),
    }
end

function R.ActionableMutationText(text)
    local parser = A.Parser or {}
    if type(parser.ActionableText) ~= "function" then return nil end
    local norm = R.Normalize(text)
    local actionable = R.Normalize(parser.ActionableText(text))
    if actionable == "" or actionable == norm then return nil end
    if norm:match("^how%s+do%s+i%s+") or norm:match("^how%s+can%s+i%s+")
        or norm:match("^where%s+") or norm:match("^can%s+i%s+")
        or norm:match("^show%s+me%s+where%s+")
        or norm:match("^help%s+me%s+find%s+") or norm:match("^help%s+me%s+locate%s+")
    then
        return nil
    end
    return actionable
end

function R.TryConversationalMutation(text, coreHandler)
    local norm = R.Normalize(text)
    if norm:find("target s target", 1, true)
        or norm:find("target's target", 1, true)
        or norm:find("targets target", 1, true)
        or (norm:find("target target", 1, true) and norm:find("on target frame", 1, true))
    then
        return nil
    end
    local movement = R.TryTextMovementConversation(text, coreHandler)
    if movement then return movement end
    local castbarIconPosition = R.TryCastbarIconFixedPositionConversation(text)
    if castbarIconPosition then return castbarIconPosition end
    local castbarComponentMovement = R.TryCastbarComponentMovementConversation(text)
    if castbarComponentMovement then return castbarComponentMovement end
    local castbarMovement = R.TryCastbarMovementConversation(text)
    if castbarMovement then return castbarMovement end
    local incompleteMovement = R.TryIncompleteMovementConversation(text)
    if incompleteMovement then return incompleteMovement end

    local actionable = R.ActionableMutationText(text)
    if not actionable then return nil end
    local openEnded = R.TryOpenEndedSettingIdea and R.TryOpenEndedSettingIdea(actionable, coreHandler)
    if openEnded then return openEnded end
    if not R.HasUnmistakableMutationRequest(actionable) then return nil end
    local result = type(coreHandler) == "function" and coreHandler(actionable) or nil
    if result and not A.RouterIsUnknownResult(result) then return result end
    return nil
end

function R.LooksLikeUnitNameTextRequest(norm)
    norm = R.Normalize(norm)
    if norm == "" or not R.ContainsAny(norm, { "name", "names", "unit name" }) then return false end
    if R.ContainsAny(norm, {
        "castbar", "cast bar", "spell name", "cast name",
        "aura", "auras", "buff", "buffs", "debuff", "debuffs",
        "profile", "profiles", "profile name",
        "ellipsis", "no ellipsis", "truncate", "truncation",
    }) then
        return false
    end
    local unit = R.UnitScopeFromText(norm)
    return unit ~= nil
end

function R.TextPowerSettingFollowupResults(unit, unitLabel, textKind, settingLabel)
    unit = tostring(unit or "")
    unitLabel = tostring(unitLabel or "")
    textKind = tostring(textKind or "")
    settingLabel = tostring(settingLabel or "")
    local key
    if textKind == "name" then
        key = unit .. ".showName"
    elseif textKind == "health" then
        key = unit .. ".showHP"
    elseif textKind == "power" then
        key = unit .. ".showPowerText"
    elseif textKind == "status" then
        key = unit .. ".statusTextEnabled"
    end
    if key and key ~= "." then
        return R.SettingFollowupResults(key, settingLabel) or R.SettingFollowupResultsByQuery(settingLabel, settingLabel)
    end
    if textKind == "font" and unitLabel ~= "" then
        local fontLabel = unitLabel .. " Font Size"
        return R.SettingFollowupResultsByQuery(fontLabel, fontLabel) or R.SettingFollowupResultsByQuery(settingLabel, settingLabel)
    end
    if settingLabel ~= "" then return R.SettingFollowupResultsByQuery(settingLabel, settingLabel) end
    return nil
end

function R.UnitPageFollowupResults(unit, unitLabel, description)
    unit = tostring(unit or "")
    unitLabel = tostring(unitLabel or "")
    local unitPages = {
        player = "uf_player",
        target = "uf_target",
        focus = "uf_focus",
        pet = "uf_pet",
        boss = "uf_boss",
        targettarget = "uf_targettarget",
        focustarget = "uf_focustarget",
    }
    local page = unitPages[unit]
    if not page then return nil end
    local pageLabel = A.DisplayPageLabel and A.DisplayPageLabel(page, unitLabel ~= "" and unitLabel or "MSUF page") or unitLabel
    return {
        {
            kind = "page",
            key = page,
            label = pageLabel or unitLabel or page,
            page = page,
            pageLabel = pageLabel,
            description = description,
            canOpen = true,
            canExplain = true,
        },
    }
end

function R.PageFollowupResults(page, pageLabel, description)
    page = tostring(page or "")
    if page == "" then return nil end
    pageLabel = tostring(pageLabel or "")
    if pageLabel == "" and A.DisplayPageLabel then pageLabel = A.DisplayPageLabel(page, "MSUF page") end
    if pageLabel == "" then pageLabel = "MSUF page" end
    return {
        {
            kind = "page",
            key = page,
            label = pageLabel,
            page = page,
            pageLabel = pageLabel,
            description = description,
            canOpen = true,
            canExplain = true,
        },
    }
end

function R.PowerBarSettingFollowupResults(unit, settingLabel, norm)
    unit = tostring(unit or "")
    settingLabel = tostring(settingLabel or "")
    norm = R.Normalize(norm)
    local key = unit .. ".showPowerBar"
    if R.ContainsAny(norm, { "detach", "detaches", "detached", "separate", "undock", "own bar" })
        or settingLabel:find("Detach Power Bar", 1, true)
    then
        key = unit .. ".powerBarDetached"
    elseif R.ContainsAny(norm, { "x offset", "left", "right" }) then
        key = unit .. ".detachedPowerBarOffsetX"
    elseif R.ContainsAny(norm, { "y offset", "up", "down" }) then
        key = unit .. ".detachedPowerBarOffsetY"
    end
    if key ~= "." then
        return R.SettingFollowupResults(key, settingLabel) or R.SettingFollowupResultsByQuery(settingLabel, settingLabel)
    end
    if settingLabel ~= "" then return R.SettingFollowupResultsByQuery(settingLabel, settingLabel) end
    return nil
end

A.RouterTryTextPowerSettingShortcut = function(norm, coreHandler)
    local asksLocation = R.AsksSettingLocation(norm)
    if not asksLocation then return nil end

    local unit, unitLabel = R.UnitScopeFromText(norm)
    if not unit or not unitLabel then return nil end

    local textMovement = R.TextMovementIntent and R.TextMovementIntent(norm) or nil
    if textMovement then
        textMovement.readOnly = true
        return R.TextMovementGuidance(textMovement, true)
    end

    local mentionsPowerBar = R.ContainsAny(norm, A.RouterTextPowerProblemTerms.powerBar)
    if mentionsPowerBar then
        local settingLabel = unitLabel .. " Power Bar"
        if R.ContainsAny(norm, { "detach", "detaches", "detached", "separate", "undock", "own bar" }) then
            settingLabel = unitLabel .. " Detach Power Bar from Frame"
        elseif R.ContainsAny(norm, { "position", "move", "anchor", "offset", "wrong place", "where" }) then
            settingLabel = unitLabel .. " Power Bar Position"
        end
        local bodyPrefix = R.ContainsAny(norm, { "offset", "x offset", "y offset" }) and "Power Bar offset help: " or "Power Bar help: "
        local reply = A.RouterTextPowerProblemReply(
            settingLabel .. " setting location",
            bodyPrefix .. settingLabel .. " lives on the " .. unitLabel .. " page. Open " .. unitLabel .. " and use the power-bar visibility, detach, width, height, anchor, and X/Y offset controls for that unit.",
            "open " .. unit .. "; detach " .. unit .. " power bar; move " .. unit .. " power bar down 8.",
            "Open " .. unitLabel .. " | detach " .. unit .. " power bar"
        )
        reply.status = "info"
        reply.result = "info"
        reply.searchResults = R.PowerBarSettingFollowupResults(unit, settingLabel, norm)
        return reply
    end

    local textKind, settingKindLabel, commandNoun = R.TextSettingFromText(norm)
    local settingLabel = unitLabel .. " " .. settingKindLabel
    if R.ContainsAny(norm, { "format", "percent", "percentage", "current", "current max", "value" }) then
        settingLabel = settingLabel .. " Format"
    end
    if textKind == "font" then
        local reply = A.RouterTextPowerProblemReply(
            settingLabel .. " setting location",
            "Unit frame text help: " .. unitLabel .. " text font sizes live on the " .. unitLabel .. " page. Use " .. unitLabel .. " Name Font Size, " .. unitLabel .. " HP Font Size, and " .. unitLabel .. " Power Font Size depending on which text line you mean.",
            "open " .. unit .. "; set " .. unit .. " name text size to 14; set " .. unit .. " hp text size to 14.",
            "Open " .. unitLabel .. " | set " .. unit .. " name text size to 14"
        )
        reply.status = "info"
        reply.result = "info"
        reply.searchResults = R.TextPowerSettingFollowupResults(unit, unitLabel, textKind, settingLabel)
        return reply
    end
    local reply = A.RouterTextPowerProblemReply(
        settingLabel .. " setting location",
        "Unit frame text help: " .. settingLabel .. " lives on the " .. unitLabel .. " page. Open " .. unitLabel .. " and use the text visibility, slot, format, font size, anchor, and offset controls for that frame.",
        "open " .. unit .. "; " .. ((R.WantsVisibilityOn(norm) and not R.WantsVisibilityOff(norm)) and "turn on " or "turn off ") .. unit .. " " .. commandNoun .. "; set " .. unit .. " " .. commandNoun .. " size to 14.",
        "Open " .. unitLabel .. " | " .. ((R.WantsVisibilityOn(norm) and not R.WantsVisibilityOff(norm)) and "turn on " or "turn off ") .. unit .. " " .. commandNoun
    )
    reply.status = "info"
    reply.result = "info"
    if not R.ContainsAny(norm, { "format", "percent", "percentage", "current", "current max", "value" }) then
        reply.searchResults = R.TextPowerSettingFollowupResults(unit, unitLabel, textKind, settingLabel)
    else
        reply.searchResults = R.UnitPageFollowupResults(unit, unitLabel, "Text format is configured through text slots and related text controls on this unit page.")
    end
    return reply
end

A.RouterTryTextPowerProblemShortcut = function(text, coreHandler)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    if norm:match("^search%s+") or norm:match("^find%s+") or norm:match("^look%s+for%s+")
        or norm:match("^suche%s+") or norm:match("^finde%s+")
    then
        return nil
    end

    local terms = A.RouterTextPowerProblemTerms
    local mentionsText = R.ContainsAny(norm, terms.text) or R.LooksLikeUnitNameTextRequest(norm)
    local mentionsPowerBar = R.ContainsAny(norm, terms.powerBar)
    if not mentionsText and not mentionsPowerBar then return nil end

    local settingResult = A.RouterTryTextPowerSettingShortcut and A.RouterTryTextPowerSettingShortcut(norm, coreHandler)
    if settingResult then return settingResult end

    if norm:match("%d") and R.ContainsAny(norm, R.MUTATION_TERMS)
        and not R.HasNaturalProblemTerm(norm)
        and not R.ContainsAny(norm, terms.format)
        and not R.ContainsAny(norm, terms.position)
    then
        return nil
    end

    if mentionsText and R.ContainsAny(norm, terms.format) then
        return A.RouterTextPowerProblemReply(
            "Text format help",
            "Unit-frame text format is controlled by the text slot and format options for the specific frame. Group-frame text lives in Group Layout. Name the frame and text type before I change it, so I do not overwrite the wrong slot.",
            "set target hp text left current; set player health text to percent; open fonts.",
            "Open Fonts | Open Player | Open Target | Open Group Layout"
        )
    end

    if mentionsText and R.HasNaturalProblemTerm(norm) then
        return A.RouterTextPowerProblemReply(
            "Text visibility help",
            "If frame text is missing, check whether the specific text element is enabled, whether the slot is empty, and whether font size, color, alpha, or range fade makes it unreadable.",
            "set player name font size to 14; show target health text; open fonts.",
            "Open Fonts | Open Player | Open Target | Open Group Layout"
        )
    end

    if mentionsPowerBar and R.ContainsAny(norm, terms.position) then
        return A.RouterTextPowerProblemReply(
            "Power bar position help",
            "Power bar placement depends on whether the bar is attached to the frame or detached. For detached power bars, use width, height, anchor, X offset, and Y offset on the unit-frame page.",
            "open target; move target power bar down 8; attach target power bar to frame.",
            "Open Player | Open Target | Open Bars"
        )
    end

    if mentionsPowerBar and R.HasNaturalProblemTerm(norm) then
        return A.RouterTextPowerProblemReply(
            "Power bar visibility help",
            "Power bars can be hidden by unit visibility, power-bar enable settings, detach settings, opacity, or zero-sized layout. Name the unit if you want me to run the exact check.",
            "check target power bar; check player power bar; open target.",
            "Open Player | Open Target | Open Bars"
        )
    end

    return nil
end

