}

function R.RegistryCurrentValueSubjectTooBroad(subject)
    subject = R.Normalize(subject)
    if subject == "" then return true end
    if R.BROAD_PAGE_LOCATION_SUBJECTS[subject] or R.BROAD_SETTING_EXPLAIN_SUBJECTS[subject] then return true end
    if R.BROAD_CURRENT_VALUE_SUBJECTS[subject] then return true end
    return false
end

function R.RegistryLocationSubject(norm)
    norm = R.Normalize(norm)
    local stripTrailingLocationCopula = norm:match("^show%s+me%s+where%s+") ~= nil
        or norm:match("^tell%s+me%s+where%s+") ~= nil
    local prefixes = {
        "can you help me to find ", "can you help me to locate ",
        "could you help me to find ", "could you help me to locate ",
        "would you help me to find ", "would you help me to locate ",
        "can you help me find ", "can you help me locate ",
        "could you help me find ", "could you help me locate ",
        "would you help me find ", "would you help me locate ",
        "help me to find ", "help me to locate ",
        "how do i use ", "how can i use ",
        "where do i change ", "where can i change ", "where do i set ", "where can i set ",
        "where do i configure ", "where can i configure ", "where do i adjust ", "where can i adjust ",
        "where do i show ", "where can i show ", "where do i hide ", "where can i hide ",
        "where do i display ", "where can i display ",
        "where do i turn on ", "where can i turn on ", "where do i turn off ", "where can i turn off ",
        "where do i enable ", "where can i enable ", "where do i disable ", "where can i disable ",
        "how do i change ", "how can i change ", "how do i set ", "how can i set ",
        "how do i configure ", "how can i configure ", "how do i adjust ", "how can i adjust ",
        "how do i show ", "how can i show ", "how do i hide ", "how can i hide ",
        "how do i display ", "how can i display ",
        "how do i turn on ", "how can i turn on ", "how do i turn off ", "how can i turn off ",
        "how do i enable ", "how can i enable ", "how do i disable ", "how can i disable ",
        "can i turn on ", "can i turn off ", "can i enable ", "can i disable ",
        "can i show ", "can i hide ", "can i display ",
        "is there a way to turn on ", "is there a way to turn off ",
        "is there a way to enable ", "is there a way to disable ",
        "is there a way to show ", "is there a way to hide ", "is there a way to display ",
        "which setting controls ", "what setting controls ",
        "which option controls ", "what option controls ",
        "which control changes ", "what control changes ",
        "which controls ", "what controls ",
        "help me find ", "help me locate ", "show me where ", "tell me where ",
        "where do i find ", "where can i find ", "where is the ", "where is ",
        "which page has ", "what page has ", "which menu has ", "what menu has ",
        "wo kann ich ", "wo finde ich ", "wo ist ", "wo sind ",
        "wie kann ich ", "wie aendere ich ", "welche einstellung steuert ", "welche option steuert ",
    }
    for i = 1, #prefixes do
        local prefix = prefixes[i]
        if norm:sub(1, #prefix) == prefix then
            norm = R.Trim(norm:sub(#prefix + 1))
            break
        end
    end
    norm = norm:gsub("^the%s+", ""):gsub("^die%s+", ""):gsub("^der%s+", ""):gsub("^das%s+", "")
    if stripTrailingLocationCopula then
        -- Natural requests commonly put the verb after the setting name:
        -- "show me where target max name length is".  The trailing verb is
        -- navigation grammar, not part of the registered label or alias.
        norm = norm:gsub("%s+is%s+located$", ""):gsub("%s+is$", "")
            :gsub("%s+are%s+located$", ""):gsub("%s+are$", "")
    end
    norm = norm:gsub("%s+ausblenden$", ""):gsub("%s+einblenden$", "")
        :gsub("%s+aendern$", ""):gsub("%s+einstellen$", ""):gsub("%s+konfigurieren$", "")
        :gsub("%s+finden$", "")
    return R.Trim(norm)
end

function R.LooksLikeBroadPageLocationQuestion(norm)
    local subject = R.RegistryLocationSubject(norm)
    if subject == "" then return false end
    return R.BROAD_PAGE_LOCATION_SUBJECTS[subject] == true
end

