function R.LooksLikeRegistrySettingStateQuestion(norm)
    norm = R.Normalize(norm)
    if norm == "" then return false end
    if not (norm:match("^is%s+") or norm:match("^is%s+the%s+")
        or norm:match("^are%s+") or norm:match("^are%s+the%s+")
        or norm:match("^do%s+") or norm:match("^do%s+i%s+have%s+") or norm:match("^do%s+we%s+have%s+")
        or norm:match("^does%s+") or norm:match("^will%s+")
        or norm:match("^can%s+i%s+see%s+") or norm:match("^can%s+we%s+see%s+")
        or norm:match("^can%s+i%s+se%s+") or norm:match("^can%s+we%s+se%s+"))
    then
        return false
    end
    if not R.ContainsAny(norm, {
        "enabled", "disabled", "visible", "shown", "showing", "hidden",
        "turned on", "turned off", "switched on", "switched off", "on", "off",
        "show", "shows", "shwo", "shwos", "see", "se",
    }) then
        return false
    end
    if R.ContainsAny(norm, { "safe", "needed", "necessary", "recommended", "better", "good", "bad" }) then return false end
    return true
end

function R.RegistryCurrentValueExpectedBoolean(norm)
    norm = R.Normalize(norm)
    if R.ContainsAny(norm, { "disabled", "hidden", "turned off", "turnd off", "turn off", "switched off", "switchd off", "off" }) then return false end
    if R.ContainsAny(norm, { "enabled", "visible", "shown", "showing", "turned on", "turnd on", "turn on", "switched on", "switchd on", "on" }) then return true end
    if R.LooksLikeRegistrySettingStateQuestion(norm)
        and (R.ContainsAny(norm, { "show", "shows", "shwo", "shwos" })
            or norm:match("^can%s+i%s+see%s+") or norm:match("^can%s+we%s+see%s+")
            or norm:match("^can%s+i%s+se%s+") or norm:match("^can%s+we%s+se%s+"))
    then
        return true
    end
    return nil
end

function R.LooksLikeRegistrySettingCurrentValueQuestion(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    if type(R.LooksLikeRegistrySettingDecisionQuestion) == "function"
        and R.LooksLikeRegistrySettingDecisionQuestion(norm)
    then
        -- Recommendation wording can contain state words such as "showing"
        -- or "on".  It still asks for advice, so the decision specialist must
        -- run before the plain current-value reader.
        return false
    end
    if norm:match("^is%s+there%s+") or norm:match("^is%s+it%s+possible%s+to%s+") then return false end
    if A.RouterLooksLikeExplicitSearchRequest and A.RouterLooksLikeExplicitSearchRequest(norm) then return false end
    if norm == "current value" or norm == "value now" then return false end
    if norm:match("^what%s+is%s+the%s+current%s+")
        or norm:match("^tell%s+me%s+the%s+")
        or norm:match("^how%s+wide%s+is%s+")
        or norm:match("^did%s+i%s+set%s+")
        or norm:match("^did%s+we%s+set%s+")
        or norm:match("^is%s+.+%s+[%+%-]?%d+%.?%d*$")
        or norm:match("^was%s+ist%s+.+aktuell")
        or norm:match("^was%s+ist%s+d[ie][er]*%s+aktuell")
        or norm:match("^habe%s+ich%s+.+%s+auf%s+[%+%-]?%d+%.?%d*%s+gesetzt$")
        or norm:match("^ist%s+.+%s+[%+%-]?%d+%.?%d*$")
        or norm:match("^.+%s+current%s+value$")
    then
        local subject = R.RegistryCurrentValueSubject(norm)
        return subject ~= "" and subject ~= norm
    end
    if R.ContainsAny(norm, {
        "current value of", "current value for",
        "current val of", "current val for",
        "curent value of", "curent value for",
        "curent val of", "curent val for",
        "show current value of", "show current value for",
        "show current val of", "show current val for",
        "show curent value of", "show curent value for",
        "show me current value of", "show me current value for",
        "show me current val of", "show me current val for",
        "show me curent value of", "show me curent value for",
        "show the current value of", "show the current value for",
        "show the current val of", "show the current val for",
        "show the curent value of", "show the curent value for",
        "show me the current value of", "show me the current value for",
        "show me the current val of", "show me the current val for",
        "show me the curent value of", "show me the curent value for",
        "get current value of", "get current value for",
        "get current val of", "get current val for",
        "get curent value of", "get curent value for",
        "get the current value of", "get the current value for",
        "get the current val of", "get the current val for",
        "get the curent value of", "get the curent value for",
        "what is the current value of", "what is the current value for",
        "what is the current val of", "what is the current val for",
        "what is the curent value of", "what is the curent value for",
        "what is current value of", "what is current value for",
        "what is current val of", "what is current val for",
        "what is curent value of", "what is curent value for",
        "what value is", "what is the value of", "what is the value for",
    }) then
        local subject = R.RegistryCurrentValueSubject(norm)
        if subject == "" then return false end
        if subject == "it" or subject == "that" or subject == "this" then return false end
        if subject:match("^result%s+%d+") or subject:match("^option%s+%d+") then return false end
        return true
    end
    if (norm:match("^what%s+is%s+") or norm:match("^what%s+are%s+") or norm:match("^what%s+s%s+") or norm:match("^whats%s+"))
        and R.ContainsAny(norm, { "set to", "set at", "currently", "right now" })
    then
        local subject = R.RegistryCurrentValueSubject(norm)
        if subject == "" or subject == norm then return false end
        if subject == "it" or subject == "that" or subject == "this" then return false end
        if subject:match("^result%s+%d+") or subject:match("^option%s+%d+") then return false end
        return true
    end
    if (norm:match("^is%s+") or norm:match("^is%s+the%s+") or norm:match("^are%s+") or norm:match("^are%s+the%s+"))
        and R.ContainsAny(norm, { "enabled", "disabled", "visible", "shown", "showing", "hidden", "on", "off" })
        and not R.ContainsAny(norm, { "safe", "needed", "necessary", "recommended", "better", "good", "bad" })
    then
        local subject = R.RegistryCurrentValueSubject(norm)
        if subject == "" or subject == norm then return false end
        if subject == "it" or subject == "that" or subject == "this" then return false end
        if subject:match("^result%s+%d+") or subject:match("^option%s+%d+") then return false end
        return true
    end
    if R.LooksLikeRegistrySettingStateQuestion(norm) then
        local subject = R.RegistryCurrentValueSubject(norm)
        if subject == "" or subject == norm then return false end
        if subject == "it" or subject == "that" or subject == "this" then return false end
        if subject:match("^result%s+%d+") or subject:match("^option%s+%d+") then return false end
        return true
    end
    return false
end

function R.LooksLikeRegistrySettingExplainQuestion(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    if A.RouterLooksLikeExplicitSearchRequest and A.RouterLooksLikeExplicitSearchRequest(norm) then return false end
    if R.ContainsAny(norm, { "why are", "why is my", "why are my", "not showing", "missing", "doesnt work", "doesn't work" }) then return false end
    if not R.ContainsAny(norm, {
        "what does", "what is", "explain", "describe", "tell me about",
        "why would i use", "why should i use", "why would i change", "why should i change",
    }) then
        return false
    end
    local subject = R.RegistryExplainSubject(norm)
    if subject == "" then return false end
    if R.BROAD_PAGE_LOCATION_SUBJECTS[subject] then return false end
    if R.BROAD_SETTING_EXPLAIN_SUBJECTS[subject] then return false end
    if subject:find("where", 1, true) then return false end
    if subject:match("^result%s+%d+") or subject:match("^option%s+%d+") then return false end
    return true
end

local NATURAL_DECISION_QUALITIES = {
    "good", "better", "safe", "sensible", "reasonable", "useful",
    "recommended", "necessary", "needed", "bad", "okay", "ok", "fine",
    "acceptable", "advisable",
}

local NATURAL_DECISION_DIMENSIONS = {
    wide = "width", wider = "width", narrow = "width", narrower = "width",
    tall = "height", taller = "height", short = "height", shorter = "height",
    big = "size", bigger = "size", large = "size", larger = "size",
    small = "size", smaller = "size",
}

local function CleanNaturalDecisionSubject(subject)
    subject = R.Trim(subject or "")
    subject = subject:gsub("^my%s+", ""):gsub("^the%s+", "")
    local prefixes = {
        "i am setting ", "i am changing ", "i am making ", "i am adjusting ",
        "i set ", "i change ", "i make ", "i adjust ",
        "we set ", "we change ", "we make ", "we adjust ",
        "turning on ", "turning off ", "turn on ", "turn off ",
        "showing ", "hiding ", "show ", "hide ",
        "enabling ", "disabling ", "enable ", "disable ",
        "using ", "keeping ", "use ", "keep ",
        "setting ", "changing ", "making ", "adjusting ",
        "set ", "change ", "make ", "adjust ", "leave ",
    }
    for i = 1, #prefixes do
        local prefix = prefixes[i]
        if subject:sub(1, #prefix) == prefix then
            subject = R.Trim(subject:sub(#prefix + 1))
            break
        end
    end
    subject = subject:gsub("%s+to%s+[%+%-]?%d+%.?%d*$", "")
        :gsub("%s+at%s+[%+%-]?%d+%.?%d*$", "")
        :gsub("%s+was%s+[%+%-]?%d+%.?%d*$", "")
    return subject
end

function R.NaturalRegistryDecisionSubject(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    local number = "[%+%-]?%d+%.?%d*"

    local subject = norm:match("^is%s+(.+)%s+a%s+good%s+idea$")
        or norm:match("^is%s+it%s+a%s+good%s+idea%s+to%s+(.+)$")
        or norm:match("^is%s+it%s+worth%s+(.+)$")
        or norm:match("^is%s+(.+)%s+worth%s+enabling$")
        or norm:match("^is%s+(.+)%s+worth%s+disabling$")
        or norm:match("^is%s+(.+)%s+worth%s+showing$")
        or norm:match("^is%s+(.+)%s+worth%s+hiding$")
        or norm:match("^do%s+you%s+think%s+i%s+should%s+(.+)$")
        or norm:match("^do%s+you%s+think%s+(.+)%s+should%s+be%s+on$")
        or norm:match("^do%s+you%s+think%s+(.+)%s+should%s+be%s+off$")
        or norm:match("^do%s+you%s+think%s+(.+)%s+should%s+be%s+enabled$")
        or norm:match("^do%s+you%s+think%s+(.+)%s+should%s+be%s+disabled$")
        or norm:match("^do%s+you%s+think%s+(.+)%s+should%s+be%s+" .. number .. "$")
        or norm:match("^would%s+it%s+be%s+better%s+if%s+i%s+(.+)$")
        or norm:match("^would%s+it%s+be%s+better%s+if%s+(.+)%s+was%s+" .. number .. "$")
        or norm:match("^would%s+it%s+help%s+to%s+(.+)$")
        or norm:match("^could%s+" .. number .. "%s+work%s+for%s+(.+)$")
        or norm:match("^is%s+" .. number .. "%s+too%s+much%s+for%s+(.+)$")
        or norm:match("^is%s+(.+)%s+" .. number .. "%s+too%s+much$")
        or norm:match("^do%s+i%s+need%s+(.+)%s+on$")
        or norm:match("^do%s+i%s+need%s+(.+)%s+off$")
        or norm:match("^do%s+i%s+need%s+(.+)%s+enabled$")
        or norm:match("^do%s+i%s+need%s+(.+)%s+disabled$")
        or norm:match("^do%s+i%s+really%s+need%s+to%s+(.+)$")
        or norm:match("^would%s+you%s+keep%s+(.+)%s+on$")
        or norm:match("^would%s+you%s+keep%s+(.+)%s+off$")
        or norm:match("^should%s+we%s+(.+)$")
        or norm:match("^should%s+i%s+leave%s+(.+)%s+on$")
        or norm:match("^should%s+i%s+leave%s+(.+)%s+off$")
        or norm:match("^what%s+if%s+i%s+(.+)$")
        or norm:match("^what%s+if%s+we%s+(.+)$")
        or norm:match("^how%s+about%s+(.+)$")
    if subject then return CleanNaturalDecisionSubject(subject) end

    for i = 1, #NATURAL_DECISION_QUALITIES do
        local quality = NATURAL_DECISION_QUALITIES[i]
        subject = norm:match("^is%s+" .. number .. "%s+a%s+" .. quality .. "%s+(.+)$")
            or norm:match("^do%s+you%s+think%s+" .. number .. "%s+is%s+a%s+" .. quality .. "%s+(.+)$")
            or norm:match("^do%s+you%s+think%s+(.+)%s+at%s+" .. number .. "%s+is%s+" .. quality .. "$")
            or norm:match("^is%s+" .. number .. "%s+" .. quality .. "%s+for%s+(.+)$")
            or norm:match("^would%s+" .. number .. "%s+be%s+" .. quality .. "%s+for%s+(.+)$")
            or norm:match("^is%s+(.+)%s+" .. number .. "%s+a%s+" .. quality .. "%s+value$")
            or norm:match("^is%s+(.+)%s+" .. number .. "%s+" .. quality .. "$")
            or norm:match("^is%s+(.+)%s+" .. quality .. "%s+at%s+" .. number .. "$")
            or norm:match("^is%s+(.+)%s+" .. quality .. "%s+on$")
            or norm:match("^is%s+(.+)%s+" .. quality .. "%s+off$")
            or norm:match("^is%s+it%s+" .. quality .. "%s+to%s+(.+)$")
            or norm:match("^would%s+(.+)%s+" .. number .. "%s+be%s+" .. quality .. "$")
            or norm:match("^would%s+(.+)%s+be%s+" .. quality .. "%s+on$")
            or norm:match("^would%s+(.+)%s+be%s+" .. quality .. "%s+off$")
            or norm:match("^would%s+(.+)%s+on%s+be%s+" .. quality .. "$")
            or norm:match("^would%s+(.+)%s+off%s+be%s+" .. quality .. "$")
            or norm:match("^would%s+(.+)%s+be%s+" .. quality .. "$")
            or norm:match("^is%s+(.+)%s+on%s+" .. quality .. "$")
            or norm:match("^is%s+(.+)%s+off%s+" .. quality .. "$")
            or norm:match("^is%s+(.+)%s+" .. quality .. "$")
        if subject then return CleanNaturalDecisionSubject(subject) end
    end

    subject = norm:match("^do%s+you%s+recommend%s+(.+)%s+" .. number .. "$")
        or norm:match("^do%s+you%s+recommend%s+(.+)$")
        or norm:match("^would%s+you%s+recommend%s+(.+)%s+" .. number .. "$")
        or norm:match("^would%s+you%s+recommend%s+(.+)$")
        or norm:match("^would%s+you%s+suggest%s+(.+)%s+" .. number .. "$")
        or norm:match("^would%s+you%s+suggest%s+(.+)$")
        or norm:match("^what%s+(.+)%s+do%s+you%s+recommend$")
        or norm:match("^should%s+(.+)%s+be%s+" .. number .. "$")
        or norm:match("^should%s+(.+)%s+be%s+on$")
        or norm:match("^should%s+(.+)%s+be%s+off$")
        or norm:match("^should%s+(.+)%s+be%s+enabled$")
        or norm:match("^should%s+(.+)%s+be%s+disabled$")
    if subject then return CleanNaturalDecisionSubject(subject) end

    for adjective, dimension in pairs(NATURAL_DECISION_DIMENSIONS) do
        subject = norm:match("^is%s+" .. number .. "%s+too%s+" .. adjective .. "%s+for%s+(.+)$")
            or norm:match("^would%s+" .. number .. "%s+be%s+too%s+" .. adjective .. "%s+for%s+(.+)$")
            or norm:match("^will%s+" .. number .. "%s+be%s+too%s+" .. adjective .. "%s+for%s+(.+)$")
            or norm:match("^is%s+my%s+(.+)%s+too%s+" .. adjective .. "$")
            or norm:match("^is%s+(.+)%s+too%s+" .. adjective .. "$")
        if subject then
            subject = CleanNaturalDecisionSubject(subject)
            if not R.HasNormalizedPhrase(subject, dimension) then
                subject = subject:gsub("%s+frame$", "")
                subject = R.Trim(subject .. " " .. dimension)
            end
            return subject
        end
    end

    subject = norm:match("^is%s+(.+)%s+too%s+high%s+at%s+" .. number .. "$")
        or norm:match("^is%s+(.+)%s+too%s+low%s+at%s+" .. number .. "$")
        or norm:match("^is%s+(.+)%s+too%s+high$")
        or norm:match("^is%s+(.+)%s+too%s+low$")
    if subject then return CleanNaturalDecisionSubject(subject) end
    return nil
end

function R.RegistryDecisionSubject(norm)
    norm = R.Normalize(norm)
    local naturalSubject = R.NaturalRegistryDecisionSubject(norm)
    if naturalSubject then return naturalSubject end
    -- How-to and lookup scaffolding carries zero setting information but
    -- poisons the knowledge search ("how do i get rounded corners on my
    -- frames" scores 0; the same words without the scaffold land on Rounded
    -- Frame Texture). Strip the interrogative shell before subject matching.
    local howto = norm:match("^how%s+do%s+i%s+(.+)$") or norm:match("^how%s+can%s+i%s+(.+)$")
        or norm:match("^how%s+do%s+you%s+(.+)$") or norm:match("^how%s+would%s+i%s+(.+)$")
        or norm:match("^how%s+to%s+(.+)$")
        or norm:match("^where%s+do%s+i%s+(.+)$") or norm:match("^where%s+can%s+i%s+(.+)$")
        or norm:match("^show%s+me%s+the%s+(.+)$") or norm:match("^show%s+me%s+(.+)$")
        or norm:match("^wie%s+kann%s+ich%s+(.+)$") or norm:match("^wie%s+mache%s+ich%s+(.+)$")
        or norm:match("^wie%s+bekomme%s+ich%s+(.+)$") or norm:match("^wo%s+finde%s+ich%s+(.+)$")
    if howto then norm = R.Trim(howto) end
    local whatDoes = norm:match("^what%s+does%s+(.+)%s+do%s+on%s+the%s+.+%s+page$")
        or norm:match("^what%s+does%s+(.+)%s+do$")
        or norm:match("^was%s+macht%s+(.+)$")
    if whatDoes then norm = R.Trim(whatDoes) end
    local property, scope = norm:match("^what%s+(.+)%s+do%s+you%s+recommend%s+for%s+(.+)$")
    if property and scope then return R.Trim(scope .. " " .. property) end
    local directSubject = norm:match("^what%s+do%s+you%s+recommend%s+for%s+(.+)$")
        or norm:match("^which%s+(.+)%s+do%s+you%s+recommend$")
        or norm:match("^welche%s+(.+)%s+empfiehlst%s+du$")
        or norm:match("^welchen%s+(.+)%s+empfiehlst%s+du$")
    if directSubject then norm = directSubject end
    local prefixes = {
        "should i set ", "should i change ", "should i make ", "should i adjust ",
        "should i turn on ", "should i turn off ", "should i enable ", "should i disable ",
        "should i show ", "should i hide ", "should i use ", "should i keep ",
        "do i need to turn on ", "do i need to turn off ", "do i need to enable ", "do i need to disable ",
        "do i need to show ", "do i need to hide ", "do i need to use ",
        "do i need the ", "do i need ",
        "is it safe to turn on ", "is it safe to turn off ", "is it safe to enable ", "is it safe to disable ",
        "is it safe to show ", "is it safe to hide ", "is it safe to use ",
        "would it be safe to turn on ", "would it be safe to turn off ",
        "would it be safe to enable ", "would it be safe to disable ",
        "would it be safe to show ", "would it be safe to hide ", "would it be safe to use ",
        "would it be better to set ", "would it be better to change ",
        "would it be better to make ", "would it be better to adjust ",
        "would it be better to turn on ", "would it be better to turn off ",
        "would it be better to enable ", "would it be better to disable ",
        "would it be better to show ", "would it be better to hide ",
        "would it be better to use ", "would it be better to keep ",
        "would it be better with ", "would i be better off with ",
        "would it be better if ", "would i be better with ",
        "soll ich ", "sollte ich ", "darf ich ",
    }
    local stripBareNumericValue = false
    for i = 1, #prefixes do
        local prefix = prefixes[i]
        if norm:sub(1, #prefix) == prefix then
            norm = R.Trim(norm:sub(#prefix + 1))
            stripBareNumericValue = prefix == "would it be better with "
                or prefix == "would i be better off with "
                or prefix == "would i be better with "
            break
        end
    end
    norm = norm:gsub("%s+to%s+[%+%-]?%d+%.?%d*$", "")
    norm = norm:gsub("%s+at%s+[%+%-]?%d+%.?%d*$", "")
        :gsub("%s+were%s+[%+%-]?%d+%.?%d*$", "")
    if stripBareNumericValue then
        norm = norm:gsub("%s+[%+%-]?%d+%.?%d*$", "")
    end
    norm = norm:gsub("%s+were%s+on$", ""):gsub("%s+were%s+off$", "")
        :gsub("%s+were%s+enabled$", ""):gsub("%s+were%s+disabled$", "")
    norm = norm:gsub("%s+auf%s+[%+%-]?%d+%.?%d*%s+setzen$", "")
        :gsub("%s+auf%s+[%+%-]?%d+%.?%d*%s+aendern$", "")
        :gsub("%s+auf%s+[%+%-]?%d+%.?%d*$", "")
    norm = norm:gsub("%s+setzen$", ""):gsub("%s+aendern$", "")
    norm = norm:gsub("^the%s+", "")
    return R.Trim(norm)
end

function R.RegistryCurrentValueExpectedNumber(norm)
    norm = R.Normalize(norm)
    local raw = norm:match("^did%s+i%s+set%s+.+%s+to%s+([%+%-]?%d+%.?%d*)$")
        or norm:match("^did%s+we%s+set%s+.+%s+to%s+([%+%-]?%d+%.?%d*)$")
        or norm:match("^is%s+.+%s+([%+%-]?%d+%.?%d*)$")
        or norm:match("^habe%s+ich%s+.+%s+auf%s+([%+%-]?%d+%.?%d*)%s+gesetzt$")
        or norm:match("^haben%s+wir%s+.+%s+auf%s+([%+%-]?%d+%.?%d*)%s+gesetzt$")
        or norm:match("^ist%s+.+%s+([%+%-]?%d+%.?%d*)$")
    return raw and tonumber(raw) or nil
end

function R.RegistryDecisionProposedNumber(norm)
    norm = R.Normalize(norm)
    local number = "([%+%-]?%d+%.?%d*)"
    local raw = norm:match("^is%s+" .. number .. "%s+a%s+")
        or norm:match("^do%s+you%s+think%s+" .. number .. "%s+is%s+")
        or norm:match("^do%s+you%s+think%s+.+%s+should%s+be%s+" .. number .. "$")
        or norm:match("^do%s+you%s+think%s+.+%s+at%s+" .. number .. "%s+is%s+")
        or norm:match("^is%s+" .. number .. "%s+.+%s+for%s+")
        or norm:match("^is%s+.+%s+" .. number .. "%s+a%s+.+%s+value$")
        or norm:match("^is%s+.+%s+" .. number .. "%s+[%a]+$")
        or norm:match("^is%s+.+%s+[%a]+%s+at%s+" .. number .. "$")
        or norm:match("^is%s+" .. number .. "%s+too%s+")
        or norm:match("^is%s+.+%s+" .. number .. "%s+too%s+much$")
        or norm:match("^is%s+.+%s+too%s+[%a]+%s+at%s+" .. number .. "$")
        or norm:match("^would%s+" .. number .. "%s+be%s+too%s+")
        or norm:match("^would%s+" .. number .. "%s+be%s+[%a]+%s+for%s+")
        or norm:match("^will%s+" .. number .. "%s+be%s+too%s+")
        or norm:match("^could%s+" .. number .. "%s+work%s+for%s+")
        or norm:match("^would%s+.+%s+" .. number .. "%s+be%s+")
        or norm:match("^do%s+you%s+recommend%s+.+%s+" .. number .. "$")
        or norm:match("^would%s+you%s+recommend%s+.+%s+" .. number .. "$")
        or norm:match("^would%s+you%s+suggest%s+.+%s+" .. number .. "$")
        or norm:match("^should%s+.+%s+be%s+" .. number .. "$")
        or norm:match("%s+to%s+" .. number .. "$")
        or norm:match("%s+at%s+" .. number .. "$")
        or norm:match("%s+were%s+" .. number .. "$")
        or norm:match("%s+was%s+" .. number .. "$")
        or norm:match("^would%s+it%s+be%s+better%s+with%s+.+%s+" .. number .. "$")
        or norm:match("^would%s+i%s+be%s+better%s+off%s+with%s+.+%s+" .. number .. "$")
    return raw and tonumber(raw) or nil
end

function R.LooksLikeRegistrySettingDecisionQuestion(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    if A.RouterLooksLikeExplicitSearchRequest and A.RouterLooksLikeExplicitSearchRequest(norm) then return false end
    -- "Where should I go ..." asks for a menu location.  The word "should"
    -- must not promote that navigation request into the advice lane before
    -- scoped page help gets a chance to answer it.
    if R.ContainsAny(norm, { "where should i go", "where should i go to", "where should i go for" }) then
        return false
    end
    local naturalSubject = R.NaturalRegistryDecisionSubject(norm)
    if naturalSubject then
        -- Bare pronouns need conversational/result context; they are not an
        -- exact setting identity. Let the decision-guidance lane handle them
        -- instead of allowing fuzzy registry search to choose an unrelated
        -- control such as the first setting on a page.
        if naturalSubject == "this" or naturalSubject == "that" or naturalSubject == "it"
            or naturalSubject == "this setting" or naturalSubject == "that setting"
            or naturalSubject == "this option" or naturalSubject == "that option"
            or naturalSubject == "the setting" or naturalSubject == "the option"
        then
            return false
        end
        return true
    end
    if not R.ContainsAny(norm, {
        "should i set", "should i change", "should i make", "should i adjust",
        "should i turn on", "should i turn off", "should i enable", "should i disable",
        "should i show", "should i hide", "should i use", "should i keep",
        "do i need", "do i need to",
        "is it safe to turn on", "is it safe to turn off", "is it safe to enable", "is it safe to disable",
        "is it safe to show", "is it safe to hide", "is it safe to use",
        "would it be safe to turn on", "would it be safe to turn off",
        "would it be safe to enable", "would it be safe to disable",
        "would it be safe to show", "would it be safe to hide", "would it be safe to use",
        "would it be better to set", "would it be better to change",
        "would it be better to make", "would it be better to adjust",
        "would it be better to turn on", "would it be better to turn off",
        "would it be better to enable", "would it be better to disable",
        "would it be better to show", "would it be better to hide",
        "would it be better to use", "would it be better to keep",
        "would it be better with", "would i be better off with",
        "would it be better if", "would i be better with",
        "what do you recommend for", "do you recommend", "which", "recommend for",
        -- Direct comparisons are advice questions too. Without these the
        -- request fell through to the mutation lane, so asking "what's better,
        -- class color or custom color" silently switched the colour mode.
        "whats better", "what is better", "which is better", "which one is better",
        "is it better", "is it better to", "are they better", "is that better",
        "better than", "better or", "or better",
        "worth it", "is it worth", "should we",
        "soll ich", "sollte ich", "darf ich", "empfiehlst du",
        "was ist besser", "welches ist besser", "ist es besser", "besser als",
        "lohnt sich", "lohnt es sich",
    }) then
        return false
    end
    local subject = R.RegistryDecisionSubject(norm)
    if subject == "" or subject == norm then return false end
    if subject:match("^result%s+%d+") or subject:match("^option%s+%d+") then return false end
    return true
end

function R.RegistryTroubleshootingSubject(norm)
    norm = R.Normalize(norm)
    local prefixes = {
        "why cant i see ", "why can't i see ", "why can t i see ", "why can i not see ",
        "why do i not see ", "why dont i see ", "why don't i see ", "why don t i see ",
        "why is my ", "why is the ", "why is ",
        "why are my ", "why are the ", "why are ",
    }
    for i = 1, #prefixes do
        local prefix = prefixes[i]
        if norm:sub(1, #prefix) == prefix then
            norm = R.Trim(norm:sub(#prefix + 1))
            break
        end
    end
    local suffixes = {
        " not showing", " not shown", " not visible", " missing", " hidden",
        " gone", " invisible", " disabled", " turned off",
    }
    for i = 1, #suffixes do
        local suffix = suffixes[i]
        if norm:sub(-#suffix) == suffix then
            norm = R.Trim(norm:sub(1, #norm - #suffix))
            break
        end
    end
    norm = norm:gsub("^the%s+", "")
    return R.Trim(norm)
end

function R.IsBroadTroubleshootingSubject(subject)
    subject = R.Normalize(subject)
    if subject == "" then return true end
    local broad = {
        "player buffs", "target buffs", "focus buffs", "boss buffs", "party buffs", "raid buffs", "mythic raid buffs",
        "player debuffs", "target debuffs", "focus debuffs", "boss debuffs", "party debuffs", "raid debuffs", "mythic raid debuffs",
        "player cast bar", "target cast bar", "focus cast bar", "boss cast bar",
        "player castbar", "target castbar", "focus castbar", "boss castbar",
        "class resource", "class resources", "class power", "class powers",
        "frames", "unit frames", "unitframes", "profile", "profiles",
        "player frame", "target frame", "focus frame", "pet frame",
        "boss frame", "boss frames", "party frames", "raid frames",
        "group frame", "group frames", "mythic raid frames",
    }
    for i = 1, #broad do
        if subject == broad[i] then return true end
    end
    return false
end

function R.LooksLikeRegistrySettingTroubleshootingQuestion(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    if A.RouterLooksLikeExplicitSearchRequest and A.RouterLooksLikeExplicitSearchRequest(norm) then return false end
    local asksWhyCantSee = R.ContainsAny(norm, {
        "why cant i see", "why can't i see", "why can t i see", "why can i not see",
        "why do i not see", "why dont i see", "why don't i see", "why don t i see",
    })
    if not (norm:match("^why%s+") ~= nil or asksWhyCantSee) then
        return false
    end
    if not asksWhyCantSee and not R.ContainsAny(norm, R.VISIBILITY_PROBLEM_TERMS) then return false end
    local subject = R.RegistryTroubleshootingSubject(norm)
    if subject == "" or subject == norm then return false end
    if R.IsBroadTroubleshootingSubject(subject) then return false end
    return true
end

function R.RegistryRequestedScope(norm)
    norm = R.Normalize(norm)
    local groupScope, groupLabel = R.GroupScopeFromText(norm)
    if groupScope then return "group", groupScope, groupLabel end
    local unit, unitLabel = R.UnitFrameScopeFromText and R.UnitFrameScopeFromText(norm) or R.UnitScopeFromText(norm)
    if unit then return "unit", unit, unitLabel end
    return nil, nil, nil
end

function R.RegistryItemScopeScore(item, scopeKind, scope, scopeLabel)
    if not scopeKind or not scope or type(item) ~= "table" then return 0 end
    local setting = item.setting or {}
    local hay = R.Normalize(table.concat({
        tostring(item.label or ""),
        tostring(item.pageLabel or ""),
        tostring(item.page or ""),
        tostring(item.key or ""),
        tostring(setting.key or ""),
        tostring(setting.unit or ""),
        tostring(setting.frameType or ""),
    }, " "))
    local score = 0
    if scopeKind == "unit" then
        if scope == "target" and R.ContainsAny(hay, { "target of target", "targettarget", "focus target", "focustarget" }) then return -800 end
        if scope == "focus" and R.ContainsAny(hay, { "focus target", "focustarget" }) then return -800 end
        if scope == "targettarget" and R.ContainsAny(hay, { "target of target", "targettarget" }) then score = score + 260 end
        if scope == "focustarget" and R.ContainsAny(hay, { "focus target", "focustarget" }) then score = score + 260 end
        if tostring(setting.unit or "") == scope then score = score + 260 end
        if R.ContainsAny(hay, { scope, tostring(scopeLabel or "") }) then score = score + 180 end
        if score == 0 then score = score - 120 end
    elseif scopeKind == "group" then
        if scope == "raid" and R.ContainsAny(hay, { "mythic raid", "mythicraid" }) then score = score - 260 end
        if tostring(setting.unit or "") == scope then score = score + 260 end
        if R.ContainsAny(hay, { scope, tostring(scopeLabel or "") }) then score = score + 180 end
        if score == 0 then score = score - 120 end
    end
    return score
end

function R.RegistryLocationResultFollowups(entries, limit)
    local out = {}
    limit = math.min(tonumber(limit) or 4, #(entries or {}))
    for i = 1, limit do
        local item = entries[i] and entries[i].item
        if item then
            out[#out + 1] = {
                kind = item.kind,
                key = item.key,
                label = item.label,
                page = item.page,
                pageLabel = item.pageLabel,
                category = item.category,
                description = item.description,
                controlType = item.controlType,
                settingKey = item.setting and item.setting.key,
                actionKey = item.action and item.action.key
                    or ((item.kind == "action" or item.kind == "diagnostic") and item.key or nil),
                canOpen = item.canOpen,
                canExplain = item.canExplain,
            }
        end
    end
    return out
end

function R.FallbackPageForSetting(setting)
    local resolver = A.ResolveMenuPageForSetting
        or (A.Knowledge and A.Knowledge.ResolveSettingPage)
    if type(resolver) == "function" then return resolver(setting) end
    return type(setting) == "table" and setting.page or nil
end

function R.SettingFollowupResults(settingKey, query)
    settingKey = tostring(settingKey or "")
    if settingKey == "" then return nil end
    local registry = A.Registry
    local setting = registry and type(registry.GetSetting) == "function" and registry:GetSetting(settingKey) or nil
    query = tostring(query or (setting and setting.label) or settingKey)

    -- A caller with an exact registry key already has the authoritative
    -- owner. Build its single follow-up directly instead of scoring the whole
    -- knowledge index to rediscover the same setting.
    local directItem = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(settingKey) or nil
    if directItem then return R.RegistryLocationResultFollowups({ { item = directItem } }, 1) end

    if A.Knowledge and type(A.Knowledge.Search) == "function" then
        local results = A.Knowledge.Search(query, 12, { kind = "setting", ignoreCurrentPage = true }) or {}
        for i = 1, #results do
            local item = results[i] and results[i].item
            local itemSetting = item and item.setting
            if tostring(itemSetting and itemSetting.key or item and item.settingKey or item and item.key or "") == settingKey then
                return R.RegistryLocationResultFollowups({ { item = item } }, 1)
            end
        end
    end

    if not setting then return nil end
    local page = R.FallbackPageForSetting(setting)
    local pageLabel = page and A.DisplayPageLabel and A.DisplayPageLabel(page, "MSUF page") or nil
    return {
        {
            kind = "setting",
            key = setting.key,
            settingKey = setting.key,
            label = setting.label,
            page = page,
            pageLabel = pageLabel,
            category = setting.category,
            controlType = setting.type,
            canOpen = page ~= nil,
            canExplain = true,
        },
    }
end

function R.SettingFollowupResultsByQuery(query, exactLabel)
    query = tostring(query or "")
    if query == "" then return nil end
    local exactNorm = R.Normalize(exactLabel or query)

    -- Specialist routes pass their display label here. The compact registry
    -- matcher can resolve an exact label without the much broader FAQ/action/
    -- page knowledge scan, while the existing search remains the fallback for
    -- labels that do not map to a concrete setting.
    local compact = R.CompactRegistrySettingSearchEntries
        and R.CompactRegistrySettingSearchEntries(exactLabel or query, 12) or nil
    for i = 1, #(compact or {}) do
        local item = compact[i] and compact[i].item
        if item and item.kind == "setting" and R.Normalize(item.label or "") == exactNorm then
            return R.RegistryLocationResultFollowups({ { item = item } }, 1)
        end
    end

    if not (A.Knowledge and type(A.Knowledge.Search) == "function") then return nil end
    local results = A.Knowledge.Search(query, 12, { kind = "setting", ignoreCurrentPage = true }) or {}
    local first
    for i = 1, #results do
        local item = results[i] and results[i].item
        if item and item.kind == "setting" then
            first = first or item
            if exactNorm ~= "" and R.Normalize(item.label or "") == exactNorm then
                return R.RegistryLocationResultFollowups({ { item = item } }, 1)
            end
        end
    end
    if first then return R.RegistryLocationResultFollowups({ { item = first } }, 1) end
    return nil
end

function R.RegistrySettingExample(item)
    if type(item) ~= "table" then return nil end
    local setting = item.setting or {}
    local label = tostring(item.label or setting.label or "that setting")
    local kind = tostring(item.controlType or setting.type or "")
    if kind == "boolean" then return "turn on " .. label end
    if kind == "number" then
        local normLabel = R.Normalize(label)
        local value = tonumber(setting.default)
        if not value or value == 0 then value = tonumber(setting.min) end
        if not value or value == 0 then
            if R.ContainsAny(normLabel, { "font", "text size", "font size" }) then value = 14
            elseif R.ContainsAny(normLabel, { "width" }) then value = 250
            elseif R.ContainsAny(normLabel, { "height" }) then value = 40
            elseif R.ContainsAny(normLabel, { "range fade alpha", "range fade opacity" }) then value = 40
            elseif R.ContainsAny(normLabel, { "opacity", "alpha" }) then value = 80
            else value = 1 end
        end
        return "set " .. label .. " to " .. tostring(value)
    end
    if kind == "color" then return "set " .. label .. " to red" end
    if kind == "enum" then return "set " .. label .. " to one of its listed choices" end
    if kind == "string" then return "set " .. label .. " to the value you want" end
    return "open " .. tostring(item.pageLabel or "the matching page")
end

function R.RegistrySettingTypeText(controlType, item)
    local setting = item and (item.setting or item) or { type = controlType }
    if type(A.DisplaySettingControl) == "function" then
        return A.DisplaySettingControl(setting, "article")
    end
    return "an MSUF option"
end

function R.RegistryLocationLine(index, item)
    local label = tostring(item and item.label or "MSUF setting")
    local pageLabel = tostring(item and item.pageLabel or "MSUF page")
    return tostring(index) .. ". " .. label .. " - " .. pageLabel
end

function R.RegistryCloseMatchAllowed(item, queryNorm)
    local setting = item and item.setting or {}
    local hay = R.Normalize(table.concat({
        tostring(item and item.label or ""),
        tostring(item and item.key or ""),
        tostring(item and item.pageLabel or ""),
        tostring(setting.key or ""),
    }, " "))
    local groups = {
        { query = { "padding" }, item = { "padding" } },
        { query = { "font size", "text size" }, item = { "font size", "text size", "size" } },
        { query = { "border" }, item = { "border", "outline" } },
        { query = { "outline" }, item = { "outline", "border" } },
        { query = { "background", "backdrop" }, item = { "background", "backdrop" } },
        { query = { "preset", "blacklist" }, item = { "preset", "blacklist", "hidden aura" } },
    }
    for i = 1, #groups do
        local group = groups[i]
        if R.ContainsAny(queryNorm, group.query) and not R.ContainsAny(hay, group.item) then return false end
    end
    return true
end

function R.HasTargetTargetInlineSubject(norm)
    norm = R.Normalize(norm)
    return R.ContainsAny(norm, { "target of target", "targettarget", "tot", "targets target" })
end

function R.HasTargetTargetInlineFrameContext(norm)
    norm = R.Normalize(norm)
    return R.ContainsAny(norm, {
        "target frame", "the target frame",
        "on target", "on the target", "on target frame", "on the target frame",
        "in target", "in the target", "in target frame", "in the target frame",
        "inside target", "inside the target", "inside target frame", "inside the target frame",
        "inline",
    })
end

function R.LooksLikeTargetTargetInlineNameRequest(norm)
    norm = R.Normalize(norm)
    if norm == "" then return false end
    if not R.HasTargetTargetInlineSubject(norm) then return false end
    if not R.HasTargetTargetInlineFrameContext(norm) then return false end
    if not R.ContainsAny(norm, { "name", "name text", "text" }) then return false end
    if R.ContainsAny(norm, { "health", "hp", "power", "mana", "font size", "text size", "bigger", "larger", "smaller" }) then return false end
    return true
end

R.COMPACT_SETTING_STOP_WORDS = {
    ["the"] = true, ["a"] = true, ["an"] = true,
    ["frame"] = true, ["frames"] = true, ["setting"] = true, ["settings"] = true,
    ["option"] = true, ["options"] = true, ["control"] = true, ["controls"] = true,
}
R.COMPACT_SETTING_WORDS = {
    breite = "width", hoehe = "height", groesse = "size", textur = "texture",
    spieler = "player", ziel = "target", gruppe = "group", bereit = "ready",
}

function R.CompactRegistrySettingTokens(text)
    local norm = tostring(text or ""):lower():gsub("[^%w]+", " "):gsub("%s+", " ")
    norm = R.Trim(norm):gsub("cast bar", "castbar")
    local words, set = {}, {}
    for word in norm:gmatch("%S+") do
        word = R.COMPACT_SETTING_WORDS[word] or word
        if not R.COMPACT_SETTING_STOP_WORDS[word] and not set[word] then
            set[word] = true
            words[#words + 1] = word
        end
    end
    return words, set
end

function R.CompactRegistrySettingLabel(text)
    return R.Trim(tostring(text or ""):lower():gsub("[^%w]+", " "):gsub("%s+", " ")):gsub("cast bar", "castbar")
end

function R.EnsureCompleteSettingRegistry()
    local auto = A.AutoCoverage
    if auto and type(auto.EnsureFilled) == "function" then auto.EnsureFilled() end
    local registry = A.Registry
    return registry and type(registry.AllSettings) == "function" and registry:AllSettings() or nil
end

local function CopyCompactRegistryEntries(entries)
    if type(entries) ~= "table" then return nil end
    local copy = {}
    for i = 1, #entries do
        local source = entries[i]
        local itemCopy = {}
        for key, value in pairs(source.item or {}) do itemCopy[key] = value end
        copy[i] = { score = source.score, rawScore = source.rawScore, item = itemCopy }
    end
    return copy
end

function R.CompactRegistrySettingSearchEntries(text, limit)
    local queryWords = R.CompactRegistrySettingTokens(text)
    if #queryWords < 2 then return nil end
    local settings = R.EnsureCompleteSettingRegistry()
    if type(settings) ~= "table" then return nil end
    limit = tonumber(limit) or 16

    local matches = {}
    local queryJoined = table.concat(queryWords, " ")
    local cached = R._compactRegistrySettingSearchCache
    if cached and cached.settings == settings and cached.count == #settings
        and cached.query == queryJoined and cached.limit == limit
    then
        return cached.entries ~= false and CopyCompactRegistryEntries(cached.entries) or nil
    end
    for i = 1, #settings do
        if i % 64 == 0 and type(A.MaybeYield) == "function" then A.MaybeYield() end
        local setting = settings[i]
        local candidateText = R.CompactRegistrySettingLabel(setting and setting.label or "")
        local paddedCandidate = " " .. candidateText .. " "
        local all = candidateText ~= ""
        for j = 1, #queryWords do
            if not paddedCandidate:find(" " .. queryWords[j] .. " ", 1, true) then all = false; break end
        end
        if all then
            local candidateCount = 0
            for _ in candidateText:gmatch("%S+") do candidateCount = candidateCount + 1 end
            local extra = candidateCount - #queryWords
            local score = 1000 + (#queryWords * 100) - (extra * 20)
            if candidateText == queryJoined then score = score + 3000 end
            local page = R.FallbackPageForSetting(setting)
            local pageLabel = page and A.DisplayPageLabel and A.DisplayPageLabel(page, setting.category or "MSUF page")
                or tostring(setting.category or "MSUF page")
            matches[#matches + 1] = {
                score = score,
                rawScore = score,
                item = {
                    kind = "setting",
                    key = setting.key,
                    settingKey = setting.key,
                    setting = setting,
                    label = setting.label,
                    page = page,
                    pageLabel = pageLabel,
                    category = setting.category,
                    unit = setting.unit,
                    controlType = setting.type,
                    canOpen = page ~= nil,
                    canExplain = true,
                },
            }
        end
    end
    if #matches == 0 then
        R._compactRegistrySettingSearchCache = {
            settings = settings, count = #settings, query = queryJoined, limit = limit, entries = false,
        }
        return nil
    end
    table.sort(matches, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        return tostring(a.item and a.item.label or "") < tostring(b.item and b.item.label or "")
    end)
    while #matches > limit do matches[#matches] = nil end
    R._compactRegistrySettingSearchCache = {
        settings = settings, count = #settings, query = queryJoined, limit = limit,
        entries = CopyCompactRegistryEntries(matches),
    }
    return matches
end

-- Reuse the parser's already-bounded exact-alias index for conversational
-- location questions.  This avoids a second large alias table and lets an
-- exact registered phrase win before broad page/help wording.  The index is
-- built lazily only after the LoadOnDemand Assistant receives a request.
function R.ExactRegistrySettingAliasEntries(subject, limit)
    subject = R.Normalize(subject)
    if subject == "" then return nil end
    local tokenCount = 0
    for _ in subject:gmatch("%S+") do tokenCount = tokenCount + 1 end
    if tokenCount == 0 then return nil end
    local settings = R.EnsureCompleteSettingRegistry()
    local parser = A.Parser or {}
    local find = parser._FindRegistryExactAliasSettings
    local ensure = parser._EnsureRegistryExactAliasIndex
    if type(settings) ~= "table" then return nil end
    local bucket
    if type(find) == "function" then
        bucket = find(settings, subject, tonumber(limit) or 16)
    elseif type(ensure) == "function" then
        local index = ensure(settings)
        bucket = index and index.byLength and index.byLength[tokenCount]
            and index.byLength[tokenCount][subject] or nil
    end
    if type(bucket) ~= "table" or #bucket == 0 then return nil end

    local entries, seen = {}, {}
    for i = 1, #bucket do
        local setting = bucket[i]
        local key = tostring(setting and setting.key or "")
        if key ~= "" and not seen[key] then
            seen[key] = true
            local item = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(key) or nil
            if item then entries[#entries + 1] = { score = 20000, rawScore = 20000, item = item } end
        end
        if #entries >= (tonumber(limit) or 16) then break end
    end
    if #entries == 0 then return nil end
    table.sort(entries, function(a, b)
        return tostring(a.item and a.item.label or "") < tostring(b.item and b.item.label or "")
    end)
    return entries
end

function R.ExactRegistrySettingLabelEntries(subject, limit)
    subject = R.Normalize(subject)
    if subject == "" then return nil end
    local settings = R.EnsureCompleteSettingRegistry()
    if type(settings) ~= "table" then return nil end
    limit = math.max(1, math.floor(tonumber(limit) or 16))

    -- Exact location questions do not need a permanent label index for every
    -- registered control.  Scan once for the requested label and retain only
    -- that bounded result.  Repeated natural stems for the same knob are then
    -- constant-time, while the LoD Assistant avoids keeping another 4k-entry
    -- table alive for the whole menu session.
    local cached = R._registryExactLabelLookupCache
    local bucket
    if type(cached) == "table"
        and cached.settings == settings
        and cached.count == #settings
        and cached.subject == subject
        and cached.limit == limit
    then
        bucket = cached.bucket ~= false and cached.bucket or nil
    else
        bucket = {}
        for i = 1, #settings do
            if i % 64 == 0 and type(A.MaybeYield) == "function" then A.MaybeYield() end
            local setting = settings[i]
            local label = R.Normalize(setting and setting.label or "")
            if label ~= "" then
                if label == subject then bucket[#bucket + 1] = setting end
                if #bucket >= limit then break end
            end
        end
        R._registryExactLabelLookupCache = {
            settings = settings,
            count = #settings,
            subject = subject,
            limit = limit,
            bucket = #bucket > 0 and bucket or false,
        }
        if #bucket == 0 then bucket = nil end
    end
    if type(bucket) ~= "table" or #bucket == 0 then return nil end
    local entries = {}
    for i = 1, math.min(#bucket, limit) do
        local item = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(bucket[i].key) or nil
        if item then entries[#entries + 1] = { score = 30000, rawScore = 30000, item = item } end
    end
    return #entries > 0 and entries or nil
end

-- A handful of natural search phrases describe the menu's ownership rather
-- than repeating the visible control label. Keep these lookups deterministic:
-- they are exact, O(1), and avoid letting broad words such as "global" or
-- "class resources" outrank the control the user actually named.
R.EXPLICIT_SEARCH_CANONICAL_KEYS = {
    ["class resources player power width"] = "player.detachedPowerBarWidth",
    ["class resources player power bar width"] = "player.detachedPowerBarWidth",
    ["class resource player power width"] = "player.detachedPowerBarWidth",
    ["class resource player power bar width"] = "player.detachedPowerBarWidth",
    ["class resources player power texture"] = "player.powerBarTexture",
    ["class resources player power bar texture"] = "player.powerBarTexture",
    ["class resource player power texture"] = "player.powerBarTexture",
    ["class resource player power bar texture"] = "player.powerBarTexture",
    ["player power bar anchor"] = "player.detachedPowerBarAnchorToClassPower",
    ["global font outline"] = "fontScope.shared.outline",
    ["global text outline"] = "fontScope.shared.outline",
    ["global font monochrome"] = "fontScope.shared.fontMonochrome",
    ["global monochrome font"] = "fontScope.shared.fontMonochrome",
    ["global font slug"] = "fontScope.shared.fontMonochrome",
    ["global slug rendering"] = "fontScope.shared.fontMonochrome",
    ["global bar right absorb"] = "general.absorbAnchorMode",
    ["global absorb right"] = "general.absorbAnchorMode",
    ["global bar absorb color"] = "general.absorbBarColor",
    ["global absorb bar color"] = "general.absorbBarColor",
    ["global bar right color"] = "general.gradientDirection",
    ["global bar gradient direction"] = "general.gradientDirection",
}

function R.RegistryActionItemForKey(actionKey, page)
    actionKey = tostring(actionKey or "")
    local registry = A.Registry
    local action = actionKey ~= "" and registry and type(registry.GetAction) == "function"
        and registry:GetAction(actionKey) or nil
    if not action then return nil end
    page = tostring(action.page or action.pageKey or page or "")
    if page == "" then page = nil end
    local pageLabel = page and A.DisplayPageLabel and A.DisplayPageLabel(page, "MSUF page") or nil
    return {
        kind = action.type == "diagnostic" and "diagnostic" or "action",
        key = action.key,
        actionKey = action.key,
        label = type(A.DisplayActionLabel) == "function" and A.DisplayActionLabel(action)
            or tostring(action.label or action.key),
        page = page,
        pageLabel = pageLabel,
        category = action.category or action.type,
        controlType = action.type,
        description = action.description or action.summary,
        action = action,
        canOpen = page ~= nil,
        canExplain = true,
    }
end

function R.CanonicalExplicitSearchEntries(subject)
    subject = R.Normalize(subject)
    local key = R.EXPLICIT_SEARCH_CANONICAL_KEYS[subject]
    if key then
        local item = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(key) or nil
        return item and { { score = 10000, rawScore = 10000, item = item } } or nil
    end

    if subject == "group indicator test mode"
        or subject == "group indicators test mode"
        or subject == "group status indicator test mode"
    then
        local item = R.RegistryActionItemForKey("preview_group_status_icon", "gf_indicators")
        return item and { { score = 10000, rawScore = 10000, item = item } } or nil
    end

    if subject == "spell indicator tint alpha"
        or subject == "group spell indicator tint alpha"
        or subject == "spell indicator opacity"
        or subject == "group spell indicator opacity"
    then
        local item = R.RegistryActionItemForKey("set_group_spell_indicator_aura", "gf_auras")
        return item and { { score = 10000, rawScore = 10000, item = item } } or nil
    end

    if subject == "unit text size" or subject == "unit frame text size" then
        local keys = { "player.hpFontSize", "player.powerFontSize", "player.nameFontSize" }
        local entries = {}
        for i = 1, #keys do
            local item = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey(keys[i]) or nil
            if item then entries[#entries + 1] = { score = 10001 - i, rawScore = 10001 - i, item = item } end
        end
        return #entries > 0 and entries or nil
    end

    if subject == "raid background color" or subject == "raid frame background color" then
        local backdrop = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey("gf_raid.bgColor") or nil
        local dead = R.RegistrySettingItemForKey and R.RegistrySettingItemForKey("gf_raid.deadBgColor") or nil
        local entries = {}
        if backdrop then entries[#entries + 1] = { score = 10000, rawScore = 10000, item = backdrop } end
        if dead then entries[#entries + 1] = { score = 9999, rawScore = 9999, item = dead } end
        return #entries > 0 and entries or nil, "raid_background"
    end

    return nil
end

function R.ExactRegistryLocationEntries(text)
    local norm = R.Normalize(text)
    if not R.LooksLikeRegistrySettingLocationQuestion(norm) then return nil end
    local subject = R.RegistryLocationSubject(norm)
    if R.ContainsAny(subject, { "font size", "text size" })
        and not R.ContainsAny(subject, {
            "name", "health", "hp", "power", "mana", "status", "castbar", "cast bar",
            "cooldown", "timer", "stack", "duration", "class resource", "class power",
        })
    then
        -- A frame-level "font size" can mean name, HP, power, status, or a
        -- shared font. Keep the guided multi-option answer instead of letting
        -- one broad registered alias silently choose for the user.
        return nil
    end
    local directKey = R.NameShorteningDotsSettingKey(text)
    local directItem = directKey and R.RegistrySettingItemForKey(directKey) or nil
    return (directItem and { { item = directItem, score = 40000, rawScore = 40000 } })
        or (subject ~= "" and R.ExactRegistrySettingLabelEntries(subject, 16))
        or (subject ~= "" and R.CanonicalExplicitSearchEntries(subject))
        or (subject ~= "" and R.ExactRegistrySettingAliasEntries(subject, 16))
end

function R.RegistryLocationPrefersSpecialistGuidance(text)
    local subject = R.RegistryLocationSubject(text)
    if subject == "" then return false end

    -- These are useful feature families, not leaf controls. Their specialist
    -- answers explain the connected visibility, layout, style, and filtering
    -- controls. Deliberately narrow forms keep precise qualified requests free
    -- to use their reviewed leaf route.
    if subject == "portrait" or subject == "portrait options" then return true end
    if subject == "class resource width"
        or subject == "class resources width"
        or subject == "class power width"
    then
        return true
    end
    if R.ContainsAny(subject, { "font size", "text size" })
        and not R.ContainsAny(subject, {
            "name", "health", "hp", "power", "mana", "status", "castbar", "cast bar",
            "cooldown", "timer", "stack", "duration", "class resource", "class power",
        })
    then
        return true
    end
    local scopes = {
        ["player"] = true, ["target"] = true, ["focus"] = true, ["pet"] = true,
        ["target of target"] = true, ["focus target"] = true, ["boss"] = true,
        ["party"] = true, ["raid"] = true, ["mythic raid"] = true,
    }
    local families = {
        "portrait", "power text", "buff", "buffs", "debuff", "debuffs",
        "ready check", "ready checks", "ready check icon", "ready check icons",
    }
    for i = 1, #families do
        local suffix = " " .. families[i]
        if subject:sub(-#suffix) == suffix then
            local requestedScope = R.Trim(subject:sub(1, #subject - #suffix))
            if scopes[requestedScope] then return true end
        end
    end
    return false
end

function R.RegistryLocationNeedsExactLeafPrecedence(text)
    local subject = R.RegistryLocationSubject(text)
    if subject == "" then return false end
    local padded = " " .. subject .. " "
    local qualifiers = {
        -- These qualifiers distinguish the name-shortening leaf controls from
        -- the broader Name Text family that otherwise answers first.  Other
        -- precise families already have richer specialist routes (ready-check
        -- size, cast colors, aura text, layout spacing, and so on), so they
        -- deliberately continue through normal routing.
        " max name length ", " maximum name length ", " name max length ",
        " name maximum length ", " name length ", " name ellipsis ", " name dots ",
    }
    for i = 1, #qualifiers do
        if padded:find(qualifiers[i], 1, true) then return true end
    end
    if R.NameShorteningDotsSettingKey and R.NameShorteningDotsSettingKey(text) then return true end
    return false
end

function R.TryExactRegistrySettingLocation(text, coreHandler, precomputedEntries)
    local entries = precomputedEntries or R.ExactRegistryLocationEntries(text)
    if not entries or #entries == 0 then return nil end
    return A.RouterTryRegistrySettingLocationShortcut
        and A.RouterTryRegistrySettingLocationShortcut(text, coreHandler, entries) or nil
end

function R.TryRegistryLocationSpecialistGuidance(text, coreHandler)
    -- Keep the same reviewed feature specialists that normal late routing
    -- uses, but let natural "show me where ... is" wording reach them before
    -- generic display/search handling can turn it into an arbitrary result
    -- list. Each shortcut is read-only for a location question.
    return (A.RouterTryVisualSettingShortcut and A.RouterTryVisualSettingShortcut(text, coreHandler))
        or (A.RouterTryMovementSettingShortcut and A.RouterTryMovementSettingShortcut(text, coreHandler))
        or (A.RouterTryUnitFrameSettingShortcut and A.RouterTryUnitFrameSettingShortcut(text, coreHandler))
        or (A.RouterTryEditModeProblemShortcut and A.RouterTryEditModeProblemShortcut(text, coreHandler))
        or (A.RouterTryProfileProblemShortcut and A.RouterTryProfileProblemShortcut(text, coreHandler))
        or (A.RouterTryGroupLayoutProblemShortcut and A.RouterTryGroupLayoutProblemShortcut(text, coreHandler))
        or (A.RouterTryAuraProblemShortcut and A.RouterTryAuraProblemShortcut(text, coreHandler))
        or (A.RouterTryCastbarProblemShortcut and A.RouterTryCastbarProblemShortcut(text, coreHandler))
        or (A.RouterTryTextPowerProblemShortcut and A.RouterTryTextPowerProblemShortcut(text, coreHandler))
        or (A.RouterTryUnitFrameProblemShortcut and A.RouterTryUnitFrameProblemShortcut(text, coreHandler))
        or (A.RouterTryIndicatorProblemShortcut and A.RouterTryIndicatorProblemShortcut(text, coreHandler))
        or (A.RouterTryClassResourceProblemShortcut and A.RouterTryClassResourceProblemShortcut(text, coreHandler))
        or (A.RouterTryGameplayProblemShortcut and A.RouterTryGameplayProblemShortcut(text, coreHandler))
end

function R.TryCompactExplicitSettingSearch(text)
    local norm = R.Normalize(text)
    local subject = norm:match("^search%s+(.+)$") or norm:match("^find%s+(.+)$")
        or norm:match("^suche%s+(.+)$") or norm:match("^finde%s+(.+)$")
    if not subject or subject == "" then return nil end
    local entries, canonicalKind = R.CanonicalExplicitSearchEntries(subject)
    if not entries then entries = R.CompactRegistrySettingSearchEntries(subject, 5) end
    if not entries then return nil end
    local visible = math.min(3, #entries)
    local lines
    if canonicalKind == "raid_background" and visible > 1 then
        lines = {
            "Raid background color could mean two different MSUF controls. Pick the one you meant:",
        }
    else
        lines = { visible == 1 and "I found this in MSUF:" or "I found these MSUF matches:" }
    end
    for i = 1, visible do lines[#lines + 1] = R.RegistryLocationLine(i, entries[i].item) end
    if canonicalKind == "raid_background" and visible > 1 then
        lines[#lines + 1] = "Raid Backdrop Color is the normal frame background. Raid Dead Background Color is the special background used for dead members."
        lines[#lines + 1] = "Reply with 1 or 2, or ask me to open or explain that result."
    else
        lines[#lines + 1] = "You can ask me to open a page, explain a result, or change an option directly."
    end
    return {
        text = table.concat(lines, "\n"),
        status = canonicalKind == "raid_background" and visible > 1 and "ambiguous" or "info",
        result = canonicalKind == "raid_background" and visible > 1 and "ambiguous" or "info",
        summary = "Assistant compact registry search",
        searchResults = R.RegistryLocationResultFollowups(entries, visible),
    }
end

function R.RegistrySettingSearchEntries(text, norm, limit)
    local compact = R.CompactRegistrySettingSearchEntries(text, limit)
    if compact then return compact end
    if not (A.Knowledge and type(A.Knowledge.Search) == "function") then return nil end
    local results = A.Knowledge.Search(text, tonumber(limit) or 16, { kind = "setting", ignoreCurrentPage = true })
    -- Knowledge.Search uses nil as a deliberate cold-index sentinel. Preserve
    -- it separately from a ready-but-empty result so first-load routing does
    -- not poison the open-ended cache with a generic page fallback.
    if results == nil then return nil, true end
    if #results == 0 then return nil end

    -- A single color channel (generated R/G/B/A component) is never the answer
    -- to a fuzzy setting search: MSUF colors are set through a color picker, so
    -- "player portrait background color" must reach the color setting, not its
    -- red channel.  Channels stay reachable by their exact name through the
    -- exact-alias path; they are only dropped from fuzzy candidate ranking.
    local requestsChannel = R.ContainsAny(norm, {
        "red channel", "green channel", "blue channel", "alpha channel",
        "color channel", "colour channel", "channel value",
    })
    local scopeKind, scope, scopeLabel = R.RegistryRequestedScope(norm)
    local entries = {}
    for i = 1, #results do
        local item = results[i] and results[i].item
        if item and item.kind == "setting"
            and not (not requestsChannel and item.setting and item.setting.assistantColorChannel == true)
        then
            local setting = item.setting or {}
            local score = (tonumber(results[i].score) or 0) + R.RegistryItemScopeScore(item, scopeKind, scope, scopeLabel)
            if tostring(setting.key or item.key or "") == "targettarget.showToTInTargetName"
                and R.LooksLikeTargetTargetInlineNameRequest(norm)
            then
                score = score + 700
            end
            if score > 0 then entries[#entries + 1] = { item = item, score = score, rawScore = tonumber(results[i].score) or 0 } end
        end
    end
    if #entries == 0 then return nil end
    table.sort(entries, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        return tostring(a.item and a.item.label or "") < tostring(b.item and b.item.label or "")
    end)
    return entries
end

function R.RegistryValueLabel(setting, value)
    if value == nil then return nil end
    if setting and type(setting.valueLabels) == "table" and setting.valueLabels[value] ~= nil then
        return tostring(setting.valueLabels[value])
    end
    if type(value) == "boolean" then return value and "enabled" or "disabled" end
    if type(value) == "table" then
        if type(value.label) == "string" and value.label ~= "" then return tostring(value.label) end
        local r = tonumber(value.r or value[1])
        local g = tonumber(value.g or value[2])
        local b = tonumber(value.b or value[3])
        if r and g and b then
            r = math.max(0, math.min(255, math.floor((r <= 1 and r * 255 or r) + 0.5)))
            g = math.max(0, math.min(255, math.floor((g <= 1 and g * 255 or g) + 0.5)))
            b = math.max(0, math.min(255, math.floor((b <= 1 and b * 255 or b) + 0.5)))
            return string.format("#%02X%02X%02X", r, g, b)
        end
        return "custom value"
    end
    if setting and (setting.type == "enum" or type(setting.values) == "table") and type(A.HumanizeDisplayKey) == "function" then
        return A.HumanizeDisplayKey(value)
    end
    return tostring(value)
end

function R.RegistryCurrentValueLine(item)
    local setting = item and item.setting
    if not setting or type(setting.get) ~= "function" then return nil end
    local value = setting.get()
    local label = R.RegistryValueLabel(setting, value)
    if label == nil or label == "" then return nil end
    return "Current value: " .. tostring(label) .. "."
end

-- Human-readable label for a related setting key, used when reporting a
-- graph verdict.  Falls back to the raw key so a missing registry label can
-- never blank out the sentence.
local function GraphVerdictSettingLabel(key)
    key = tostring(key or "")
    if key == "" then return key end
    local related = A.Registry and type(A.Registry.GetSetting) == "function"
        and A.Registry:GetSetting(key) or nil
    local label = related and related.label
    return (type(label) == "string" and label ~= "") and label or key
end

local function GraphVerdictJoinLabels(edges, keyField, limit)
    local labels, seen = {}, {}
    for i = 1, #(edges or {}) do
        local key = tostring(edges[i] and edges[i][keyField] or "")
        if key ~= "" and not seen[key] then
            seen[key] = true
            labels[#labels + 1] = GraphVerdictSettingLabel(key)
            if #labels >= (limit or 3) then break end
        end
    end
    if #labels == 0 then return nil end
    return table.concat(labels, ", ")
end

-- Enrich a plain "explain this setting" answer with the live dependency-graph
-- verdict.  The graph already knows why a control is currently ineffective,
-- where its value is inherited from, and what it conflicts with; the static
-- purpose/type/value lines cannot express that.  Returns a single sentence
-- only when the verdict is non-trivial (blocked, inheriting, or conflicting);
-- an effective, independent setting stays silent so the common answer keeps
-- its length.  The evaluator fails closed with (nil, error) during combat,
-- while the menu is closed, or for an unknown key, so this degrades to
-- today's answer without a guard of its own.
--
-- This enrichment never forces a graph build.  It reads only the guard-free
-- EvaluateSettingDependenciesIfBuilt, which returns nil unless the dependency
-- graph is already built for the requested scope; the regular evaluator would
-- otherwise re-scan the whole registry twice and run AutoCoverage, making a
-- cold explain answer pay tens of milliseconds for one extra sentence.  When
-- the graph is not built yet the line is simply omitted; a later
-- relationship/why question builds it once and subsequent explain answers pick
-- the verdict up for free.
function R.RegistrySettingGraphVerdictLine(item)
    if type(A.EvaluateSettingDependenciesIfBuilt) ~= "function" then return nil end
    local key = tostring((item and (item.settingKey or item.key))
        or (item and item.setting and item.setting.key) or "")
    if key == "" then return nil end
    local ok, evaluation = pcall(A.EvaluateSettingDependenciesIfBuilt, key)
    if not ok or type(evaluation) ~= "table" then return nil end

    if type(evaluation.blockers) == "table" and #evaluation.blockers > 0 then
        local labels = GraphVerdictJoinLabels(evaluation.blockers, "to", 3)
        if labels then
            return "Right now it is not fully effective because " .. labels
                .. " is not in the required state."
        end
    end
    if type(evaluation.activeConflicts) == "table" and #evaluation.activeConflicts > 0 then
        local labels = GraphVerdictJoinLabels(evaluation.activeConflicts, "to", 3)
        if labels then
            return "It currently conflicts with " .. labels .. "."
        end
    end
    if type(evaluation.inheritedFrom) == "table" and #evaluation.inheritedFrom > 0 then
        local labels = GraphVerdictJoinLabels(evaluation.inheritedFrom, "to", 3)
        if labels then
            return "Its effective value is currently inherited from " .. labels
                .. "; turn on the scope override to make it independent."
        end
    end
    return nil
end

function R.RegistrySettingPurpose(item)
    item = item or {}
    local setting = item.setting or {}
    local label = tostring(item.label or setting.label or "This MSUF setting")
    local normLabel = R.Normalize(label)
    local desc = item.description or setting.description or setting.summary
    if type(desc) == "string" and desc ~= "" then
        desc = R.Trim(desc)
        if desc:sub(-1) ~= "." then desc = desc .. "." end
        return desc
    end
    local kind = tostring(item.controlType or setting.type or "setting")
    -- The declared control type owns the meaning. Label words only refine an
    -- explanation inside a compatible type, so a boolean Border is never
    -- described as a style and an enum Outline is never called thickness.
    if kind == "boolean" then
        if R.ContainsAny(normLabel, { "range fade" }) then return label .. " turns out-of-range frame fading on or off." end
        return label .. " turns that MSUF option on or off."
    end
    if kind == "color" then
        if R.ContainsAny(normLabel, { "dead background color" }) then return label .. " controls the color used behind dead group members so they are easier to spot." end
        if R.ContainsAny(normLabel, { "background color", "backdrop color" }) then return label .. " controls the background color used by that frame or element." end
        return label .. " sets the color used by that MSUF option."
    end
    if kind == "number" then
        if R.ContainsAny(normLabel, { "spell name font size" }) then return label .. " controls the cast-bar spell-name text size." end
        if R.ContainsAny(normLabel, { "font size", "text size" }) then return label .. " controls how large that text is drawn." end
        if R.ContainsAny(normLabel, { "range fade alpha", "range fade opacity" }) then return label .. " controls how faded out-of-range frames become." end
        if R.ContainsAny(normLabel, { "opacity", "alpha" }) then return label .. " controls the opacity amount for that MSUF option." end
        if R.ContainsAny(normLabel, { "border padding" }) then return label .. " controls the spacing around the group border so the outline has room around the frames." end
        if R.ContainsAny(normLabel, { "border thickness", "outline thickness", "outline size" }) then return label .. " controls how thick the border or outline is." end
        return label .. " changes the numeric amount for that MSUF option."
    end
    if kind == "enum" then
        if R.ContainsAny(normLabel, { "hidden aura preset", "blacklist preset" }) then return label .. " chooses a preset for hidden/blacklisted aura handling." end
        if R.ContainsAny(normLabel, { "health color scheme", "health color mode" }) then return label .. " chooses how MSUF colors the health bar." end
        if R.ContainsAny(normLabel, { "outline", "border" }) then return label .. " chooses which outline or border style MSUF uses." end
        return label .. " chooses which mode or style MSUF uses for that option."
    end
    if kind == "string" then return label .. " stores the text, media name, or free-form value used by that option." end
    return label .. " is an MSUF setting on this area of the menu."
end

function R.RegistryEnumChoicesLine(item)
    local setting = item and item.setting
    if not setting or type(setting.values) ~= "table" or #setting.values == 0 or #setting.values > 8 then return nil end
    local values = {}
    for i = 1, #setting.values do
        local value = setting.values[i]
        values[#values + 1] = R.RegistryValueLabel(setting, value)
    end
    return "Choices: " .. table.concat(values, ", ") .. "."
end

R.OPEN_ENDED_SETTING_MUTATION_VERBS = {
    set = true, change = true, make = true, adjust = true, modify = true,
    edit = true, switch = true, choose = true, alter = true, update = true,
    tweak = true, configure = true,
    -- "put Target Power Gradient Strength to 75" is the same statement as
    -- "set ... to 75"; without it the subject kept the verb, matched no label,
    -- and a topic lane answered instead.
    put = true,
}

R.OPEN_ENDED_SETTING_IGNORED_WORDS = {
    ["a"] = true, ["an"] = true, ["the"] = true, ["my"] = true,
    ["this"] = true, ["that"] = true, ["of"] = true, ["for"] = true,
    ["on"] = true, ["in"] = true, ["to"] = true, ["as"] = true,
}

function R.OpenEndedMutationSubject(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    norm = norm:gsub("^please%s+", "")
        :gsub("^can%s+you%s+", "")
        :gsub("^could%s+you%s+", "")
        :gsub("^would%s+you%s+", "")
        :gsub("^i%s+would%s+like%s+to%s+", "")
        :gsub("^i%s+want%s+to%s+", "")
        :gsub("^id%s+like%s+to%s+", "")
        :gsub("^help%s+me%s+", "")
    local verb, subject = norm:match("^(%S+)%s+(.+)$")
    if not (verb and R.OPEN_ENDED_SETTING_MUTATION_VERBS[verb]) then return nil end
    subject = R.Trim(subject:gsub("^the%s+", ""))
    subject = subject:gsub("grow%s+direction", "growth direction")
    for _ = 1, 3 do
        subject = R.Trim(subject
            :gsub("%s+different$", "")
            :gsub("%s+differently$", "")
            :gsub("%s+somehow$", "")
            :gsub("%s+around$", "")
            :gsub("%s+please$", "")
            :gsub("%s+for%s+me$", ""))
    end
    if subject == "" then return nil end
    local connectorAt
    local connectors = { " to ", " as ", " = ", " auf ", " zu " }
    for i = 1, #connectors do
        local connector = connectors[i]
        local at = subject:find(connector, 1, true)
        if at and (not connectorAt or at < connectorAt) then connectorAt = at end
    end
    local explicitConnector = connectorAt ~= nil
    if connectorAt then subject = R.Trim(subject:sub(1, connectorAt - 1)) end
    if subject == "" then return nil end
    if not explicitConnector and subject:match("%f[%d]%d+%.?%d*%f[^%d]") then return nil end
    if not explicitConnector and R.ContainsAny(subject, {
        "bigger", "larger", "smaller", "increase", "decrease", "raise", "lower",
        "more", "less", "brighter", "darker", "wider", "narrower", "taller", "shorter",
    }) then
        return nil
    end
    if not explicitConnector and R.ContainsAny(subject, { "growth", "direction", "anchor", "position" })
        and (subject:match("%s+left$") or subject:match("%s+right$")
            or subject:match("%s+up$") or subject:match("%s+down$")
            or subject:match("%s+links$") or subject:match("%s+rechts$")
            or subject:match("%s+hoch$") or subject:match("%s+runter$"))
    then
        return nil
    end
    local parser = A.Parser or {}
    if not explicitConnector and type(parser.ExtractColor) == "function" then
        local first = parser.ExtractColor(text, norm)
        if first ~= nil then return nil end
    end
    return subject, norm, explicitConnector
end

function R.OpenEndedManualSettingEntries(subject)
    local scope = subject:match("^(player)%s+name%s+font$")
        or subject:match("^(target)%s+name%s+font$")
        or subject:match("^(focus)%s+name%s+font$")
        or subject:match("^(pet)%s+name%s+font$")
        or subject:match("^(boss)%s+name%s+font$")
    local keys
    if scope then
        keys = { "general.fontKey", "fontScope." .. scope .. ".override", scope .. ".nameFontSize" }
    else
        scope = subject:match("^(player)%s+portrait%s+style$")
            or subject:match("^(target)%s+portrait%s+style$")
            or subject:match("^(focus)%s+portrait%s+style$")
            or subject:match("^(pet)%s+portrait%s+style$")
            or subject:match("^(boss)%s+portrait%s+style$")
        if scope then
            keys = {
                scope .. ".portraitClassStyle", scope .. ".portraitBorderStyle",
                scope .. ".portraitRender", scope .. ".portraitMode",
            }
        else
            scope = subject:match("^(player)%s+portrait$")
                or subject:match("^(target)%s+portrait$")
                or subject:match("^(focus)%s+portrait$")
                or subject:match("^(pet)%s+portrait$")
                or subject:match("^(boss)%s+portrait$")
            if scope then
                keys = {
                    scope .. ".portraitMode", scope .. ".portraitRender",
                    scope .. ".portraitBorderStyle", scope .. ".portraitClassStyle",
                }
            elseif subject == "party portrait"
                or subject == "group portrait"
                or subject == "group frame portrait"
                or subject == "group frames portrait"
            then
                keys = {
                    "gf_party.portraitMode", "gf_party.portraitRender",
                    "gf_party.portraitBorderStyle", "gf_party.portraitClassStyle",
                }
            end
        end
    end
    if not keys then
        scope = subject:match("^(player)%s+name%s+position$")
            or subject:match("^(target)%s+name%s+position$")
            or subject:match("^(focus)%s+name%s+position$")
            or subject:match("^(pet)%s+name%s+position$")
            or subject:match("^(boss)%s+name%s+position$")
        if scope then
            keys = { scope .. ".nameTextAnchor", scope .. ".nameOffsetX", scope .. ".nameOffsetY" }
        end
    end
    if not keys then
        scope = subject:match("^(player)%s+frame%s+color$")
            or subject:match("^(target)%s+frame%s+color$")
            or subject:match("^(focus)%s+frame%s+color$")
            or subject:match("^(pet)%s+frame%s+color$")
            or subject:match("^(boss)%s+frame%s+color$")
        if scope then
            keys = {
                scope .. ".healthColorMode", "barScope." .. scope .. ".barOutlineColor",
                "fontScope." .. scope .. ".nameColorMode", "fontScope." .. scope .. ".colorHealthTextByHealth",
            }
        end
    end
    if not keys then
        scope = subject:match("^(player)%s+cast%s*bar$")
            or subject:match("^(target)%s+cast%s*bar$")
            or subject:match("^(focus)%s+cast%s*bar$")
            or subject:match("^(boss)%s+cast%s*bar$")
        if scope == "target" then
            keys = { "general.enableTargetCastbar", "general.castbarTargetBarWidth", "general.castbarTargetBarHeight" }
        elseif scope == "focus" then
            keys = { "general.enableFocusCastbar", "general.castbarFocusBarWidth", "general.castbarFocusBarHeight" }
        elseif scope == "boss" then
            keys = { "general.enableBossCastbar", "general.bossCastbarWidth", "general.bossCastbarHeight" }
        end
    end
    if not keys then
        scope = subject:match("^(player)%s+frame%s+growth$")
            or subject:match("^(target)%s+frame%s+growth$")
            or subject:match("^(focus)%s+frame%s+growth$")
            or subject:match("^(boss)%s+frame%s+growth$")
        if scope then
            keys = { "auras3." .. scope .. ".buff.growth", "auras3." .. scope .. ".debuff.growth" }
        end
    end
    if not keys and (subject == "castbar interrupt colors" or subject == "cast bar interrupt colors"
        or subject == "castbar interrupt color" or subject == "cast bar interrupt color")
    then
        keys = {
            "general.castbarInterruptibleColor",
            "general.castbarNonInterruptibleColor",
            "general.castbarInterruptUnavailableColor",
            "general.castbarInterruptFeedbackColor",
        }
    end
    if not keys then
        scope = subject:match("^(player)%s+health%s+text$")
            or subject:match("^(target)%s+health%s+text$")
            or subject:match("^(focus)%s+health%s+text$")
            or subject:match("^(pet)%s+health%s+text$")
            or subject:match("^(boss)%s+health%s+text$")
            or subject:match("^(player)%s+hp%s+text$")
            or subject:match("^(target)%s+hp%s+text$")
            or subject:match("^(focus)%s+hp%s+text$")
            or subject:match("^(pet)%s+hp%s+text$")
            or subject:match("^(boss)%s+hp%s+text$")
        if scope then
            keys = {
                scope .. ".showHP", scope .. ".hpFontSize",
                "fontScope." .. scope .. ".colorHealthTextByHealth", scope .. ".hpTextSeparator",
            }
        end
    end
    if not keys then return nil end
    local entries = {}
    for i = 1, #keys do
        local item = R.RegistrySettingItemForKey(keys[i])
        if item then
            entries[#entries + 1] = {
                item = item, score = 5000 - i, rawScore = 5000 - i,
                manual = true, visibleLimit = #keys <= 4 and #keys or 3,
            }
        end
    end
    return #entries > 0 and entries or nil
end

function R.OpenEndedSubjectMatchesSetting(subject, setting)
    if type(setting) ~= "table" then return false end
    local parts = { tostring(setting.label or "") }
    for i = 1, #(setting.aliases or {}) do parts[#parts + 1] = tostring(setting.aliases[i] or "") end
    local hay = " " .. R.Normalize(table.concat(parts, " ")) .. " "
    local meaningful = 0
    for word in R.Normalize(subject):gmatch("%S+") do
        if not R.OPEN_ENDED_SETTING_IGNORED_WORDS[word] then
            meaningful = meaningful + 1
            if not hay:find(" " .. word .. " ", 1, true) then return false end
        end
    end
    return meaningful >= 2
end

function R.OpenEndedSubjectSettingRelation(subject, setting)
    if type(setting) ~= "table" then return false, false end
    local phrases = { tostring(setting.label or "") }
    for i = 1, #(setting.aliases or {}) do phrases[#phrases + 1] = tostring(setting.aliases[i] or "") end
    subject = R.Normalize(subject)
    local namesSetting, explicitTail = false, false
    for i = 1, #phrases do
        local phrase = R.Normalize(phrases[i])
        if phrase ~= "" then
            if subject == phrase or phrase:sub(1, #subject + 1) == subject .. " " then
                namesSetting = true
            elseif subject:sub(1, #phrase + 1) == phrase .. " " then
                local tail = R.Trim(subject:sub(#phrase + 2))
                tail = tail:gsub("^direction%s*", "")
                    :gsub("^mode%s*", "")
                    :gsub("^style%s*", "")
                    :gsub("^setting%s*", "")
                    :gsub("^option%s*", "")
                tail = R.Trim(tail)
                if tail == "" then namesSetting = true else explicitTail = true end
            end
        end
    end
    if namesSetting then return true, false end
    if setting.type == "enum" and type(setting.valueAliases) == "table" then
        for alias in pairs(setting.valueAliases) do
            alias = R.Normalize(alias)
            if alias ~= "" and (subject == alias or subject:sub(-#alias - 1) == " " .. alias) then
                return false, true
            end
        end
    end
    return false, explicitTail
end

function R.OpenEndedScopeMatchesSetting(norm, setting)
    local scopeKind, scope = R.RegistryRequestedScope(norm)
    if not scopeKind or not scope or type(setting) ~= "table" then return true end
    local unit = tostring(setting.unit or "")
    if unit == "" or unit == "global" or unit == "shared" or unit == "all" then return true end
    if scopeKind == "unit" then return unit == scope end
    if scopeKind == "group" then return unit == scope end
    return true
end

function R.LooksLikeNaturalEvaluationQuestion(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    if R.NaturalRegistryDecisionSubject(norm) then return true end
    local lead = norm:match("^do%s+you%s+think%s+")
        or norm:match("^do%s+i%s+really%s+need%s+")
        or norm:match("^would%s+you%s+recommend%s+")
        or norm:match("^would%s+you%s+suggest%s+")
        or norm:match("^would%s+you%s+keep%s+")
        or norm:match("^should%s+i%s+")
        or norm:match("^should%s+we%s+")
        or norm:match("^would%s+")
        or norm:match("^will%s+")
        or norm:match("^could%s+[%+%-]?%d")
        or norm:match("^is%s+")
        or norm:match("^what%s+if%s+")
        or norm:match("^how%s+about%s+")
    if not lead then return false end
    local evaluative = R.ContainsAny(norm, {
        "good", "better", "best", "bad", "safe", "sensible", "reasonable",
        "useful", "recommended", "recommend", "suggest", "necessary", "needed",
        "need", "okay", "ok", "fine", "acceptable", "advisable", "worth",
        "too wide", "too narrow", "too tall", "too short", "too big", "too small",
        "too high", "too low", "too much", "work for", "help to", "should", "keep",
    })
    if not evaluative then return false end
    return norm:match("[%+%-]?%d+%.?%d*") ~= nil
        or R.ContainsAny(norm, R.MUTATION_TERMS)
        or R.ContainsAny(norm, { " on", " off", "enabled", "disabled", "visible", "hidden", "showing", "hiding" })
end

function R.OpenEndedSettingEntries(subject, norm)
    local canonical = subject:gsub("%s+text%s+size$", " font size")
    local leadingScope, scopedTail = canonical:match("^(%S+)%s+(.+)$")
    local recognizedScope = leadingScope == "player" or leadingScope == "target"
        or leadingScope == "focus" or leadingScope == "boss"
    if recognizedScope and (scopedTail == "castbar texture" or scopedTail == "cast bar texture") then
        canonical = "castbar texture"
    elseif recognizedScope and scopedTail == "power bar texture" then
        canonical = "power bar texture"
    end

    -- Reviewed semantic families such as "player portrait" intentionally
    -- represent several controls. Preserve that richer clarification first;
    -- otherwise a complete visible label (or reviewed alias) outranks fuzzy
    -- topical matches for the thousands of individual leaf controls.
    local entries = R.OpenEndedManualSettingEntries(canonical)
    if not entries then
        entries = R.ExactRegistrySettingLabelEntries(canonical, 16)
        if entries then
            for i = 1, #entries do entries[i].exactSettingName = true end
        end
    end
    if not entries then
        entries = R.CanonicalExplicitSearchEntries(canonical)
        for i = 1, #(entries or {}) do entries[i].manual = true end
    end
    if not entries then entries = R.CompactRegistrySettingSearchEntries(canonical, 10) end
    local searchCold = false
    if not entries then entries, searchCold = R.RegistrySettingSearchEntries(canonical, norm, 12) end
    if not entries then return nil, canonical, nil, searchCold end

    -- A generated colour component (…ColorR/G/B/A) is never what an open-ended
    -- request means unless it actually says "channel": "set player alpha to 50"
    -- is frame opacity, not the alpha of some portrait border colour. The
    -- registry search path already drops these; this path has to as well or the
    -- channels crowd out the real control and force a pointless clarification.
    local requestsChannel = R.ContainsAny(norm, {
        "red channel", "green channel", "blue channel", "alpha channel",
        "color channel", "colour channel", "channel value",
    })

    local filtered, seen, explicitValue, namesAnySetting = {}, {}, false, false
    for i = 1, #entries do
        local entry = entries[i]
        local item = entry and entry.item
        local setting = item and item.setting
        if setting and setting.assistantColorChannel == true and not requestsChannel then
            setting = nil
            item = nil
        end
        local key = setting and tostring(setting.key or "") or ""
        local namesSetting, hasExplicitTail = R.OpenEndedSubjectSettingRelation(canonical, setting)
        local semanticMatch = entry.manual == true or namesSetting or R.OpenEndedSubjectMatchesSetting(canonical, setting)
        local scopeMatch = R.OpenEndedScopeMatchesSetting(norm, setting)
        if scopeMatch and semanticMatch and hasExplicitTail then explicitValue = true end
        if scopeMatch and semanticMatch and namesSetting then namesAnySetting = true end
        if key ~= "" and not seen[key] and scopeMatch and semanticMatch then
            seen[key] = true
            filtered[#filtered + 1] = entry
        end
    end
    return #filtered > 0 and filtered or nil, canonical, explicitValue and not namesAnySetting, searchCold
end

function R.OpenEndedLikelyPage(subject, norm)
    local page, label, detail
    if R.ContainsAny(subject, { "castbar", "cast bar", "cast texture", "spell cast" }) then
        page, label, detail = "opt_castbar", "Cast Bars", "Cast-bar controls live in Cast Bars."
    elseif R.ContainsAny(subject, { "portrait" }) then
        local unit, unitLabel = R.UnitScopeFromText(norm)
        if unit and unitLabel then return { unit = unit, label = unitLabel, detail = unitLabel .. " portrait controls live on the " .. unitLabel .. " page." } end
        local groupScope = R.GroupScopeFromText(norm)
        if groupScope == "party" then
            return {
                page = "gf_layout",
                label = "Group Layout",
                detail = "Party Group Frame portrait controls live in Group Layout.",
            }
        end
    elseif R.ContainsAny(subject, { "font", "text outline", "text rendering" }) then
        page, label, detail = "opt_fonts", "Fonts", "Font family, outline, rendering, and scoped font overrides live in Fonts."
    elseif R.ContainsAny(subject, { "color", "colour", "tint" }) then
        page, label, detail = "opt_colors", "Colors", "Shared and scoped color controls live in Colors."
    elseif R.ContainsAny(subject, { "aura", "buff", "debuff" }) then
        local groupScope = R.GroupScopeFromText(norm)
        if groupScope then
            page, label, detail = "gf_auras", "Group Auras", "Party and Raid aura controls live in Group Auras."
        elseif R.ContainsAny(subject, { "appearance", "shared", "theme", "icon shape", "icon border", "icon shadow" }) then
            page, label, detail = "auras3_styling", "Global Aura Appearance", "The global Aura icon theme is selected by Aura product in Appearance > Aura Style."
        else
            local unit, unitLabel = R.UnitScopeFromText(norm)
            if unit and unitLabel then
                return { unit = unit, label = unitLabel, detail = unitLabel .. " Aura Options and Aura Style live on the " .. unitLabel .. " UnitFrame page." }
            end
            page, label, detail = "uf_player", "Player UnitFrame", "Aura Options and Aura Style are frame-local. Open the intended UnitFrame; Player is the starting scope."
        end
    elseif R.ContainsAny(subject, { "raid spacing", "party spacing", "group spacing", "growth direction", "group layout" }) then
        page, label, detail = "gf_layout", "Group Layout", "Party and Raid frame geometry controls live in Group Layout."
    elseif R.ContainsAny(subject, { "class resource", "class power", "combo point", "holy power" }) then
        page, label, detail = "classpower", "Class Resources", "Class-resource controls live in Class Resources."
    elseif R.ContainsAny(subject, { "bar", "texture", "absorb", "power" }) then
        page, label, detail = "opt_bars", "Bars", "Bar textures, power bars, absorbs, gradients, and outlines live in Bars."
    end
    return page and { page = page, label = label, detail = detail } or nil
end

function R.OpenEndedSettingAnalysis(text)
    local norm = R.Normalize(text)
    local cached = R._openEndedSettingCache
    if type(cached) == "table" and cached.text == norm then
        return cached.analysis ~= false and cached.analysis or nil
    end
    local subject, fullNorm, explicitConnector = R.OpenEndedMutationSubject(text)
    if not subject then
        R._openEndedSettingCache = { text = norm, analysis = false }
        return nil
    end
    local entries, canonical, explicitTail, searchCold = R.OpenEndedSettingEntries(subject, fullNorm)
    if explicitTail and not explicitConnector then
        R._openEndedSettingCache = { text = norm, analysis = false }
        return nil
    end
    local page = R.OpenEndedLikelyPage(subject, fullNorm)
    local analysis = (entries or page) and {
        subject = subject, canonical = canonical or subject, norm = fullNorm,
        entries = entries, page = page, explicitValue = explicitConnector == true,
        searchCold = searchCold == true,
    } or nil
    if not searchCold then
        R._openEndedSettingCache = { text = norm, analysis = analysis or false }
    end
    return analysis
end

function R.OpenEndedEntriesAreConfident(entries)
    if type(entries) ~= "table" or #entries == 0 then return false end
    if #entries == 1 then return true end
    local first, second = entries[1], entries[2]
    local score1, score2 = tonumber(first.score) or 0, tonumber(second.score) or 0
    local raw1, raw2 = tonumber(first.rawScore) or 0, tonumber(second.rawScore) or 0
    return (score1 >= 4000 and score2 < 3000)
        or (score1 >= score2 + 500)
        or (raw1 >= 300 and raw1 >= raw2 + 80)
end

-- True when the request names exactly one of these candidates by its full
-- label. The clarifier ranks candidates by score, which cannot separate "Boss
-- Cast Bar" from "Boss Castbar Width"/"Boss Castbar Height" -- all three
-- contain every word the player typed, so all three scored alike and the
-- Assistant applied none of them. A label the player reproduced in full is the
-- control they meant; only an exact match counts, so a prefix never wins.
function R.OpenEndedEntriesNameOneControl(entries, text)
    if type(entries) ~= "table" or #entries < 2 then return nil end
    if type(R.CommandNamedSettingLabel) ~= "function" then return nil end
    -- CommandNamedSettingLabel returns nil unless the label index is already
    -- warm, to protect Submit's 8ms synchronous preflight. This lane is not that
    -- preflight: it runs only when a clarification list is about to be built, so
    -- it can pay for the index rather than fall back to asking the player.
    if type(R.EnsureSettingLabelIndex) == "function" then R.EnsureSettingLabelIndex() end
    local label = R.CommandNamedSettingLabel(text)
    if not label then return nil end
    local wanted = R.Normalize(label)
    if wanted == "" then return nil end
    local match, count = nil, 0
    for i = 1, #entries do
        local item = entries[i] and entries[i].item
        local setting = item and item.setting
        local candidate = setting and R.Normalize(tostring(setting.label or "")) or nil
        if candidate == wanted then
            count = count + 1
            if count > 1 then return nil end
            match = entries[i]
        end
    end
    return count == 1 and match or nil
end

local function OpenEndedEnumContainsValue(setting, value)
    if not (setting and setting.type == "enum" and type(setting.values) == "table") then return false end
    for i = 1, #setting.values do
        local candidate = setting.values[i]
        if type(candidate) == "table" then candidate = candidate.value or candidate.key end
        if candidate == value or tostring(candidate or ""):lower() == tostring(value or ""):lower() then return true end
    end
    return false
end

-- Words the label-prefix fallback may ignore in a value tail. Anything else
-- left over means part of the request was never understood.
R.VALUE_TAIL_FILLER_WORDS = {
    to = true, as = true, is = true, be = true, ["="] = true, value = true,
    please = true, now = true, it = true, the = true, a = true, an = true,
    auf = true, zu = true, als = true, wert = true, bitte = true, jetzt = true,
}

-- "set player name bold text on" has no Bold Text control on a unit frame, so
-- the label-prefix scan matched "player name" and treated "bold text on" as its
-- value -- silently toggling the name off instead of saying it did not
-- understand "bold". A value tail may only contain the value itself plus
-- filler; leftover content words mean the request was only partly understood.
function R.ValueTailIsOnlyValue(setting, valueText)
    local norm = R.Normalize(valueText or "")
    if norm == "" then return false end
    -- Free-form text (names, spell IDs, custom strings) legitimately carries
    -- arbitrary words, so only closed value domains are checked here.
    local settingType = tostring(setting and setting.type or "")
    if settingType ~= "boolean" then return true end
    for word in norm:gmatch("%S+") do
        if not R.VALUE_TAIL_FILLER_WORDS[word] then
            local isBooleanWord = R.ContainsAny(word, {
                "on", "off", "true", "false", "yes", "no", "enable", "enabled",
                "disable", "disabled", "show", "shown", "hide", "hidden",
                "an", "aus", "ja", "nein", "ein", "einschalten", "ausschalten",
            })
            if not isBooleanWord then return false end
        end
    end
    return true
end

-- A specialist parser may safely break a generic name tie when it produced one
-- fixed-list change and the supplied value belongs to exactly one of the
-- candidate settings. Example: "portrait to 2D" fits Portrait Render, but not
-- Portrait Position or Portrait Border. Free-form strings never qualify.
function R.OpenEndedSpecialistProvesUniqueEnumValue(plan, entries)
    if type(plan) ~= "table" or plan.kind ~= "changes" or type(plan.changes) ~= "table" or #plan.changes ~= 1 then return false end
    if type(entries) ~= "table" or #entries < 2 then return false end
    local change = plan.changes[1]
    local selected = change and change.setting
    local selectedKey = tostring(selected and selected.key or "")
    if selectedKey == "" or not OpenEndedEnumContainsValue(selected, change.value) then return false end

    local selectedIsCandidate, compatible = false, 0
    for i = 1, #entries do
        local setting = entries[i] and entries[i].item and entries[i].item.setting
        if setting and tostring(setting.key or "") == selectedKey then selectedIsCandidate = true end
        if OpenEndedEnumContainsValue(setting, change.value) then compatible = compatible + 1 end
    end
    return selectedIsCandidate and compatible == 1
end

-- A parser plan built by a dedicated semantic lane carries no matchScore --
-- that field is stamped only by the broad fuzzy registry match this Router
-- lane exists to fail closed against. So a scoreless single-change plan is the
-- one kind of parser answer that is safe to prefer over "I could not identify
-- one exact MSUF control": the lane recognised the whole sentence, it did not
-- guess at a name. Used only at give-up points, never ahead of the Router's own
-- exact-label and named-control resolution.
function R.OpenEndedSpecialistOwnsChange(plan)
    if type(plan) ~= "table" or plan.kind ~= "changes" then return false end
    if type(plan.changes) ~= "table" or #plan.changes == 0 then return false end
    for i = 1, #plan.changes do
        local change = plan.changes[i]
        if type(change) ~= "table" then return false end
        if change.matchScore ~= nil then return false end
        local setting = change.setting
        if type(setting) ~= "table" or tostring(setting.key or "") == "" then return false end
        if change.value == nil and change.relativeDelta == nil then return false end
    end
    return true
end

function R.OpenEndedSettingCurrentValue(setting)
    if not (setting and type(setting.get) == "function") then return nil end
    local ok, value = pcall(setting.get)
    if not ok then return nil end
    return R.RegistryValueLabel(setting, value)
end

function R.OpenEndedSettingChoices(setting)
    if not setting then return nil end
    local parser = A.Parser or {}
    if type(parser.RefreshRegistrySettingValues) == "function" then
        parser.RefreshRegistrySettingValues(setting)
    end
    local values
    if setting.type == "boolean" then
        values = { true, false }
    elseif (setting.type == "enum" or setting.type == "string")
        and type(setting.values) == "table" and #setting.values > 0 and #setting.values <= 24
    then
        values = setting.values
    else
        return nil
    end
    local choices = {}
    for i = 1, #values do
        local value = values[i]
        local valueLabel = R.RegistryValueLabel(setting, value)
        choices[#choices + 1] = {
            setting = setting,
            value = value,
            valueLabel = valueLabel,
            label = type(A.DisplaySettingValueLabel) == "function"
                and A.DisplaySettingValueLabel(setting, valueLabel, setting.label or "Option")
                or (tostring(setting.label or "Option") .. ": " .. tostring(valueLabel)),
        }
    end
    return choices
end

local function ExactMutationBody(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    for _ = 1, 3 do
        local previous = norm
        norm = norm:gsub("^please%s+", "")
            :gsub("^can%s+you%s+", "")
            :gsub("^could%s+you%s+", "")
            :gsub("^would%s+you%s+", "")
            :gsub("^i%s+would%s+like%s+to%s+", "")
            :gsub("^i%s+want%s+to%s+", "")
            :gsub("^id%s+like%s+to%s+", "")
            :gsub("^help%s+me%s+", "")
            -- Without the "to" these are still plain commands naming a control:
            -- "i want Target Power Gradient Strength to be 75". Stripped after
            -- the "... to " forms above so the longer match always wins.
            :gsub("^i%s+would%s+like%s+", "")
            :gsub("^i%s+want%s+", "")
            :gsub("^i%s+need%s+", "")
            :gsub("^id%s+like%s+", "")
            :gsub("^just%s+", "")
            :gsub("^now%s+", "")
            :gsub("^hey%s+", "")
            :gsub("^assistant%s+", "")
        if norm == previous then break end
    end
    local verb, body = norm:match("^(%S+)%s+(.+)$")
    -- Players also state the change without any verb at all ("Target Width to
    -- 300") or with one outside the curated set ("put X to 75"). The subject
    -- still has to match ONE control's complete visible label further down, so
    -- accepting the bare text here cannot capture anything that was not named
    -- exactly -- and without it those shapes lost the exemption and a topic lane
    -- answered instead (it enabled the power gradient rather than setting its
    -- strength).
    if not (verb and R.OPEN_ENDED_SETTING_MUTATION_VERBS[verb]) then
        body = norm
    end
    body = R.Trim(body:gsub("%s+please$", ""))
    -- A determiner or possessive between the verb and the control name is not
    -- part of the label ("set MY player width to 300", "set THE target width").
    -- Leaving it in meant the body never matched a control, so the request lost
    -- its exact-mutation exemption further up and the fail-closed guard turned
    -- an explicit command into a read-only answer that changed nothing.
    for _ = 1, 2 do
        local previous = body
        body = body:gsub("^the%s+", ""):gsub("^my%s+", ""):gsub("^our%s+", "")
            :gsub("^its%s+", ""):gsub("^msuf%s+", ""):gsub("^a%s+", ""):gsub("^an%s+", "")
        if body == previous then break end
    end
    body = R.Trim(body)
    return body ~= "" and body or nil
end

local function UniqueExactMutationEntry(subject)
    subject = R.Trim(subject)
    if subject == "" then return nil end
    local leadingScope, scopedTail = subject:match("^(%S+)%s+(.+)$")
    if scopedTail == "power bar texture"
        and (leadingScope == "player" or leadingScope == "target"
            or leadingScope == "focus" or leadingScope == "boss")
    then
        return nil
    end
    local semanticFamily = R.OpenEndedManualSettingEntries(subject)
    if type(semanticFamily) == "table" and #semanticFamily > 0 then return nil end
    -- This priority lane is intentionally limited to the complete visible
    -- label. Natural aliases such as "player portrait" can name a family of
    -- controls and still belong to the semantic disambiguation path.
    local entries = R.ExactRegistrySettingLabelEntries(subject, 3)
    if type(entries) ~= "table" or #entries ~= 1 then return nil end
    return entries[1].item
end

-- Boolean commands never state their value with "to", so ExactMutationBody --
-- which only accepts the value-assignment verbs -- never matched them, and a
-- request that named one control EXACTLY still lost to a topic lane:
-- "turn on Boss Texture Layer Gradient Down" wrote the bar-gradient pair
-- (enableGradient + gradientDirection=DOWN) instead of the control the player
-- named, while "set Boss Texture Layer Gradient Down to on" worked.
-- These shapes now earn the same exact-label precedence.
--
-- "show"/"hide" are deliberately absent: for a hide-named control they mean the
-- OPPOSITE polarity (RegistryPhrases[51] lists "show" as false for hide* keys),
-- and "show me X" is navigation, not a mutation.
local BOOLEAN_EXACT_COMMAND_PREFIXES = {
    { "^turn%s+on%s+", "on" }, { "^turn%s+off%s+", "off" },
    { "^switch%s+on%s+", "on" }, { "^switch%s+off%s+", "off" },
    { "^toggle%s+on%s+", "on" }, { "^toggle%s+off%s+", "off" },
    { "^enable%s+", "on" }, { "^disable%s+", "off" },
    { "^activate%s+", "on" }, { "^deactivate%s+", "off" },
}
-- Trailing polarity: "turn X on", "toggle X off".
local BOOLEAN_EXACT_COMMAND_SUFFIXES = { { "%s+on$", "on" }, { "%s+off$", "off" } }

-- show/hide are only unambiguous when the named control's OWN name says nothing
-- about hiding or showing. "show Boss Texture Layer Gradient Down" can only mean
-- switch it on; "show Party Hide Name on Dead or Offline" means the opposite of
-- switching it on, so that one stays with the inference that understands it.
local BOOLEAN_EXACT_COMMAND_POLARITY_PREFIXES = {
    { "^show%s+", "on" }, { "^hide%s+", "off" },
}
local function SettingNameStatesPolarity(setting)
    local hay = (tostring(setting and setting.label or "") .. " "
        .. tostring(setting and setting.attribute or "") .. " "
        .. tostring(setting and setting.key or "")):lower()
    return hay:find("hide", 1, true) ~= nil or hay:find("hidden", 1, true) ~= nil
        or hay:find("show", 1, true) ~= nil or hay:find("shown", 1, true) ~= nil
end

local function ExactBooleanMutationMatch(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    for _ = 1, 3 do
        local previous = norm
        norm = norm:gsub("^please%s+", "")
            :gsub("^can%s+you%s+", ""):gsub("^could%s+you%s+", "")
            :gsub("^would%s+you%s+", ""):gsub("^just%s+", ""):gsub("^now%s+", "")
            :gsub("^hey%s+", ""):gsub("^assistant%s+", "")
        if norm == previous then break end
    end
    norm = R.Trim((norm:gsub("%s+please$", "")))

    local body, value, polarityVerb
    for i = 1, #BOOLEAN_EXACT_COMMAND_PREFIXES do
        local entry = BOOLEAN_EXACT_COMMAND_PREFIXES[i]
        if norm:find(entry[1]) then
            body, value = (norm:gsub(entry[1], "")), entry[2]
            break
        end
    end
    -- "show me X" asks to be taken to the control, so it is never a mutation.
    if not body and not norm:find("^show%s+me%f[%W]") then
        for i = 1, #BOOLEAN_EXACT_COMMAND_POLARITY_PREFIXES do
            local entry = BOOLEAN_EXACT_COMMAND_POLARITY_PREFIXES[i]
            if norm:find(entry[1]) then
                body, value, polarityVerb = (norm:gsub(entry[1], "")), entry[2], true
                break
            end
        end
    end
    if not body then
        local tail = norm:match("^turn%s+(.+)$") or norm:match("^toggle%s+(.+)$")
            or norm:match("^make%s+(.+)$") or norm:match("^switch%s+(.+)$")
            or norm:match("^set%s+(.+)$")
        for i = 1, (tail and #BOOLEAN_EXACT_COMMAND_SUFFIXES or 0) do
            local entry = BOOLEAN_EXACT_COMMAND_SUFFIXES[i]
            if tail:find(entry[1]) then
                body, value = (tail:gsub(entry[1], "")), entry[2]
                break
            end
        end
    end
    if not body then return nil end

    for _ = 1, 2 do
        local previous = body
        body = body:gsub("^the%s+", ""):gsub("^my%s+", ""):gsub("^our%s+", "")
            :gsub("^its%s+", ""):gsub("^msuf%s+", "")
        if body == previous then break end
    end
    body = R.Trim(body)
    if body == "" then return nil end

    local item = UniqueExactMutationEntry(body)
    local setting = item and item.setting
    -- Only booleans: a polarity verb aimed at anything else is not an exact
    -- value statement and belongs to the existing inference.
    if not (setting and setting.type == "boolean") then return nil end
    -- Controls whose own name says Hide/Show already have reviewed inverted
    -- semantics in the established parser (for example Fully Hide Blizzard
    -- PlayerFrame).  Let that lane own every verb form, not only bare
    -- show/hide, so "turn on <hide control>" cannot flip the backing key the
    -- wrong way around.
    if SettingNameStatesPolarity(setting)
        or R.ContainsAny(body, { "hide", "hidden", "show", "shown" })
    then
        return nil
    end
    return item, true, value
end

local function ExactMutationMatch(text)
    -- Problem reports such as "Menu Language is wrong" name a real control and
    -- use the grammatical connector "is", but they do not provide a value.
    -- Keep them on the diagnostic/help lanes instead of presenting "wrong" as
    -- an invalid enum choice.
    local normalized = R.Normalize(text)
    if (type(R.HasNaturalProblemTerm) == "function" and R.HasNaturalProblemTerm(normalized))
        or R.ContainsAny(normalized, { "wrong", "not right", "unreadable", "confusing", "bad language" })
    then
        return nil
    end
    local booleanItem, booleanHasValue, booleanValue = ExactBooleanMutationMatch(text)
    if booleanItem then return booleanItem, booleanHasValue, booleanValue end
    local body = ExactMutationBody(text)
    if not body then return nil end

    -- Try the whole body first. This prevents numbers and words such as "to"
    -- that are genuinely part of a label from being mistaken for a value.
    local item = UniqueExactMutationEntry(body)
    if item then return item, false end

    local bestItem, bestValue, bestAt
    local padded = " " .. body .. " "
    local connectors = { " to ", " as ", " is ", " be ", " value ", " = ", " auf ", " zu ", " als " }
    for i = 1, #connectors do
        local startAt = 1
        while true do
            local at, finish = padded:find(connectors[i], startAt, true)
            if not at then break end
            local subject = R.Trim(padded:sub(2, at - 1))
            local valueText = R.Trim(padded:sub(finish + 1, -2))
            local candidate = valueText ~= "" and UniqueExactMutationEntry(subject) or nil
            if candidate and (not bestAt or at > bestAt) then
                bestItem, bestValue, bestAt = candidate, valueText, at
            end
            startAt = at + 1
        end
    end
    if not bestItem then
        local tokens = {}
        for token in body:gmatch("%S+") do tokens[#tokens + 1] = token end
        -- Users often omit "to": "set Target Width 300". Try the
        -- longest complete visible label prefix first. A whole-label match
        -- above already protected labels that legitimately end in numbers.
        for cut = #tokens - 1, 2, -1 do
            local subject = table.concat(tokens, " ", 1, cut)
            local candidate = UniqueExactMutationEntry(subject)
            local setting = candidate and candidate.setting
            if setting and not (setting.type == "string" and setting.closedValues ~= true) then
                local valueText = table.concat(tokens, " ", cut + 1)
                local parser = A.Parser or {}
                local synthetic = "set " .. tostring(setting.label or subject) .. " to " .. valueText
                local parsedValue = type(parser.ValueForRegistrySetting) == "function"
                    and parser.ValueForRegistrySetting(setting, R.Normalize(synthetic), synthetic) or nil
                if parsedValue ~= nil and R.ValueTailIsOnlyValue(setting, valueText) then
                    bestItem = candidate
                    bestValue = valueText
                    break
                end
            end
        end
    end
    return bestItem, bestItem ~= nil, bestValue
end

function R.IsExactRegistrySettingMutation(text)
    return ExactMutationMatch(text) ~= nil
end

function R.OpenColorSettingPickerResult(item, summary)
    local setting = item and item.setting
    if not (setting and setting.type == "color"
        and type(A.OpenColorSettingPickerForSetting) == "function")
    then
        return nil
    end
    local opened, message = A.OpenColorSettingPickerForSetting(
        setting, item.page, item.label or setting.label)
    if opened ~= true then return nil end
    return {
        text = tostring(message or ("Opened Color Painter for " .. tostring(item.label or setting.label or "that color") .. "."))
            .. "\nColor changes preview live. Done keeps the selected color; Cancel restores the original color.",
        status = "navigated",
        result = "navigated",
        summary = summary or "Opens Color Painter for the exact Assistant color setting.",
        colorPickerOpened = true,
        settingKey = setting.key,
    }
end

-- A request names the FAMILY and states a value of one particular kind:
-- "make the frame outline red" names the outline and a colour, "make the frame
-- border half transparent" names it and an opacity. The bare family words
-- ("frame outline") belong to the thickness slider, so both were answered with
-- "what value do you want me to use for ... Thickness?".
--
-- The sibling is found the way a player would name it: append the kind's own
-- word to the subject and look that up. No new index and no ranking change.
local VALUE_KIND_SUFFIXES = {
    color = { " color", " colour" },
    opacity = { " opacity", " alpha" },
    anchor = { " anchor", " bar anchor" },
    texture = { " texture", " bar texture" },
}
local COLOR_VALUE_WORDS = {
    "red", "green", "blue", "yellow", "orange", "purple", "pink", "white", "black",
    "grey", "gray", "cyan", "magenta", "brown", "teal", "gold",
}
local OPACITY_VALUE_WORDS = {
    "transparent", "opaque", "see through", "invisible", "translucent",
}
-- "anchor the heal absorb bar to the left side" states a POSITION, and the bare
-- family words ("heal absorb bar") belong to the show toggle -- so the toggle
-- answered a question about where the bar sits.
-- Texture keys are the value kind most often stated next to a family name
-- ("use the flat texture for the maximum health loss overlay").
local TEXTURE_VALUE_WORDS = {
    "flat texture", "blizzard texture", "skills texture", "outline texture",
    "raidhp texture", "raidpower texture", "solid texture",
}
local ANCHOR_VALUE_WORDS = {
    "left side", "right side", "to the left", "to the right",
    "follow the hp bar", "follow the health bar", "follow hp bar",
    "reverse from max", "overflow",
}

-- The setting TYPE a stated value needs, for callers that rank candidates
-- rather than look up a sibling by name.
function R.StatedValueKindForText(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    if R.ContainsAny(norm, COLOR_VALUE_WORDS) then return "color" end
    if R.ContainsAny(norm, OPACITY_VALUE_WORDS) then return "number" end
    if R.ContainsAny(norm, ANCHOR_VALUE_WORDS) then return "enum" end
    if R.ContainsAny(norm, TEXTURE_VALUE_WORDS) then return "string" end
    return nil
end

function R.SiblingSettingForStatedValueKind(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    local kind
    if R.ContainsAny(norm, COLOR_VALUE_WORDS) then kind = "color"
    elseif R.ContainsAny(norm, OPACITY_VALUE_WORDS) then kind = "opacity"
    elseif R.ContainsAny(norm, ANCHOR_VALUE_WORDS) then kind = "anchor"
    elseif R.ContainsAny(norm, TEXTURE_VALUE_WORDS) then kind = "texture" end
    if not kind then return nil end
    local subject = type(R.CommandSubjectPhrase) == "function" and R.CommandSubjectPhrase(text) or nil
    if not subject or subject == "" then return nil end
    -- Peel the value words off the tail: what remains is the family name.
    local words = kind == "color" and COLOR_VALUE_WORDS
        or kind == "anchor" and ANCHOR_VALUE_WORDS
        or kind == "texture" and TEXTURE_VALUE_WORDS
        or OPACITY_VALUE_WORDS
    local trimmed, changed = subject, true
    while changed do
        changed = false
        for i = 1, #words do
            local stripped = trimmed:gsub("%s+" .. words[i] .. "$", "")
            if stripped ~= trimmed then trimmed, changed = R.Trim(stripped), true end
        end
        for _, filler in ipairs({ "half", "fully", "more", "less", "a bit", "slightly", "completely" }) do
            local stripped = trimmed:gsub("%s+" .. filler .. "$", "")
            if stripped ~= trimmed then trimmed, changed = R.Trim(stripped), true end
        end
        -- "shield bar 50 transparent": the amount sits between the family name
        -- and the value word once the tail has been peeled.
        local withoutNumber = trimmed:gsub("%s+%d+%.?%d*%%?$", "")
        if withoutNumber ~= trimmed then trimmed, changed = R.Trim(withoutNumber), true end
    end
    if trimmed == "" then return nil end
    local map = R.EnsureSettingLabelIndex and R.EnsureSettingLabelIndex()
    local aliasMap = R.EnsureSettingAliasIndex and R.EnsureSettingAliasIndex()
    for _, suffix in ipairs(VALUE_KIND_SUFFIXES[kind]) do
        local candidate = trimmed .. suffix
        local setting = (map and map[candidate]) or (aliasMap and aliasMap[candidate]) or nil
        if type(setting) == "table" and type(setting.set) == "function" then
            local wanted = kind == "color" and "color"
                or kind == "anchor" and "enum"
                or kind == "texture" and "string"
                or "number"
            if setting.type == wanted then return setting end
        end
    end
    return nil
end

function R.StatedValueKindSiblingPlan(text)
    local setting = R.SiblingSettingForStatedValueKind(text)
    if not setting then return nil end
    local parser = A.Parser or {}
    local value = type(parser.ValueForRegistrySetting) == "function"
        and parser.ValueForRegistrySetting(setting, R.Normalize(text), text) or nil
    if value == nil then
        -- "half transparent" states a direction, not a number; the planner
        -- turns that into a step on the opacity slider.
        local plan = type(parser.PlanForExactRegistrySetting) == "function"
            and parser.PlanForExactRegistrySetting(setting, R.Normalize(text), text) or nil
        if type(plan) == "table" and plan.kind == "changes" then
            plan.raw, plan.sourceText = text, text
            return plan
        end
        return nil
    end
    return {
        kind = "changes",
        changes = { { setting = setting, value = value } },
        label = tostring(setting.label or setting.key),
        summary = "Changes the sibling control the stated value belongs to.",
        raw = text,
        sourceText = text,
        exactSettingMutation = true,
    }
end

local function ExactSettingValuePrompt(item, invalidValue)
    local setting = item and item.setting
    if not setting then return nil end
    local pickerResult = R.OpenColorSettingPickerResult(item,
        invalidValue and "Opens Color Painter after an invalid color value."
            or "Opens Color Painter for a value-less color request.")
    if pickerResult then return pickerResult end
    local current = R.OpenEndedSettingCurrentValue(setting)
    local location = R.RegistryLocationLine(1, item):gsub("^1%.%s*", "")
    local lines = {
        invalidValue and
            ("I found the exact MSUF control, but that is not one of its available values, so I kept it unchanged.")
            or ("I found the exact MSUF control, but you did not choose a value, so I kept it unchanged."),
        location,
    }
    if current ~= nil then lines[#lines + 1] = "Current value: " .. tostring(current) .. "." end

    local choices = R.OpenEndedSettingChoices(setting)
    if choices then
        lines[#lines + 1] = tostring(A.SetPendingChoices(choices) or "Choose one of the listed values.")
    else
        local guidance = "Tell me the value you want, or ask me to open the control."
        if setting.type == "number" then
            local parts = {}
            if setting.min ~= nil then parts[#parts + 1] = "min " .. tostring(setting.min) end
            if setting.max ~= nil then parts[#parts + 1] = "max " .. tostring(setting.max) end
            if setting.step ~= nil then parts[#parts + 1] = "step " .. tostring(setting.step) end
            guidance = "Choose a number" .. (#parts > 0 and (" (" .. table.concat(parts, ", ") .. ")") or "") .. ", or ask me to open the control."
        elseif setting.type == "color" then
            guidance = "Choose a color name, RGB value, or #RRGGBB, or ask me to open the color control."
        elseif setting.type == "string" then
            guidance = "Tell me the text or named value you want, or ask me to open the control."
        end
        if type(A.StartPendingFlow) == "function" then
            A.StartPendingFlow("settingValue", {
                settingKey = setting.key,
                expectedType = setting.type,
                label = item.label or setting.label,
                page = item.page,
            })
        end
        lines[#lines + 1] = guidance
    end
    return {
        text = table.concat(lines, "\n"),
        status = "ambiguous",
        result = "ambiguous",
        summary = invalidValue and "Offers valid values for the exact MSUF control."
            or "Requests a value for the exact MSUF control.",
        searchResults = R.RegistryLocationResultFollowups({ { item = item } }, 1),
    }
end

local function ComparativeSizeSettingItem(fragment)
    fragment = R.Normalize(fragment)
    local unit = R.UnitScopeFromText(fragment)
    if not unit then return nil end
    local attribute
    if R.ContainsAny(fragment, { "portrait", "portrait size" }) then
        attribute = "portraitSizeOverride"
    elseif fragment:match("%f[%a]name%f[%A]") then
        attribute = "nameFontSize"
    elseif R.ContainsAny(fragment, { "health text", "hp text", "health font", "hp font" }) then
        attribute = "hpFontSize"
    elseif R.ContainsAny(fragment, { "power text", "mana text", "energy text", "rage text", "power font" }) then
        attribute = "powerFontSize"
    end
    return attribute and R.RegistrySettingItemForKey
        and R.RegistrySettingItemForKey(tostring(unit) .. "." .. tostring(attribute)) or nil
end

function R.LooksLikeComparativeSizeRelationshipRequest(text)
    local norm = R.Normalize(text)
    if not R.ContainsAny(norm, { "make ", "set ", "change ", "adjust " }) then return false end
    if not R.ContainsAny(norm, {
        "bigger than", "larger than", "smaller than", "wider than",
        "narrower than", "taller than", "shorter than", "higher than", "lower than",
    }) then
        return false
    end
    local sizeSubjects = 0
    for _, term in ipairs({ "portrait", " name", "health text", "hp text", "power text", "mana text", "energy text", "rage text" }) do
        local startAt = 1
        while true do
            local at = norm:find(term, startAt, true)
            if not at then break end
            sizeSubjects = sizeSubjects + 1
            startAt = at + #term
        end
    end
    return sizeSubjects >= 2
end

-- "Bigger than" identifies a subject and a reference, but it does not say
-- how much larger the subject should become. Keep the reference immutable and
-- retain exactly the subject setting for a numeric follow-up instead of letting
-- broad geometry shortcuts treat every mentioned component as a write target.
function R.TryComparativeSizeRelationshipRequest(text)
    local norm = R.Normalize(text)
    if not R.LooksLikeComparativeSizeRelationshipRequest(norm) then return nil end
    local relation, relationAt
    for _, candidate in ipairs({
        "bigger than", "larger than", "smaller than", "wider than",
        "narrower than", "taller than", "shorter than", "higher than", "lower than",
    }) do
        local at = norm:find(" " .. candidate .. " ", 1, true)
        if at then relation, relationAt = candidate, at break end
    end
    if not relationAt then return nil end

    local subjectText = R.Trim(norm:sub(1, relationAt - 1))
    local referenceText = R.Trim(norm:sub(relationAt + #relation + 2))
    subjectText = subjectText:gsub("^please%s+", "")
        :gsub("^make%s+", ""):gsub("^set%s+", "")
        :gsub("^change%s+", ""):gsub("^adjust%s+", "")
    local subjectItem = ComparativeSizeSettingItem(subjectText)
    local referenceItem = ComparativeSizeSettingItem(referenceText)
    local subjectSetting = subjectItem and subjectItem.setting
    local referenceSetting = referenceItem and referenceItem.setting
    if not (subjectSetting and referenceSetting) then return nil end

    local subjectValue = R.OpenEndedSettingCurrentValue(subjectSetting)
    local referenceValue = R.OpenEndedSettingCurrentValue(referenceSetting)
    if type(A.StartPendingFlow) == "function" then
        A.StartPendingFlow("settingValue", {
            settingKey = subjectSetting.key,
            expectedType = subjectSetting.type,
            label = subjectItem.label or subjectSetting.label,
            page = subjectItem.page,
        })
    end
    local range = {}
    if subjectSetting.min ~= nil then range[#range + 1] = "min " .. tostring(subjectSetting.min) end
    if subjectSetting.max ~= nil then range[#range + 1] = "max " .. tostring(subjectSetting.max) end
    if subjectSetting.step ~= nil then range[#range + 1] = "step " .. tostring(subjectSetting.step) end
    local lines = {
        "I understood " .. tostring(subjectItem.label or subjectSetting.label or subjectSetting.key)
            .. " as the only setting you want to change; "
            .. tostring(referenceItem.label or referenceSetting.label or referenceSetting.key)
            .. " is only the comparison reference and will stay unchanged.",
        "'" .. tostring(relation) .. "' does not specify the final amount, so I kept both settings unchanged.",
    }
    if subjectValue ~= nil or referenceValue ~= nil then
        lines[#lines + 1] = "Current values: subject " .. tostring(subjectValue or "unknown")
            .. ", reference " .. tostring(referenceValue or "unknown") .. "."
    end
    lines[#lines + 1] = "Reply with the subject's exact value"
        .. (#range > 0 and (" (" .. table.concat(range, ", ") .. ")") or "")
        .. ", ask me to open it, or say cancel."
    return {
        text = table.concat(lines, "\n"),
        status = "ambiguous",
        result = "ambiguous",
        summary = "Clarifies a comparative size request without mutating its reference setting.",
        searchResults = R.RegistryLocationResultFollowups({ { item = subjectItem } }, 1),
    }
end

-- A request for a recommendation is not an instruction. Every mutation lane
-- below the decision shortcut treats a matched control as something to write,
-- so "what's better, class colour or custom colour" silently switched the
-- colour mode. These two detectors let routing fail closed instead.
R.ADVICE_QUESTION_TERMS = {
    "whats better", "what is better", "which is better", "which one is better",
    "is it better", "are they better", "is that better", "better than",
    "should i", "should we", "do i need", "do you recommend", "what do you recommend",
    "is it worth", "worth it", "does it help", "do i have to",
    "worth changing", "worth using", "worth turning on", "worth enabling",
    "was ist besser", "welches ist besser", "ist es besser", "besser als",
    "soll ich", "sollte ich", "empfiehlst du", "lohnt sich", "lohnt es sich",
    "brauche ich", "muss ich",
}

R.COMPARATIVE_RELATION_TERMS = {
    "bigger than", "larger than", "smaller than", "wider than", "narrower than",
    "taller than", "shorter than", "higher than", "lower than",
    "groesser als", "kleiner als", "breiter als", "schmaler als",
}

function R.IsAdviceQuestion(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    return R.ContainsAny(norm, R.ADVICE_QUESTION_TERMS)
end

-- "Make debuffs bigger than buffs" states an ordering, never a final amount.
-- Any value written here would be invented, so without a number this is a
-- question about two controls, not a command.
function R.IsAmountlessComparativeRequest(text)
    local norm = R.Normalize(text)
    if norm:match("%d") then return false end
    return R.ContainsAny(norm, R.COMPARATIVE_RELATION_TERMS)
end

-- One exact label must not swallow a multi-clause sentence. In
-- "set target width to 250 and height to 60" the unique label match is
-- "target width", but the value scan then reads the sentence's last number and
-- writes 60 into the width while the height is never set. When the sentence
-- really describes several option changes, the compound pipeline owns it.
function R.ExactMutationSpansSeveralChanges(text)
    local normalized = R.Normalize(text)
    if not (normalized:find(" and ", 1, true) or normalized:find(" und ", 1, true)) then return false end
    local numbers = 0
    for _ in normalized:gmatch("[-+]?%d+%.?%d*") do
        numbers = numbers + 1
        if numbers >= 2 then break end
    end
    if numbers < 2 then return false end
    local parsed = type(A.Parse) == "function" and A.Parse(text) or nil
    return type(parsed) == "table" and parsed.kind == "changes"
        and type(parsed.changes) == "table" and #parsed.changes >= 2
end

-- Exact visible setting names own their commands before broad feature parsers.
-- This is deliberately bounded to one unique label/alias and a clear mutation
-- verb, so natural ideas still receive semantic guidance instead of raw writes.
function R.TryExactRegistrySettingMutation(text)
    local item, hasExplicitValue = ExactMutationMatch(text)
    local setting = item and item.setting
    if not setting then return nil end
    if hasExplicitValue and R.ExactMutationSpansSeveralChanges(text) then return nil end
    local parser = A.Parser or {}
    if not hasExplicitValue then
        -- "make the corners rounder" names the control and states a direction
        -- but no number, and the same is true of every comparative request.
        -- The planner turns that into one step; only when it cannot does the
        -- request really lack a value.
        --
        -- "use the flat texture for the absorb bar" does carry its value, just
        -- in front of the control, so the canonical rewrite is tried first.
        local planText = text
        local reordered = R.CanonicalValueBeforeControlCommand(text, true)
        if reordered and type(parser.PlanForExactRegistrySetting) == "function" then
            local reorderedPlan = parser.PlanForExactRegistrySetting(setting, R.Normalize(reordered), reordered)
            if type(reorderedPlan) == "table" and reorderedPlan.kind == "changes" then
                planText = reordered
            end
        end
        local siblingPlan = R.StatedValueKindSiblingPlan(text)
        if siblingPlan and type(A.ExecutePlan) == "function" then
            local okSibling, siblingResult = pcall(A.ExecutePlan, siblingPlan, { sourceText = text })
            if okSibling and type(siblingResult) == "table"
                and not A.RouterIsUnknownResult(siblingResult)
            then
                return siblingResult
            end
        end
        local relativePlan = type(parser.PlanForExactRegistrySetting) == "function"
            and parser.PlanForExactRegistrySetting(setting, R.Normalize(planText), planText) or nil
        if type(relativePlan) == "table" and relativePlan.kind == "changes"
            and type(A.ExecutePlan) == "function"
        then
            return A.ExecutePlan(relativePlan, { sourceText = text })
        end
        return ExactSettingValuePrompt(item, false)
    end

    local plan = type(parser.PlanForExactRegistrySetting) == "function"
        and parser.PlanForExactRegistrySetting(setting, R.Normalize(text), text) or nil
    if not plan then return ExactSettingValuePrompt(item, true) end
    if plan.kind == "changes" and type(A.ExecutePlan) == "function" then
        return A.ExecutePlan(plan, { sourceText = text })
    end
    if plan.kind == "ambiguous" and type(plan.choices) == "table" then
        return ExactSettingValuePrompt(item, true)
    end
    if plan.kind == "answer" and tostring(plan.status or "") == "ambiguous"
        and type(plan.pendingSetting) == "table"
    then
        return ExactSettingValuePrompt(item, true)
    end
    if plan.text then
        return {
            text = plan.text,
            status = plan.status or "ambiguous",
            result = plan.status or "ambiguous",
            summary = plan.summary or "Clarifies the exact MSUF setting value.",
            searchResults = R.RegistryLocationResultFollowups({ { item = item } }, 1),
        }
    end
    return ExactSettingValuePrompt(item, true)
end

local function RetainConfidentSettingValueQuestion(entries, result)
    if type(result) ~= "table" or type(entries) ~= "table" or #entries == 0 then return end
    local status = tostring(result.status or result.result or "")
    local response = R.Normalize(result.text or "")
    if status ~= "ambiguous" or not R.ContainsAny(response, {
        "what value", "choose a number", "use a number", "tell me the value", "type the value",
    }) then
        return
    end
    if not R.OpenEndedEntriesAreConfident(entries) then return end
    local item = entries[1] and entries[1].item
    local setting = item and item.setting
    if not setting then return end
    if type(A.StartPendingFlow) == "function" then
        A.StartPendingFlow("settingValue", {
            settingKey = setting.key,
            expectedType = setting.type,
            label = item.label or setting.label,
            page = item.page,
        })
    end
    if result.searchResults == nil and R.RegistryLocationResultFollowups then
        result.searchResults = R.RegistryLocationResultFollowups({ entries[1] }, 1)
    end
end

function R.TryOpenEndedSettingIdea(text, coreHandler)
    local parser = A.Parser or {}
    -- This lane ranks fuzzy candidates and asks when several look plausible.
    -- That is right for a vague idea, but wrong once the player has typed a
    -- control's exact visible name: "set my Boss Absorb Bar Opacity to 75"
    -- resolves to exactly one setting, yet the fuzzy list still contained
    -- near-misses and the request was answered with a chooser. An exact
    -- whole-phrase match is not an idea -- it is the answer.
    -- Shared with the fail-closed read-only guard on purpose: if the two lanes
    -- disagree about what counts as an exact match, a request stands down here
    -- and is refused there, so nothing applies it.
    if R.ExactAliasSingleChange(text) then return nil end
    local actionable = type(parser.ActionableText) == "function" and parser.ActionableText(text) or nil
    if actionable and R.Normalize(actionable) ~= "" and R.Normalize(actionable) ~= R.Normalize(text)
        and R.OpenEndedMutationSubject(actionable) ~= nil
    then
        text = actionable
    end
    local analysis = R.OpenEndedSettingAnalysis(text)
    if not analysis then return nil end
    if type(A.RouterClearPendingResultsForRoute) == "function" then A.RouterClearPendingResultsForRoute() end

    local entries = analysis.entries
    if analysis.explicitValue == true then
        local auraDetail = A.RouterTryAuraDetailSettingShortcut
            and A.RouterTryAuraDetailSettingShortcut(R.Normalize(text), coreHandler)
        if auraDetail then return auraDetail end

        -- Specialist parsers know semantic distinctions the generic registry
        -- search cannot infer (for example Raid aura cooldown text still
        -- needs a Buff/Debuff lane). Mutations may bypass the generic response
        -- only when a fixed-list value proves one unique candidate.
        local parseOk, specialized = false, nil
        if type(A.Parse) == "function" then parseOk, specialized = pcall(A.Parse, text) end
        local specialistCanRun = specialized and (
            specialized.kind == "answer" or specialized.kind == "ambiguous"
            or R.OpenEndedSpecialistProvesUniqueEnumValue(specialized, entries)
        )
        if parseOk and specialistCanRun
            and type(coreHandler) == "function"
        then
            local savedCache = R._openEndedSettingCache
            R._openEndedSettingCache = { text = R.Normalize(text), analysis = false }
            local ok, result = pcall(coreHandler, text)
            R._openEndedSettingCache = savedCache
            if not ok then error(result, 0) end
            if result and not A.RouterIsUnknownResult(result) then
                RetainConfidentSettingValueQuestion(entries, result)
                return result
            end
        end
        if R.OpenEndedEntriesAreConfident(entries) and type(coreHandler) == "function" then
            -- This request was intentionally fail-closed before the direct
            -- write path. Once the Router has proven an exact control and a
            -- supplied value, allow only this cached Core call through that
            -- same guard; restore the analysis immediately afterwards.
            local savedCache = R._openEndedSettingCache
            R._openEndedSettingCache = { text = R.Normalize(text), analysis = false }
            local ok, result = pcall(coreHandler, text)
            R._openEndedSettingCache = savedCache
            if not ok then error(result, 0) end
            if result and not A.RouterIsUnknownResult(result)
                and not (type(A.RouterIsNoClueResult) == "function" and A.RouterIsNoClueResult(result))
            then
                RetainConfidentSettingValueQuestion(entries, result)
                return result
            end
        end
        -- A control named in full is not ambiguous, however the scores fall.
        -- Without this, "set Boss Cast Bar to off" offered Boss Cast Bar, Boss
        -- Castbar Width and Boss Castbar Height as equals and changed nothing,
        -- so the three castbar enable toggles could not be switched off by
        -- their own names.
        if type(entries) == "table" and #entries > 1 and type(coreHandler) == "function"
            and not R.OpenEndedEntriesAreConfident(entries)
            and R.OpenEndedEntriesNameOneControl(entries, text)
        then
            local savedCache = R._openEndedSettingCache
            R._openEndedSettingCache = { text = R.Normalize(text), analysis = false }
            local ok, result = pcall(coreHandler, text)
            R._openEndedSettingCache = savedCache
            if not ok then error(result, 0) end
            if result and not A.RouterIsUnknownResult(result)
                and not (type(A.RouterIsNoClueResult) == "function" and A.RouterIsNoClueResult(result))
            then
                RetainConfidentSettingValueQuestion(entries, result)
                return result
            end
        end
        -- A dimension idiom hides the attribute noun ("6 pixels tall" is a
        -- height), so the ranked candidates are every control whose name merely
        -- contains the subject -- for "make the shield bar 6 pixels tall" that
        -- was the seven per-unit frame Heights. The rewritten sentence is only
        -- used when it resolves to exactly one control, which is what separates
        -- it from the list below.
        if type(coreHandler) == "function" then
            local sized = R.CanonicalDimensionCommand(text)
            if sized then
                local result = coreHandler(sized)
                if result and not A.RouterIsUnknownResult(result)
                    and not (type(A.RouterIsNoClueResult) == "function" and A.RouterIsNoClueResult(result))
                then
                    RetainConfidentSettingValueQuestion(entries, result)
                    return result
                end
            end
        end
        -- Last check before offering a list: the request may spell one control's
        -- visible label in full, for a label no other setting shares. That is
        -- not a candidate among several, it is the control -- and for the types
        -- the exact-alias pre-pass declines (colours above all) this is the only
        -- lane that can see it. Runs here, at a give-up point, because it forces
        -- the label index.
        if type(R.ExactLabelSingleChange) == "function" and type(A.ExecutePlan) == "function" then
            local plan = R.ExactLabelSingleChange(text)
            if plan then
                local ok, result = pcall(A.ExecutePlan, plan, { sourceText = text })
                if ok and type(result) == "table" and not A.RouterIsUnknownResult(result) then
                    return result
                end
            end
        end
        -- "change the bar texture to flat" names no frame, and every per-unit
        -- copy of the same option answers to the same bare words. A request
        -- that mentions no frame means the shared control, so when exactly one
        -- candidate is the global one, that is the answer rather than a list.
        if type(entries) == "table" and #entries > 1 and type(A.ExecutePlan) == "function"
            and not R.OpenEndedEntriesAreConfident(entries)
            and not (type(R.UnitScopeFromText) == "function" and R.UnitScopeFromText(R.Normalize(text)))
        then
            local namedItem = R.EntriesNamedExactlyOnce(entries, text)
            local parser = A.Parser or {}
            local setting = namedItem and namedItem.setting or nil
            local value = setting and type(parser.ValueForRegistrySetting) == "function"
                and parser.ValueForRegistrySetting(setting, R.Normalize(text), text) or nil
            if value ~= nil then
                local ok, result = pcall(A.ExecutePlan, {
                    kind = "changes",
                    changes = { { setting = setting, value = value } },
                    label = tostring(setting.label or setting.key),
                    summary = "Changes the one control whose own name the request spells.",
                    raw = text,
                    sourceText = text,
                }, { sourceText = text })
                if ok and type(result) == "table" and not A.RouterIsUnknownResult(result) then
                    return result
                end
            end
        end
        if type(entries) == "table" and #entries > 1 and not R.OpenEndedEntriesAreConfident(entries) then
            local visible = math.min(tonumber(entries[1] and entries[1].visibleLimit) or 3, #entries)
            -- The value is already known, so a number should FINISH the change,
            -- not merely scroll the menu somewhere. Registering search results
            -- here made the reply say "pick a number" and then answer that
            -- number with navigation ("...could not scroll the menu there"),
            -- leaving the player to retype the whole request. Pending choices
            -- carry the setting AND the parsed value, so "2" applies it.
            --
            -- All of them or none: a partial list would silently drop a
            -- candidate the player was choosing between.
            local parser = A.Parser or {}
            if type(A.SetPendingChoices) == "function"
                and type(parser.ValueForRegistrySetting) == "function"
            then
                local normalized = R.Normalize(text)
                local choices = {}
                for i = 1, visible do
                    local item = entries[i] and entries[i].item
                    local setting = item and item.setting
                    local value = setting and parser.ValueForRegistrySetting(setting, normalized, text)
                    if value ~= nil then
                        choices[#choices + 1] = {
                            setting = setting,
                            value = value,
                            label = tostring(setting.label or setting.key),
                        }
                    end
                end
                if #choices == visible then
                    local choiceText = A.SetPendingChoices(choices)
                    if choiceText then
                        return {
                            text = "Several MSUF controls fit that name, so I did not apply it to the wrong one.\n"
                                .. choiceText,
                            status = "ambiguous",
                            summary = "Clarifies the control before applying a supplied value.",
                        }
                    end
                end
            end
            local lines = {
                "I understood that you supplied a value, but several MSUF controls fit the setting name, so I did not apply it to the wrong one. Pick the control you meant:",
            }
            for i = 1, visible do lines[#lines + 1] = R.RegistryLocationLine(i, entries[i].item) end
            lines[#lines + 1] = "Reply with a number, then tell me the value again or ask me to open that control."
            return {
                text = table.concat(lines, "\n"),
                status = "ambiguous",
                summary = "Clarifies the control before applying a supplied value.",
                searchResults = R.RegistryLocationResultFollowups(entries, visible),
            }
        end
        -- Give-up point. Every Router resolution above has declined, so the
        -- alternative to letting the parser's specialist lane run is telling
        -- the player to go find the control themselves. "set the raid frame bar
        -- outline thickness to 3" reaches here -- the singular "raid frame"
        -- keeps it out of the fuzzy index that the plural form hits -- while
        -- the bar-outline lane had already resolved it exactly.
        if type(coreHandler) == "function" and R.OpenEndedSpecialistOwnsChange(specialized) then
            local savedCache = R._openEndedSettingCache
            R._openEndedSettingCache = { text = R.Normalize(text), analysis = false }
            local ok, result = pcall(coreHandler, text)
            R._openEndedSettingCache = savedCache
            if not ok then error(result, 0) end
            if result and not A.RouterIsUnknownResult(result)
                and not (type(A.RouterIsNoClueResult) == "function" and A.RouterIsNoClueResult(result))
            then
                RetainConfidentSettingValueQuestion(entries, result)
                return result
            end
        end
        local page = analysis.page
        if page then
            -- The player supplied a real value and the curated registry could
            -- not place it. Before settling for "here is the page to look at",
            -- give the generated schema its turn: it covers Menu2 controls the
            -- registry never modelled, which is exactly why this lane ran out
            -- of options. Aura icon border thickness lives only there.
            local schemaResult = A.ControlSchema and A.ControlSchema.TryConversation
                and A.ControlSchema.TryConversation(text)
            if schemaResult then return schemaResult end
            local followups = page.unit
                and R.UnitPageFollowupResults(page.unit, page.label, page.detail)
                or R.PageFollowupResults(page.page, page.label, page.detail)
            return {
                text = "I understood the value, but I could not identify one exact MSUF control safely, so I did not apply it.\nBest place to check: " .. tostring(page.label) .. ". " .. tostring(page.detail) .. "\nOpen that page and name the exact control, and I will use the value you requested.",
                status = "ambiguous",
                summary = "Offers the closest MSUF page after a concrete value could not be mapped safely.",
                searchResults = followups,
            }
        end
        return nil
    end
    if type(entries) ~= "table" or #entries == 0 then
        -- Last chance before "here is the page to start on": the player may have
        -- named the control exactly but put the state at the end. Hand the
        -- canonical rewrite to the ordinary command path so it goes through the
        -- same value parsing, confirmation and undo as any other command.
        if type(coreHandler) == "function" then
            local canonical = R.CanonicalTrailingStateCommand(text, true)
                or R.CanonicalValueConnectorCommand(text, true)
                or R.CanonicalValueBeforeControlCommand(text, true)
                or R.CanonicalDimensionCommand(text, true)
            if canonical then
                local rewritten = coreHandler(canonical)
                if rewritten and not A.RouterIsUnknownResult(rewritten) then return rewritten end
            end
        end
        if type(A.ExecutePlan) == "function" then
            local plan = R.NamedBooleanIntentPlan(text)
            if plan then
                local ok, result = pcall(A.ExecutePlan, plan, { sourceText = text })
                if ok and type(result) == "table" and not A.RouterIsUnknownResult(result) then
                    return result
                end
            end
        end
        local page = analysis.page
        if not page then return nil end
        local followups
        if page.unit then
            followups = R.UnitPageFollowupResults(page.unit, page.label, page.detail)
        else
            followups = R.PageFollowupResults(page.page, page.label, page.detail)
        end
        return {
            text = "I understand the MSUF area, but not one exact control well enough to guess, so I kept everything unchanged.\nBest place to start: " .. tostring(page.label) .. ". " .. tostring(page.detail) .. "\nOpen that page, or add the control name or intended result and I will narrow it down.",
            status = "ambiguous",
            summary = "Offers the closest MSUF control family for an open-ended request.",
            searchResults = followups,
        }
    end

    if not R.OpenEndedEntriesAreConfident(entries) then
        local visible = math.min(tonumber(entries[1] and entries[1].visibleLimit) or 3, #entries)
        local lines = {
            "That request could mean several MSUF controls, so I kept everything unchanged. Pick the control you meant:",
        }
        for i = 1, visible do lines[#lines + 1] = R.RegistryLocationLine(i, entries[i].item) end
        lines[#lines + 1] = "Reply with a number, or ask me to open or explain one of them."
        return {
            text = table.concat(lines, "\n"),
            status = "ambiguous",
            summary = "Offers matching MSUF controls for an open-ended request.",
            searchResults = R.RegistryLocationResultFollowups(entries, visible),
        }
    end

    local item = entries[1].item
    local setting = item and item.setting
    if not setting then return nil end
    -- A control whose NAME ends in a state word can swallow the request's
    -- value. "make focus frame on" matched "Focus Force Blizzard Frame On" and
    -- reported "you did not choose a value" -- the trailing "on" had been read
    -- as the last word of the name. When the request ends in that same word,
    -- the plain reading is the value, so hand the canonical sentence to the
    -- ordinary command path first and only fall through if it declines.
    if type(coreHandler) == "function" then
        local normText = R.Normalize(text)
        local tail = normText:match("%s(%a+)$")
        local label = R.Normalize(setting.label or "")
        if tail and TRAILING_STATE_WORDS[tail] and label:match("%s" .. tail .. "$") then
            local canonical = R.CanonicalTrailingStateCommand(text, true)
            if canonical then
                local rewritten = coreHandler(canonical)
                if rewritten and not A.RouterIsUnknownResult(rewritten) then return rewritten end
            end
        end
    end
    -- The open-ended lane lands here with the right control whenever the
    -- request states a direction instead of a value ("make the corners
    -- rounder") or puts the value in front of the control ("use the flat
    -- texture for the absorb bar"). Both carry enough to act on, so try them
    -- before answering with "you did not choose a value".
    do
        local parser = A.Parser or {}
        if type(parser.PlanForExactRegistrySetting) == "function" then
            local reordered = R.CanonicalValueBeforeControlCommand(text, true)
            for _, candidate in ipairs({ reordered or text, text }) do
                local plan = parser.PlanForExactRegistrySetting(setting, R.Normalize(candidate), candidate)
                if type(plan) == "table" and plan.kind == "changes" and type(A.ExecutePlan) == "function" then
                    return A.ExecutePlan(plan, { sourceText = text })
                end
            end
        end
    end
    local pickerResult = R.OpenColorSettingPickerResult(item,
        "Opens Color Painter for an open-ended color request.")
    if pickerResult then return pickerResult end
    local current = R.OpenEndedSettingCurrentValue(setting)
    local location = R.RegistryLocationLine(1, item):gsub("^1%.%s*", "")
    local prefix = "I found the exact MSUF control, but you did not choose a value, so I kept it unchanged.\n" .. location
    if current ~= nil then prefix = prefix .. "\nCurrent value: " .. tostring(current) .. "." end

    local choices = R.OpenEndedSettingChoices(setting)
    if choices then
        local choiceText = A.SetPendingChoices(choices)
        return {
            text = prefix .. "\n" .. tostring(choiceText or "Choose one of the listed values."),
            status = "ambiguous",
            summary = "Offers valid values for an open-ended MSUF setting request.",
        }
    end

    local guidance = "Tell me the value you want, or ask me to open the control."
    if setting.type == "number" then
        local parts = {}
        if setting.min ~= nil then parts[#parts + 1] = "min " .. tostring(setting.min) end
        if setting.max ~= nil then parts[#parts + 1] = "max " .. tostring(setting.max) end
        if setting.step ~= nil then parts[#parts + 1] = "step " .. tostring(setting.step) end
        guidance = "Choose a number" .. (#parts > 0 and (" (" .. table.concat(parts, ", ") .. ")") or "") .. ", or ask me to open the control."
    elseif setting.type == "color" then
        guidance = "Choose a color name, RGB value, or #RRGGBB, or ask me to open the color control."
    elseif setting.type == "string" then
        guidance = "Tell me the text or media name you want, or ask me to open the control."
    end
    if type(A.StartPendingFlow) == "function" then
        A.StartPendingFlow("settingValue", {
            settingKey = setting.key,
            expectedType = setting.type,
            label = item.label or setting.label,
            page = item.page,
        })
    end
    return {
        text = prefix .. "\n" .. guidance,
        status = "ambiguous",
        summary = "Requests the missing value for an exact MSUF control.",
        searchResults = R.RegistryLocationResultFollowups(entries, 1),
        selectPendingResult = 1,
    }
end

