function R.BroadPageNavigationCanonical(text)
    local norm = R.Normalize(text)
    local subject = norm:match("^open%s+(.+)$")
        or norm:match("^take%s+me%s+to%s+(.+)$")
        or norm:match("^direct%s+me%s+to%s+(.+)$")
        or norm:match("^bring%s+me%s+to%s+(.+)$")
        or norm:match("^lead%s+me%s+to%s+(.+)$")
        or norm:match("^go%s+to%s+(.+)$")
        or norm:match("^jump%s+to%s+(.+)$")
        or norm:match("^navigate%s+to%s+(.+)$")
        or norm:match("^show%s+me%s+(.+)$")
        or norm:match("^find%s+(.+)$")
        or norm:match("^where%s+is%s+(.+)$")
        or norm:match("^where%s+are%s+(.+)$")
    if not subject then return nil end
    subject = R.Trim(subject:gsub("^the%s+", ""):gsub("%s+page$", ""):gsub("%s+menu$", "")
        :gsub("%s+options$", ""):gsub("%s+settings$", ""))
    return DIRECT_NAVIGATION_PAGE_SUBJECTS[subject]
end

function A.RouterIsBroadPageNavigationRequest(text)
    return R.BroadPageNavigationCanonical(text) ~= nil
end

function R.TryBroadPageNavigation(text, coreHandler)
    local canonical = R.BroadPageNavigationCanonical(text)
    if not canonical or type(coreHandler) ~= "function" then return nil end
    return coreHandler(canonical)
end

function R.TryDirectSettingNavigation(text, coreHandler)
    local norm = R.Normalize(text)
    if norm == "" or R.LooksLikeGuidedTourRequest(norm) then return nil end
    local direct = norm:match("^take%s+me%s+to%s+(.+)$")
        or norm:match("^direct%s+me%s+to%s+(.+)$")
        or norm:match("^bring%s+me%s+to%s+(.+)$")
        or norm:match("^lead%s+me%s+to%s+(.+)$")
        or norm:match("^go%s+to%s+(.+)$")
        or norm:match("^find%s+and%s+open%s+(.+)$")
        or norm:match("^jump%s+to%s+(.+)$")
        or norm:match("^navigate%s+to%s+(.+)$")
        or norm:match("^show%s+me%s+(.+)$")
        or norm:match("^open%s+(.+)$")
    if not direct then return nil end
    direct = R.Trim(direct:gsub("^the%s+", ""):gsub("^exact%s+", "")
        :gsub("%s+setting$", ""):gsub("%s+option$", ""):gsub("%s+control$", "")
        :gsub("%s+slider$", ""):gsub("%s+dropdown$", ""):gsub("%s+toggle$", "")
        :gsub("%s+checkbox$", ""):gsub("%s+picker$", ""))
    if direct == "" or not R.RegistrySettingSearchEntries then return nil end
    -- Broad page commands already have an exact, stable open_page route. Do
    -- not reinterpret them as a similarly named leaf setting merely because
    -- the user used conversational wording such as "take me to Colors".
    if DIRECT_NAVIGATION_PAGE_SUBJECTS[direct] then return nil end
    -- Established navigation tools (profile import, anchor picker, recovery,
    -- previews, Edit Mode, and similar actions) are more specific than a fuzzy
    -- leaf-setting match. Preserve their registered action contract; exact
    -- control wording such as "target width" typically has no action plan and
    -- continues into the setting search below.
    if type(coreHandler) == "function" and type(A.Parse) == "function" then
        local parsed = A.Parse(text)
        local actionKey = parsed and parsed.kind == "action" and parsed.action and parsed.action.key or nil
        -- Navigation phrasing can contain a real target value ("take me to
        -- Raid Debuff Filter: dispellable" or "direct me to Target Portrait
        -- Position: left"). The ordinary parser already resolves the exact
        -- typed setting, but executing that plan would mutate it. Reuse only
        -- its stable setting identity and open the control instead.
        if parsed and parsed.kind == "changes" and type(parsed.changes) == "table"
            and #parsed.changes > 0
        then
            local primary = parsed.changes[1]
            local primarySetting = primary and primary.setting
            local exactNavigation = type(primarySetting) == "table"
                and tostring(primarySetting.key or "") ~= ""
            -- Some specialist plans append boolean=true prerequisites after
            -- the requested enum/filter. They still have one unambiguous
            -- primary control. A genuine multi-setting request must remain a
            -- choice instead of silently selecting its first control.
            if exactNavigation and #parsed.changes > 1 then
                for i = 2, #parsed.changes do
                    local dependency = parsed.changes[i]
                    local dependencySetting = dependency and dependency.setting
                    if type(dependencySetting) ~= "table"
                        or dependencySetting.type ~= "boolean"
                        or dependency.value ~= true
                    then
                        exactNavigation = false
                        break
                    end
                end
            end
            if exactNavigation and R.RegistrySettingItemForKey then
                local item = R.RegistrySettingItemForKey(primarySetting.key)
                local exactResult = item and R.OpenExactSettingItem(item) or nil
                if exactResult then return exactResult end
            end
        end
        local function RunParsedAction()
            local actionResult = coreHandler(text)
            if actionResult and not A.RouterIsUnknownResult(actionResult) then return actionResult end
            if parsed and type(A.ExecutePlan) == "function" then
                actionResult = A.ExecutePlan(parsed)
                if actionResult and R.IsExplicitNavigationCommand(text) then actionResult = R.AsNavigationResult(actionResult) end
                return actionResult
            end
            return nil
        end
        local actionMutability = parsed and parsed.action and tostring(parsed.action.mutability or "") or ""
        if actionKey and actionKey ~= "open_page" and actionKey ~= "open_setting_control"
            and (actionMutability == "navigation" or actionMutability == "readOnly")
        then
            local actionResult = RunParsedAction()
            if actionResult and actionResult._readOnlyGuard ~= true
                and not A.RouterIsUnknownResult(actionResult)
            then
                return actionResult
            end
        elseif actionKey == "open_page" and (direct:match("%s+options$")
            or direct:match("%s+settings$") or direct:match("%s+page$") or direct:match("%s+menu$"))
        then
            local pageResult = RunParsedAction()
            if pageResult and not A.RouterIsUnknownResult(pageResult) then
                -- Page-style aura wording still names one readable lane state
                -- (for example "show me target buff settings"). Preserve the
                -- successful page route, but include that lane's current value
                -- so navigation answers the named setting instead of returning
                -- only a generic "opened" acknowledgement.
                local scope, _, groupScope = R.AuraScopeForDetailText(norm)
                local lane = R.AuraLaneFromText(norm)
                if scope and not groupScope and lane and R.RegistrySettingItemForKey
                    and R.RegistrySettingCurrentValueLine
                then
                    local item = R.RegistrySettingItemForKey("auras3." .. scope .. "." .. lane .. ".visible")
                    local valueLine = item and R.RegistrySettingCurrentValueLine(item) or nil
                    local body = tostring(pageResult.text or "")
                    if valueLine and not body:find("Current value:", 1, true) then
                        pageResult.text = body ~= "" and (body .. "\n" .. valueLine) or valueLine
                    end
                end
                return pageResult
            end
        end
    end
    local entries = R.RegistrySettingSearchEntries(direct, norm, 8)
    local top = entries and entries[1]
    if not top or not top.item then return nil end
    local nextScore = tonumber(entries[2] and entries[2].rawScore) or -10000
    local rawScore = tonumber(top.rawScore) or 0
    local exactLabel = R.RegistrySubjectMatchesLabel and R.RegistrySubjectMatchesLabel(top.item, direct)
    if rawScore >= 600 and (exactLabel or rawScore - nextScore >= 300) then
        return R.OpenExactSettingItem(top.item)
    end
    local visible = math.min(3, #entries)
    if visible < 1 then return nil end
    local lines = { "I found a few possible MSUF controls. Pick the one you want me to open:" }
    for i = 1, visible do lines[#lines + 1] = tostring(i) .. ". " .. tostring(entries[i].item.label or "MSUF setting") end
    return {
        text = table.concat(lines, "\n"),
        status = "ambiguous",
        result = "ambiguous",
        summary = "Assistant direct setting navigation choices",
        searchResults = R.RegistryLocationResultFollowups(entries, visible),
    }
end

local SETTING_BROWSER_PAGE_SIZE = 8
local SETTING_BROWSER_PAGE_ALIASES = {
    ["cast bars"] = "opt_castbar", ["cast bar"] = "opt_castbar", ["castbars"] = "opt_castbar",
    ["colors"] = "opt_colors", ["colours"] = "opt_colors", ["fonts"] = "opt_fonts",
    ["bars"] = "opt_bars", ["gameplay"] = "gameplay", ["profiles"] = "profiles",
    ["class resources"] = "classpower", ["class power"] = "classpower",
    ["modules"] = "modules", ["misc"] = "opt_misc", ["miscellaneous"] = "opt_misc",
    ["group layout"] = "gf_layout", ["group health"] = "gf_layout", ["group text"] = "gf_layout",
    ["group effects"] = "gf_bars", ["group dispel overlay"] = "gf_bars",
    ["group indicators"] = "gf_indicators", ["group auras"] = "gf_auras",
}

local function SettingBrowserSubject(norm)
    if norm == "list all settings" or norm == "show all settings" or norm == "browse all settings"
        or norm == "list every setting" or norm == "show every setting"
    then
        return "all"
    end
    local patterns = {
        "^list%s+all%s+(.+)%s+settings$", "^show%s+all%s+(.+)%s+settings$", "^browse%s+all%s+(.+)%s+settings$",
        "^list%s+(.+)%s+settings$", "^show%s+(.+)%s+settings$", "^browse%s+(.+)%s+settings$",
        "^list%s+all%s+(.+)%s+options$", "^show%s+all%s+(.+)%s+options$", "^browse%s+(.+)%s+controls$",
    }
    for _, pattern in ipairs(patterns) do
        local subject = norm:match(pattern)
        if subject and subject ~= "" then
            subject = R.Trim(subject):gsub("^me%s+", "")
            if subject ~= "" then return subject end
        end
    end
    return nil
end

local function SettingBrowserSpec(subject)
    subject = R.Normalize(subject)
    if subject == "all" then return { subject = subject, title = "All page-resolvable MSUF settings" } end

    local function isScopeOnly(scope, label)
        local normalized = {}
        local function add(value)
            value = R.Normalize(value)
            if value ~= "" then normalized[value] = true end
        end
        add(scope)
        add(label)
        add(tostring(label or "") .. " frame")
        add(tostring(label or "") .. " frames")
        for _, alias in ipairs((A.UnitAliases and A.UnitAliases[scope]) or {}) do add(alias) end
        if scope == "player" then add("my frame") end
        return normalized[subject] == true
    end

    local unit, unitLabel = R.UnitFrameScopeFromText(subject)
    if unit then
        local scopeOnly = isScopeOnly(unit, unitLabel)
        return {
            subject = subject,
            unit = unit,
            term = scopeOnly and nil or subject,
            title = scopeOnly and (tostring(unitLabel or unit) .. " settings") or (subject:gsub("^%l", string.upper) .. " settings"),
        }
    end
    local group, groupLabel = R.GroupScopeFromText(subject)
    if group then
        local scopeOnly = isScopeOnly(group, groupLabel)
        return {
            subject = subject,
            group = group,
            term = scopeOnly and nil or subject,
            title = scopeOnly and (tostring(groupLabel or group) .. " settings") or (subject:gsub("^%l", string.upper) .. " settings"),
        }
    end
    local page = SETTING_BROWSER_PAGE_ALIASES[subject]
    if page then
        local title = type(A.DisplayPageLabel) == "function" and A.DisplayPageLabel(page, subject) or subject
        return { subject = subject, page = page, title = tostring(title) .. " settings" }
    end
    return { subject = subject, term = subject, title = tostring(subject:gsub("^%l", string.upper)) .. " settings" }
end

local function SettingBrowserResolvedPage(setting)
    local page = setting and setting.page
    local resolver = A.ResolveMenuPageForSetting or (A.Knowledge and A.Knowledge.ResolveSettingPage)
    if (page == nil or page == "") and type(resolver) == "function" then
        local ok, value = pcall(resolver, setting)
        if ok then page = value end
    end
    page = tostring(page or "")
    return page ~= "" and page or nil
end

local function SettingBrowserMatches(setting, page, spec)
    if not page then return false end
    if spec.unit and not (tostring(setting.unit or "") == spec.unit or page == "uf_" .. spec.unit) then return false end
    if spec.group then
        local unit = tostring(setting.unit or "")
        if unit ~= spec.group and unit ~= "gf_" .. spec.group then return false end
    end
    if spec.page and page ~= spec.page then return false end
    if not spec.term then return true end
    local haystack = R.Normalize(table.concat({
        tostring(setting.key or ""), tostring(setting.label or ""), tostring(setting.attribute or ""),
        tostring(setting.category or ""), tostring(setting.frameType or ""), tostring(setting.unit or ""), tostring(page),
    }, " "))
    local parser = A.Parser
    if parser and type(parser.MeaningTokens) == "function" then
        local haystackSet = parser.MeaningTokens(haystack)
        local _, wanted = parser.MeaningTokens(spec.term)
        if type(haystackSet) == "table" and type(wanted) == "table" and #wanted > 0 then
            for i = 1, #wanted do
                if not haystackSet[wanted[i]] then return false end
            end
            return true
        end
    end
    return R.HasNormalizedPhrase(haystack, spec.term)
end

local function SettingBrowserEntries(spec)
    local registry = A.Registry
    local settings = R.EnsureCompleteSettingRegistry() or {}
    local cache = R._settingBrowserCache
    if type(cache) == "table"
        and cache.registry == registry
        and cache.count == #settings
        and cache.subject == spec.subject
        and type(cache.entries) == "table"
    then
        return cache.entries
    end
    local out = {}
    for index, setting in ipairs(settings) do
        if index % 64 == 0 and type(A.MaybeYield) == "function" then A.MaybeYield() end
        local page = SettingBrowserResolvedPage(setting)
        if SettingBrowserMatches(setting, page, spec) then
            -- Keep the full scan allocation-light. Only the eight visible rows
            -- need navigation result objects; materializing all 4k+ settings
            -- here made an explicit "list all settings" request unnecessarily
            -- expensive and retained no useful state for the next turn.
            out[#out + 1] = setting
        end
    end
    table.sort(out, function(left, right)
        local a, b = R.Normalize(left.label), R.Normalize(right.label)
        if a ~= b then return a < b end
        return tostring(left.key or "") < tostring(right.key or "")
    end)
    -- Retain only the active browser's lightweight reference list while the
    -- menu is open. A different subject replaces it, and menu hide/new task
    -- clears it, so follow-up pagination is O(visible rows) without creating a
    -- permanent all-settings cache.
    R._settingBrowserCache = {
        registry = registry,
        count = #settings,
        subject = spec.subject,
        entries = out,
    }
    return out
end

function A.ClearRouterTransientCaches()
    R._settingBrowserCache = nil
    R._openEndedSettingCache = nil
    R._registryExactLabelLookupCache = nil
end

function R.TrySettingBrowserShortcut(text)
    local norm = R.Normalize(text)
    local context = A.GetContext and A.GetContext() or nil
    local browser = type(context) == "table" and context.settingBrowser or nil
    local subject = SettingBrowserSubject(norm)
    local direction
    if not subject and type(browser) == "table" then
        if R.ContainsAny(norm, { "next settings", "next setting page", "more settings", "show more settings" }) then direction = 1 end
        if R.ContainsAny(norm, { "previous settings", "previous setting page", "back settings", "show previous settings" }) then direction = -1 end
    end
    if not subject and not direction then return nil end

    local spec = SettingBrowserSpec(subject or browser.subject)
    local entries = SettingBrowserEntries(spec)
    if #entries == 0 then
        return {
            text = "I couldn't find a page-resolvable MSUF setting list for '" .. tostring(subject or browser.subject) .. "'. Try a frame or page such as Target, Auras, Cast Bars, Colors, or Group Layout.",
            status = "info",
            summary = "Assistant setting browser no match",
        }
    end
    local offset = subject and 1 or (tonumber(browser.offset) or 1) + direction * SETTING_BROWSER_PAGE_SIZE
    local maxOffset = math.floor((#entries - 1) / SETTING_BROWSER_PAGE_SIZE) * SETTING_BROWSER_PAGE_SIZE + 1
    if offset < 1 then offset = 1 end
    if offset > maxOffset then offset = maxOffset end
    if type(context) == "table" then
        context.settingBrowser = { subject = spec.subject, offset = offset }
    end
    local last = math.min(#entries, offset + SETTING_BROWSER_PAGE_SIZE - 1)
    local visible = {}
    local lines = { tostring(spec.title), tostring(offset) .. "-" .. tostring(last) .. " of " .. tostring(#entries) }
    for index = offset, last do
        local setting = entries[index]
        local item = R.RegistrySettingItemForKey(setting and setting.key)
        if item then visible[#visible + 1] = { item = item } end
        local current
        if setting and type(setting.get) == "function" then
            local ok, value = pcall(setting.get)
            if ok and type(R.RegistryValueLabel) == "function" then current = R.RegistryValueLabel(setting, value) end
        end
        local suffix = " — " .. R.SettingControlNoun(item)
        if current ~= nil and tostring(current) ~= "" then suffix = suffix .. ", current " .. tostring(current) end
        if setting and setting.assistantMutationSafe == false then suffix = suffix .. ", read-only fallback" end
        lines[#lines + 1] = tostring(#visible) .. ". " .. tostring(item and (item.label or item.key) or setting and (setting.label or setting.key) or "MSUF setting") .. suffix
    end
    lines[#lines + 1] = "Reply 'next settings' or 'previous settings'. You can also say 'open result 2' or 'explain result 2'."
    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Assistant paginated setting browser",
        searchResults = R.RegistryLocationResultFollowups(visible, #visible),
    }
end

R.LAST_CHANGE_EXPLAIN_FOLLOWUP_TERMS = {
    "what does it do", "what does that do", "what does this do",
    "what does it mean", "what does that mean", "what does this mean",
    "explain it", "explain that", "explain this",
    "why should i use it", "why should i use that", "why should i use this",
    "why would i use it", "why would i use that", "why would i use this",
    "what is it for", "what is that for", "what is this for",
    "what does it help with", "what does that help with", "what does this help with",
}

function R.LastChangedSettingItem()
    local ctx = A.GetContext and A.GetContext() or nil
    local key = tostring(ctx and ctx.lastSetting or "")
    if key == "" and type(ctx and ctx.lastChangeBundle) == "table" then
        for i = #ctx.lastChangeBundle, 1, -1 do
            key = tostring(ctx.lastChangeBundle[i] and ctx.lastChangeBundle[i].key or "")
            if key ~= "" then break end
        end
    end
    if key == "" then return nil, ctx end

    local registry = A.Registry
    local setting = registry and type(registry.GetSetting) == "function" and registry:GetSetting(key) or nil
    if not setting then return nil, ctx end

    local page = setting.page or R.FallbackPageForSetting(setting)
    local pageLabel = page and A.DisplayPageLabel and A.DisplayPageLabel(page, "MSUF page") or nil
    local label = type(A.DisplaySettingLabel) == "function" and A.DisplaySettingLabel(setting) or tostring(setting.label or key)
    return {
        kind = "setting",
        key = key,
        settingKey = key,
        label = label,
        page = page,
        pageLabel = pageLabel,
        category = setting.category,
        controlType = setting.type,
        setting = setting,
        canOpen = page ~= nil,
        canExplain = true,
    }, ctx
end

function R.LastChangeFollowupHasSubject(norm)
    norm = R.Normalize(norm)
    if norm == "current value" or norm == "value now" then return true end
    if R.HasNormalizedPhrase(norm, "it")
        or R.HasNormalizedPhrase(norm, "that")
        or R.HasNormalizedPhrase(norm, "this")
    then
        return true
    end
    return R.ContainsAny(norm, {
        "last setting", "last option", "same setting", "same option",
        "the setting", "the option", "last change", "previous change",
    })
end

function R.LastChangeFollowupHasExplicitOtherSubject(norm)
    norm = R.Normalize(norm)
    if R.ContainsAny(norm, {
        "result 1", "result 2", "result 3", "option 1", "option 2", "option 3",
        "choice 1", "choice 2", "choice 3",
    }) then
        return true
    end
    if norm:find(" of ", 1, true)
        and not R.ContainsAny(norm, { "of it", "of that", "of this", "of the last setting", "of last setting", "of the last option", "of last option" })
    then
        return true
    end
    if norm:find(" for ", 1, true)
        and not R.ContainsAny(norm, { "for it", "for that", "for this", "for the last setting", "for last setting", "for the last option", "for last option" })
    then
        return true
    end
    return false
end

function R.LastChangedSettingCurrentValueLine(item, ctx)
    local setting = item and item.setting
    if not setting then return nil end
    local value
    if type(setting.get) == "function" then
        value = setting.get()
    else
        value = ctx and ctx.lastValue
    end
    local valueLabel = R.RegistryValueLabel(setting, value)
    if valueLabel == nil or valueLabel == "" then return nil end
    return "Current value: " .. tostring(item.label or setting.label or "that setting") .. " is " .. tostring(valueLabel) .. "."
end

function R.TryLastChangeSettingFollowup(text)
    local norm = R.Normalize(text)
    if norm == "" then return nil end
    if not R.LastChangeFollowupHasSubject(norm) or R.LastChangeFollowupHasExplicitOtherSubject(norm) then return nil end

    local asksOpenControl = R.ContainsAny(norm, R.LAST_CHANGE_OPEN_CONTROL_TERMS)
    local asksValue = R.ContainsAny(norm, R.LAST_CHANGE_VALUE_FOLLOWUP_TERMS)
    local asksLocation = R.ContainsAny(norm, R.LAST_CHANGE_LOCATION_FOLLOWUP_TERMS)
    local asksExplain = R.ContainsAny(norm, R.LAST_CHANGE_EXPLAIN_FOLLOWUP_TERMS)
    if not asksOpenControl and not asksValue and not asksLocation and not asksExplain then return nil end

    local item, ctx = R.LastChangedSettingItem()
    if not item then return nil end

    local label = tostring(item.label or "Last changed setting")
    local pageLabel = tostring(item.pageLabel or "the matching MSUF page")
    local controlType = tostring(item.controlType or (item.setting and item.setting.type) or "setting")
    local valueLine = R.LastChangedSettingCurrentValueLine(item, ctx)
    local example = R.RegistrySettingExample(item)
    local lines = {}

    if asksOpenControl then
        return R.OpenExactSettingItem(item)
    end

    if asksLocation and not asksValue and not asksExplain then
        lines[#lines + 1] = label .. " setting location"
        lines[#lines + 1] = "This is the last setting I changed. It lives on " .. pageLabel .. " and is " .. R.RegistrySettingTypeText(controlType, item) .. ". I did not change it from this location question."
        if valueLine then lines[#lines + 1] = valueLine end
        if example and example ~= "" then lines[#lines + 1] = "Examples: open " .. pageLabel:lower() .. "; " .. example .. "." end
        local noun = R.SettingControlNoun(item)
        lines[#lines + 1] = "Do you want me to open and focus that exact " .. noun .. "? Reply: open it."
        return {
            text = table.concat(lines, "\n"),
            status = "info",
            result = "info",
            summary = "Shows where the last changed setting lives.",
            searchResults = { item },
            selectPendingResult = 1,
        }
    end

    if asksValue and not asksExplain then
        lines[#lines + 1] = label .. " current value"
        lines[#lines + 1] = "This is the last setting I changed."
        lines[#lines + 1] = valueLine or "I do not have a saved current value for " .. label .. "."
        lines[#lines + 1] = "It lives on " .. pageLabel .. ". Ask 'undo' to revert the last Assistant change if needed."
        lines[#lines + 1] = "You can ask: where is it | what does it do" .. (example and (" | " .. example) or "")
        return {
            text = table.concat(lines, "\n"),
            status = "info",
            result = "info",
            summary = "Shows the current value for the last changed setting.",
        }
    end

    lines[#lines + 1] = label .. " explanation"
    lines[#lines + 1] = "This is the last setting I changed."
    lines[#lines + 1] = R.RegistrySettingPurpose(item)
    lines[#lines + 1] = label .. " lives on " .. pageLabel .. ". It is " .. R.RegistrySettingTypeText(controlType, item) .. ". I did not change it from this explanation question."
    if valueLine then lines[#lines + 1] = valueLine end
    local choicesLine = R.RegistryEnumChoicesLine(item)
    if choicesLine then lines[#lines + 1] = choicesLine end
    if example and example ~= "" then lines[#lines + 1] = "Examples: open " .. pageLabel:lower() .. "; " .. example .. "." end
    lines[#lines + 1] = "You can ask: where is it | what is it now | undo"
    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Explains the last changed setting.",
    }
end

function R.RegistryRelatedLine(close)
    if type(close) ~= "table" or #close <= 1 then return nil end
    local related = {}
    for i = 2, math.min(#close, 3) do
        local label = close[i] and close[i].item and close[i].item.label
        if label then related[#related + 1] = tostring(label) end
    end
    if #related == 0 then return nil end
    return "Related nearby settings: " .. table.concat(related, "; ") .. "."
end

function R.RegistrySubjectMatchesLabel(item, subject)
    local label = R.Normalize(item and item.label or "")
    subject = R.Normalize(subject)
    if label == "" or subject == "" then return false end
    local matched = 0
    for token in subject:gmatch("%S+") do
        if #token > 2 then
            if not R.HasNormalizedPhrase(label, token) then return false end
            matched = matched + 1
        end
    end
    return matched > 0
end

function R.RegistrySettingCurrentValueLine(item)
    local setting = item and item.setting
    if not setting or type(setting.get) ~= "function" then return nil end
    local value = setting.get()
    local valueLabel = R.RegistryValueLabel(setting, value)
    if valueLabel == nil or valueLabel == "" then return nil end
    local label = tostring(item.label or setting.label or "MSUF setting")
    return "Current value: " .. label .. " is " .. tostring(valueLabel) .. "."
end

function R.RegistrySettingItemForKey(settingKey)
    settingKey = tostring(settingKey or "")
    if settingKey == "" then return nil end
    local registry = A.Registry
    local setting = registry and type(registry.GetSetting) == "function" and registry:GetSetting(settingKey) or nil
    if not setting then return nil end

    -- AutoCoverage retains inverse legacy name-anchor spellings as raw
    -- compatibility fallbacks: unit frames own `nameTextAnchor`, while group
    -- frames own `nameAnchor`. An exact visible-label lookup can otherwise let
    -- the generated string shadow win before the semantic parser reaches the
    -- reviewed enum, turning a harmless explicit no-op into an unsafe refusal.
    if setting.generated == true and setting.type == "string" then
        local owner = settingKey:match("^(.-)%.nameAnchor$")
        local reviewedKey = owner and (owner .. ".nameTextAnchor") or nil
        if not reviewedKey then
            owner = settingKey:match("^(.-)%.nameTextAnchor$")
            reviewedKey = owner and (owner .. ".nameAnchor") or nil
        end
        local reviewed = reviewedKey and registry:GetSetting(reviewedKey) or nil
        if reviewed and reviewed.generated ~= true and reviewed.type == "enum" then
            settingKey, setting = reviewedKey, reviewed
        end
    end

    local page = setting.page or R.FallbackPageForSetting(setting)
    local pageLabel = page and A.DisplayPageLabel and A.DisplayPageLabel(page, "MSUF page") or nil
    local label = type(A.DisplaySettingLabel) == "function" and A.DisplaySettingLabel(setting) or tostring(setting.label or settingKey)
    return {
        kind = "setting",
        key = settingKey,
        settingKey = settingKey,
        label = label,
        page = page,
        pageLabel = pageLabel,
        category = setting.category,
        controlType = setting.type,
        setting = setting,
        canOpen = page ~= nil,
        canExplain = true,
    }
end

function R.RegistryVisibilityCurrentValueSettingKey(subject, norm)
    subject = R.Normalize(subject)
    norm = R.Normalize(norm)
    if subject == "" then return nil end
    if not R.ContainsAny(norm, {
        "visible", "visble", "shown", "showing", "hidden", "hiden",
        "enabled", "enabld", "disabled", "disabld",
        "turned on", "turnd on", "turned off", "turnd off",
        "on", "off", "show", "shows", "shwo", "shwos", "see", "se",
    }) then return nil end

    if R.ContainsAny(subject, { "party frame", "party frames", "party group frame", "party group frames" }) then return "gf_party.enabled" end
    if R.ContainsAny(subject, { "raid frame", "raid frames", "raid group frame", "raid group frames" }) then return "gf_raid.enabled" end
    if R.ContainsAny(subject, { "mythic raid frame", "mythic raid frames", "mythic frame", "mythic frames", "mythic group frame", "mythic group frames" }) then return "gf_mythicraid.enabled" end

    if R.ContainsAny(subject, { "player frame", "my frame", "self frame" }) then return "player.enabled" end
    if R.ContainsAny(subject, { "target frame", "target unit frame" }) then return "target.enabled" end
    if R.ContainsAny(subject, { "focus frame", "focus unit frame" }) then return "focus.enabled" end
    if R.ContainsAny(subject, { "pet frame", "pet unit frame" }) then return "pet.enabled" end
    if R.ContainsAny(subject, { "boss frame", "boss frames", "boss unit frame", "boss unit frames" }) then return "boss.enabled" end
    if R.ContainsAny(subject, { "target of target frame", "target of target unit frame", "targettarget frame", "tot frame" }) then return "targettarget.enabled" end
    if R.ContainsAny(subject, { "focus target frame", "focus target unit frame", "focustarget frame" }) then return "focustarget.enabled" end
    return nil
end

function R.RegistryCurrentValueClarification(subject, entries, limit)
    local lines = { "Current value clarification" }
    local visible = math.min(tonumber(limit) or 3, #(entries or {}))
    if visible > 0 then
        lines[#lines + 1] = "I found multiple possible MSUF settings for " .. tostring(subject or "that request") .. ":"
        for i = 1, visible do
            local item = entries[i] and entries[i].item or {}
            local line = R.RegistryLocationLine(i, item)
            local valueLine = R.RegistrySettingCurrentValueLine(item)
            if valueLine then
                line = line .. "; " .. valueLine
            end
            lines[#lines + 1] = line
        end
        lines[#lines + 1] = "Pick a result or ask for the exact setting name. I did not change anything."
        lines[#lines + 1] = "You can ask: current value of result 1 | explain result 1 | open result 1"
        return {
            text = table.concat(lines, "\n"),
            status = "info",
            result = "info",
            summary = "Assistant registry current value clarification",
            searchResults = R.RegistryLocationResultFollowups(entries, visible),
        }
    end

    lines[#lines + 1] = "I could not confidently identify which MSUF setting you mean. Name the frame and setting, for example 'current value of target cast bar height'."
    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Assistant registry current value clarification",
    }
end

R.CROSS_FRAME_TEXT_UNIT_TERMS = {
    { unit = "targettarget", label = "Target of Target", terms = { "target of target", "targettarget", "targets target", "tot" } },
    { unit = "focustarget", label = "Focus Target", terms = { "focus target", "focustarget" } },
    { unit = "player", label = "Player", terms = { "player", "player frame", "my frame", "self" } },
    { unit = "target", label = "Target", terms = { "target", "target frame" } },
    { unit = "focus", label = "Focus", terms = { "focus", "focus frame" } },
    { unit = "pet", label = "Pet", terms = { "pet", "pet frame" } },
    { unit = "boss", label = "Boss", terms = { "boss", "boss frame", "boss frames" } },
}

function R.CrossFrameTextUnitInFragment(fragment)
    fragment = R.Normalize(fragment)
    if fragment == "" then return nil, nil end
    for i = 1, #R.CROSS_FRAME_TEXT_UNIT_TERMS do
        local spec = R.CROSS_FRAME_TEXT_UNIT_TERMS[i]
        for j = 1, #(spec.terms or {}) do
            if R.HasNormalizedPhrase(fragment, spec.terms[j]) then return spec.unit, spec.label end
        end
    end
    return nil, nil
end

function R.CrossFrameTextRequestParts(norm)
    norm = R.Normalize(norm)
    if norm == "" then return nil end
    if not R.ContainsAny(norm, {
        "name", "name text", "health text", "hp text", "power text", "mana text",
        "font size", "text size", "bigger", "larger", "smaller",
    }) then
        return nil
    end
    local patterns = {
        "^(.-)%s+on%s+the%s+(.+)$",
        "^(.-)%s+on%s+(.+)$",
        "^(.-)%s+from%s+the%s+(.+)$",
        "^(.-)%s+from%s+(.+)$",
        "^(.-)%s+in%s+the%s+(.+)$",
        "^(.-)%s+in%s+(.+)$",
    }
    for i = 1, #patterns do
        local before, after = norm:match(patterns[i])
        local subjectUnit, subjectLabel = R.CrossFrameTextUnitInFragment(before)
        local frameUnit, frameLabel = R.CrossFrameTextUnitInFragment(after)
        if subjectUnit and frameUnit then
            return subjectUnit, subjectLabel, frameUnit, frameLabel
        end
    end
    return nil
end

function R.CrossFrameTextFieldLabel(norm)
    norm = R.Normalize(norm)
    if R.ContainsAny(norm, { "health text", "hp text", "health value", "hp value" }) then return "health text" end
    if R.ContainsAny(norm, { "power text", "mana text", "resource text" }) then return "power text" end
    if R.ContainsAny(norm, { "font size", "text size", "bigger", "larger", "smaller" }) then return "name text size" end
    if R.ContainsAny(norm, { "name", "name text" }) then return "name text" end
    return "text"
end

function R.CrossFrameVisualFieldLabel(norm)
    norm = R.Normalize(norm)
    if R.ContainsAny(norm, { "castbar", "cast bar", "cast bars" }) then return "cast bar" end
    if R.ContainsAny(norm, { "debuff", "debuffs", "debuff icons", "debuff lane" }) then return "debuffs" end
    if R.ContainsAny(norm, { "buff", "buffs", "buff icons", "buff lane" }) then return "buffs" end
    if R.ContainsAny(norm, { "aura", "auras", "aura icons" }) then return "auras" end
    if R.ContainsAny(norm, {
        "raid marker", "raid markers", "raid icon", "raid icons", "marker icon",
        "moon icon", "skull icon", "cross icon", "square icon", "triangle icon",
        "diamond icon", "star icon", "circle icon",
    }) then return "raid marker icon" end
    if R.ContainsAny(norm, { "portrait", "portraits" }) then return "portrait" end
    if R.ContainsAny(norm, { "health bar", "hp bar" }) then return "health bar" end
    if R.ContainsAny(norm, { "power bar", "mana bar", "resource bar" }) then return "power bar" end
    return nil
end

function R.CrossFrameVisualRequestParts(norm)
    norm = R.Normalize(norm)
    if norm == "" then return nil end
    if not R.CrossFrameVisualFieldLabel(norm) then return nil end

    local patterns = {
        "^(.-)%s+on%s+the%s+(.+)$",
        "^(.-)%s+on%s+(.+)$",
        "^(.-)%s+in%s+the%s+(.+)$",
        "^(.-)%s+in%s+(.+)$",
        "^(.-)%s+inside%s+the%s+(.+)$",
        "^(.-)%s+inside%s+(.+)$",
        "^(.-)%s+from%s+the%s+(.+)$",
        "^(.-)%s+from%s+(.+)$",
    }
    for i = 1, #patterns do
        local before, after = norm:match(patterns[i])
        local fieldLabel = before and R.CrossFrameVisualFieldLabel(before) or nil
        local subjectUnit, subjectLabel = R.CrossFrameTextUnitInFragment(before)
        local frameUnit, frameLabel = R.CrossFrameTextUnitInFragment(after)
        if fieldLabel and subjectUnit and frameUnit then
            return subjectUnit, subjectLabel, frameUnit, frameLabel, fieldLabel
        end
    end
    return nil
end

function A.RouterTryCrossFrameTextRequestShortcut(text, coreHandler)
    local norm = R.Normalize(text)
    local subjectUnit, subjectLabel, frameUnit, frameLabel = R.CrossFrameTextRequestParts(norm)
    if not subjectUnit or not frameUnit or subjectUnit == frameUnit then return nil end

    local fieldLabel = R.CrossFrameTextFieldLabel(norm)
    local isTotInlineName = subjectUnit == "targettarget"
        and frameUnit == "target"
        and fieldLabel == "name text"
        and not R.ContainsAny(norm, { "health", "hp", "power", "mana", "font size", "text size", "bigger", "larger", "smaller" })
    if isTotInlineName then return nil end

    local body
    local examples
    local actions
    if subjectUnit == "targettarget" and frameUnit == "target" then
        body = "Target of Target name can be shown inline on the Target frame, but only as the inline Target Target text option. MSUF does not expose separate inline Target of Target health, power, or font-size controls on the Target frame. I did not change anything from this cross-frame request."
        examples = "show target of target name on target frame; open target; open target of target; make target of target name bigger on target of target frame."
        actions = "Open Target | Open Target of Target | show target of target name on target frame"
    elseif subjectUnit == "focustarget" and frameUnit == "focus" then
        body = "Focus Target has its own frame and text options. MSUF does not expose separate inline Focus Target text on the Focus frame. I did not change anything from this cross-frame request."
        examples = "show focus target frame; show focus target name; open focus target."
        actions = "Open Focus Target | show focus target name"
    else
        body = subjectLabel .. " " .. fieldLabel .. " belongs to the " .. subjectLabel .. " frame, while " .. frameLabel .. " text belongs to the " .. frameLabel .. " frame. I did not change both frames from this cross-frame request."
        local subjectCommand = "show " .. subjectLabel:lower() .. " name"
        if fieldLabel == "health text" then
            subjectCommand = "show " .. subjectLabel:lower() .. " health text"
        elseif fieldLabel == "power text" then
            subjectCommand = "show " .. subjectLabel:lower() .. " power text"
        elseif fieldLabel == "name text size" then
            subjectCommand = "make " .. subjectLabel:lower() .. " name bigger"
        end
        examples = subjectCommand .. "; open " .. subjectLabel:lower() .. "; open " .. frameLabel:lower() .. "."
        actions = "Open " .. subjectLabel .. " | Open " .. frameLabel
    end

    return {
        text = "Cross-frame text clarification\n" .. body .. "\nExamples: " .. examples .. "\nYou can ask: " .. actions,
        status = "info",
        result = "info",
        summary = "Assistant cross-frame text clarification",
    }
end

function A.RouterTryCrossFrameVisualRequestShortcut(text, coreHandler)
    local norm = R.Normalize(text)
    local subjectUnit, subjectLabel, frameUnit, frameLabel, fieldLabel = R.CrossFrameVisualRequestParts(norm)
    if not subjectUnit or not frameUnit or subjectUnit == frameUnit or not fieldLabel then return nil end

    local examples
    local actions
    if fieldLabel == "cast bar" then
        examples = "show " .. subjectLabel:lower() .. " cast bar; open cast bars; open " .. subjectLabel:lower() .. "."
        actions = "Open Cast Bars | Open " .. subjectLabel .. " | Open " .. frameLabel
    elseif fieldLabel == "buffs" or fieldLabel == "debuffs" or fieldLabel == "auras" then
        examples = "show " .. subjectLabel:lower() .. " " .. fieldLabel .. "; show " .. frameLabel:lower() .. " " .. fieldLabel .. "; open auras."
        actions = "Open Auras | Open " .. subjectLabel .. " | Open " .. frameLabel
    else
        examples = "show " .. subjectLabel:lower() .. " " .. fieldLabel .. "; show " .. frameLabel:lower() .. " " .. fieldLabel .. "; open " .. subjectLabel:lower() .. "."
        actions = "Open " .. subjectLabel .. " | Open " .. frameLabel
    end

    local plural = fieldLabel == "buffs" or fieldLabel == "debuffs" or fieldLabel == "auras"
    local be = plural and "are" or "is"
    local belongs = plural and "They belong" or "It belongs"
    local settingNoun = plural and "settings" or "setting"
    local body = subjectLabel .. " " .. fieldLabel .. " " .. be .. " frame-specific. " .. belongs .. " to the " .. subjectLabel .. " frame; the " .. frameLabel .. " frame has its own separate " .. fieldLabel .. " " .. settingNoun .. " when MSUF exposes one. I did not change either frame from this cross-frame request."
    return {
        text = "Cross-frame visual clarification\n" .. body .. "\nExamples: " .. examples .. "\nYou can ask: " .. actions,
        status = "info",
        result = "info",
        summary = "Assistant cross-frame visual clarification",
    }
end

function R.IsTargetTargetInlineLocationQuestion(norm)
    norm = R.Normalize(norm)
    if norm == "" then return false end
    return norm:match("^where%s+") ~= nil
        or norm:match("^which%s+") ~= nil
        or norm:match("^what%s+setting") ~= nil
        or norm:match("^what%s+option") ~= nil
        or norm:match("^what%s+controls") ~= nil
        or norm:match("^how%s+do%s+i") ~= nil
        or norm:match("^how%s+can%s+i") ~= nil
        or norm:match("^can%s+i") ~= nil
        or norm:match("^is%s+there%s+a%s+way") ~= nil
        or R.ContainsAny(norm, { "help me find", "help me locate", "tell me where", "show me where", "looking for" })
end

function A.RouterTryTargetTargetInlineNameShortcut(text, coreHandler)
    local norm = R.Normalize(text)
    if not R.LooksLikeTargetTargetInlineNameRequest(norm) then return nil end
    if norm:match("^why%s+") then return nil end

    if R.IsTargetTargetInlineLocationQuestion(norm) then
        if A.RouterTryRegistrySettingLocationShortcut then
            local location = A.RouterTryRegistrySettingLocationShortcut("where can I turn on Target Target Inline Text", coreHandler)
            if location then return location end
        end
        return {
            text = "Target Target Inline Text setting location\nTarget Target Inline Text lives on Target. I did not change it.",
            status = "info",
            result = "info",
            summary = "Assistant ToT inline location",
        }
    end

    local wantsOff = R.WantsVisibilityOff(norm)
    local wantsOn = R.WantsVisibilityOn(norm) or R.ContainsAny(norm, { "visible" })
    if not wantsOff and not wantsOn then return nil end

    local command = (wantsOff and "turn off " or "turn on ") .. "Target Target Inline Text"
    return R.CoreControl(coreHandler, command, "Target Target Inline Text lives on Target. Ask 'open target' to inspect it first.", "info")
end

function R.DependentTargetProblemKind(norm)
    norm = R.Normalize(norm)
    if R.ContainsAny(norm, { "target of target", "targettarget", "targets target", "tot" }) then
        return "targettarget", "Target of Target", "Target", "Target Target Inline Text", "Target of Target Name"
    end
    if R.ContainsAny(norm, { "focus target", "focustarget" }) then
        return "focustarget", "Focus Target", "Focus", nil, "Focus Target Name"
    end
    return nil
end

function R.LooksLikeDependentTargetProblem(norm)
    norm = R.Normalize(norm)
    if norm == "" then return false end
    if R.ContainsAny(norm, { "castbar", "cast bar", "cast bars", "buff", "buffs", "debuff", "debuffs", "aura", "auras" }) then return false end
    if not R.DependentTargetProblemKind(norm) then return false end
    if R.HasNaturalProblemTerm(norm) or R.ContainsAny(norm, R.VISIBILITY_PROBLEM_TERMS) then return true end
    return R.ContainsAny(norm, { "where is", "where are", "where can", "how do i show", "how can i show" })
end

function R.HasRawAuraDoT(text)
    return tostring(text or ""):find("%f[%a]DoT[sS]?%f[%A]") ~= nil
end

function R.NameShorteningDotsSettingKey(text)
    local raw = tostring(text or "")
    local norm = R.Normalize(raw)
    if R.HasRawAuraDoT(raw) then return nil end
    local explicitName = R.ContainsAny(norm, {
        "name", "names", "short name", "short names", "shortened name", "shortened names",
        "shorten", "shortening", "truncate", "truncation", "cut off name", "cut off names",
    })
    local hasDots = R.ContainsAny(norm, {
        "dot", "dots", "ellipsis", "ellipses", "trailing dots", "three dots", "two dots",
        "name dots", "name ellipsis",
    }) or (explicitName and (raw:find("%.%.") ~= nil or raw:find("…", 1, true) ~= nil))
    if not hasDots then return nil end
    if not explicitName and R.ContainsAny(norm, {
        "corner", "status", "indicator", "spell indicator", "combo point", "class resource",
        "class power", "aura", "buff", "debuff", "castbar", "spell name",
    }) then
        return nil
    end
    if R.ContainsAny(norm, { "all names", "all unit names", "all shortened names", "shared names", "global names" }) then
        return "fontScope.shared.shortenNameNoEllipsis"
    end
    local parser = A.Parser or {}
    local groups = type(parser.DetectGroups) == "function" and parser.DetectGroups(norm) or {}
    if groups[1] then return "gf_" .. tostring(groups[1]) .. ".nameNoEllipsis" end
    local scope = type(parser.DetectGlobalScope) == "function" and parser.DetectGlobalScope(norm) or nil
    if not scope or scope == "player" or scope == "gf_party" or scope == "gf_raid" then return nil end
    return "fontScope." .. tostring(scope) .. ".shortenNameNoEllipsis"
end

function R.LooksLikeNameShorteningDotsRequest(text)
    return R.NameShorteningDotsSettingKey(text) ~= nil
end

function R.DependentTargetMentionsParentFrame(norm, parentLabel)
    norm = R.Normalize(norm)
    parentLabel = R.Normalize(parentLabel)
    if parentLabel == "target" then
        return R.ContainsAny(norm, { "target frame", "on target", "on the target", "in target", "in the target", "inside target", "inside the target" })
    end
    if parentLabel == "focus" then
        return R.ContainsAny(norm, { "focus frame", "on focus", "on the focus", "in focus", "in the focus", "inside focus", "inside the focus" })
    end
    return false
end

function A.RouterTryDependentTargetTroubleshootingShortcut(text, coreHandler)
    local norm = R.Normalize(text)
    if not R.LooksLikeDependentTargetProblem(norm) then return nil end

    local unit, unitLabel, parentLabel, inlineLabel, frameNameLabel = R.DependentTargetProblemKind(norm)
    if not unit or not unitLabel or not parentLabel then return nil end

    local mentionsParentFrame = R.DependentTargetMentionsParentFrame(norm, parentLabel)
    local followQuery = frameNameLabel
    local exactLabel = frameNameLabel
    local body
    local examples
    local actions

    if unit == "targettarget" and mentionsParentFrame and inlineLabel then
        followQuery = inlineLabel
        exactLabel = inlineLabel
        body = "On the Target frame, Target of Target is shown through Target Target Inline Text. If it is missing, check that setting first. It only has visible content when your current target actually has a target. The separate Target of Target frame also has its own visibility and name settings. I did not change anything from this troubleshooting question."
        examples = "turn on target target inline text; open target; open target of target; show target of target frame."
        actions = "Open Target | Open Target of Target | Current Value"
    elseif unit == "focustarget" and mentionsParentFrame then
        body = "Focus Target is a separate MSUF frame, not inline text inside the Focus frame. If it is missing, check Focus Target frame visibility, Focus Target Name, frame alpha/size, and whether your focus actually has a target. I did not change anything from this troubleshooting question."
        examples = "show focus target frame; show focus target name; open focus target."
        actions = "Open Focus Target | Current Value"
    else
        body = unitLabel .. " only has visible content when the watched unit has a target. If it is missing, check " .. unitLabel .. " frame visibility, " .. frameNameLabel .. ", frame alpha/size, active profile, and whether the unit actually has a target. I did not change anything from this troubleshooting question."
        examples = "show " .. unitLabel:lower() .. " frame; show " .. unitLabel:lower() .. " name; open " .. unitLabel:lower() .. "."
        actions = "Open " .. unitLabel .. " | Current Value"
    end

    return {
        text = unitLabel .. " visibility help\n" .. body .. "\nExamples: " .. examples .. "\nYou can ask: " .. actions,
        status = "info",
        result = "info",
        summary = "Assistant dependent target troubleshooting",
        searchResults = R.SettingFollowupResultsByQuery(followQuery, exactLabel),
    }
end

function A.RouterTryRegistrySettingExplainShortcut(text, coreHandler, precomputedEntries)
    local norm = R.Normalize(text)
    if not R.LooksLikeRegistrySettingExplainQuestion(norm) then return nil end
    local subject = R.RegistryExplainSubject(norm)
    local entries = precomputedEntries or R.RegistrySettingSearchEntries(subject ~= "" and subject or text, norm, 16)
    if not entries or #entries == 0 then return nil end

    local top = entries[1]
    local exactLabelMatch = R.RegistrySubjectMatchesLabel(top and top.item, subject)
    if not top or (top.score < 340 and not (exactLabelMatch and top.score >= 260)) then return nil end
    if (tonumber(top.rawScore) or 0) < 260 and not R.RegistryRequestedScope(norm) then return nil end
    local runnerUp = entries[2]
    if not exactLabelMatch and runnerUp
        and (tonumber(runnerUp.score) or 0) >= (tonumber(top.score) or 0) - 40
        and (tonumber(runnerUp.rawScore) or 0) >= (tonumber(top.rawScore) or 0) - 40
    then
        return nil
    end

    local close = { top }
    for i = 2, #entries do
        if #close >= 3 then break end
        local includeRelated = entries[i].score >= top.score - 140
            and (tonumber(entries[i].rawScore) or 0) >= (tonumber(top.rawScore) or 0) - 120
            and R.RegistryCloseMatchAllowed(entries[i].item, norm)
        if not includeRelated and exactLabelMatch
            and R.RegistrySubjectMatchesLabel(entries[i].item, subject)
            and R.RegistryCloseMatchAllowed(entries[i].item, norm)
        then
            includeRelated = true
        end
        if includeRelated then
            close[#close + 1] = entries[i]
        end
    end

    local item = top.item or {}
    local label = tostring(item.label or "MSUF setting")
    local pageLabel = tostring(item.pageLabel or "MSUF page")
    local controlType = tostring(item.controlType or (item.setting and item.setting.type) or "setting")
    local example = R.RegistrySettingExample(item)
    local lines = {
        label .. " explanation",
        R.RegistrySettingPurpose(item),
        label .. " lives on " .. pageLabel .. ". It is " .. R.RegistrySettingTypeText(controlType, item) .. ". I did not change it.",
    }
    local valueLine = R.RegistryCurrentValueLine(item)
    if valueLine then lines[#lines + 1] = valueLine end
    local verdictLine = R.RegistrySettingGraphVerdictLine(item)
    if verdictLine then lines[#lines + 1] = verdictLine end
    local choicesLine = R.RegistryEnumChoicesLine(item)
    if choicesLine then lines[#lines + 1] = choicesLine end
    local relatedLine = R.RegistryRelatedLine(close)
    if relatedLine then lines[#lines + 1] = relatedLine end
    if example and example ~= "" then lines[#lines + 1] = "Examples: open " .. pageLabel:lower() .. "; " .. example .. "." end
    lines[#lines + 1] = "You can ask: Open " .. pageLabel .. " | Current Value" .. (example and (" | " .. example) or "")

    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Assistant registry setting explanation",
        searchResults = R.RegistryLocationResultFollowups(close, #close),
    }
end

function A.RouterTryRegistrySettingCurrentValueShortcut(text, coreHandler, precomputedEntries)
    local norm = R.Normalize(text)
    if not R.LooksLikeRegistrySettingCurrentValueQuestion(norm) then return nil end
    local subject = R.RegistryCurrentValueSubject(norm)
    local directKey = R.RegistryVisibilityCurrentValueSettingKey(subject, norm)
    local directItem = directKey and R.RegistrySettingItemForKey(directKey) or nil
    local entries = precomputedEntries
        or (directItem and { { item = directItem, score = 9999, rawScore = 9999 } })
        or R.RegistrySettingSearchEntries(subject ~= "" and subject or text, norm, 16)
    if not entries or #entries == 0 then return R.RegistryCurrentValueClarification(subject, nil, 0) end
    local top = entries[1]
    if not directItem and (not top or (tonumber(top.rawScore) or 0) < 220) then
        return R.RegistryCurrentValueClarification(subject, nil, 0)
    end
    if not directItem and R.RegistryCurrentValueSubjectTooBroad(subject) then
        return R.RegistryCurrentValueClarification(subject, entries, 3)
    end

    local exactLabelMatch = directItem ~= nil or R.RegistrySubjectMatchesLabel(top and top.item, subject)
    if not top or (top.score < 340 and not (exactLabelMatch and top.score >= 260)) then
        return R.RegistryCurrentValueClarification(subject, entries, 3)
    end
    if (tonumber(top.rawScore) or 0) < 260 and not R.RegistryRequestedScope(norm) then
        return R.RegistryCurrentValueClarification(subject, entries, 3)
    end

    local close = { top }
    for i = 2, #entries do
        if #close >= 3 then break end
        local includeRelated = entries[i].score >= top.score - 140
            and (tonumber(entries[i].rawScore) or 0) >= (tonumber(top.rawScore) or 0) - 120
            and R.RegistryCloseMatchAllowed(entries[i].item, norm)
        if not includeRelated and exactLabelMatch
            and R.RegistrySubjectMatchesLabel(entries[i].item, subject)
            and R.RegistryCloseMatchAllowed(entries[i].item, norm)
        then
            includeRelated = true
        end
        if includeRelated then close[#close + 1] = entries[i] end
    end
    if #close > 1 and not exactLabelMatch then
        return R.RegistryCurrentValueClarification(subject, close, #close)
    end

    local item = top.item or {}
    local setting = item.setting
    local label = tostring(item.label or "MSUF setting")
    local pageLabel = tostring(item.pageLabel or "MSUF page")
    local controlType = tostring(item.controlType or (setting and setting.type) or "setting")
    local valueLine = R.RegistrySettingCurrentValueLine(item)
    local example = R.RegistrySettingExample(item)
    local lines = { label .. " current value" }

    local expectedBoolean = R.RegistryCurrentValueExpectedBoolean(norm)
    if setting and setting.type == "boolean" and expectedBoolean ~= nil and type(setting.get) == "function" then
        local current = setting.get()
        if type(current) == "boolean" then
            lines[#lines + 1] = (current == expectedBoolean and "Yes." or "No.")
        end
    end

    local expectedNumber = R.RegistryCurrentValueExpectedNumber(norm)
    if setting and setting.type == "number" and expectedNumber ~= nil and type(setting.get) == "function" then
        local current = tonumber(setting.get())
        if current ~= nil then
            local epsilon = math.max(0.000001, math.abs(expectedNumber) * 0.000001)
            lines[#lines + 1] = (math.abs(current - expectedNumber) <= epsilon and "Yes." or "No.")
        end
    end

    lines[#lines + 1] = valueLine or ("I cannot read a saved current value for " .. label .. " right now.")
    lines[#lines + 1] = label .. " lives on " .. pageLabel .. ". It is " .. R.RegistrySettingTypeText(controlType, item) .. ". I did not change it."
    local choicesLine = R.RegistryEnumChoicesLine(item)
    if choicesLine then lines[#lines + 1] = choicesLine end
    local relatedLine = R.RegistryRelatedLine(close)
    if relatedLine then lines[#lines + 1] = relatedLine end
    if example and example ~= "" then lines[#lines + 1] = "Examples: open " .. pageLabel:lower() .. "; " .. example .. "." end
    lines[#lines + 1] = "You can ask: Open " .. pageLabel .. " | Explain Result 1" .. (example and (" | " .. example) or "")

    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Assistant registry setting current value",
        searchResults = R.RegistryLocationResultFollowups({ top }, 1),
    }
end

-- Recurring "which is better" questions have real answers inside MSUF's own
-- domain, and refusing to give one is not neutrality -- it is just unhelpful.
-- Each entry states a recommendation, says what it depends on, and hands over
-- the exact command for either choice. Nothing here mutates.
R.ADVICE_TOPICS = {
    {
        match = { "class color", "class colour", "custom color", "custom colour", "klassenfarbe", "eigene farbe" },
        needs = { "class", "custom", "klassenfarbe", "eigene" },
        lines = {
            "Class colour vs custom colour",
            "Use class colour when you need to identify people fast -- healing, dispelling, any group content. It is the reason most raiders keep it on.",
            "Use a custom colour for frames that are always the same unit anyway: your own player frame, or a target frame you want to match a UI theme.",
            "Many setups mix them: class colour on group frames, custom on the player frame.",
            "Say 'set party health color mode to class' or 'set player health color mode to custom' and I will apply it.",
        },
    },
    {
        match = { "auras on top", "auras on bottom", "buffs on top", "buffs on bottom", "aura anchor", "auren oben", "auren unten" },
        needs = { "top", "bottom", "oben", "unten" },
        lines = {
            "Auras above or below the frame",
            "Below the frame is the safer default: auras grow away from the health bar, so a long buff list never covers the health text you are reading.",
            "Above works well when the frame sits at the bottom of the screen, or when you want auras closer to your eye line during a fight.",
            "Whichever you pick, keep the growth direction pointing away from the frame so the list expands into empty space.",
            "Say 'set target buff anchor to top' or 'set target buff anchor to bottom' and I will apply it.",
        },
    },
    {
        match = { "percent", "percentage", "numbers", "prozent", "zahlen" },
        needs = { "percent", "percentage", "percentages", "number", "numbers", "prozent", "zahl", "zahlen" },
        lines = {
            "Percentages vs raw numbers",
            "Percentages are the better default: they mean the same thing on every unit, so you can judge a target at a glance without knowing its maximum health.",
            "Raw numbers matter when the absolute amount does -- healers watching an effective-health pool, or tracking whether a heal will overheal.",
            "You do not have to choose: MSUF gives each frame a left, center and right slot, so many setups put the percentage in one and the number in another.",
            "Say 'set player hp right slot to percent' or 'set player hp left slot to current' and I will apply it.",
        },
    },
}

function R.AdviceTopicReply(text)
    local norm = R.Normalize(text)
    for i = 1, #R.ADVICE_TOPICS do
        local topic = R.ADVICE_TOPICS[i]
        if R.ContainsAny(norm, topic.match) then
            -- Both sides of the comparison must actually be present, or a
            -- passing mention of one word would trigger a lecture.
            local hits = 0
            for j = 1, #topic.needs do
                if R.ContainsAny(norm, { topic.needs[j] }) then hits = hits + 1 end
            end
            if hits >= 2 then
                return {
                    text = table.concat(topic.lines, "\n") .. "\nI did not change anything yet.",
                    status = "info",
                    result = "info",
                    summary = "Answers a preference question with a recommendation, without changing MSUF.",
                }
            end
        end
    end
    return nil
end

-- A "bold" request names a control that only exists per frame (Font Outline),
-- or per group (Party's Bold Text). The parser correctly refuses to write the
-- name/text control the phrase happens to mention -- but refusing silently
-- leaves "I want my name text bold" with no answer at all. Say where bold
-- actually lives instead.
function R.TryStylingQualifierGuidance(text)
    local norm = R.Normalize(text)
    if not R.ContainsAny(norm, { "bold", "italic" }) then return nil end
    local parser = A.Parser
    if type(parser) ~= "table" or type(parser.StylingQualifiersInText) ~= "function" then return nil end
    if not parser.StylingQualifiersInText(norm) then return nil end

    local units = type(parser.DetectUnits) == "function" and parser.DetectUnits(norm) or {}
    local groups = type(parser.DetectGroups) == "function" and parser.DetectGroups(norm) or {}
    local scope = (#units == 1 and tostring(units[1])) or (#groups == 1 and ("gf_" .. tostring(groups[1]))) or nil

    local lines = {}
    if R.ContainsAny(norm, { "italic" }) then
        lines[#lines + 1] = "MSUF has no italic option: WoW fonts expose outline and shadow, not italics."
        lines[#lines + 1] = "The closest look is a heavier outline -- say 'set player font outline to thick outline'."
        return {
            text = table.concat(lines, "\n"),
            status = "info",
            result = "info",
            summary = "Explains that MSUF exposes outline rather than italics.",
        }
    end

    lines[#lines + 1] = "Bold text in MSUF"
    lines[#lines + 1] = "Unit frames have no separate bold switch, and no per-element one either -- what makes their text read as bold is the frame's Font Outline, which applies to every text on that frame."
    lines[#lines + 1] = "Party frames are the exception: they have their own Bold Text toggle."
    if scope and scope:find("^gf_") then
        lines[#lines + 1] = "For that group, say 'turn on party bold text'."
    elseif scope then
        local label = scope:gsub("^%l", string.upper)
        lines[#lines + 1] = "For " .. label .. ", say 'set " .. scope .. " font outline to thick outline'."
    else
        lines[#lines + 1] = "Name the frame and I will set it, for example 'set player font outline to thick outline' or 'turn on party bold text'."
    end
    lines[#lines + 1] = "I did not change anything."
    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Explains where bold text lives without changing MSUF.",
    }
end

-- Read-only answer for advice questions and amount-less comparisons that the
-- decision shortcut could not pin to a single control. It names the controls
-- involved so the player can decide, and states plainly that nothing changed.
function R.AdvisoryNoMutationReply(text, comparative)
    local topicReply = not comparative and R.AdviceTopicReply(text) or nil
    if topicReply then return topicReply end
    local norm = R.Normalize(text)
    local subject = R.RegistryDecisionSubject and R.RegistryDecisionSubject(norm) or ""
    if subject == "" then subject = norm end
    local entries = R.RegistrySettingSearchEntries and R.RegistrySettingSearchEntries(subject, norm, 5) or nil

    local lines = {}
    if comparative == "lookup" then
        -- Asked *about* a control rather than asked to change one.
        lines[#lines + 1] = "Here is what I can point you at — I did not change anything."
    elseif comparative then
        lines[#lines + 1] = "That tells me the order you want, not the size, so I kept MSUF unchanged."
        lines[#lines + 1] = "Give me the exact amount and I will set it, for example 'set target debuff icon size to 30'."
    else
        lines[#lines + 1] = "That is a preference call, so I did not change anything."
    end

    if entries and #entries > 0 then
        lines[#lines + 1] = comparative and "The controls involved:" or "The controls this affects:"
        for i = 1, math.min(#entries, 5) do
            local item = entries[i].item or {}
            lines[#lines + 1] = string.format("%d. %s - %s",
                i, tostring(item.label or "MSUF setting"), tostring(item.pageLabel or "MSUF page"))
        end
        lines[#lines + 1] = "Ask me to open or explain any of them, or name the exact value you want."
        return {
            text = table.concat(lines, "\n"),
            status = "info",
            result = "info",
            summary = "Answers a preference question without changing MSUF.",
            searchResults = R.RegistryLocationResultFollowups and R.RegistryLocationResultFollowups(entries, 5) or nil,
        }
    end

    lines[#lines + 1] = "Name the frame and the option you are weighing up and I will explain both sides, for example 'explain target health bar color mode'."
    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Answers a preference question without changing MSUF.",
    }
end

function A.RouterTryRegistrySettingDecisionShortcut(text, coreHandler)
    local norm = R.Normalize(text)
    if not R.LooksLikeRegistrySettingDecisionQuestion(norm) then return nil end
    local subject = R.RegistryDecisionSubject(norm)
    local entries = R.RegistrySettingSearchEntries(subject ~= "" and subject or text, norm, 16)
    if not entries or #entries == 0 then return nil end

    local top = entries[1]
    local exactLabelMatch = R.RegistrySubjectMatchesLabel(top and top.item, subject)
    if not top or (top.score < 340 and not (exactLabelMatch and top.score >= 260)) then return nil end
    if (tonumber(top.rawScore) or 0) < 260 and not R.RegistryRequestedScope(norm) then return nil end

    local item = top.item or {}
    local setting = item.setting
    local label = tostring(item.label or "MSUF setting")
    local pageLabel = tostring(item.pageLabel or "MSUF page")
    local example = R.RegistrySettingExample(item)
    local lines = {
        label .. " decision help",
        R.RegistrySettingPurpose(item),
        label .. " lives on " .. pageLabel .. ". I did not change it.",
    }
    local valueLine = R.RegistryCurrentValueLine(item)
    if valueLine then lines[#lines + 1] = valueLine end
    if setting and setting.type == "number" then
        local current = type(setting.get) == "function" and tonumber(setting.get()) or nil
        local step = tonumber(setting.step) or 1
        local proposed = R.RegistryDecisionProposedNumber(norm)
        local candidate = proposed
        local proposedText = proposed and tostring(proposed) or nil
        if proposed ~= nil and setting.percent == true and proposed > 1 then
            candidate = proposed / 100
            proposedText = tostring(proposed) .. "%"
        end
        if candidate ~= nil then
            local minimum, maximum = tonumber(setting.min), tonumber(setting.max)
            if (minimum ~= nil and candidate < minimum) or (maximum ~= nil and candidate > maximum) then
                local range
                if minimum ~= nil and maximum ~= nil then
                    range = tostring(minimum) .. " to " .. tostring(maximum)
                elseif minimum ~= nil then
                    range = tostring(minimum) .. " or higher"
                else
                    range = tostring(maximum) .. " or lower"
                end
                lines[#lines + 1] = proposedText .. " is outside this setting's allowed range of " .. range
                    .. ", so I would not recommend applying it. I kept the current value unchanged."
            elseif current ~= nil then
                local comparison
                if math.abs(candidate - current) < 0.000001 then
                    comparison = "matches the current value"
                elseif candidate > current then
                    comparison = "is higher than the current value, " .. tostring(current)
                else
                    comparison = "is lower than the current value, " .. tostring(current)
                end
                local range = minimum ~= nil and maximum ~= nil
                    and (" It is within the allowed range of " .. tostring(minimum) .. " to " .. tostring(maximum) .. ".") or ""
                lines[#lines + 1] = proposedText .. " " .. comparison .. "." .. range
                    .. " It can be sensible if the frame stays readable and does not crowd nearby UI; compare it in the live preview before changing it."
            else
                lines[#lines + 1] = proposedText
                    .. " is a valid candidate inside this control's range. Compare it in the live preview before changing it; there is no single best value for every layout."
            end
        elseif current ~= nil then
            lines[#lines + 1] = "Your current value, " .. tostring(current)
                .. ", is a sensible starting point if the frame is readable and does not crowd nearby UI. Adjust it in "
                .. tostring(step) .. "-point steps while watching the live preview; there is no single best value for every layout."
        else
            lines[#lines + 1] = "There is no single best number for every layout. Start inside the allowed range and adjust in "
                .. tostring(step) .. "-point steps while watching the live preview."
        end
    elseif setting and setting.type == "enum" then
        lines[#lines + 1] = "Keep the current mode when it produces the behavior you want; compare the listed choices in the live preview before switching."
    elseif R.ContainsAny(norm, { "is it safe", "would it be safe" }) then
        lines[#lines + 1] = "Normal MSUF setting changes can be undone, but the safer first step is to inspect the setting or ask for its current value before changing it."
    else
        lines[#lines + 1] = "Keep it enabled if it improves readability or gameplay information for you. Turn it off only if it is visual noise, duplicated elsewhere, or part of a layout you intentionally simplified."
    end
    if example and example ~= "" then lines[#lines + 1] = "Examples: open " .. pageLabel:lower() .. "; " .. example .. "." end
    lines[#lines + 1] = "You can ask: Open " .. pageLabel .. " | Current Value" .. (example and (" | " .. example) or "")

    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Assistant registry setting decision guidance",
        searchResults = R.RegistryLocationResultFollowups({ top }, 1),
    }
end

function A.RouterTryRegistrySettingTroubleshootingShortcut(text, coreHandler)
    local norm = R.Normalize(text)
    if not R.LooksLikeRegistrySettingTroubleshootingQuestion(norm) then return nil end
    local subject = R.RegistryTroubleshootingSubject(norm)
    local entries = R.RegistrySettingSearchEntries(subject ~= "" and subject or text, norm, 16)
    if not entries or #entries == 0 then return nil end

    local top = entries[1]
    local exactLabelMatch = R.RegistrySubjectMatchesLabel(top and top.item, subject)
    if not top or (top.score < 340 and not (exactLabelMatch and top.score >= 260)) then return nil end
    if (tonumber(top.rawScore) or 0) < 260 and not R.RegistryRequestedScope(norm) then return nil end
    local runnerUp = entries[2]
    if not exactLabelMatch and runnerUp
        and (tonumber(runnerUp.score) or 0) >= (tonumber(top.score) or 0) - 40
        and (tonumber(runnerUp.rawScore) or 0) >= (tonumber(top.rawScore) or 0) - 40
    then
        return nil
    end
    local item = top.item or {}
    local label = tostring(item.label or "MSUF setting")
    local pageLabel = tostring(item.pageLabel or "MSUF page")
    local example = R.RegistrySettingExample(item)
    local lines = {
        label .. " troubleshooting help",
        R.RegistrySettingPurpose(item),
        label .. " lives on " .. pageLabel .. ". I did not change it.",
    }
    local valueLine = R.RegistryCurrentValueLine(item)
    if valueLine then lines[#lines + 1] = valueLine end
    lines[#lines + 1] = "If it is missing or not showing, check this setting first, then the related parent visibility option, size/count limits, alpha/opacity, filters, combat state, and the active profile."
    if example and example ~= "" then lines[#lines + 1] = "Examples: open " .. pageLabel:lower() .. "; current value; " .. example .. "." end
    lines[#lines + 1] = "You can ask: Open " .. pageLabel .. " | Current Value" .. (example and (" | " .. example) or "")

    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Assistant registry setting troubleshooting",
        searchResults = R.RegistryLocationResultFollowups({ top }, 1),
    }
end

function A.RouterTryRegistrySettingLocationShortcut(text, coreHandler, precomputedEntries)
    local norm = R.Normalize(text)
    if not R.LooksLikeRegistrySettingLocationQuestion(norm) then return nil end
    local subject = R.RegistryLocationSubject(norm)
    local directKey = R.NameShorteningDotsSettingKey(text)
    local directItem = directKey and R.RegistrySettingItemForKey(directKey) or nil
    local entries = precomputedEntries
        or (directItem and { { item = directItem, score = 10000, rawScore = 10000 } })
        or (subject ~= "" and R.ExactRegistrySettingLabelEntries(subject, 16))
        or (subject ~= "" and R.CanonicalExplicitSearchEntries(subject))
        or (subject ~= "" and R.ExactRegistrySettingAliasEntries(subject, 16))
        or R.RegistrySettingSearchEntries(subject ~= "" and subject or text, norm, 16)
    if not entries or #entries == 0 then return nil end

    local top = entries[1]
    if not top or top.score < 340 then return nil end
    local item = top.item or {}
    local label = tostring(item.label or "MSUF setting")
    local pageLabel = tostring(item.pageLabel or "MSUF page")
    local controlType = tostring(item.controlType or "setting")
    local example = R.RegistrySettingExample(item)
    local close = {}
    close[1] = top
    for i = 2, #entries do
        if #close >= 8 then break end
        if entries[i].score >= top.score - 140
            and (tonumber(entries[i].rawScore) or 0) >= (tonumber(top.rawScore) or 0) - 120
            and R.RegistryCloseMatchAllowed(entries[i].item, norm)
        then
            close[#close + 1] = entries[i]
        end
    end

    local lines
    if #close > 1 then
        lines = { "Matching settings location" }
        lines[#lines + 1] = "Closest MSUF settings:"
        for i = 1, #close do lines[#lines + 1] = R.RegistryLocationLine(i, close[i].item) end
        if #entries > #close then
            lines[#lines + 1] = "More related controls exist. Add the distinguishing detail (for example style, maximum length, or ellipsis), and include the frame name if it is not already clear."
        end
        lines[#lines + 1] = "I did not change anything from this location question. Ask to open or explain a result before changing it."
    else
        lines = {
            label .. " setting location",
            label .. " lives on " .. pageLabel .. ". It is " .. R.RegistrySettingTypeText(controlType, item) .. ". I did not change it from this location question.",
        }
        local setting = item.setting or {}
        local attribute = tostring(setting.attribute or ""):lower()
        local moveAxis = tostring(setting.moveAxis or ""):lower()
        if moveAxis == "x" or attribute:match("offsetx$") or attribute:match("xoffset$") then
            lines[#lines + 1] = "Use this horizontal offset to move it left or right; lower values move left and higher values move right. I kept it unchanged."
        elseif moveAxis == "y" or attribute:match("offsety$") or attribute:match("yoffset$") then
            lines[#lines + 1] = "Use this vertical offset to move it up or down; lower values move down and higher values move up. I kept it unchanged."
        elseif attribute:find("spacing", 1, true) or R.Normalize(label):find("spacing", 1, true) then
            lines[#lines + 1] = "This controls the gap between frames or adjacent elements in that layout."
        end
    end
    if example and example ~= "" then lines[#lines + 1] = "Examples: open " .. pageLabel:lower() .. "; " .. example .. "." end
    lines[#lines + 1] = "You can ask: Open " .. pageLabel .. " | Explain Result 1" .. (example and (" | " .. example) or "")

    return {
        text = table.concat(lines, "\n"),
        status = "info",
        result = "info",
        summary = "Assistant registry setting location",
        searchResults = R.RegistryLocationResultFollowups(close, #close),
        -- A singular, high-confidence location answer establishes an explicit
        -- conversational referent ("it").  A generic search list does not.
        selectPendingResult = #close == 1 and 1 or nil,
    }
end

function R.ContextualSettingFollowupItem()
    local pending = A.pendingResults
    if type(pending) == "table" and #pending == 1 and type(pending[1]) == "table" then
        return pending[1]
    end
    local ctx = A.GetContext and A.GetContext() or nil
    local key = type(ctx) == "table" and tostring(ctx.lastSetting or "") or ""
    if key ~= "" and type(R.RegistrySettingItemForKey) == "function" then
        return R.RegistrySettingItemForKey(key)
    end
    return nil
end

function R.TryContextualSettingAdviceFollowup(text, coreHandler)
    local norm = R.Normalize(text)
    local wantsDecision = R.ContainsAny(norm, {
        "is that good", "is this good", "is it good", "is that a good value",
        "what do you recommend", "what would you recommend", "would you keep it",
        "should i keep it", "is that sensible", "is this sensible",
    })
    local wantsWhy = norm == "why" or norm == "why that" or norm == "why this"
        or norm == "why that change" or norm == "why this change"
    if not wantsDecision and not wantsWhy then return nil end
    local item = R.ContextualSettingFollowupItem()
    local label = item and tostring(item.label or item.settingKey or item.key or "") or ""
    if label == "" then return nil end
    if wantsWhy and A.RouterTryRegistrySettingExplainShortcut then
        return A.RouterTryRegistrySettingExplainShortcut("explain " .. label, coreHandler)
    end
    if wantsDecision and A.RouterTryRegistrySettingDecisionShortcut then
        return A.RouterTryRegistrySettingDecisionShortcut("should i use " .. label, coreHandler)
    end
    return nil
end

function R.TryGeneralGuidanceShortcut(text, coreHandler)    local norm = R.Normalize(text)
    if norm == "" then return nil end
    -- Every reply below is a setup article. None of them is the right answer to
    -- a request that already names one control -- "i want raid heal prediction
    -- off" was answered with advice about raid healing. Guarding the whole
    -- shortcut once beats bolting the same check onto each reply, and the cost
    -- is only paid for value-carrying requests (see TopicAnswerSurvivesExactControl).
    if R.TopicAnswerSurvivesExactControl(true, text) == nil then return nil end

    local combinedGuidanceResult = R.CombinedGuidanceReply(norm)
    if combinedGuidanceResult then return combinedGuidanceResult end

    local classGuidanceResult = R.ClassGuidanceReply(norm)
    if classGuidanceResult then return classGuidanceResult end

    if R.LooksLikeRoleGuidanceRequest(norm) then
        return R.RoleGuidanceReply(norm)
    end

    if R.LooksLikeContentGuidanceRequest(norm) then
        return R.ContentGuidanceReply(norm)
    end

    if R.ContainsAny(norm, R.SETUP_GUIDANCE_TERMS) then
        if type(coreHandler) == "function" then
            local result = coreHandler("guided setup")
            if result and not A.RouterIsUnknownResult(result) then return result end
        end
        return R.SetupGuidanceReply()
    end

    if R.ContainsAny(norm, R.RECOVERY_GUIDANCE_TERMS) then
        return R.RecoveryGuidanceReply()
    end

    if R.ContainsAny(norm, R.CONTEXTLESS_GUIDANCE_TERMS) then
        return R.ContextlessGuidanceReply()
    end

    return nil
end

R.GROUP_AURA_CONTEXT_BLOCKERS = {    "unitframe", "unitframes", "unit frame", "unit frames",
    "target of target", "focus target", "player", "target", "focus", "pet", "boss",
    "party", "raid", "mythic raid", "party frames", "raid frames",
    "castbar", "cast bar", "profile", "profiles", "class resource", "class power", "gameplay",
    "edit mode", "editmode", "bearbeitungsmodus",
}

function R.ShouldKeepGroupAuraContext(norm)    return M and M.activeKey == "gf_auras"
        and R.ContainsAny(norm, R.AURA_BUFF_TERMS)
        and not R.ContainsAny(norm, R.GROUP_AURA_CONTEXT_BLOCKERS)
end

function R.ShouldSkipContext(text)    local norm = R.Normalize(text)
    if norm == "" then return true end
    if R.ContainsAny(norm, R.FLOW_TERMS) then return true end
    if R.ContainsAny(norm, R.NAV_HELP_TERMS) then return true end
    if R.ContainsAny(norm, {
        "what did you change", "what changed", "what was changed", "what did you do",
        "what did you just change", "what exactly did you change", "what did you set",
        "last change", "last assistant change", "previous change", "what is it now",
        "what is it set to", "current value", "value now", "show last change",
        "show me last change", "show me the last change",
    }) then return true end
    if R.ContainsAny(norm, R.EXPLICIT_DOMAIN_TERMS) and not R.ShouldKeepGroupAuraContext(norm) then return true end
    if R.ContainsAny(norm, {
        "it", "that", "this", "same", "do it", "do that", "again", "more", "less",
        "opposite", "other way", "hide it", "clear it", "remove it", "move it",
    }) then return true end
    if R.ContainsAny(norm, {
        "unitframe", "unitframes", "unit frame", "unit frames",
        "target of target", "focus target", "mythic raid", "player", "target", "focus", "pet", "boss",
        "party", "raid", "party frames", "raid frames", "group frames",
    }) then return true end
    local parser = A.Parser or {}
    if type(parser.DetectUnits) == "function" and #(parser.DetectUnits(norm) or {}) > 0 then return true end
    if type(parser.DetectGroups) == "function" and #(parser.DetectGroups(norm) or {}) > 0 then return true end
    return false
end

function R.CurrentPageContext()    local key = M and M.activeKey
    if type(key) ~= "string" or key == "" then return nil end
    return R.PAGE_CONTEXT[key]
end

function R.CurrentPageSummaryLabel()    local ctx = R.CurrentPageContext()
    if ctx and type(ctx.label) == "string" and ctx.label ~= "" then return ctx.label end
    local key = M and M.activeKey
    if A and type(A.DisplayPageLabel) == "function" and type(key) == "string" and key ~= "" then
        return A.DisplayPageLabel(key, "MSUF page")
    end
    return "MSUF page"
end

function R.CurrentGroupScopePrefix()    local scope = M and M.gfScope
    if type(scope) ~= "string" or scope == "" then return nil end
    scope = R.Normalize(scope)
    return R.GROUP_SCOPE_PREFIXES[scope]
end

function R.AddUnique(out, value)    value = R.Trim(value)
    if value == "" then return end
    for i = 1, #out do if out[i] == value then return end end
    out[#out + 1] = value
end

function R.ContextPrefixes(ctx)    local prefixes = {}
    local key = M and M.activeKey
    if R.GROUP_CONTEXT_PAGES[key] then
        R.AddUnique(prefixes, R.CurrentGroupScopePrefix() or "")
    end
    if ctx and ctx.prefix then R.AddUnique(prefixes, ctx.prefix) end
    return prefixes
end

function R.StripBooleanWords(text)    local out = R.Normalize(text)
    out = out:gsub("^turn%s+", "")
    out = out:gsub("^set%s+", "")
    out = out:gsub("^make%s+", "")
    out = out:gsub("^change%s+", "")
    out = out:gsub("^increase%s+", "")
    out = out:gsub("^decrease%s+", "")
    out = out:gsub("^raise%s+", "")
    out = out:gsub("^lower%s+", "")
    out = out:gsub("^detach%s+", "")
    out = out:gsub("^attach%s+", "")
    out = out:gsub("^undock%s+", "")
    out = out:gsub("^dock%s+", "")
    out = out:gsub("^on%s+", "")
    out = out:gsub("^off%s+", "")
    out = out:gsub("^enable%s+", "")
    out = out:gsub("^disable%s+", "")
    out = out:gsub("^einschalten%s+", "")
    out = out:gsub("^ausschalten%s+", "")
    out = out:gsub("^einblenden%s+", "")
    out = out:gsub("^ausblenden%s+", "")
    out = out:gsub("^show%s+", "")
    out = out:gsub("^hide%s+", "")
    out = out:gsub("^erhoehe%s+", "")
    out = out:gsub("^erhoehen%s+", "")
    out = out:gsub("^senke%s+", "")
    out = out:gsub("^reduziere%s+", "")
    out = out:gsub("^abkoppeln%s+", "")
    out = out:gsub("^ankoppeln%s+", "")
    out = out:gsub("%s+on$", "")
    out = out:gsub("%s+off$", "")
    out = out:gsub("%s+enabled$", "")
    out = out:gsub("%s+disabled$", "")
    out = out:gsub("%s+an$", "")
    out = out:gsub("%s+aus$", "")
    return R.Trim(out)
end


function R.StripLeadingCommand(text)    local out = R.Normalize(text)
    out = out:gsub("^set%s+", "")
    out = out:gsub("^change%s+", "")
    out = out:gsub("^make%s+", "")
    out = out:gsub("^increase%s+", "")
    out = out:gsub("^decrease%s+", "")
    out = out:gsub("^raise%s+", "")
    out = out:gsub("^lower%s+", "")
    out = out:gsub("^detach%s+", "")
    out = out:gsub("^attach%s+", "")
    out = out:gsub("^undock%s+", "")
    out = out:gsub("^dock%s+", "")
    out = out:gsub("^erhoehe%s+", "")
    out = out:gsub("^erhoehen%s+", "")
    out = out:gsub("^senke%s+", "")
    out = out:gsub("^reduziere%s+", "")
    out = out:gsub("^abkoppeln%s+", "")
    out = out:gsub("^ankoppeln%s+", "")
    out = out:gsub("^use%s+", "")
    out = out:gsub("^select%s+", "")
    out = out:gsub("^choose%s+", "")
    return R.Trim(out)
end

function R.LeadingRelativeCommand(text)    local norm = R.Normalize(text)
    if R.ContainsAny(norm, { "decrease", "lower", "reduce", "smaller", "shrink", "less", "senke", "reduziere", "kleiner", "weniger" }) then
        return "decrease"
    end
    if R.ContainsAny(norm, { "increase", "raise", "higher", "more", "larger", "bigger", "grow", "erhoehe", "erhoehen", "hoeher", "groesser" }) then
        return "increase"
    end
    return nil
end

function R.AddBooleanContextVariants(variants, prefix, text)    local norm = R.Normalize(text)
    local noun = R.StripBooleanWords(text)
    if noun == "" then return end
    if R.ContainsAny(norm, { "off", "disable", "disabled", "hide", "aus", "deaktivieren", "ausschalten", "verstecken", "ausblenden" }) then
        R.AddUnique(variants, "turn off " .. prefix .. " " .. noun)
        R.AddUnique(variants, "disable " .. prefix .. " " .. noun)
    elseif R.ContainsAny(norm, { "on", "enable", "enabled", "show", "an", "aktivieren", "einschalten", "anzeigen", "einblenden" }) then
        R.AddUnique(variants, "turn on " .. prefix .. " " .. noun)
        R.AddUnique(variants, "enable " .. prefix .. " " .. noun)
    end
end

function R.ContextualVariants(text)    if R.ShouldSkipContext(text) then return nil end
    local ctx = R.CurrentPageContext()
    if not ctx or not ctx.prefix then return nil end
    local norm = R.Normalize(text)
    local variants = {}
    local prefixes = R.ContextPrefixes(ctx)
    local prefix = prefixes[1] or ctx.prefix

    if M.activeKey == "profiles" then
        if norm == "export" or norm == "export profile" then
            R.AddUnique(variants, "export current profile")
        elseif norm == "import" or norm == "import profile" then
            R.AddUnique(variants, "import profile")
        elseif norm == "copy" or norm == "copy profile" then
            R.AddUnique(variants, "copy current profile")
        else
            R.AddUnique(variants, prefix .. " " .. text)
        end
    elseif M.activeKey == "opt_castbar" then
        local noun = R.StripLeadingCommand(text)
        local relativeVerb = R.LeadingRelativeCommand(text)
        if norm == "show timer" or norm == "enable timer" then R.AddUnique(variants, "show target cast time text") end
        if norm == "hide timer" or norm == "disable timer" then R.AddUnique(variants, "hide target cast time text") end
        R.AddBooleanContextVariants(variants, "castbar", text)
        R.AddUnique(variants, "castbar " .. text)
        R.AddUnique(variants, "set castbar " .. text)
        if noun ~= "" and noun ~= R.Normalize(text) then
            if relativeVerb then R.AddUnique(variants, relativeVerb .. " castbar " .. noun) end
            R.AddUnique(variants, "set castbar " .. noun)
            R.AddUnique(variants, "change castbar " .. noun)
        end
        R.AddUnique(variants, "target castbar " .. text)
    elseif M.activeKey == "opt_bars" then
        local noun = R.StripLeadingCommand(text)
        local relativeVerb = R.LeadingRelativeCommand(text)
        R.AddBooleanContextVariants(variants, "bar", text)
        R.AddUnique(variants, "bar " .. text)
        R.AddUnique(variants, "set bar " .. text)
        if noun ~= "" and noun ~= R.Normalize(text) then
            if relativeVerb then R.AddUnique(variants, relativeVerb .. " bar " .. noun) end
            R.AddUnique(variants, "set bar " .. noun)
            R.AddUnique(variants, "change bar " .. noun)
        end
    elseif M.activeKey == "opt_fonts" then
        local noun = R.StripLeadingCommand(text)
        R.AddUnique(variants, "font " .. text)
        R.AddUnique(variants, "set font " .. text)
        if noun ~= "" and noun ~= R.Normalize(text) then
            R.AddUnique(variants, "set font " .. noun)
            R.AddUnique(variants, "change font " .. noun)
        end
    elseif M.activeKey == "opt_colors" then
        R.AddUnique(variants, text .. " color")
        R.AddUnique(variants, "set " .. text)
        R.AddUnique(variants, "global " .. text)
    else
        local noun = R.StripLeadingCommand(text)
        local relativeVerb = R.LeadingRelativeCommand(text)
        for i = 1, #prefixes do
            local scopedPrefix = prefixes[i]
            R.AddBooleanContextVariants(variants, scopedPrefix, text)
            R.AddUnique(variants, scopedPrefix .. " " .. text)
            R.AddUnique(variants, "set " .. scopedPrefix .. " " .. text)
            if noun ~= "" and noun ~= R.Normalize(text) then
                if relativeVerb then R.AddUnique(variants, relativeVerb .. " " .. scopedPrefix .. " " .. noun) end
                R.AddUnique(variants, "set " .. scopedPrefix .. " " .. noun)
                R.AddUnique(variants, "change " .. scopedPrefix .. " " .. noun)
            end
        end
    end
    return #variants > 0 and variants or nil
end

function A.RouterShouldPreferPageContext(text)
    if not R.CurrentPageContext() or R.ShouldSkipContext(text) then return false end
    return R.ContextualVariants(text) ~= nil
end

function R.TryContext(text, coreHandler)    if type(coreHandler) ~= "function" then return nil end
    local variants = R.ContextualVariants(text)
    if not variants then return nil end
    local basePending = A.RouterSnapshotPendingState()
    local bestAmbiguous
    local bestAmbiguousPending
    for i = 1, #variants do
        R.MaybeYield()
        local result = coreHandler(variants[i])
        if result and not A.RouterIsUnknownResult(result) then
            if not A.RouterIsAmbiguousResult(result) then
                local contextSummary = "Current-page context: " .. R.CurrentPageSummaryLabel()
                local priorSummary = tostring(result.summary or "")
                if not priorSummary:find("Current-page context:", 1, true) then
                    if priorSummary ~= "" and priorSummary ~= "MSUF options change." and priorSummary ~= "Changes the matched option." then
                        contextSummary = contextSummary .. " - " .. priorSummary
                    end
                    result.summary = contextSummary
                end
                return result
            end
            local ambiguousPending = A.RouterSnapshotPendingState()
            A.RouterRestorePendingState(basePending)
            bestAmbiguous = bestAmbiguous or result
            bestAmbiguousPending = bestAmbiguousPending or ambiguousPending
        else
            A.RouterRestorePendingState(basePending)
        end
    end
    if bestAmbiguous and bestAmbiguousPending then A.RouterRestorePendingState(bestAmbiguousPending) end
    return bestAmbiguous
end

function R.MutationFallbackVariants(text)    local norm = R.Normalize(text)
    local variants = {}
    if norm == "" then return variants end

    if R.ContainsAny(norm, { "open", "oeffne" }) then
        R.AddUnique(variants, norm:gsub("^oeffne%s+", "open "))
    end

    if R.ContainsAny(norm, { "turn off", "turn on", "enable", "disable", "show", "hide", "an", "aus", "aktivieren", "deaktivieren", "einschalten", "ausschalten", "anzeigen", "verstecken", "einblenden", "ausblenden" }) then
        R.AddUnique(variants, norm:gsub("^turn%s+off%s+", "disable "))
        R.AddUnique(variants, norm:gsub("^turn%s+on%s+", "enable "))
        R.AddUnique(variants, norm:gsub("^show%s+", "turn on "))
        R.AddUnique(variants, norm:gsub("^hide%s+", "turn off "))
        R.AddUnique(variants, norm:gsub("^disable%s+", "turn off "))
        R.AddUnique(variants, norm:gsub("^enable%s+", "turn on "))
        R.AddUnique(variants, norm:gsub("^ausschalten%s+", "turn off "))
        R.AddUnique(variants, norm:gsub("^ausblenden%s+", "turn off "))
        R.AddUnique(variants, norm:gsub("^einschalten%s+", "turn on "))
        R.AddUnique(variants, norm:gsub("^einblenden%s+", "turn on "))
    end

    return variants
end

function A.RouterTryMutationFallbacks(text, coreHandler)
    if type(coreHandler) ~= "function" then return nil end
    local variants = R.MutationFallbackVariants(text)
    local limit = math.min(#variants, 4)
    for i = 1, limit do
        R.MaybeYield()
        if variants[i] ~= R.Normalize(text) then
            local result = coreHandler(variants[i])
            if result and not A.RouterIsUnknownResult(result) then
                result.summary = result.summary or "Matched by a wording shortcut."
                return result
            end
        end
    end
    return nil
end

function A.RouterLooksLikeExplicitSearchRequest(text)
    local norm = R.Normalize(text)
    return norm:match("^search%s+") ~= nil
        or norm:match("^search%s+for%s+") ~= nil
        or norm:match("^find%s+") ~= nil
        or norm:match("^find%s+me%s+") ~= nil
        or norm:match("^help%s+me%s+find%s+") ~= nil
        or norm:match("^look%s+for%s+") ~= nil
        or norm:match("^suche%s+") ~= nil
        or norm:match("^finde%s+") ~= nil
end

function A.RouterLooksLikeExactActionPhrase(text)
    local parser = A.Parser or {}
    if type(parser.ParseExactActionPhraseShortcut) ~= "function" then return false end
    local parsed = parser.ParseExactActionPhraseShortcut(R.Normalize(text), text)
    return type(parsed) == "table" and (parsed.kind == "action" or parsed.kind == "choice")
end

function A.RouterLooksLikePendingChoiceFollowup(text)
    local norm = R.Normalize(text)
    if norm == "" then return false end
    if norm:match("^%d+$") then return true end
    if norm == "what" then return true end
    if R.IsStandaloneCancelReply(norm) then return true end
    if R.ContainsAny(norm, R.FLOW_TERMS) then return true end
    if R.ContainsAny(norm, {
        "option", "choice", "listed option", "listed choice",
        "fix it", "fix that", "apply it", "apply that", "do it", "do that",
        "use it", "use that", "select it", "select that", "pick it", "pick that",
        "open it", "open that", "open this", "open option", "open choice",
        "explain it", "explain that", "explain this", "explain option", "explain choice",
        "why this", "why that", "why it", "tell me more", "more details",
        "current value", "value now", "simple explanation", "explain it simpler",
    }) then
        return true
    end
    if R.ContainsAny(norm, { "it", "this", "that" })
        and R.ContainsAny(norm, { "open", "show", "explain", "describe", "why", "apply", "use", "select", "pick", "run" })
    then
        return true
    end
    return false
end

function A.RouterLooksLikePendingChoiceTopicSwitch(text)
    local norm = R.Normalize(text)
    if norm == "" or A.RouterLooksLikePendingChoiceFollowup(norm) then return false end
    if A.RouterLooksLikeExplicitSearchRequest(norm) then return true end
    if R.ContainsAny(norm, {
        "run checks", "run check", "run diagnostics", "health check",
        "profile status", "show profile summary", "assistant support text",
    }) then
        return true
    end
    if R.LooksLikeBugReportRequest(norm) or R.LooksLikeGuidedTourRequest(norm) then return true end
    if R.ContainsAny(norm, { "here", "this page", "current page", "page help" })
        and R.ContainsAny(norm, { "help", "commands", "what can", "what settings", "explain", "how can", "how do", "where can", "where do" })
    then
        return true
    end
    if R.LooksLikeKnowledgeQuestionPrefix(norm)
        or R.LooksLikeLocalWowUiKnowledgeRequest(norm)
        or R.LooksLikeScopedHelpKnowledgeRequest(norm)
        or R.LooksLikeKnowledgeFirstRequest(norm)
    then
        return true
    end
    if R.LooksLikeRoleGuidanceRequest(norm)
        or R.LooksLikeContentGuidanceRequest(norm)
        or R.LooksLikeClassGuidanceRequest(norm)
    then
        return true
    end
    if R.LooksLikeLiveUnitColorQuestion(norm) or R.TrySignalProblemShortcut(norm) or R.TryReadabilityShortcut(norm) or R.TryColorContrastShortcut(norm) then
        return true
    end
    if A.RouterTryAssistantUsabilityProblemShortcut and A.RouterTryAssistantUsabilityProblemShortcut(norm, nil) then return true end
    if A.RouterTryDecisionGuidanceShortcut and A.RouterTryDecisionGuidanceShortcut(norm, nil) then return true end
    if A.RouterTrySafePlanningShortcut and A.RouterTrySafePlanningShortcut(norm, nil) then return true end
    if A.RouterLooksLikeVisualSettingTopic and A.RouterLooksLikeVisualSettingTopic(norm) then return true end
    if A.RouterLooksLikeMovementSettingTopic and A.RouterLooksLikeMovementSettingTopic(norm) then return true end
    if A.RouterLooksLikeUnitFrameSettingTopic and A.RouterLooksLikeUnitFrameSettingTopic(norm) then return true end
    if R.LooksLikeRegistrySettingDecisionQuestion and R.LooksLikeRegistrySettingDecisionQuestion(norm) then return true end
    if R.LooksLikeRegistrySettingCurrentValueQuestion and R.LooksLikeRegistrySettingCurrentValueQuestion(norm) then return true end
    if R.LooksLikeRegistrySettingExplainQuestion and R.LooksLikeRegistrySettingExplainQuestion(norm) then return true end
    if R.LooksLikeRegistrySettingTroubleshootingQuestion and R.LooksLikeRegistrySettingTroubleshootingQuestion(norm) then return true end
    if R.LooksLikeRegistrySettingLocationQuestion and R.LooksLikeRegistrySettingLocationQuestion(norm) then return true end
    if A.RouterTryEditModeProblemShortcut and A.RouterTryEditModeProblemShortcut(norm, nil) then return true end
    if A.RouterTryProfileProblemShortcut and A.RouterTryProfileProblemShortcut(norm, nil) then return true end
    if A.RouterTryGroupLayoutProblemShortcut and A.RouterTryGroupLayoutProblemShortcut(norm, nil) then return true end
    if A.RouterTryAuraProblemShortcut and A.RouterTryAuraProblemShortcut(norm, nil) then return true end
    if A.RouterTryCastbarProblemShortcut and A.RouterTryCastbarProblemShortcut(norm, nil) then return true end
    if A.RouterTryTextPowerProblemShortcut and A.RouterTryTextPowerProblemShortcut(norm, nil) then return true end
    if A.RouterTryUnitFrameProblemShortcut and A.RouterTryUnitFrameProblemShortcut(norm, nil) then return true end
    if A.RouterTryIndicatorProblemShortcut and A.RouterTryIndicatorProblemShortcut(norm, nil) then return true end
    if A.RouterTryClassResourceProblemShortcut and A.RouterTryClassResourceProblemShortcut(norm, nil) then return true end
    if A.RouterTryGameplayProblemShortcut and A.RouterTryGameplayProblemShortcut(norm, nil) then return true end
    if A.RouterLooksLikeMiscProblemTopic and A.RouterLooksLikeMiscProblemTopic(norm) then return true end
    if (R.HasNaturalProblemTerm(norm) or R.ContainsAny(norm, R.VISIBILITY_PROBLEM_TERMS))
        and (R.ContainsAny(norm, R.NATURAL_GENERIC_PROBLEM_TOPICS)
            or R.ContainsAny(norm, R.NATURAL_CONCRETE_VISIBILITY_TOPICS)
            or R.ContainsAny(norm, R.VISIBILITY_AURA_TERMS)
            or R.ContainsAny(norm, R.VISIBILITY_CASTBAR_TERMS))
    then
        return true
    end
    return false
end

function A.RouteInput(text, coreHandler)
    text = R.Trim(text)
    if text == "" then return nil end
    -- A concrete ecosystem question starts a new topic. Handle it before any
    -- pending confirmation or free-form workflow can reinterpret an addon name
    -- as "yes", a profile destination, or a setting value.
    if A.Knowledge and type(A.Knowledge.LooksLikeComplementaryAddonQuestion) == "function"
        and A.Knowledge.LooksLikeComplementaryAddonQuestion(text)
        and type(A.Knowledge.Answer) == "function"
    then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
        if answer then
            local hadPending = type(A.RouterHasBlockingPendingAssistantState) == "function"
                and A.RouterHasBlockingPendingAssistantState() == true
            local hadPendingResults = (type(A.RouterHasPendingSearchResults) == "function" and A.RouterHasPendingSearchResults())
                or (type(A.RouterHasPendingSelectedResult) == "function" and A.RouterHasPendingSelectedResult())
            if hadPending and type(A.CancelPendingMutationState) == "function" then
                A.CancelPendingMutationState()
            end
            if type(A.RouterClearPendingChoicesForRoute) == "function" then
                A.RouterClearPendingChoicesForRoute()
            end
            if type(A.RouterClearPendingResultsForRoute) == "function" then
                A.RouterClearPendingResultsForRoute()
            end
            A.lastAssistantHelpContext = nil
            A.lastAssistantPlanningContext = nil
            -- A new topic must retire the persisted copy too, or the old help
            -- subject would come back on the next reload.
            A.RouterPersistHelpContext()
            if hadPending or hadPendingResults then
                answer.text = tostring(answer.text or "")
                    .. "\nI cleared the previous pending choice or change because you started a new topic."
            end
            return answer
        end
    end
    -- Pending workflows must see the user's original casing and punctuation.
    -- The routing-language normalizer below intentionally lowercases ordinary
    -- intent text, which is correct for matching but would corrupt free-form
    -- values and profile names (for example "Shadow Word: Pain").
    local pendingFlow = A.Workflow and type(A.Workflow.PendingFlow) == "function"
        and A.Workflow.PendingFlow() or nil
    if type(pendingFlow) == "table" and type(A.HandlePendingFlow) == "function" then
        local pendingResult = A.HandlePendingFlow(text)
        if pendingResult then return pendingResult end
    end
    -- "Does MSUF have X?" asks whether a capability exists; it is never a
    -- request to change one. This has to run ahead of the mutation
    -- specialists: setting labels routinely contain digits ("Texture Layer 3
    -- Offset X"), and a value-hungry lane downstream would read that digit as
    -- the value to write and silently move the frame. Pending confirmations
    -- still win, so an in-flight choice is not hijacked.
    local hasBlockingPending = type(A.RouterHasBlockingPendingAssistantState) == "function"
        and A.RouterHasBlockingPendingAssistantState() == true
    if not hasBlockingPending and R.TryFeatureExistenceQuestion then
        local existence = R.TryFeatureExistenceQuestion(text, coreHandler)
        if existence then return existence end
    end

    -- "Reset everything" / "hide everything" name a scope rather than a
    -- control. Explain the real options instead of letting a fuzzy lane pick
    -- one wholesale action on the user's behalf.
    if not hasBlockingPending and R.TryGlobalScopeGuidance then
        local scoped = R.TryGlobalScopeGuidance(text)
        if scoped then return scoped end
    end

    -- An NPC-qualified bar colour request must reach the NPC control instead of
    -- the nearest generic bar colour mode.
    if not hasBlockingPending and R.TryNpcQualifiedBarColorRequest then
        local npcBar = R.TryNpcQualifiedBarColorRequest(text)
        if npcBar then return npcBar end
    end

    -- A frame-wide aura effect is described by its look, not its name.
    if not hasBlockingPending and R.TryFullFrameAuraEffectRequest then
        local fullFrame = R.TryFullFrameAuraEffectRequest(text)
        if fullFrame then return fullFrame end
    end

    -- "No, I meant target" re-aims the change that just happened rather than
    -- starting a new request.
    if not hasBlockingPending and R.TryRetargetCorrection then
        local retarget = R.TryRetargetCorrection(text, coreHandler)
        if retarget then return retarget end
    end

    if R.IsExplicitMutationRefusal(text) then
        local action = R.ExplicitMutationRefusalAction(text)
        if type(A.CancelPendingMutationState) == "function" then
            A.CancelPendingMutationState()
        end
        local refusalNorm = R.Normalize(text)
        local germanRefusal = R.ContainsAny(refusalNorm, {
            "nicht", "nein", "abbrechen", "rueckgaengig", "wiederholen",
            "anwenden", "uebernehmen", "bestaetigen", "mach das", "mach es",
        })
        if germanRefusal then action = nil end
        local object = action and action:match("^hide%s+(.+)$") or nil
        local lines = { "Understood — I kept MSUF unchanged." }
        if object and object ~= "" then
            lines[#lines + 1] = "I did not hide " .. tostring(object) .. ". If you want it visible, say 'show " .. tostring(object) .. "'."
        elseif action and action ~= "" then
            lines[#lines + 1] = "I did not " .. tostring(action) .. ". Tell me the result you do want, or ask me to show the relevant options."
        else
            lines[#lines + 1] = "Tell me the result you do want, or ask me to show the relevant options."
        end
        return { text = table.concat(lines, "\n"), status = "info", summary = "Acknowledges an explicit request not to make a change." }
    end
    local scopedExclusion = R.ScopedMutationExclusion(text)
    if scopedExclusion then
        if type(A.CancelPendingMutationState) == "function" then A.CancelPendingMutationState() end
        if scopedExclusion.cancel then
            return {
                text = "Understood - neither named MSUF control was changed.",
                status = "info",
                summary = "Honors a neither/nor exclusion without changing MSUF.",
            }
        end
        local result = type(coreHandler) == "function" and coreHandler(scopedExclusion.keep) or nil
        if type(result) ~= "table" then
            return {
                text = "I could not safely isolate the requested change, so I kept every named MSUF control unchanged.",
                status = "ambiguous",
                summary = "Scoped exclusion could not be planned safely.",
            }
        end
        local status = tostring(result.status or result.result or "")
        if status ~= "applied" and status ~= "unchanged" then return result end
        result.text = tostring(result.text or "")
            .. "\nI left " .. tostring(scopedExclusion.excluded) .. " unchanged, as requested."
        result.summary = "Applies only the included MSUF control and preserves the explicitly excluded control."
        return result
    end
    -- "What is MSUF" / "who are you" / "are you an AI" are exact identity
    -- questions, not fuzzy option searches. Answered this late they were
    -- intercepted by a no-match lane that offered settings whose labels merely
    -- contain "MSUF". Pending confirmations are untouched: this only answers.
    if R.LooksLikeAssistantIdentityQuestion(text) then
        local identityReply = R.HumanConversationReply(text)
        if identityReply then return identityReply end
    end

    -- Build requests are answered with the real sequence, before any lane can
    -- read a stray "player frame" out of "track shield wall on my player frame"
    -- and report on an unrelated toggle. This never writes.
    local creationGuidance = R.TryCreationGuidance(text)
    if creationGuidance then return creationGuidance end

    local routedText = R.StripResponseLanguageDirective(text)
    if routedText ~= "" then text = routedText end
    text = R.NormalizeNumericAddCommand(text) or text
    R.ClearStaleHelpContextForInput(text)
    R.ClearStalePlanningContextForInput(text)

    local hasCore = type(coreHandler) == "function"
    local coreCache = {}
    local function Core(value)
        if not hasCore then return nil end
        value = R.Trim(value)
        if coreCache[value] == nil then
            local result = coreHandler(value)
            if result and result._readOnlyGuard == true then result = nil end
            if result and R.IsExplicitNavigationCommand(value) then
                result = R.AsNavigationResult(result)
            elseif result and R.IsExplicitReadOnlyDiagnosticCommand(value) then
                result = R.AsReadOnlyResult(result)
            end
            coreCache[value] = result or false
        end
        return coreCache[value] ~= false and coreCache[value] or nil
    end

    -- Guided-tour wording is an explicit onboarding action, not a page-help or
    -- fuzzy setting query. Resolve it before those read-only lanes can consume
    -- phrases such as "show me around MSUF" as generic guidance.
    if R.LooksLikeGuidedTourRequest(text) and hasCore then
        local guidedResult = Core(text)
        if guidedResult and not A.RouterIsUnknownResult(guidedResult) then return guidedResult end
    end

    -- Priority Frames have two state owners: eight profile settings are safe
    -- direct writes, while character pins require a live hovered group unit.
    -- Resolve questions and pin-by-name wording before Aura "show only" and
    -- generic Name parsers can reinterpret co-tank/player language. Compound
    -- requests containing an unsafe pin operation fail as one atomic request.
    do
        local normalized = R.Normalize(text)
        local priorityTopic = R.ContainsAny(normalized, {
            "priority frame", "priority frames", "priorityframe", "priorityframes", "priority strip",
            "priority pin", "priority pins", "pinned frame", "pinned frames", "pinned player", "pinned players",
            "co tank frame", "co tank frames", "co-tank frame", "co-tank frames", "cotank frame", "cotank frames",
            "off tank frame", "off tank frames", "off-tank frame", "off-tank frames",
            "prioritaetsframe", "prioritaetsframes", "prioritaetsrahmen",
        })
        if priorityTopic then
            local clearPinMutation = normalized:match("^clear%s+.-pin")
                or normalized:match("%s+and%s+clear%s+.-pin")
            local rowPinMutation = normalized:match("^remove%s+.-pin")
                or normalized:match("^reorder%s+.-pin")
                or normalized:match("^move%s+.-pinned%s+player")
                or normalized:match("%s+and%s+remove%s+.-pin")
                or normalized:match("%s+and%s+move%s+.-pinned%s+player")
            local typedPinMutation = not clearPinMutation and not rowPinMutation and (
                normalized:find("%f[%a]pin%f[%A]")
                or normalized:find("%f[%a]unpin%f[%A]")
            )
            local pinMutation = clearPinMutation or rowPinMutation or typedPinMutation

            local function PlacementValue(valueText)
                if R.ContainsAny(valueText, { "free position", " freely", " detached", " free" }) then
                    return "free"
                elseif R.ContainsAny(valueText, { "above", " on top", " top of" }) then
                    return "above"
                elseif R.ContainsAny(valueText, { "below", " underneath", " bottom of" }) then
                    return "below"
                elseif R.ContainsAny(valueText, { "left", "links" }) then
                    return "left"
                elseif R.ContainsAny(valueText, { "right", "rechts" }) then
                    return "right"
                end
            end

            -- "Can/could/would you ..." is a polite command when it carries
            -- a concrete mutation verb. Preserve question safety for "can I"
            -- and "can Priority Frames ..." capability questions, but do not
            -- turn an explicit polite setting request into read-only help.
            local politeSubject = normalized:match("^can%s+you%s+(.+)$")
                or normalized:match("^could%s+you%s+(.+)$")
                or normalized:match("^would%s+you%s+(.+)$")
                or normalized:match("^please%s+(.+)$")
            local politeMutation = politeSubject and (
                politeSubject:match("^enable%s+") or politeSubject:match("^disable%s+")
                or politeSubject:match("^set%s+") or politeSubject:match("^change%s+")
                or politeSubject:match("^make%s+") or politeSubject:match("^turn%s+")
                or politeSubject:match("^show%s+priority%s+") or politeSubject:match("^show%s+pinned%s+")
                or politeSubject:match("^hide%s+priority%s+") or politeSubject:match("^hide%s+pinned%s+")
                or politeSubject:match("^place%s+") or politeSubject:match("^position%s+")
                or politeSubject:match("^attach%s+")
            )
            if politeMutation and not pinMutation then
                local placementVerb = politeSubject:match("^place%s+") or politeSubject:match("^position%s+")
                    or politeSubject:match("^attach%s+")
                local placementValue = placementVerb and PlacementValue(politeSubject) or nil
                local command = placementValue and ("set priority frame placement to " .. placementValue)
                    or politeSubject
                local result = Core(command)
                if result and not A.RouterIsUnknownResult(result) then return result end
            end

            local questionOrRequest = normalized:match("^what%s+") or normalized:match("^why%s+")
                or normalized:match("^how%s+") or normalized:match("^where%s+")
                or normalized:match("^when%s+") or normalized:match("^which%s+")
                or normalized:match("^who%s+") or (not politeMutation and normalized:match("^can%s+"))
                or (not politeMutation and normalized:match("^could%s+"))
                or (not politeMutation and normalized:match("^would%s+"))
                or normalized:match("^should%s+") or normalized:match("^do%s+")
                or normalized:match("^does%s+") or normalized:match("^is%s+")
                or normalized:match("^are%s+") or normalized:match("^will%s+")
                or normalized:find("feature request", 1, true)
                or normalized:find("feature suggestion", 1, true)
                or normalized:match("^please%s+add%s+.-frame")

            if pinMutation or questionOrRequest then
                local query = typedPinMutation and "how do I pin or unpin a player in Priority Frames?" or text
                local answer = A.Knowledge and type(A.Knowledge.Answer) == "function"
                    and A.Knowledge.Answer(query, { currentPage = "gf_priority" }) or nil
                if answer then
                    answer = R.AsReadOnlyResult(answer)
                    if typedPinMutation then
                        answer.text = "I kept the whole request unchanged because Priority players cannot be selected safely by a typed name.\n"
                            .. tostring(answer.text or "")
                        answer.summary = "Keeps name-based Priority pin requests atomic and guides the hover hotkey workflow."
                    end
                    return answer
                end
                if pinMutation then
                    return {
                        text = typedPinMutation
                            and "I kept the whole request unchanged. Set the Priority Frames hover hotkey, then hover the player's MSUF Party or Raid frame and press it to pin or unpin that current group member."
                            or "I kept the character-specific pins unchanged. Open Group Frames > Priority and use the Manual pins controls for Clear, Remove, or Reorder.",
                        status = "info",
                        result = "info",
                        summary = typedPinMutation and "Priority pins require a live hovered group unit."
                            or "Priority pin management requires the live character-specific pin list.",
                    }
                end
            end

            -- Natural container-placement commands map to the reviewed enum;
            -- pixel nudges remain Edit Mode-owned and intentionally do not use
            -- this shortcut.
            local placementVerb = normalized:match("^place%s+") or normalized:match("^position%s+")
                or normalized:match("^attach%s+")
            if placementVerb then
                local value = PlacementValue(normalized)
                if value then
                    local result = Core("set priority frame placement to " .. value)
                    if result and not A.RouterIsUnknownResult(result) then return result end
                end
            end
        end
    end

    local scopedAuraGrowthClarification = R.TryScopedAuraGrowthClarification
        and R.TryScopedAuraGrowthClarification(text)
    if scopedAuraGrowthClarification then return scopedAuraGrowthClarification end

    local scopedAuraGrowthReadOnly = R.TryScopedAuraGrowthReadOnly
        and R.TryScopedAuraGrowthReadOnly(text, Core)
    if scopedAuraGrowthReadOnly then return scopedAuraGrowthReadOnly end

    local runtimeVersion = R.TryRuntimeVersionQuestion and R.TryRuntimeVersionQuestion(text)
    if runtimeVersion then return runtimeVersion end

    local contextualSettingAdvice = R.TryContextualSettingAdviceFollowup
        and R.TryContextualSettingAdviceFollowup(text, Core)
    if contextualSettingAdvice then return contextualSettingAdvice end

    local navigationNorm = R.Normalize(text)
    local navigationSubject = navigationNorm:match("^open%s+(.+)$")
        or navigationNorm:match("^show%s+me%s+(.+)$")
        or navigationNorm:match("^go%s+to%s+(.+)$")
        or navigationNorm:match("^take%s+me%s+to%s+(.+)$")
    local referentialNavigation = navigationSubject == "it"
        or navigationSubject == "that" or navigationSubject == "this"
        or navigationSubject == "the setting" or navigationSubject == "the option"
        or navigationSubject == "the control" or navigationSubject == "the result"
        or (type(A.lastAssistantPlanningContext) == "table"
            and type(R.IsExactSafePlanningFollowup) == "function"
            and R.IsExactSafePlanningFollowup(navigationNorm))
        or (type(R.LAST_CHANGE_OPEN_CONTROL_TERMS) == "table"
            and R.ContainsAny(navigationNorm, R.LAST_CHANGE_OPEN_CONTROL_TERMS))
    local guidedNavigation = type(R.LooksLikeGuidedTourRequest) == "function"
        and R.LooksLikeGuidedTourRequest(text)
    local locationNavigation = type(R.LooksLikeRegistrySettingLocationQuestion) == "function"
        and R.LooksLikeRegistrySettingLocationQuestion(text)
    local exactPageDestination = R.BroadPageNavigationCanonical
        and R.BroadPageNavigationCanonical(text) or nil
    local supportNavigation = navigationNorm == "support links"
        or navigationNorm == "show support links" or navigationNorm == "show me support links"
        or navigationNorm == "zeige support links" or navigationNorm == "zeige mir support links"
        or navigationNorm == "support links anzeigen"
    local pendingNavigation = (A.RouterHasPendingSearchResults()
            and R.LooksLikePendingResultReply(text))
        or (A.RouterHasPendingChoices()
            and A.RouterLooksLikePendingChoiceFollowup(text))
    if not referentialNavigation and not guidedNavigation
        and (not locationNavigation or exactPageDestination ~= nil) and not supportNavigation
        and not pendingNavigation
        and ((type(R.IsExplicitNavigationCommand) == "function" and R.IsExplicitNavigationCommand(text))
            or exactPageDestination ~= nil)
    then
        -- Navigation intent has global precedence over every setting/action
        -- specialist. A value token inside the requested label (for example
        -- "take me to raid debuff dispellable filter") describes the control
        -- to focus; it never grants permission to write that value.
        -- Exact page/control navigation is more specific than the parser's
        -- broad page fallback.  In particular, "show me target portrait
        -- position dropdown" can parse as Open Target even though the real
        -- requested destination is the Target Portrait Position control.
        local navigation = R.TryBroadPageNavigation
            and R.TryBroadPageNavigation(text, Core) or nil
        if not navigation and R.TryDirectSettingNavigation then
            navigation = R.TryDirectSettingNavigation(text, Core)
        end
        if not navigation and type(A.Parse) == "function" then
            local parsedNavigation = A.Parse(text)
            local action = parsedNavigation and parsedNavigation.kind == "action"
                and parsedNavigation.action or nil
            local mutability = action and tostring(action.mutability or "") or ""
            if action and (mutability == "navigation" or mutability == "readOnly") then
                navigation = Core(text)
            end
        end
        if navigation then return R.AsNavigationResult(navigation) end
        -- "Show me <exact control>" names a real destination even when the
        -- navigation resolvers cannot reach it (no live menu, or a control the
        -- bridge does not expose). Say where it lives instead of claiming the
        -- wording was unclear -- the wording was exact.
        local navNamed = type(A.RouterNamedSettingLabel) == "function"
            and A.RouterNamedSettingLabel(text) or nil
        if navNamed and navNamed ~= "" then
            local navLocated = A.RouterTryRegistrySettingLocationShortcut
                and A.RouterTryRegistrySettingLocationShortcut("where is " .. navNamed, Core)
            if navLocated then return navLocated end
            local navDirect = R.NamedSettingDirectAnswer and R.NamedSettingDirectAnswer(navNamed)
            if navDirect then return navDirect end
        end
        -- Before conceding, run the same knowledge retrieval the advisory
        -- lane uses: a request like "show me the healing that is on its way"
        -- names no control, but its folded subject ranks Heal Prediction
        -- Overlay far above everything else. Naming the closest controls
        -- turns a dead end into a one-reply detour; the generic text stays
        -- for genuinely unmatchable wording (and while the index is cold).
        local navSubject = R.RegistryDecisionSubject and R.RegistryDecisionSubject(text) or nil
        local navEntries = (navSubject and navSubject ~= "" and R.RegistrySettingSearchEntries)
            and R.RegistrySettingSearchEntries(navSubject, R.Normalize(text), 5) or nil
        if navEntries and #navEntries > 0 then
            local navLines = {
                "I could not match that wording to one exact MSUF destination, so I kept every setting unchanged. The closest controls:",
            }
            for i = 1, math.min(#navEntries, 3) do
                local navItem = navEntries[i].item or {}
                navLines[#navLines + 1] = string.format("%d. %s - %s",
                    i, tostring(navItem.label or "MSUF setting"), tostring(navItem.pageLabel or "MSUF page"))
            end
            navLines[#navLines + 1] = "Say a number to open one, or name the exact control."
            return {
                text = table.concat(navLines, "\n"),
                status = "info",
                result = "info",
                summary = "Explicit navigation request did not authorize a setting change.",
                searchResults = R.RegistryLocationResultFollowups
                    and R.RegistryLocationResultFollowups(navEntries, 3) or nil,
            }
        end
        return {
            text = "I could not identify one exact MSUF destination from that wording, so I kept every setting unchanged. Name the page or exact control you want me to open.",
            status = "info",
            result = "info",
            summary = "Explicit navigation request did not authorize a setting change.",
        }
    end

    local exploratoryCapability = R.PotentialUnsupportedCapabilityCommand(text)
    if exploratoryCapability then
        local topic = R.ObviousUnsupportedCapabilityTopic(exploratoryCapability)
        local subject = R.CapabilityCommandSubject(exploratoryCapability)
        local confirmed, nearest
        if not topic then confirmed, nearest = R.VerifiedCapabilitySettingEntries(subject) end
        if topic or not confirmed then
            return R.UnsupportedCapabilityReply(exploratoryCapability, nearest, topic)
        end
        -- A verified polite request may continue through the normal mutation
        -- route. Only unverified/out-of-scope wording is intercepted here.
    end

    if R.IsCapabilityMutationQuestion(text) then
        local norm = R.Normalize(text)
        local command = norm:gsub("^is%s+it%s+possible%s+to%s+", "")
            :gsub("^would%s+it%s+be%s+possible%s+to%s+", "")
            :gsub("^could%s+i%s+", "")
        local topic = R.ObviousUnsupportedCapabilityTopic(command)
        local subject = R.CapabilityCommandSubject(command)
        local confirmed, nearest
        if not topic then confirmed, nearest = R.VerifiedCapabilitySettingEntries(subject) end
        if topic or not confirmed then
            return R.UnsupportedCapabilityReply(command, nearest, topic)
        end
        local location = subject ~= "" and A.RouterTryRegistrySettingLocationShortcut
            and A.RouterTryRegistrySettingLocationShortcut("where is " .. subject, Core, confirmed) or nil
        if location then
            location.text = "Yes - MSUF has a matching control. I kept it unchanged because you asked whether it was possible.\n" .. tostring(location.text or "")
            location.status, location.result = "info", "info"
            location.summary = "Answers a setting capability question without changing it."
            return location
        end
        return {
            text = "I found a matching MSUF control, but could not build reliable navigation for it. I kept everything unchanged. Ask me to search for '"
                .. tostring(subject) .. "' or name the exact page you want.",
            status = "info",
            summary = "Answers a verified capability question without applying a change.",
        }
    end

    -- Direct text and cast-bar movement must use the same exact X/Y/Anchor
    -- owners as polite conversational requests. Running this before generic
    -- shortcuts prevents an ordinal or direction word from being mistaken for
    -- an absolute offset and avoids cold construction of broad parser indices.
    do
        local normalized = R.Normalize(text)
        local startsMovement = normalized:match("^move%s+") or normalized:match("^nudge%s+")
            or normalized:match("^shift%s+") or normalized:match("^position%s+")
            or normalized:match("^reposition%s+") or normalized:match("^offset%s+")
            or normalized:match("^raise%s+") or normalized:match("^lower%s+")
        if startsMovement then
            local directTextMovement = R.TryTextMovementConversation(text, Core)
            if directTextMovement then return directTextMovement end
        end
        -- Actionable polite wrappers are stripped inside the cast-bar intents.
        -- Typed icon placement and component X/Y movement resolve first; root
        -- movement remains the fallback, while read-only how/where wording
        -- continues to the richer help routes.
        -- Merely containing "castbar" is not a movement request. "set Boss
        -- Castbar Time Position to LEFT" names an enum control whose VALUE is
        -- LEFT; this block read the direction word and wrote Castbar X to -10 --
        -- a wrong write, not just a miss. A request that names one control
        -- outright belongs to that control.
        if (startsMovement or normalized:find("castbar", 1, true)
            or normalized:find("cast bar", 1, true))
            and not (type(R.RequestNamesOneControl) == "function" and R.RequestNamesOneControl(text))
        then
            local directCastbarIconPosition = R.TryCastbarIconFixedPositionConversation(text)
            if directCastbarIconPosition then return directCastbarIconPosition end
            local directCastbarComponentMovement = R.TryCastbarComponentMovementConversation(text)
            if directCastbarComponentMovement then return directCastbarComponentMovement end
            local directCastbarMovement = R.TryCastbarMovementConversation(text)
            if directCastbarMovement then return directCastbarMovement end
        end
    end

    -- Explicit help wrappers describe an area the player wants to understand;
    -- they are not a value-less mutation. Resolve those scoped requests before
    -- exact registry matching can turn "trying to change target buffs" into an
    -- on/off choice or "help me locate ready checks" into a raw control dump.
    do
        local normalized = R.Normalize(text)
        local scopedHelpWrapper = normalized:match("^help%s+me%s+find%s+")
            or normalized:match("^help%s+me%s+locate%s+")
            or normalized:match("^i%s+am%s+trying%s+")
            or normalized:match("^i'm%s+trying%s+")
            or normalized:match("^im%s+trying%s+")
            or normalized:match("^i%s+need%s+help%s+with%s+")
        if scopedHelpWrapper
            and R.LooksLikeScopedHelpKnowledgeRequest(text)
            and A.Knowledge and type(A.Knowledge.Answer) == "function"
        then
            local subject = normalized:match("^i%s+am%s+trying%s+to%s+change%s+(.+)$")
                or normalized:match("^im%s+trying%s+to%s+change%s+(.+)$")
            if not subject and normalized:find("ready check", 1, true) then
                subject = normalized:match("^help%s+me%s+find%s+(.+)$")
                    or normalized:match("^help%s+me%s+locate%s+(.+)$")
                if subject then
                    subject = subject:gsub("ready checks", "ready check icon")
                    if subject:find("ready check", 1, true) and not subject:find("icon", 1, true) then subject = subject .. " icon" end
                end
            end
            local compactLocation = subject and R.TryCompactExplicitSettingSearch
                and R.TryCompactExplicitSettingSearch("find " .. subject) or nil
            if compactLocation and normalized:find("ready check", 1, true) then
                compactLocation.text = "Group Status & Indicators help\n" .. tostring(compactLocation.text or "")
            elseif compactLocation and normalized:find("target buff", 1, true) then
                compactLocation.text = "Aura Buffs help\n" .. tostring(compactLocation.text or "")
            elseif compactLocation and normalized:find("target debuff", 1, true) then
                compactLocation.text = "Aura Debuffs help\n" .. tostring(compactLocation.text or "")
            end
            if compactLocation then return compactLocation end
            local settingLocation = R.AsksSettingLocation(normalized)
                and R.TryRegistryLocationSpecialistGuidance
                and R.TryRegistryLocationSpecialistGuidance(text, Core) or nil
            if settingLocation then return settingLocation end
            -- Before the encyclopaedia answers: the sentence may describe a
            -- boolean control by result rather than by state ("mark shields
            -- that overflow past full health"). That is an instruction, and
            -- an article about the area is the wrong reply to it.
            if type(A.ExecutePlan) == "function" and type(R.NamedBooleanIntentPlan) == "function" then
                local intentPlan = R.NamedBooleanIntentPlan(text)
                if intentPlan then
                    local okIntent, intentResult = pcall(A.ExecutePlan, intentPlan, { sourceText = text })
                    if okIntent and type(intentResult) == "table"
                        and not A.RouterIsUnknownResult(intentResult)
                    then
                        return intentResult
                    end
                end
            end
            local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
            if answer then return answer end
        end
    end

    local pageOptionLocation = R.TryPageOptionLocationShortcut(text, Core)
    if pageOptionLocation then return pageOptionLocation end

    local broadPageLocationSubject = R.RegistryLocationSubject(text)
    local broadPageLocationLabel = R.PageLocationLabelForText(R.Normalize(text))
    local utilityPageLocation = broadPageLocationLabel and ({
        ["Support Links"] = true,
        ["Changelog"] = true,
        ["Dashboard Scaling"] = true,
        ["Display Recovery"] = true,
        ["Modules"] = true,
    })[broadPageLocationLabel]
    if utilityPageLocation
        or (broadPageLocationSubject ~= "" and R.BROAD_PAGE_LOCATION_SUBJECTS[broadPageLocationSubject])
    then
        local broadPageLocation = R.TryPageLocationShortcut(text, Core)
        if broadPageLocation then return broadPageLocation end
    end

    -- A complete registry label or registered natural alias is more specific
    -- than broad help families such as "name text" or "power text". Resolve
    -- exact location questions first so every registered control remains
    -- directly findable without a question mark or menu-size assumptions.
    local exactLocationNorm = R.Normalize(text)
    local literalExactLocation = exactLocationNorm:match("^where%s+is%s+")
        or exactLocationNorm:match("^where%s+are%s+")
        or exactLocationNorm:match("^wheres%s+")
    local naturalDisplayLocation = exactLocationNorm:match("^show%s+me%s+where%s+")
        or exactLocationNorm:match("^tell%s+me%s+where%s+")
    local prefersSpecialistLocation = R.RegistryLocationPrefersSpecialistGuidance(text)
    local exactLeafLocation = literalExactLocation or R.RegistryLocationNeedsExactLeafPrecedence(text)
    -- Exact entries are consumed only by the exact-leaf and natural-display
    -- branches below. Avoid scanning every registry label for other location
    -- wording that will continue to a reviewed specialist route anyway.
    local exactLocationEntries = (exactLeafLocation or naturalDisplayLocation)
        and not prefersSpecialistLocation and R.ExactRegistryLocationEntries
        and R.ExactRegistryLocationEntries(text) or nil
    local exactRegistryLocation = exactLocationEntries and exactLeafLocation
        and not R.RegistryLocationPrefersSpecialistGuidance(text)
        and R.TryExactRegistrySettingLocation
        and R.TryExactRegistrySettingLocation(text, Core, exactLocationEntries)
    if exactRegistryLocation then return exactRegistryLocation end

    -- Natural display wording is easily mistaken for a generic search. Give
    -- connected feature families their human guide first. If no family owns a
    -- complete exact label, return that exact location instead of fuzzy rows.
    if naturalDisplayLocation or prefersSpecialistLocation then
        local specialistLocation = R.TryRegistryLocationSpecialistGuidance(text, Core)
        if specialistLocation then return specialistLocation end
        if naturalDisplayLocation and exactLocationEntries and R.TryExactRegistrySettingLocation then
            local exactDisplayLocation = R.TryExactRegistrySettingLocation(text, Core, exactLocationEntries)
            if exactDisplayLocation then return exactDisplayLocation end
        end
    end

    -- The beginner phrase is never a setting search. Resolve this exact form
    -- before stale page/results context can feed its ordinary words into fuzzy
    -- matching; result-specific forms such as "explain it simpler" must stay
    -- on their richer pending-result path.
    do
        local normalized = R.Normalize(text)
        if normalized == "explain like im new"
            or normalized == "explain like i'm new"
            or normalized == "explain like i am new"
        then
            local guidance = A.RouterTryDecisionGuidanceShortcut
                and A.RouterTryDecisionGuidanceShortcut(text, Core)
            if guidance then return guidance end
        end
    end

    -- Goal-level comparisons and subjective cleanup requests are planning,
    -- not permission to toggle the first fuzzy registry match. Keep this next
    -- to decision guidance so stale menu context cannot turn "party or raid"
    -- or "hide useless buffs" into an unrelated write.
    do
        local normalized = R.Normalize(text)
        local terms = A.RouterSafePlanningTerms or {}
        local broadImportantAura = normalized == "show important debuffs"
            or normalized == "show important buffs"
        local earlyPlanningIntent = R.ContainsAny(normalized, terms.compare or {})
            or R.ContainsAny(normalized, terms.overload or {})
            or R.ContainsAny(normalized, terms.recommendationFollowup or {})
            or R.ContainsAny(normalized, terms.vagueTarget or {})
            or broadImportantAura
            or (R.ContainsAny(normalized, terms.subjectiveAura or {})
                and R.ContainsAny(normalized, terms.aura or {}))
        if earlyPlanningIntent then
            local earlySafePlanning = A.RouterTrySafePlanningShortcut
                and A.RouterTrySafePlanningShortcut(text, Core)
            if earlySafePlanning then return earlySafePlanning end
        end
    end

    -- Retired Private Aura layout labels still exist in generated read-only
    -- inventory data, but they must never alias ordinary Buff/Debuff lanes.
    -- Resolve this safety boundary before the setting browser or visible-page
    -- context can reinterpret the requested size/anchor/count as a live Aura
    -- mutation. The parser owns the canonical explanation when available;
    -- the local fallback keeps the public route fail-closed during partial
    -- runtime loads as well.
    do
        local normalized = R.Normalize(text)
        if R.ContainsAny(normalized, {
            "private aura", "private auras", "private-aura", "private-auras",
        }) then
            local parsed = type(A.Parse) == "function" and A.Parse(text) or nil
            if type(parsed) == "table" and parsed.kind == "answer"
                and tostring(parsed.status or "info") == "info"
            then
                return {
                    text = parsed.text,
                    status = "info",
                    result = "info",
                    kind = "unsupported",
                    summary = parsed.summary,
                }
            end
            return {
                text = "MSUF has no standalone Private Aura layout control here, so I kept every Buff and Debuff option unchanged. Name a normal Buff or Debuff lane if that is what you want to resize or move.",
                status = "info",
                result = "info",
                kind = "unsupported",
                summary = "Keeps retired private-aura layout wording from changing ordinary Aura lanes.",
            }
        end
    end

    -- Exact page names outrank the all-setting browser. Without this guard,
    -- queries such as "where is Group Status & Indicators" were answered
    -- with an unrelated fuzzy leaf setting even though the destination is a
    -- first-class Menu page. Navigation is ephemeral and never grants write
    -- permission.
    local exactPageNavigation = R.TryBroadPageNavigation and R.TryBroadPageNavigation(text, Core)
    if exactPageNavigation and not A.RouterIsUnknownResult(exactPageNavigation) then
        return R.AsNavigationResult(exactPageNavigation)
    end

    local settingBrowserResult = R.TrySettingBrowserShortcut and R.TrySettingBrowserShortcut(text)
    if settingBrowserResult then return settingBrowserResult end

    -- Complete reviewed semantic commands outrank page-local terse context.
    -- Scope and value are deliberately closed so this cannot broaden writes:
    -- unit Name Anchor owns the reviewed unit text enum, while shared group
    -- Aura Spacing owns the reviewed Buff+Debuff pair as one transaction.
    if hasCore and not A.RouterHasPendingConfirmationOrFlow()
        and R.ReviewedSemanticMutationKind(text)
    then
        local reviewedSemanticMutation = Core(text)
        if reviewedSemanticMutation and not A.RouterIsUnknownResult(reviewedSemanticMutation) then
            return reviewedSemanticMutation
        end
    end

    -- Resolve referential help replies before broad navigation parses
    -- "open that" as a fuzzy setting name. The help context already owns a
    -- concrete first Open action, so following it is both faster and safer.
    local contextualHelpResult = R.TryHelpContextFollowup
        and R.TryHelpContextFollowup(text, coreHandler)
    if contextualHelpResult then return contextualHelpResult end

    -- A fully scoped readability request is a deliberate topic switch. Let it
    -- replace stale non-blocking search/guide state before that state can turn
    -- the request into a broad Aura choice.
    if not A.RouterHasPendingConfirmationOrFlow() then
        -- A named signal problem (for example dispellable debuffs) carries
        -- more information than the generic words "hard to see".
        local signalTopic = R.TrySignalProblemShortcut(text)
        if not signalTopic then
            local readabilityTopic = R.TryReadabilityShortcut(text)
            if readabilityTopic then return readabilityTopic end
        end
    end

    -- Short commands on Group Auras inherit the visible Party/Raid/Mythic
    -- scope. Resolve that O(1) page context before broad Aura aliases can match
    -- a shared control or fan out across every frame.
    if hasCore and not A.RouterHasPendingConfirmationOrFlow()
        and R.ShouldKeepGroupAuraContext(R.Normalize(text))
        and R.CurrentGroupScopePrefix() ~= nil
        and R.StartsWithMutationCommand(text)
        and not R.HasNaturalProblemTerm(R.Normalize(text))
    then
        local groupAuraContextResult = R.TryContext(text, Core)
        if groupAuraContextResult and not A.RouterIsUnknownResult(groupAuraContextResult) then
            return groupAuraContextResult
        end
    end

    local broadPageNavigation = R.TryBroadPageNavigation(text, Core)
    if broadPageNavigation and not A.RouterIsUnknownResult(broadPageNavigation) then return broadPageNavigation end

    -- Native exact aura lists are narrower than lane visibility.  Resolve
    -- their registered action before broad Aura help/visibility shortcuts can
    -- reinterpret a named spell as a request to toggle the whole lane.
    do
        local parser = A.Parser or {}
        local normalized = R.Normalize(text)
        local spellValue = type(parser.AuraBlacklistSpellValue) == "function"
            and parser.AuraBlacklistSpellValue(text) or nil
        local exactAuraListIntent = normalized:find("blacklist", 1, true)
            or normalized:find("whitelist", 1, true)
            or (spellValue and (normalized:find("aura", 1, true)
                or normalized:find("buff", 1, true) or normalized:find("debuff", 1, true)))
        local descriptiveIcon = R.AuraSpecificIconFilterRequest
            and R.AuraSpecificIconFilterRequest(normalized)
        local specificSpell = R.AuraSpecificSpellRequest and R.AuraSpecificSpellRequest(normalized)
        if exactAuraListIntent and not descriptiveIcon and not specificSpell then
            local exactAuraResult = Core(text)
            if exactAuraResult and not A.RouterIsUnknownResult(exactAuraResult) then return exactAuraResult end
        end
    end

    -- A named/icon-described aura is more specific than the surrounding unit
    -- frame. Resolve it before generic "hide <player frame>" shortcuts can
    -- disable the entire frame merely because the sentence ends with that
    -- scope (for example, "hide Power Word: Shield on player frame").
    do
        local normalized = R.Normalize(text)
        if (R.AuraSpecificSpellRequest and R.AuraSpecificSpellRequest(normalized))
            or (R.AuraSpecificIconFilterRequest and R.AuraSpecificIconFilterRequest(normalized))
        then
            local specificAuraResult = A.RouterTryAuraProblemShortcut
                and A.RouterTryAuraProblemShortcut(text, Core)
            if specificAuraResult then return specificAuraResult end
        end
    end

    local hasPendingState = A.RouterHasPendingAssistantState()
    local hasBlockingPendingState = A.RouterHasBlockingPendingAssistantState()
    local hasPendingChoices = A.RouterHasPendingChoices()
    local hasPendingResults = A.RouterHasPendingSearchResults()
    if hasPendingResults and type(A.RouterLooksLikeExplicitSettingRelationshipRequest) == "function"
        and A.RouterLooksLikeExplicitSettingRelationshipRequest(text)
    then
        A.RouterClearPendingResultsForRoute()
        hasPendingState = A.RouterHasPendingAssistantState()
        hasBlockingPendingState = A.RouterHasBlockingPendingAssistantState()
        hasPendingResults = false
    end
    local pendingResultReply = hasPendingResults and R.LooksLikePendingResultReply(text)
    local auraFilterAnswerIntent = A.RouterTryAuraFilterStatusShortcut
        and R.AuraFilterStatusWantsAnswer
        and R.AuraFilterStatusWantsAnswer(text)
    if auraFilterAnswerIntent
        and not R.ContainsAny(text, { "result", "results", "option", "options", "entry", "entries" })
    then
        pendingResultReply = false
    end
    local explicitSearchRequest = A.RouterLooksLikeExplicitSearchRequest(text)
    local parserIntent = A.Parser and type(A.Parser.NonMutatingIntent) == "function"
        and A.Parser.NonMutatingIntent(text) or nil
    if hasPendingChoices
        and not pendingResultReply
        and not A.RouterHasPendingConfirmationOrFlow()
        and ((parserIntent == "problem" and not A.RouterLooksLikePendingChoiceFollowup(text))
            or A.RouterLooksLikePendingChoiceTopicSwitch(text))
    then
        A.RouterClearPendingChoicesForRoute()
        hasPendingState = A.RouterHasPendingAssistantState()
        hasBlockingPendingState = A.RouterHasBlockingPendingAssistantState()
        hasPendingChoices = A.RouterHasPendingChoices()
    end
    if explicitSearchRequest and not hasBlockingPendingState and not pendingResultReply then
        local compactSearch = R.TryCompactExplicitSettingSearch(text)
        if compactSearch then return compactSearch end
    end
    if not hasPendingState and not pendingResultReply then
        local contextlessReference = R.TryContextlessReferenceClarification(text)
        if contextlessReference then return contextlessReference end
    end
    if R.IsExactGenericDiagnosticRequest(text) and not pendingResultReply then
        local diagnosticResult = Core(text)
        if diagnosticResult then return R.AsReadOnlyResult(diagnosticResult) end
    end
    if not hasPendingState and not pendingResultReply and R.IsStandaloneCancelReply(text) then
        return {
            text = "Cancelled. Nothing was waiting for confirmation or a choice.",
            status = "info",
            summary = "Assistant conversation",
        }
    end

    if not hasBlockingPendingState and not pendingResultReply then
        local metaConversation = R.TryEarlyAssistantMetaConversationReply(text)
        if metaConversation then return metaConversation end

        local liveColorExplanation = R.TryLiveUnitColorExplanation(text)
        if liveColorExplanation then return liveColorExplanation end

    end

    if not hasBlockingPendingState and not pendingResultReply then
        -- A request that names one unit's field on a different unit frame must
        -- resolve ownership before the exact-label mutation lane. Otherwise a
        -- complete label inside the sentence can mutate that source control
        -- even though the user explicitly named a different destination.
        -- The text helper deliberately returns nil for the one supported
        -- Target-of-Target inline-name command, allowing it to continue below.
        local exactCrossFrameText = A.RouterTryCrossFrameTextRequestShortcut
            and A.RouterTryCrossFrameTextRequestShortcut(text, Core)
        if exactCrossFrameText then return exactCrossFrameText end
        local exactCrossFrameVisual = A.RouterTryCrossFrameVisualRequestShortcut
            and A.RouterTryCrossFrameVisualRequestShortcut(text, Core)
        if exactCrossFrameVisual then return exactCrossFrameVisual end

        local comparativeSize = R.TryComparativeSizeRelationshipRequest(text)
        if comparativeSize then return comparativeSize end

        -- Bare German "castbar text groesse <n>" still leaves spell text
        -- versus time text unspecified. Keep that request read-only and return
        -- a deterministic setting list instead of depending on fuzzy registry
        -- iteration or silently choosing one text field.
        do
            local normalized = R.Normalize(text)
            local hasCastbar = R.ContainsAny(normalized, { "castbar", "cast bar", "zauberleiste" })
            local hasGermanSize = R.ContainsAny(normalized, { "groesse", "grosse", "text groesse", "text grosse" })
            local hasText = R.ContainsAny(normalized, { "text", "castbar text", "cast bar text" })
            local hasSpecificText = R.ContainsAny(normalized, {
                "spell text", "spell name", "time text", "cast time", "timer",
                "zaubername", "zeit text", "zeittext",
            })
            if normalized:match("%d") and hasCastbar and hasGermanSize and hasText and not hasSpecificText then
                local scope = normalized:match("%f[%a](player)%f[%A]")
                    or normalized:match("%f[%a](target)%f[%A]")
                    or normalized:match("%f[%a](focus)%f[%A]")
                    or normalized:match("%f[%a](boss)%f[%A]")
                local search = R.TryCompactExplicitSettingSearch(
                    "search " .. (scope and (scope .. " ") or "") .. "castbar text"
                )
                if search then return search end
            end
        end

        -- When the whole command (minus verb, determiner and value tail) equals
        -- exactly one indexed control name, the player has named the control --
        -- there is nothing to disambiguate. Several fuzzy lanes below rank
        -- near-misses and answer with a chooser, which is right for a vague
        -- idea and wrong here; "set my Boss Absorb Bar Opacity to 75" was met
        -- with "several MSUF controls fit the setting name". The parser's own
        -- pre-pass already resolves these, so hand the text to the core handler
        -- rather than re-implementing the write. This is deliberately the
        -- strict full-phrase form, not a fuzzy match.
        if hasCore then
            local parser = A.Parser or {}
            if type(parser.ParseRegistryExactAliasShortcut) == "function" then
                local ok, exact = pcall(parser.ParseRegistryExactAliasShortcut,
                    R.Normalize(text), text, { minTokens = 3, fullPhrase = true })
                if ok and type(exact) == "table" and exact.kind == "changes"
                    and type(exact.changes) == "table" and #exact.changes == 1
                then
                    local exactResult = Core(text)
                    if exactResult and not A.RouterIsUnknownResult(exactResult) then
                        return exactResult
                    end
                end
            end
        end

        local exactSettingMutation = R.TryExactRegistrySettingMutation(text)
        if exactSettingMutation then return exactSettingMutation end

        -- A value-less "move <component>" is a request for position choices,
        -- never permission to enable/disable the component. Resolve this
        -- before Aura filtering/growth and visibility parsers can reinterpret
        -- "move player buffs" as "show player buffs".
        local incompleteMovement = not R.TextMovementIntent(text)
            and R.TryIncompleteMovementConversation(text) or nil
        if incompleteMovement then return incompleteMovement end

        -- Filtering language owns several similarly named Aura controls. Run
        -- its bounded semantic parser before growth, open-ended help, page
        -- context, and fuzzy aliases can reinterpret the request.
        local auraParser = A.Parser or {}
        local auraContext = type(A.GetContext) == "function" and A.GetContext() or {}
        if type(auraParser.LooksLikeAuraFilteringConversation) == "function"
            and auraParser.LooksLikeAuraFilteringConversation(text, auraContext)
        then
            local auraFilteringResult = Core(text)
            if auraFilteringResult and not A.RouterIsUnknownResult(auraFilteringResult) then
                return auraFilteringResult
            end
        end

        local auraGrowthChoice = R.TryScopedAuraGrowthChoice(text, Core)
        if auraGrowthChoice then return auraGrowthChoice end

        -- Give the parser's visual-semantic owner first refusal before broad
        -- setting search or open-ended matching. Mixed-case DoT wording is
        -- intentionally included so it can return Aura-vs-name-dot choices
        -- instead of disabling/moving the surrounding frame.
        local rawDots = tostring(text or "")
        local semanticNameDots = R.LooksLikeNameShorteningDotsRequest(text)
        local auraDoTs = R.HasRawAuraDoT(rawDots)
        if (semanticNameDots or auraDoTs) and not R.LooksLikeRegistrySettingLocationQuestion(text) then
            local dotResult = Core(text)
            if dotResult and not A.RouterIsUnknownResult(dotResult) then return dotResult end
        end

        -- Edit Mode status and troubleshooting language owns the complete
        -- phrase. Resolve it before broad setting search can split "edit mode
        -- status" into unrelated per-frame Status Icon controls.
        local earlyEditModeProblem = A.RouterTryEditModeProblemShortcut
            and A.RouterTryEditModeProblemShortcut(text, Core)
        if earlyEditModeProblem then return earlyEditModeProblem end

        local openEndedSetting = R.TryOpenEndedSettingIdea(text, Core)
        if openEndedSetting then return openEndedSetting end

        local earlyPageHelpResult = not explicitSearchRequest and not R.LooksLikeRegistrySettingLocationQuestion(text)
            and R.TryPageHelpShortcut(text, Core) or nil
        if earlyPageHelpResult then return earlyPageHelpResult end

        local normForGermanLocation = R.Normalize(text)
        local germanLocation = normForGermanLocation:match("^wo%s+")
            or normForGermanLocation:match("^wie%s+kann%s+ich%s+")
            or normForGermanLocation:match("^welche%s+einstellung%s+")
            or normForGermanLocation:match("^welche%s+option%s+")
        if germanLocation and R.LooksLikeRegistrySettingLocationQuestion(text) then
            local subject = R.RegistryLocationSubject(text)
            local entries = subject ~= "" and R.CompactRegistrySettingSearchEntries(subject, 3) or nil
            if entries then
                local location = A.RouterTryRegistrySettingLocationShortcut and A.RouterTryRegistrySettingLocationShortcut(text, Core, entries)
                if location then return location end
            end
        end

        -- Inline Target-of-Target name location requests are narrower than
        -- general dependent-frame troubleshooting.
        local earlyTargetTargetInlineName = A.RouterTryTargetTargetInlineNameShortcut
            and A.RouterTryTargetTargetInlineNameShortcut(text, Core)
        if earlyTargetTargetInlineName then return earlyTargetTargetInlineName end

        -- "Focus target" and "target of target" are compound frame names.
        -- Resolve their missing-frame questions before fuzzy registry matching
        -- can split the phrase and explain an unrelated Focus/Target setting.
        local earlyDependentTargetTroubleshooting = A.RouterTryDependentTargetTroubleshootingShortcut
            and A.RouterTryDependentTargetTroubleshootingShortcut(text, Core)
        if earlyDependentTargetTroubleshooting then return earlyDependentTargetTroubleshooting end

        -- A full registered setting name is more specific than a broad signal
        -- family such as dispel, cast bar, or aura. Resolve it first so
        -- "Boss Debuff Dispellable Filter missing" does not collapse into
        -- generic dispel help.
        local earlyRegistryTroubleshooting = A.RouterTryRegistrySettingTroubleshootingShortcut
            and A.RouterTryRegistrySettingTroubleshootingShortcut(text, Core)
        if earlyRegistryTroubleshooting then return earlyRegistryTroubleshooting end

        -- A named tracker is more specific than its surrounding cast bar. This
        -- explanatory route must win before broad cast-bar troubleshooting.
        local earlySignalProblemResult = R.TrySignalProblemShortcut(text)
        if earlySignalProblemResult then return earlySignalProblemResult end

        local earlyLastChangeSettingFollowupResult = R.TryLastChangeSettingFollowup and R.TryLastChangeSettingFollowup(text)
        if earlyLastChangeSettingFollowupResult then return earlyLastChangeSettingFollowupResult end

        local earlyAuraFilterStatusResult = A.RouterTryAuraFilterStatusShortcut and A.RouterTryAuraFilterStatusShortcut(text)
        if earlyAuraFilterStatusResult then return earlyAuraFilterStatusResult end

        local earlyRegistrySettingCurrentValueResult = A.RouterTryRegistrySettingCurrentValueShortcut and A.RouterTryRegistrySettingCurrentValueShortcut(text, Core)
        if earlyRegistrySettingCurrentValueResult then return earlyRegistrySettingCurrentValueResult end

        local earlySettingGraphResult = A.RouterTrySettingGraphShortcut and A.RouterTrySettingGraphShortcut(text)
        if earlySettingGraphResult then return earlySettingGraphResult end

        local compactExplainSubject = R.LooksLikeRegistrySettingExplainQuestion(text) and R.RegistryExplainSubject(text) or ""
        local compactExplainEntries = compactExplainSubject ~= "" and R.CompactRegistrySettingSearchEntries(compactExplainSubject, 3) or nil
        if compactExplainEntries then
            local compactExplainResult = A.RouterTryRegistrySettingExplainShortcut and A.RouterTryRegistrySettingExplainShortcut(text, Core, compactExplainEntries)
            if compactExplainResult then return compactExplainResult end
        end

    end

    if not hasBlockingPendingState and not pendingResultReply
        and R.LooksLikeDirectDefinitionQuestion(text)
        -- "What is <exact control name>" is a definition question about that
        -- control. Knowledge answers the topic its words belong to, which sent
        -- "what is Castbar Texture" to general cast-bar guidance instead of the
        -- texture control the player named. Everything that is not an exact
        -- label still goes to Knowledge.
        and not (type(A.RouterNamedSettingLabel) == "function" and A.RouterNamedSettingLabel(text))
        and A.Knowledge and type(A.Knowledge.Answer) == "function"
    then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
        if answer then return answer end
        local noMatch = R.KnowledgeNoMatch(text)
        if noMatch then return noMatch end
    end

    local safePlanningOverride = A.RouterTrySafePlanningShortcut and A.RouterTrySafePlanningShortcut(text, Core)
    if safePlanningOverride and (pendingResultReply or hasPendingState or not hasBlockingPendingState) then
        return safePlanningOverride
    end

    local safePlanningFollowupOverride = (not hasPendingState) and (not pendingResultReply) and A.RouterTrySafePlanningFollowup and A.RouterTrySafePlanningFollowup(text, Core)
    if safePlanningFollowupOverride then return safePlanningFollowupOverride end

    if not hasBlockingPendingState and not pendingResultReply then
        local crossFrameTextResult = A.RouterTryCrossFrameTextRequestShortcut and A.RouterTryCrossFrameTextRequestShortcut(text, Core)
        if crossFrameTextResult then return crossFrameTextResult end

        local targetTargetInlineNameResult = A.RouterTryTargetTargetInlineNameShortcut and A.RouterTryTargetTargetInlineNameShortcut(text, Core)
        if targetTargetInlineNameResult then return targetTargetInlineNameResult end

        local dependentTargetTroubleshootingResult = A.RouterTryDependentTargetTroubleshootingShortcut and A.RouterTryDependentTargetTroubleshootingShortcut(text, Core)
        if dependentTargetTroubleshootingResult then return dependentTargetTroubleshootingResult end

        local crossFrameVisualResult = A.RouterTryCrossFrameVisualRequestShortcut and A.RouterTryCrossFrameVisualRequestShortcut(text, Core)
        if crossFrameVisualResult then return crossFrameVisualResult end

        local assistantUsabilityResult = A.RouterTryAssistantUsabilityProblemShortcut and A.RouterTryAssistantUsabilityProblemShortcut(text, Core)
        if assistantUsabilityResult then return assistantUsabilityResult end

        local decisionGuidanceResult = A.RouterTryDecisionGuidanceShortcut and A.RouterTryDecisionGuidanceShortcut(text, Core)
        if decisionGuidanceResult then return decisionGuidanceResult end

        local safePlanningResult = A.RouterTrySafePlanningShortcut and A.RouterTrySafePlanningShortcut(text, Core)
        if safePlanningResult then return safePlanningResult end

        local lastChangeSettingFollowupResult = R.TryLastChangeSettingFollowup and R.TryLastChangeSettingFollowup(text)
        if lastChangeSettingFollowupResult then return lastChangeSettingFollowupResult end

        local auraFilterStatusResult = A.RouterTryAuraFilterStatusShortcut and A.RouterTryAuraFilterStatusShortcut(text)
        if auraFilterStatusResult then return auraFilterStatusResult end

        local registrySettingCurrentValueResult = A.RouterTryRegistrySettingCurrentValueShortcut and A.RouterTryRegistrySettingCurrentValueShortcut(text, Core)
        if registrySettingCurrentValueResult then return registrySettingCurrentValueResult end

        local registrySettingDecisionResult = A.RouterTryRegistrySettingDecisionShortcut and A.RouterTryRegistrySettingDecisionShortcut(text, Core)
        if registrySettingDecisionResult then return registrySettingDecisionResult end

        -- The decision shortcut only answers when one control resolves
        -- confidently. Everything below this point can write, so an advice
        -- question that got this far has to be answered read-only rather than
        -- being executed as if it were an instruction.
        local amountlessComparative = R.IsAmountlessComparativeRequest(text)
        if not R.LooksLikeScopedHelpKnowledgeRequest(text)
            and (amountlessComparative or R.IsAdviceQuestion(text))
        then
            return R.AdvisoryNoMutationReply(text, amountlessComparative)
        end

        local stylingReply = R.TryStylingQualifierGuidance(text)
        if stylingReply then return stylingReply end

        local registrySettingExplainResult = A.RouterTryRegistrySettingExplainShortcut and A.RouterTryRegistrySettingExplainShortcut(text, Core)
        if registrySettingExplainResult then return registrySettingExplainResult end

        local registrySettingTroubleshootingResult = A.RouterTryRegistrySettingTroubleshootingShortcut and A.RouterTryRegistrySettingTroubleshootingShortcut(text, Core)
        if registrySettingTroubleshootingResult then return registrySettingTroubleshootingResult end

        -- Everything from here down can write. The read-only specialists above
        -- have already had their chance, so an input the parser classified as a
        -- question/lookup must not fall into a mutation lane now: "help with
        -- Boss Buff Duration Bar Display" was reaching one and answering "I
        -- changed Boss Buffs from disabled to enabled". The immediate fast path
        -- already honours this classification; this is the same rule for the
        -- full pipeline, in one place rather than per lane.
        -- Only the intents that are genuinely "tell me about this". A problem
        -- report also classifies as non-mutating, but its visibility
        -- diagnostics live further down and answer it far better than a generic
        -- control list would, so those must pass through untouched.
        do
            local parser = A.Parser or {}
            local intent = type(parser.NonMutatingIntent) == "function"
                and parser.NonMutatingIntent(R.Normalize(text)) or nil
            if intent == "lookup" or intent == "capability" then
                -- The knowledge lane normally answers these, but it sits below
                -- the mutation lanes, so consult it here rather than replacing
                -- a real answer ("why would I use a focus frame") with a
                -- generic control list. Failing closed is the fallback, not the
                -- first move.
                -- A lookup that names one exact control is about that control.
                -- Knowledge answers the *topic* a phrase belongs to, which is
                -- the wrong answer here: "what is Castbar Texture" came back
                -- with general cast-bar guidance, and "what is UnitFrame
                -- Dispel Overlay" with scaling-readability help. Knowledge
                -- still owns every lookup that does not name a control, and it
                -- has no article for most of the 6000+ leaf settings anyway.
                local namedLookup = type(A.RouterNamedSettingLabel) == "function"
                    and A.RouterNamedSettingLabel(text) or nil
                if namedLookup and namedLookup ~= "" then
                    local explained = A.RouterTryRegistrySettingExplainShortcut
                        and A.RouterTryRegistrySettingExplainShortcut("explain " .. namedLookup, Core)
                    if explained then return explained end
                    local located = A.RouterTryRegistrySettingLocationShortcut
                        and A.RouterTryRegistrySettingLocationShortcut("where is " .. namedLookup, Core)
                    if located then return located end
                    local direct = R.NamedSettingDirectAnswer and R.NamedSettingDirectAnswer(namedLookup)
                    if direct then return direct end
                end
                if A.Knowledge and type(A.Knowledge.Answer) == "function" then
                    local knowledgeAnswer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
                    if knowledgeAnswer then return knowledgeAnswer end
                end
                return R.AdvisoryNoMutationReply(text, "lookup")
            end
        end

        -- Human wrappers such as "can you help me to" must not turn a valid
        -- setting command into a generic help article. Keep the narrower Aura,
        -- cross-frame, dependent-frame, and registry specialists ahead of it;
        -- then preserve how/where questions and guide incomplete text movement.
        local conversationalMutation = R.TryConversationalMutation(text, Core)
        if conversationalMutation then return conversationalMutation end

        local directSettingNavigationResult = R.TryDirectSettingNavigation and R.TryDirectSettingNavigation(text, Core)
        if directSettingNavigationResult then return directSettingNavigationResult end

        local visualSettingResult = A.RouterTryVisualSettingShortcut and A.RouterTryVisualSettingShortcut(text, Core)
        if visualSettingResult then return visualSettingResult end

        local movementSettingResult = A.RouterTryMovementSettingShortcut and A.RouterTryMovementSettingShortcut(text, Core)
        if movementSettingResult then return movementSettingResult end

        local unitFrameSettingResult = A.RouterTryUnitFrameSettingShortcut and A.RouterTryUnitFrameSettingShortcut(text, Core)
        if unitFrameSettingResult then return unitFrameSettingResult end

        local correctionResult = R.TryCorrectionShortcut(text, Core)
        if correctionResult then return correctionResult end
    end

    if hasBlockingPendingState and not pendingResultReply then
        local blockingProfileHelpResult = A.RouterTryProfileProblemShortcut and A.RouterTryProfileProblemShortcut(text, nil)
        if blockingProfileHelpResult then return blockingProfileHelpResult end
    end

    if hasPendingState and not hasBlockingPendingState and not pendingResultReply then
        local pendingHelpContextResult = R.TryHelpContextFollowup(text, Core)
        if pendingHelpContextResult then return pendingHelpContextResult end

        if R.LooksLikeBugReportRequest(text) then return R.BugReportReply(text) end

        local pendingCrossFrameTextResult = A.RouterTryCrossFrameTextRequestShortcut and A.RouterTryCrossFrameTextRequestShortcut(text, Core)
        if pendingCrossFrameTextResult then return pendingCrossFrameTextResult end

        local pendingTargetTargetInlineNameResult = A.RouterTryTargetTargetInlineNameShortcut and A.RouterTryTargetTargetInlineNameShortcut(text, Core)
        if pendingTargetTargetInlineNameResult then return pendingTargetTargetInlineNameResult end

        local pendingDependentTargetTroubleshootingResult = A.RouterTryDependentTargetTroubleshootingShortcut and A.RouterTryDependentTargetTroubleshootingShortcut(text, Core)
        if pendingDependentTargetTroubleshootingResult then return pendingDependentTargetTroubleshootingResult end

        local pendingCrossFrameVisualResult = A.RouterTryCrossFrameVisualRequestShortcut and A.RouterTryCrossFrameVisualRequestShortcut(text, Core)
        if pendingCrossFrameVisualResult then return pendingCrossFrameVisualResult end

        local pendingAssistantUsabilityResult = A.RouterTryAssistantUsabilityProblemShortcut and A.RouterTryAssistantUsabilityProblemShortcut(text, Core)
        if pendingAssistantUsabilityResult then return pendingAssistantUsabilityResult end

        local pendingDecisionGuidanceResult = A.RouterTryDecisionGuidanceShortcut and A.RouterTryDecisionGuidanceShortcut(text, Core)
        if pendingDecisionGuidanceResult then return pendingDecisionGuidanceResult end

        local pendingSafePlanningResult = A.RouterTrySafePlanningShortcut and A.RouterTrySafePlanningShortcut(text, Core)
        if pendingSafePlanningResult then return pendingSafePlanningResult end

        local pendingLastChangeSettingFollowupResult = R.TryLastChangeSettingFollowup and R.TryLastChangeSettingFollowup(text)
        if pendingLastChangeSettingFollowupResult then return pendingLastChangeSettingFollowupResult end

        local pendingAuraFilterStatusResult = A.RouterTryAuraFilterStatusShortcut and A.RouterTryAuraFilterStatusShortcut(text)
        if pendingAuraFilterStatusResult then return pendingAuraFilterStatusResult end

        local pendingRegistrySettingCurrentValueResult = A.RouterTryRegistrySettingCurrentValueShortcut and A.RouterTryRegistrySettingCurrentValueShortcut(text, Core)
        if pendingRegistrySettingCurrentValueResult then return pendingRegistrySettingCurrentValueResult end

        local pendingRegistrySettingDecisionResult = A.RouterTryRegistrySettingDecisionShortcut and A.RouterTryRegistrySettingDecisionShortcut(text, Core)
        if pendingRegistrySettingDecisionResult then return pendingRegistrySettingDecisionResult end

        local pendingRegistrySettingExplainResult = A.RouterTryRegistrySettingExplainShortcut and A.RouterTryRegistrySettingExplainShortcut(text, Core)
        if pendingRegistrySettingExplainResult then return pendingRegistrySettingExplainResult end

        local pendingRegistrySettingTroubleshootingResult = A.RouterTryRegistrySettingTroubleshootingShortcut and A.RouterTryRegistrySettingTroubleshootingShortcut(text, Core)
        if pendingRegistrySettingTroubleshootingResult then return pendingRegistrySettingTroubleshootingResult end

        local pendingVisualSettingResult = A.RouterTryVisualSettingShortcut and A.RouterTryVisualSettingShortcut(text, Core)
        if pendingVisualSettingResult then return pendingVisualSettingResult end

        local pendingMovementSettingResult = A.RouterTryMovementSettingShortcut and A.RouterTryMovementSettingShortcut(text, Core)
        if pendingMovementSettingResult then return pendingMovementSettingResult end

        local pendingUnitFrameSettingResult = A.RouterTryUnitFrameSettingShortcut and A.RouterTryUnitFrameSettingShortcut(text, Core)
        if pendingUnitFrameSettingResult then return pendingUnitFrameSettingResult end

        local pendingEditModeProblemResult = A.RouterTryEditModeProblemShortcut and A.RouterTryEditModeProblemShortcut(text, Core)
        if pendingEditModeProblemResult then return pendingEditModeProblemResult end

        local pendingProfileProblemResult = A.RouterTryProfileProblemShortcut and A.RouterTryProfileProblemShortcut(text, Core)
        if pendingProfileProblemResult then return pendingProfileProblemResult end

        local pendingGroupLayoutProblemResult = A.RouterTryGroupLayoutProblemShortcut and A.RouterTryGroupLayoutProblemShortcut(text, Core)
        if pendingGroupLayoutProblemResult then return pendingGroupLayoutProblemResult end

        local pendingAuraProblemResult = A.RouterTryAuraProblemShortcut and A.RouterTryAuraProblemShortcut(text, Core)
        if pendingAuraProblemResult then return pendingAuraProblemResult end

        local pendingCastbarProblemResult = A.RouterTryCastbarProblemShortcut and A.RouterTryCastbarProblemShortcut(text, Core)
        if pendingCastbarProblemResult then return pendingCastbarProblemResult end

        local pendingTextPowerProblemResult = A.RouterTryTextPowerProblemShortcut and A.RouterTryTextPowerProblemShortcut(text, Core)
        if pendingTextPowerProblemResult then return pendingTextPowerProblemResult end

        local pendingUnitFrameProblemResult = A.RouterTryUnitFrameProblemShortcut and A.RouterTryUnitFrameProblemShortcut(text, Core)
        if pendingUnitFrameProblemResult then return pendingUnitFrameProblemResult end

        local pendingIndicatorProblemResult = A.RouterTryIndicatorProblemShortcut and A.RouterTryIndicatorProblemShortcut(text, Core)
        if pendingIndicatorProblemResult then return pendingIndicatorProblemResult end

        local pendingClassResourceProblemResult = A.RouterTryClassResourceProblemShortcut and A.RouterTryClassResourceProblemShortcut(text, Core)
        if pendingClassResourceProblemResult then return pendingClassResourceProblemResult end

        local pendingGameplayProblemResult = A.RouterTryGameplayProblemShortcut and A.RouterTryGameplayProblemShortcut(text, Core)
        if pendingGameplayProblemResult then return pendingGameplayProblemResult end

        local pendingRegistrySettingLocationResult = A.RouterTryRegistrySettingLocationShortcut and A.RouterTryRegistrySettingLocationShortcut(text, Core)
        if pendingRegistrySettingLocationResult then return pendingRegistrySettingLocationResult end

        local pendingNaturalProblemResult = R.TryNaturalProblemShortcut(text, Core)
        if pendingNaturalProblemResult then return pendingNaturalProblemResult end

        local pendingMiscProblemResult = A.RouterTryMiscProblemShortcut and A.RouterTryMiscProblemShortcut(text, Core)
        if pendingMiscProblemResult then return pendingMiscProblemResult end

        local pendingSignalProblemResult = R.TrySignalProblemShortcut(text)
        if pendingSignalProblemResult then return pendingSignalProblemResult end

        local pendingVisibilityResult = R.TryVisibilityDiagnosticShortcut(text, Core)
        if pendingVisibilityResult then return pendingVisibilityResult end

        local pendingColorContrastResult = R.TryColorContrastShortcut(text)
        if pendingColorContrastResult then return pendingColorContrastResult end

        local pendingReadabilityResult = R.TryReadabilityShortcut(text)
        if pendingReadabilityResult then return pendingReadabilityResult end
    end

    -- Pending confirmations/choices/flows must always win. Guided setup is lighter:
    -- it can answer short follow-ups, but unknown core replies should fall through.
    if hasCore and (
        pendingResultReply
        or (hasPendingState and not (not hasBlockingPendingState and explicitSearchRequest))
        or (R.IsStandaloneFlowReply(text) and not R.LooksLikeKnowledgeQuestionPrefix(text))
    ) then
        local pendingResult = Core(text)
        if pendingResult and (not A.RouterIsUnknownResult(pendingResult) or hasBlockingPendingState) then return pendingResult end
    end

    local earlyHelpContextResult = R.TryHelpContextFollowup(text, Core)
    if earlyHelpContextResult then return earlyHelpContextResult end

    if R.LooksLikeBugReportRequest(text) then return R.BugReportReply(text) end

    local crossFrameTextProblemResult = A.RouterTryCrossFrameTextRequestShortcut and A.RouterTryCrossFrameTextRequestShortcut(text, Core)
    if crossFrameTextProblemResult then return crossFrameTextProblemResult end

    local targetTargetInlineNameProblemResult = A.RouterTryTargetTargetInlineNameShortcut and A.RouterTryTargetTargetInlineNameShortcut(text, Core)
    if targetTargetInlineNameProblemResult then return targetTargetInlineNameProblemResult end

    local dependentTargetTroubleshootingResult = A.RouterTryDependentTargetTroubleshootingShortcut and A.RouterTryDependentTargetTroubleshootingShortcut(text, Core)
    if dependentTargetTroubleshootingResult then return dependentTargetTroubleshootingResult end

    local crossFrameVisualProblemResult = A.RouterTryCrossFrameVisualRequestShortcut and A.RouterTryCrossFrameVisualRequestShortcut(text, Core)
    if crossFrameVisualProblemResult then return crossFrameVisualProblemResult end

    local assistantUsabilityProblemResult = A.RouterTryAssistantUsabilityProblemShortcut and A.RouterTryAssistantUsabilityProblemShortcut(text, Core)
    if assistantUsabilityProblemResult then return assistantUsabilityProblemResult end

    local decisionGuidanceProblemResult = A.RouterTryDecisionGuidanceShortcut and A.RouterTryDecisionGuidanceShortcut(text, Core)
    if decisionGuidanceProblemResult then return decisionGuidanceProblemResult end

    local safePlanningProblemResult = A.RouterTrySafePlanningShortcut and A.RouterTrySafePlanningShortcut(text, Core)
    if safePlanningProblemResult then return safePlanningProblemResult end

    local lastChangeSettingFollowupProblemResult = R.TryLastChangeSettingFollowup and R.TryLastChangeSettingFollowup(text)
    if lastChangeSettingFollowupProblemResult then return lastChangeSettingFollowupProblemResult end

    local auraFilterStatusProblemResult = A.RouterTryAuraFilterStatusShortcut and A.RouterTryAuraFilterStatusShortcut(text)
    if auraFilterStatusProblemResult then return auraFilterStatusProblemResult end

    local registrySettingCurrentValueProblemResult = A.RouterTryRegistrySettingCurrentValueShortcut and A.RouterTryRegistrySettingCurrentValueShortcut(text, Core)
    if registrySettingCurrentValueProblemResult then return registrySettingCurrentValueProblemResult end

    local registrySettingDecisionProblemResult = A.RouterTryRegistrySettingDecisionShortcut and A.RouterTryRegistrySettingDecisionShortcut(text, Core)
    if registrySettingDecisionProblemResult then return registrySettingDecisionProblemResult end

    local registrySettingExplainProblemResult = A.RouterTryRegistrySettingExplainShortcut and A.RouterTryRegistrySettingExplainShortcut(text, Core)
    if registrySettingExplainProblemResult then return registrySettingExplainProblemResult end

    local registrySettingTroubleshootingProblemResult = A.RouterTryRegistrySettingTroubleshootingShortcut and A.RouterTryRegistrySettingTroubleshootingShortcut(text, Core)
    if registrySettingTroubleshootingProblemResult then return registrySettingTroubleshootingProblemResult end

    local visualSettingProblemResult = A.RouterTryVisualSettingShortcut and A.RouterTryVisualSettingShortcut(text, Core)
    if visualSettingProblemResult then return visualSettingProblemResult end

    local movementSettingProblemResult = A.RouterTryMovementSettingShortcut and A.RouterTryMovementSettingShortcut(text, Core)
    if movementSettingProblemResult then return movementSettingProblemResult end

    local unitFrameSettingProblemResult = A.RouterTryUnitFrameSettingShortcut and A.RouterTryUnitFrameSettingShortcut(text, Core)
    if unitFrameSettingProblemResult then return unitFrameSettingProblemResult end

    local editModeProblemResult = A.RouterTryEditModeProblemShortcut and A.RouterTryEditModeProblemShortcut(text, Core)
    if editModeProblemResult then return editModeProblemResult end

    local profileProblemResult = A.RouterTryProfileProblemShortcut and A.RouterTryProfileProblemShortcut(text, Core)
    if profileProblemResult then return profileProblemResult end

    local groupLayoutProblemResult = A.RouterTryGroupLayoutProblemShortcut and A.RouterTryGroupLayoutProblemShortcut(text, Core)
    if groupLayoutProblemResult then return groupLayoutProblemResult end

    local auraProblemResult = A.RouterTryAuraProblemShortcut and A.RouterTryAuraProblemShortcut(text, Core)
    if auraProblemResult then return auraProblemResult end

    local castbarProblemResult = A.RouterTryCastbarProblemShortcut and A.RouterTryCastbarProblemShortcut(text, Core)
    if castbarProblemResult then return castbarProblemResult end

    local textPowerProblemResult = A.RouterTryTextPowerProblemShortcut and A.RouterTryTextPowerProblemShortcut(text, Core)
    if textPowerProblemResult then return textPowerProblemResult end

    local unitFrameProblemResult = A.RouterTryUnitFrameProblemShortcut and A.RouterTryUnitFrameProblemShortcut(text, Core)
    if unitFrameProblemResult then return unitFrameProblemResult end

    local indicatorProblemResult = A.RouterTryIndicatorProblemShortcut and A.RouterTryIndicatorProblemShortcut(text, Core)
    if indicatorProblemResult then return indicatorProblemResult end

    local classResourceProblemResult = A.RouterTryClassResourceProblemShortcut and A.RouterTryClassResourceProblemShortcut(text, Core)
    if classResourceProblemResult then return classResourceProblemResult end

    local gameplayProblemResult = A.RouterTryGameplayProblemShortcut and A.RouterTryGameplayProblemShortcut(text, Core)
    if gameplayProblemResult then return gameplayProblemResult end

    local registrySettingLocationProblemResult = A.RouterTryRegistrySettingLocationShortcut and A.RouterTryRegistrySettingLocationShortcut(text, Core)
    if registrySettingLocationProblemResult then return registrySettingLocationProblemResult end

    local naturalProblemResult = R.TryNaturalProblemShortcut(text, Core)
    if naturalProblemResult then return naturalProblemResult end

    local miscProblemResult = A.RouterTryMiscProblemShortcut and A.RouterTryMiscProblemShortcut(text, Core)
    if miscProblemResult then return miscProblemResult end

    local signalProblemResult = R.TrySignalProblemShortcut(text)
    if signalProblemResult then return signalProblemResult end

    local visibilityResult = R.TryVisibilityDiagnosticShortcut(text, Core)
    if visibilityResult then return visibilityResult end

    -- Each of these answers with a topic article. They stay first for genuine
    -- "how do I make this readable" questions, but must not swallow a request
    -- that already names one control.
    local colorContrastResult = R.TopicAnswerSurvivesExactControl(R.TryColorContrastShortcut(text), text)
    if colorContrastResult then return colorContrastResult end

    local readabilityResult = R.TopicAnswerSurvivesExactControl(R.TryReadabilityShortcut(text), text)
    if readabilityResult then return readabilityResult end

    local pageHelpResult = not explicitSearchRequest and not R.LooksLikeRegistrySettingLocationQuestion(text)
        and R.TryPageHelpShortcut(text, Core) or nil
    pageHelpResult = R.TopicAnswerSurvivesExactControl(pageHelpResult, text)
    if pageHelpResult then return pageHelpResult end

    local pageLocationResult = R.TryPageLocationShortcut(text, Core)
    if pageLocationResult then return pageLocationResult end

    local registrySettingLocationResult = A.RouterTryRegistrySettingLocationShortcut and A.RouterTryRegistrySettingLocationShortcut(text, Core)
    if registrySettingLocationResult then return registrySettingLocationResult end

    local lateRegistrySettingExplainResult = A.RouterTryRegistrySettingExplainShortcut and A.RouterTryRegistrySettingExplainShortcut(text, Core)
    if lateRegistrySettingExplainResult then return lateRegistrySettingExplainResult end

    if R.LooksLikeScopedHelpKnowledgeRequest(text) and A.Knowledge and type(A.Knowledge.Answer) == "function" then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
        if answer then return answer end
        local noMatch = R.KnowledgeNoMatch(text)
        if noMatch then return noMatch end
    end

    local helpContextResult = R.TryHelpContextFollowup(text, Core)
    if helpContextResult then return helpContextResult end

    local generalGuidanceResult = R.TryGeneralGuidanceShortcut(text, Core)
    if generalGuidanceResult then return generalGuidanceResult end

    if not hasBlockingPendingState and not pendingResultReply and explicitSearchRequest
        and A.Knowledge and type(A.Knowledge.Answer) == "function" then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey, forceSearch = true })
        if answer then return answer end
        local noMatch = R.KnowledgeNoMatch(text)
        if noMatch then return noMatch end
    end

    if not hasBlockingPendingState and not pendingResultReply
        and not R.LooksLikeAssistantIdentityQuestion(text)
        and R.LooksLikeLocalWowUiKnowledgeRequest(text)
        and A.Knowledge and type(A.Knowledge.Answer) == "function" then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
        if answer then return answer end
        local noMatch = R.KnowledgeNoMatch(text)
        if noMatch then return noMatch end
    end

    if not hasBlockingPendingState and not pendingResultReply and hasCore and A.RouterLooksLikeExactActionPhrase(text) then
        local actionPhraseResult = Core(text)
        if actionPhraseResult and not A.RouterIsUnknownResult(actionPhraseResult) then return actionPhraseResult end
    end

    local humanResult = R.HumanConversationReply(text)
    if humanResult then return humanResult end

    if hasCore and R.LooksLikeExactAssistantKey(text) and (R.LooksLikeMutation(text) or R.StartsWithMutationCommand(text)) then
        local exactKeyResult = Core(text)
        if exactKeyResult and not A.RouterIsUnknownResult(exactKeyResult) then return exactKeyResult end
    end

    if not R.LooksLikeKnowledgeQuestionPrefix(text) then
        local parser = A.Parser or {}
        local broadAnchor = parser.ParseBroadHumanAnchorTargetAnswer and parser.ParseBroadHumanAnchorTargetAnswer(R.Normalize(text), text)
        if broadAnchor then return broadAnchor end
    end

    if hasCore and not R.LooksLikeKnowledgeQuestionPrefix(text)
        and not (R.Normalize(text):find("%d+%.%d+") or R.ContainsAny(text, {
            "release", "version", "preview", "alpha", "beta", "patch", "build", "changelog", "change log",
        }))
        and R.ContainsAny(text, {
        "what did you change", "what changed", "what was changed", "what did you do",
        "what did you just change", "what exactly did you change", "what did you set",
        "last change", "last assistant change", "previous change", "what is it now",
        "what is it set to", "current value", "value now", "show last change",
        "show me last change", "show me the last change",
    }) then
        local followupResult = Core(text)
        if followupResult and not A.RouterIsUnknownResult(followupResult) then return followupResult end
    end

    if R.LooksLikeKnowledgeFirstRequest(text) and A.Knowledge and type(A.Knowledge.Answer) == "function" then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
        if answer then return answer end
        local noMatch = R.KnowledgeNoMatch(text)
        if noMatch then return noMatch end
    end

    local parser = A.Parser or {}
    local normForScope = R.Normalize(text)
    local hasClassPowerScope = (type(parser.CLASS_POWER_TERMS) == "table" and R.ContainsAny(normForScope, parser.CLASS_POWER_TERMS))
        or R.ContainsAny(normForScope, { "resource numbers", "resource number", "resource text", "resource texts" })
    local hasExplicitScope = R.ContainsAny(normForScope, {
        "unitframe", "unitframes", "unit frame", "unit frames",
        "target of target", "focus target", "mythic raid", "player", "target", "focus", "pet", "boss",
        "party", "raid", "party frames", "raid frames", "group frames",
    })
        or hasClassPowerScope
        or (type(parser.DetectUnits) == "function" and #(parser.DetectUnits(text) or {}) > 0)
        or (type(parser.DetectGroups) == "function" and #(parser.DetectGroups(text) or {}) > 0)
    if hasExplicitScope and hasCore and not R.LooksLikeKnowledgeFirstRequest(text) then
        local scopedCoreResult = Core(text)
        if scopedCoreResult and not A.RouterIsUnknownResult(scopedCoreResult) then return scopedCoreResult end
    end

    -- Short page-local commands become useful before falling back to broad global matching.
    local contextResult = R.TryContext(text, Core)
    if contextResult and not A.RouterIsUnknownResult(contextResult) then return contextResult end

    local coreResult
    local deferredAuraFallback
    if (R.LooksLikeMutation(text) or R.StartsWithMutationCommand(text)) and hasCore then
        coreResult = Core(text)
        if R.IsAuraFallbackResult(coreResult) then
            deferredAuraFallback, coreResult = coreResult, nil
        elseif not A.RouterIsUnknownResult(coreResult) then
            return coreResult
        end
    end

    -- Release-note questions must not be mistaken for "what did you just change?" follow-ups.
    if R.LooksLikeChangelogKnowledgeRequest(text) and A.Knowledge and type(A.Knowledge.Answer) == "function" then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
        if answer then return answer end
        local noMatch = R.KnowledgeNoMatch(text)
        if noMatch then return noMatch end
    end

    if R.LooksLikeKnowledgeFirstRequest(text) and A.Knowledge and type(A.Knowledge.Answer) == "function" then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
        if answer then return answer end
        local noMatch = R.KnowledgeNoMatch(text)
        if noMatch then return noMatch end
    end

    if hasCore then
        coreResult = coreResult or Core(text)
        if R.IsAuraFallbackResult(coreResult) then
            deferredAuraFallback, coreResult = deferredAuraFallback or coreResult, nil
        elseif not A.RouterIsUnknownResult(coreResult) then
            return coreResult
        end
    end

    -- Curated registry owners, relationship guards, and the main parser have
    -- first refusal. The generated schema is the bounded semantic lane for a
    -- real public Menu2 control that still has no hand-written route.
    if not hasBlockingPendingState and not pendingResultReply then
        local schemaResult = A.ControlSchema and A.ControlSchema.TryConversation
            and A.ControlSchema.TryConversation(text)
        if schemaResult then return schemaResult end
    end

    -- Nothing better existed, so the aura "I have no control for that wording"
    -- message stands after all.
    if deferredAuraFallback then return deferredAuraFallback end

    if R.LooksLikeBareLookup(text) and A.Knowledge and type(A.Knowledge.Answer) == "function" then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
        if answer then return answer end
        local noMatch = R.KnowledgeNoMatch(text)
        if noMatch then return noMatch end
    end

    -- Mutation-like commands must not be swallowed by Search/FAQ fallback.
    -- If a setting/action command failed, return the parser failure or suggestions instead of a help article.
    if R.LooksLikeMutation(text) or R.StartsWithMutationCommand(text) then
        local fallbackResult = A.RouterTryMutationFallbacks(text, Core)
        if fallbackResult and not A.RouterIsUnknownResult(fallbackResult) then return fallbackResult end
        local auraUnsupported = R.UnsupportedAuraReply(text)
        if auraUnsupported then return auraUnsupported end
        if A.RouterIsNoClueResult(coreResult) then return A.RouterFriendlyNoMatch(text) end
        return coreResult or { text = "Include a specific frame, page, or option name, or ask for help.", status = "failed" }
    end

    if A.Knowledge and type(A.Knowledge.Answer) == "function" then
        local answer = A.Knowledge.Answer(text, { currentPage = M and M.activeKey })
        if answer then return answer end
        if R.LooksLikeKnowledgeRequest(text) then
            local noMatch = R.KnowledgeNoMatch(text)
            if noMatch then return noMatch end
        end
    end

    local auraUnsupported = R.UnsupportedAuraReply(text)
    if auraUnsupported then return auraUnsupported end

    if A.RouterIsNoClueResult(coreResult) then return A.RouterFriendlyNoMatch(text) end
    return coreResult or A.RouterFriendlyNoMatch(text)
end
